static bool common_dynamic_tier_requested() {
    static const bool enabled = [] {
        const char * env = std::getenv("GGML_MOE_COMMON_TIER_DYNAMIC");
        return env && env[0] && env[0] != '0';
    }();
    return enabled;
}

