};

static const char * q4_host_object_origin_name(uint8_t origin) {
    switch (origin) {
        case Q4_HOST_OBJECT_ORIGIN_PREFETCH: return "prefetch";
        case Q4_HOST_OBJECT_ORIGIN_PILOT: return "pilot";
        case Q4_HOST_OBJECT_ORIGIN_READ_ADMIT: return "read_admit";
        case Q4_HOST_OBJECT_ORIGIN_DEMOTE: return "demote";
        default: return "unknown";
    }
}

static bool q4_tier_layer_profile_enabled() {
    static const bool enabled = []() {
        const char *env = std::getenv("GGML_MOE_Q4_TIER_LAYER_PROFILE");
        return env && env[0] && env[0] != '0';
    }();
    return enabled;
}

static bool q4_tier_reuse_window_profile_enabled() {
    static const bool enabled = []() {
        const char *env = std::getenv("GGML_MOE_Q4_TIER_REUSE_WINDOW_PROFILE");
        return env && env[0] && env[0] != '0';
    }();
    return enabled;
}

static void q4_tier_layer_add(std::atomic<uint64_t> (&counters)[128], int layer, uint64_t value = 1) {
    if (!q4_tier_layer_profile_enabled()) return;
    if (value == 0 || layer < 0 || layer >= 128) return;
    counters[layer].fetch_add(value, std::memory_order_relaxed);
}

static int q4_tier_diag_window_tokens() {
    const char *env = std::getenv("GGML_MOE_Q4_TIER_DIAG_WINDOW_TOKENS");
    const long value = env && env[0] ? std::atol(env) : 16;
    if (value < 1) return 1;
    if (value > 512) return 512;
    return (int)value;
}

