        int copied_entries,
        uint64_t copied_bytes,
        uint64_t saved_bytes,
        uint64_t read_us,
        uint64_t h2d_enqueue_us,
        uint64_t total_us) {
    const char *path = expert_pack_v2_full_cover_down_profile_path();
    if (!path || !path[0]) return;

    static std::mutex mu;
    static bool header_written = false;
