            "saved_bytes=%.3f GiB insert_failures=%lu read_failures=%lu h2d_failures=%lu "
            "read_ms=%.3f h2d_enqueue_ms=%.3f total_ms=%.3f "
            "overlap_calls=%lu overlap_accepted=%lu overlap_rejected=%lu "
