static void copy_profile_record(
        const char *op,
        const char *tensor,
        int expert_idx,
        size_t bytes,
        bool pack_hit,
        bool ram_hit,
        bool iouring,
        double slot_wait_ms,
        double host_ms,
        double io_wait_ms,
        double enqueue_ms,
        double h2d_ms,
        double wall_ms) {
    const char *path = std::getenv("GGML_MOE_COPY_PROFILE_OUT");
    if (!path || !path[0]) return;

    static std::mutex mu;
    static bool header_written = false;
    static uint64_t seq = 0;
    std::lock_guard<std::mutex> lk(mu);

    FILE *f = std::fopen(path, "a");
    if (!f) return;
    if (!header_written) {
        std::fprintf(f,
                "seq,op,tensor,expert_idx,bytes,pack_hit,ram_hit,iouring,slot_wait_ms,host_ms,io_wait_ms,enqueue_ms,h2d_ms,wall_ms\n");
        header_written = true;
    }
    std::fprintf(f,
            "%lu,%s,%s,%d,%zu,%d,%d,%d,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            (unsigned long)++seq,
            op ? op : "",
            tensor ? tensor : "",
            expert_idx,
            bytes,
            pack_hit ? 1 : 0,
            ram_hit ? 1 : 0,
            iouring ? 1 : 0,
            slot_wait_ms,
            host_ms,
            io_wait_ms,
            enqueue_ms,
            h2d_ms,
            wall_ms);
    std::fclose(f);
}

