static bool q4_colibri_role_in_read_span(
        const q4_colibri_object_role_job &role,
        uint64_t read_offset,
        uint64_t read_bytes,
        uint64_t *relative_offset) {
    if (!role.entry || read_bytes == 0) return false;
    const uint64_t role_begin = role.entry->object_offset + role.entry->object_relative_offset;
    const uint64_t role_end = role_begin + role.entry->nbytes;
    const uint64_t read_end = read_offset + read_bytes;
    if (role_begin < read_offset || role_end > read_end || role_end < role_begin || read_end < read_offset) {
        return false;
    }
    if (relative_offset) {
        *relative_offset = role_begin - read_offset;
    }
    return true;
}

