    std::mutex mu;
    bool header_written = false;
    uint64_t seq = 0;
};

static q4_object_tier_trace_state g_q4_object_tier_trace;

static const char *q4_object_tier_trace_path() {
    static const char *path = std::getenv("GGML_MOE_Q4_OBJECT_TIER_TRACE_OUT");
    return path && path[0] ? path : nullptr;
}

static bool q4_object_tier_trace_enabled() {
    return g_expert_pack.q4_colibri && q4_object_tier_trace_path();
}

static uint64_t q4_colibri_host_object_score(
        const q4_colibri_object_marker &marker,
        int current_layer,
        uint32_t freq);

static bool q4_object_tier_trace_score_enabled() {
    return expert_pack_env_bool("GGML_MOE_Q4_OBJECT_TIER_TRACE_SCORE", false);
}

struct q4_object_tier_trace_ram_slot_snapshot {
    bool present = false;
    bool ready = false;
    bool loading = false;
    bool delete_after_h2d = false;
    uint64_t score = 0;
    uint32_t freq = 0;
    uint64_t used = 0;
};

static q4_object_tier_trace_ram_slot_snapshot q4_object_tier_trace_get_ram_snapshot(
        const q4_colibri_object_marker &marker) {
    q4_object_tier_trace_ram_slot_snapshot out;
    if (!q4_colibri_host_object_prefetch_enabled()) return out;
    std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
    if (!g_q4_host_object_prefetch.inited || !g_q4_host_object_prefetch.enabled) return out;
    size_t slot_idx = SIZE_MAX;
    if (!q4_colibri_host_object_find_ready_locked(marker, &slot_idx)) return out;
    const q4_colibri_host_object_slot &slot = g_q4_host_object_prefetch.slots[slot_idx];
    if (!q4_colibri_object_marker_matches(slot.marker, marker)) return out;
    out.present = true;
    out.ready = slot.ready;
    out.loading = slot.loading;
    out.delete_after_h2d = slot.delete_after_h2d;
    out.score = slot.score;
    out.freq = slot.freq;
    out.used = slot.used;
    return out;
}

static bool q4_tier_diag_vram_evicted_age_snapshot(
        const q4_colibri_object_marker &marker,
        uint64_t *age_out) {
    std::lock_guard<std::mutex> lock(g_q4_tier_overlap_diag.mu);
    const std::string key = q4_tier_diag_object_key(marker);
    auto it = g_q4_tier_overlap_diag.vram_evicted_epoch.find(key);
    if (it == g_q4_tier_overlap_diag.vram_evicted_epoch.end()) return false;
    const uint64_t epoch = g_q4_tier_overlap_diag.token_epoch;
    if (age_out) {
        *age_out = epoch >= it->second ? epoch - it->second : 0;
    }
    return true;
}

static void q4_object_tier_trace_record(
        const q4_colibri_object_marker &marker,
        int64_t active_rows,
        uint64_t vram_present_roles,
        uint64_t vram_ready_roles,
        bool ram_ready,
        uint64_t missing_roles,
        uint64_t scheduled_roles,
        uint64_t object_bytes,
        uint64_t logical_role_bytes,
        bool ram_lookup_allowed,
        bool ram_admit_allowed,
        bool ram_net_allowed) {
    if (!q4_object_tier_trace_enabled()) return;

    const char *demand_tier = "ssd";
    const char *provider_path = "ssd_read_h2d";
    if (vram_present_roles >= 3) {
        demand_tier = vram_ready_roles >= 3 ? "vram_full_ready" : "vram_full_pending";
        provider_path = vram_ready_roles >= 3 ? "none" : "wait_vram";
    } else if (vram_present_roles > 0) {
        demand_tier = ram_ready ? "vram_partial_ram" : "vram_partial_ssd";
        provider_path = ram_ready ? "ram_h2d" : "ssd_read_h2d";
    } else if (ram_ready) {
        demand_tier = "ram";
        provider_path = "ram_h2d";
    }

    const uint64_t epoch =
        g_q4_tier_overlap_diag.token_epoch_public.load(std::memory_order_acquire);
    uint64_t vram_eviction_age = 0;
    const bool after_vram_eviction =
        q4_tier_diag_vram_evicted_age_snapshot(marker, &vram_eviction_age);
    const bool score_trace = q4_object_tier_trace_score_enabled();
    const int current_layer = score_trace ? q4_tier_diag_current_layer_snapshot() : -1;
    const int layer_distance =
        score_trace && current_layer >= 0 && marker.layer_idx >= 0 ?
        (int)marker.layer_idx - current_layer : 0;
    const uint32_t score_freq = 1;
    const uint64_t object_score = score_trace ?
        q4_colibri_host_object_score(marker, current_layer, score_freq) : 0;
    const q4_object_tier_trace_ram_slot_snapshot ram_snapshot =
        score_trace ? q4_object_tier_trace_get_ram_snapshot(marker) : q4_object_tier_trace_ram_slot_snapshot{};

    std::lock_guard<std::mutex> lock(g_q4_object_tier_trace.mu);
    const char *path = q4_object_tier_trace_path();
    if (!path) return;
    FILE *f = std::fopen(path, "a");
    if (!f) return;
    if (!g_q4_object_tier_trace.header_written) {
        std::fprintf(f,
            "seq,epoch,layer,expert,source_idx,offset,object_bytes,active_rows,"
            "vram_present_roles,vram_ready_roles,ram_ready,missing_roles,scheduled_roles,"
            "logical_role_bytes,demand_tier,provider_path,ram_lookup_allowed,"
            "ram_admit_allowed,ram_net_allowed,after_vram_eviction,vram_eviction_age,"
            "current_layer,layer_distance,score_freq,object_score,"
            "ram_slot_present,ram_slot_ready,ram_slot_loading,ram_slot_delete_after_h2d,"
            "ram_slot_freq,ram_slot_score,ram_slot_used\n");
        g_q4_object_tier_trace.header_written = true;
    }
    std::fprintf(f,
        "%llu,%llu,%d,%d,%d,%llu,%llu,%lld,%llu,%llu,%d,%llu,%llu,%llu,%s,%s,%d,%d,%d,%d,%llu,%d,%d,%u,%llu,%d,%d,%d,%d,%u,%llu,%llu\n",
        (unsigned long long)++g_q4_object_tier_trace.seq,
        (unsigned long long)epoch,
        (int)marker.layer_idx,
        (int)marker.expert_idx,
        (int)marker.source_idx,
        (unsigned long long)marker.offset,
        (unsigned long long)object_bytes,
        (long long)active_rows,
        (unsigned long long)vram_present_roles,
        (unsigned long long)vram_ready_roles,
        ram_ready ? 1 : 0,
        (unsigned long long)missing_roles,
        (unsigned long long)scheduled_roles,
        (unsigned long long)logical_role_bytes,
        demand_tier,
        provider_path,
        ram_lookup_allowed ? 1 : 0,
        ram_admit_allowed ? 1 : 0,
        ram_net_allowed ? 1 : 0,
        after_vram_eviction ? 1 : 0,
        (unsigned long long)vram_eviction_age,
        current_layer,
        layer_distance,
        (unsigned)score_freq,
        (unsigned long long)object_score,
        ram_snapshot.present ? 1 : 0,
        ram_snapshot.ready ? 1 : 0,
        ram_snapshot.loading ? 1 : 0,
        ram_snapshot.delete_after_h2d ? 1 : 0,
        (unsigned)ram_snapshot.freq,
        (unsigned long long)ram_snapshot.score,
        (unsigned long long)ram_snapshot.used);
    std::fclose(f);
}

static q4_graph_slot_status q4_graph_vram_slot_status(const batch_vram_cache *cache, uintptr_t key) {
    q4_graph_slot_status status;
    if (!cache || !cache->pool || cache->n_slots <= 0 || key == 0) return status;
    for (int slot = 0; slot < cache->n_slots; ++slot) {
        if (cache->slot_key[slot] != key) continue;
        if (cache->slot_state[slot] != q4_colibri_slot_state::h2d_ready ||
                cache->slot_filling[slot] ||
                cache->slot_payload_bytes[slot] == 0) {
            return status;
        }
        status.present = true;
        status.pending = cache->slot_pending[slot];
        status.ready = !status.pending;
        status.slot = slot;
        return status;
    }
    return status;
}

static bool q4_graph_acquire_descriptor(
        batch_vram_cache *cache,
        const q4_graph_slot_status &status,
        uintptr_t key,
        ggml_moe_common::role kind,
        ggml_moe_expert_descriptor &descriptor) {
    if (!cache || !status.ready || status.slot < 0) return false;
    if (!ggml_moe_common::role_cache_acquire_descriptor(
            batch_cache_role_view(cache), status.slot, key, (uint64_t)key,
            kind, 0, descriptor)) {
        return false;
    }
    ++cache->descriptor_acquires;
    return true;
}

static bool q4_graph_release_descriptor(
        batch_vram_cache *cache,
        uintptr_t key,
        const ggml_moe_expert_descriptor &descriptor,
        cudaStream_t stream,
        bool record_completion) {
    if (!cache) return false;
    bool last_lease = false;
    if (!ggml_moe_common::role_cache_release_descriptor(
            batch_cache_role_view(cache), key, descriptor, &last_lease)) {
        ++cache->descriptor_stale_releases;
        return false;
    }
    if (record_completion && last_lease &&
            !batch_cache_record_slot_lease(cache, descriptor.slot_id, stream)) {
        if (stream) cudaStreamSynchronize(stream);
        return false;
    }
    ++cache->descriptor_releases;
    return true;
}

static bool q4_graph_release_descriptors(
        batch_vram_cache *cache,
        const std::vector<uintptr_t> &keys,
        const std::vector<ggml_moe_expert_descriptor> &descriptors,
        cudaStream_t stream,
        bool record_completion) {
    if (!cache || keys.size() != descriptors.size()) return false;
    bool ok = true;
    for (size_t i = 0; i < descriptors.size(); ++i) {
        ok = q4_graph_release_descriptor(
            cache, keys[i], descriptors[i], stream, record_completion) && ok;
    }
    return ok;
}

static int q4_graph_count_ready_roles(
        const char *tensor_name,
        batch_vram_cache *cache,
        const int *active_experts,
        int n_active) {
    int ready = 0;
    if (!tensor_name || !cache || !active_experts || n_active <= 0) return ready;
    for (int j = 0; j < n_active; ++j) {
        if (q4_graph_vram_ready_slot(cache, batch_key_hash(tensor_name, active_experts[j])) >= 0) {
            ++ready;
        }
    }
    return ready;
}

static const char *q4_graph_role_name(int role) {
    switch (role) {
        case 0: return "up";
        case 1: return "gate";
        case 2: return "down";
        default: return "unknown";
    }
}

static void q4_graph_report_role_line(const char *prefix, int layer, int role, uint64_t active, uint64_t ready, uint64_t full_hit) {
    if (active == 0 && ready == 0 && full_hit == 0) return;
    if (layer >= 0) {
        std::fprintf(stderr,
            "[moe_stream_batch] %s: layer=%d role=%s active_roles=%lu ready_roles=%lu "
            "miss_roles=%lu ready_rate=%.1f%% full_hit_calls=%lu\n",
            prefix, layer, q4_graph_role_name(role),
            (unsigned long)active,
            (unsigned long)ready,
            (unsigned long)(active > ready ? active - ready : 0),
            active > 0 ? 100.0 * (double)ready / (double)active : 0.0,
            (unsigned long)full_hit);
    } else {
        std::fprintf(stderr,
            "[moe_stream_batch] %s: role=%s active_roles=%lu ready_roles=%lu "
            "miss_roles=%lu ready_rate=%.1f%% full_hit_calls=%lu\n",
            prefix, q4_graph_role_name(role),
            (unsigned long)active,
            (unsigned long)ready,
            (unsigned long)(active > ready ? active - ready : 0),
            active > 0 ? 100.0 * (double)ready / (double)active : 0.0,
            (unsigned long)full_hit);
    }
}

static void q4_graph_report_miss_hist_line(const char *prefix, const std::atomic<uint64_t> *hist, int count) {
    uint64_t total = 0;
    for (int i = 0; i < count; ++i) {
        total += hist[i].load(std::memory_order_relaxed);
    }
    if (total == 0) return;
    std::fprintf(stderr, "[moe_stream_batch] %s: total=%lu", prefix, (unsigned long)total);
    for (int i = 0; i < count; ++i) {
        const uint64_t value = hist[i].load(std::memory_order_relaxed);
        if (value == 0) continue;
        if (i == count - 1) {
            std::fprintf(stderr, " miss_ge_%d=%lu", i, (unsigned long)value);
        } else {
            std::fprintf(stderr, " miss_%d=%lu", i, (unsigned long)value);
        }
    }
    std::fprintf(stderr, "\n");
}

static void q4_graph_hit_profile_report() {
    const uint64_t upgate_calls = g_q4_graph_hit_profile.upgate_calls.load(std::memory_order_relaxed);
    const uint64_t down_calls = g_q4_graph_hit_profile.down_calls.load(std::memory_order_relaxed);
    if (upgate_calls + down_calls == 0 && !q4_graph_profile_requested()) return;
    const uint64_t active_roles = g_q4_graph_hit_profile.active_roles.load(std::memory_order_relaxed);
    const uint64_t ready_roles = g_q4_graph_hit_profile.vram_ready_roles.load(std::memory_order_relaxed);
    const uint64_t miss_roles = g_q4_graph_hit_profile.vram_miss_roles.load(std::memory_order_relaxed);
    std::fprintf(stderr,
        "[moe_stream_batch] q4 graph hit-path: enabled=%d profile=%d upgate_calls=%lu down_calls=%lu "
        "prompt_skips=%lu layer_skips=%lu descriptor_overflow=%lu active_roles=%lu "
        "vram_ready_roles=%lu vram_miss_roles=%lu role_ready_rate=%.1f%% full_hit_calls=%lu "
        "upgate_full_hit_calls=%lu down_full_hit_calls=%lu blocked_host_expanded_slots=%lu "
        "would_replay_calls=%lu note=fixed-slot-device-descriptor-required\n",
        q4_graph_hit_path_requested() ? 1 : 0,
        q4_graph_profile_requested() ? 1 : 0,
        (unsigned long)upgate_calls,
        (unsigned long)down_calls,
        (unsigned long)g_q4_graph_hit_profile.prompt_skips.load(std::memory_order_relaxed),
        (unsigned long)g_q4_graph_hit_profile.layer_skips.load(std::memory_order_relaxed),
        (unsigned long)g_q4_graph_hit_profile.descriptor_overflow.load(std::memory_order_relaxed),
        (unsigned long)active_roles,
        (unsigned long)ready_roles,
        (unsigned long)miss_roles,
        active_roles > 0 ? 100.0 * (double)ready_roles / (double)active_roles : 0.0,
        (unsigned long)g_q4_graph_hit_profile.full_hit_calls.load(std::memory_order_relaxed),
        (unsigned long)g_q4_graph_hit_profile.upgate_full_hit_calls.load(std::memory_order_relaxed),
        (unsigned long)g_q4_graph_hit_profile.down_full_hit_calls.load(std::memory_order_relaxed),
        (unsigned long)g_q4_graph_hit_profile.blocked_host_expanded_slots.load(std::memory_order_relaxed),
        (unsigned long)g_q4_graph_hit_profile.would_replay_calls.load(std::memory_order_relaxed));
    q4_graph_report_role_line("q4 graph role", -1, 0,
        g_q4_graph_hit_profile.role_active_roles[0].load(std::memory_order_relaxed),
        g_q4_graph_hit_profile.role_ready_roles[0].load(std::memory_order_relaxed),
        g_q4_graph_hit_profile.upgate_full_hit_calls.load(std::memory_order_relaxed));
    q4_graph_report_role_line("q4 graph role", -1, 1,
        g_q4_graph_hit_profile.role_active_roles[1].load(std::memory_order_relaxed),
        g_q4_graph_hit_profile.role_ready_roles[1].load(std::memory_order_relaxed),
        g_q4_graph_hit_profile.upgate_full_hit_calls.load(std::memory_order_relaxed));
    q4_graph_report_role_line("q4 graph role", -1, 2,
        g_q4_graph_hit_profile.role_active_roles[2].load(std::memory_order_relaxed),
        g_q4_graph_hit_profile.role_ready_roles[2].load(std::memory_order_relaxed),
        g_q4_graph_hit_profile.down_full_hit_calls.load(std::memory_order_relaxed));
    const uint64_t post_calls = g_q4_graph_hit_profile.post_provider_calls.load(std::memory_order_relaxed);
    if (post_calls > 0) {
        const uint64_t post_objects = g_q4_graph_hit_profile.post_provider_active_objects.load(std::memory_order_relaxed);
        const uint64_t post_active_roles = post_objects * 3;
        const uint64_t post_present = g_q4_graph_hit_profile.post_provider_present_roles.load(std::memory_order_relaxed);
        const uint64_t post_pending = g_q4_graph_hit_profile.post_provider_pending_roles.load(std::memory_order_relaxed);
        const uint64_t post_ready = g_q4_graph_hit_profile.post_provider_ready_roles.load(std::memory_order_relaxed);
        std::fprintf(stderr,
            "[moe_stream_batch] q4 graph post-provider: calls=%lu active_objects=%lu "
            "active_roles=%lu present_roles=%lu pending_roles=%lu ready_roles=%lu "
            "missing_roles=%lu present_rate=%.1f%% ready_rate=%.1f%% "
            "full_present_calls=%lu full_ready_calls=%lu "
            "note=provider-complete-fixed-slot-eligibility\n",
            (unsigned long)post_calls,
            (unsigned long)post_objects,
            (unsigned long)post_active_roles,
            (unsigned long)post_present,
            (unsigned long)post_pending,
            (unsigned long)post_ready,
            (unsigned long)(post_active_roles > post_present ? post_active_roles - post_present : 0),
            post_active_roles > 0 ? 100.0 * (double)post_present / (double)post_active_roles : 0.0,
            post_active_roles > 0 ? 100.0 * (double)post_ready / (double)post_active_roles : 0.0,
            (unsigned long)g_q4_graph_hit_profile.post_provider_full_present_calls.load(std::memory_order_relaxed),
            (unsigned long)g_q4_graph_hit_profile.post_provider_full_ready_calls.load(std::memory_order_relaxed));
    }
    const uint64_t post_wait_calls = g_q4_graph_hit_profile.post_wait_calls.load(std::memory_order_relaxed);
    if (post_wait_calls > 0) {
        const uint64_t post_wait_objects = g_q4_graph_hit_profile.post_wait_active_objects.load(std::memory_order_relaxed);
        const uint64_t post_wait_active_roles = post_wait_objects * 3;
        const uint64_t post_wait_present = g_q4_graph_hit_profile.post_wait_present_roles.load(std::memory_order_relaxed);
        const uint64_t post_wait_pending = g_q4_graph_hit_profile.post_wait_pending_roles.load(std::memory_order_relaxed);
        const uint64_t post_wait_ready = g_q4_graph_hit_profile.post_wait_ready_roles.load(std::memory_order_relaxed);
        std::fprintf(stderr,
            "[moe_stream_batch] q4 graph post-wait: calls=%lu active_objects=%lu "
            "active_roles=%lu present_roles=%lu pending_roles=%lu ready_roles=%lu "
            "missing_roles=%lu present_rate=%.1f%% ready_rate=%.1f%% "
            "full_present_calls=%lu full_ready_calls=%lu "
            "note=after-active-slot-wait-before-compute\n",
            (unsigned long)post_wait_calls,
            (unsigned long)post_wait_objects,
            (unsigned long)post_wait_active_roles,
            (unsigned long)post_wait_present,
            (unsigned long)post_wait_pending,
            (unsigned long)post_wait_ready,
            (unsigned long)(post_wait_active_roles > post_wait_present ? post_wait_active_roles - post_wait_present : 0),
            post_wait_active_roles > 0 ? 100.0 * (double)post_wait_present / (double)post_wait_active_roles : 0.0,
            post_wait_active_roles > 0 ? 100.0 * (double)post_wait_ready / (double)post_wait_active_roles : 0.0,
            (unsigned long)g_q4_graph_hit_profile.post_wait_full_present_calls.load(std::memory_order_relaxed),
            (unsigned long)g_q4_graph_hit_profile.post_wait_full_ready_calls.load(std::memory_order_relaxed));
    }
    const uint64_t desc_calls = g_q4_graph_hit_profile.descriptor_dry_run_calls.load(std::memory_order_relaxed);
    const uint64_t desc_failures = g_q4_graph_hit_profile.descriptor_dry_run_failures.load(std::memory_order_relaxed);
    if (desc_calls > 0 || desc_failures > 0) {
        const uint64_t desc_objects = g_q4_graph_hit_profile.descriptor_dry_run_objects.load(std::memory_order_relaxed);
        const uint64_t desc_bytes = g_q4_graph_hit_profile.descriptor_dry_run_bytes.load(std::memory_order_relaxed);
        const uint64_t desc_copy_us = g_q4_graph_hit_profile.descriptor_dry_run_copy_us.load(std::memory_order_relaxed);
        std::fprintf(stderr,
            "[moe_stream_batch] q4 graph descriptor dry-run: enabled=%d calls=%lu objects=%lu "
            "bytes=%lu copy_us=%lu avg_copy_us=%.2f failures=%lu device_buffer_bytes=%zu\n",
            q4_graph_descriptor_dry_run_enabled() ? 1 : 0,
            (unsigned long)desc_calls,
            (unsigned long)desc_objects,
            (unsigned long)desc_bytes,
            (unsigned long)desc_copy_us,
            desc_calls > 0 ? (double)desc_copy_us / (double)desc_calls : 0.0,
            (unsigned long)desc_failures,
            g_batch.q4_graph_descriptor_buffer.bytes);
    }
    q4_graph_report_miss_hist_line("q4 graph miss hist upgate", g_q4_graph_hit_profile.upgate_miss_hist, 17);
    q4_graph_report_miss_hist_line("q4 graph miss hist down", g_q4_graph_hit_profile.down_miss_hist, 9);
    for (int layer = 0; layer < 128; ++layer) {
        const uint64_t layer_upgate = g_q4_graph_hit_profile.layer_upgate_calls[layer].load(std::memory_order_relaxed);
        const uint64_t layer_down = g_q4_graph_hit_profile.layer_down_calls[layer].load(std::memory_order_relaxed);
        const uint64_t layer_post_calls = g_q4_graph_hit_profile.layer_post_provider_calls[layer].load(std::memory_order_relaxed);
        if (layer_upgate + layer_down == 0) continue;
        const uint64_t layer_active = g_q4_graph_hit_profile.layer_active_roles[layer].load(std::memory_order_relaxed);
        const uint64_t layer_ready = g_q4_graph_hit_profile.layer_ready_roles[layer].load(std::memory_order_relaxed);
        std::fprintf(stderr,
            "[moe_stream_batch] q4 graph layer: layer=%d upgate_calls=%lu down_calls=%lu "
            "active_roles=%lu ready_roles=%lu ready_rate=%.1f%% full_hit_calls=%lu "
            "upgate_full_hit_calls=%lu down_full_hit_calls=%lu\n",
            layer,
            (unsigned long)layer_upgate,
            (unsigned long)layer_down,
            (unsigned long)layer_active,
            (unsigned long)layer_ready,
            layer_active > 0 ? 100.0 * (double)layer_ready / (double)layer_active : 0.0,
            (unsigned long)g_q4_graph_hit_profile.layer_full_hit_calls[layer].load(std::memory_order_relaxed),
            (unsigned long)g_q4_graph_hit_profile.layer_upgate_full_hit_calls[layer].load(std::memory_order_relaxed),
            (unsigned long)g_q4_graph_hit_profile.layer_down_full_hit_calls[layer].load(std::memory_order_relaxed));
        q4_graph_report_role_line("q4 graph role layer", layer, 0,
            g_q4_graph_hit_profile.layer_up_active_roles[layer].load(std::memory_order_relaxed),
            g_q4_graph_hit_profile.layer_up_ready_roles[layer].load(std::memory_order_relaxed),
            g_q4_graph_hit_profile.layer_upgate_full_hit_calls[layer].load(std::memory_order_relaxed));
        q4_graph_report_role_line("q4 graph role layer", layer, 1,
            g_q4_graph_hit_profile.layer_gate_active_roles[layer].load(std::memory_order_relaxed),
            g_q4_graph_hit_profile.layer_gate_ready_roles[layer].load(std::memory_order_relaxed),
            g_q4_graph_hit_profile.layer_upgate_full_hit_calls[layer].load(std::memory_order_relaxed));
        q4_graph_report_role_line("q4 graph role layer", layer, 2,
            g_q4_graph_hit_profile.layer_down_active_roles[layer].load(std::memory_order_relaxed),
            g_q4_graph_hit_profile.layer_down_ready_roles[layer].load(std::memory_order_relaxed),
            g_q4_graph_hit_profile.layer_down_full_hit_calls[layer].load(std::memory_order_relaxed));
        if (layer_post_calls > 0) {
            const uint64_t layer_post_objects = g_q4_graph_hit_profile.layer_post_provider_active_objects[layer].load(std::memory_order_relaxed);
            const uint64_t layer_post_active_roles = layer_post_objects * 3;
            const uint64_t layer_post_present = g_q4_graph_hit_profile.layer_post_provider_present_roles[layer].load(std::memory_order_relaxed);
            const uint64_t layer_post_pending = g_q4_graph_hit_profile.layer_post_provider_pending_roles[layer].load(std::memory_order_relaxed);
            const uint64_t layer_post_ready = g_q4_graph_hit_profile.layer_post_provider_ready_roles[layer].load(std::memory_order_relaxed);
            std::fprintf(stderr,
                "[moe_stream_batch] q4 graph post-provider layer: layer=%d calls=%lu "
                "active_objects=%lu active_roles=%lu present_roles=%lu pending_roles=%lu ready_roles=%lu "
                "missing_roles=%lu present_rate=%.1f%% ready_rate=%.1f%% "
                "full_present_calls=%lu full_ready_calls=%lu\n",
                layer,
                (unsigned long)layer_post_calls,
                (unsigned long)layer_post_objects,
                (unsigned long)layer_post_active_roles,
                (unsigned long)layer_post_present,
                (unsigned long)layer_post_pending,
                (unsigned long)layer_post_ready,
                (unsigned long)(layer_post_active_roles > layer_post_present ? layer_post_active_roles - layer_post_present : 0),
                layer_post_active_roles > 0 ? 100.0 * (double)layer_post_present / (double)layer_post_active_roles : 0.0,
                layer_post_active_roles > 0 ? 100.0 * (double)layer_post_ready / (double)layer_post_active_roles : 0.0,
                (unsigned long)g_q4_graph_hit_profile.layer_post_provider_full_present_calls[layer].load(std::memory_order_relaxed),
                (unsigned long)g_q4_graph_hit_profile.layer_post_provider_full_ready_calls[layer].load(std::memory_order_relaxed));
        }
        const uint64_t layer_post_wait_calls = g_q4_graph_hit_profile.layer_post_wait_calls[layer].load(std::memory_order_relaxed);
        if (layer_post_wait_calls > 0) {
            const uint64_t layer_post_wait_objects = g_q4_graph_hit_profile.layer_post_wait_active_objects[layer].load(std::memory_order_relaxed);
            const uint64_t layer_post_wait_active_roles = layer_post_wait_objects * 3;
            const uint64_t layer_post_wait_present = g_q4_graph_hit_profile.layer_post_wait_present_roles[layer].load(std::memory_order_relaxed);
            const uint64_t layer_post_wait_pending = g_q4_graph_hit_profile.layer_post_wait_pending_roles[layer].load(std::memory_order_relaxed);
            const uint64_t layer_post_wait_ready = g_q4_graph_hit_profile.layer_post_wait_ready_roles[layer].load(std::memory_order_relaxed);
            std::fprintf(stderr,
                "[moe_stream_batch] q4 graph post-wait layer: layer=%d calls=%lu "
                "active_objects=%lu active_roles=%lu present_roles=%lu pending_roles=%lu ready_roles=%lu "
                "missing_roles=%lu present_rate=%.1f%% ready_rate=%.1f%% "
                "full_present_calls=%lu full_ready_calls=%lu\n",
                layer,
                (unsigned long)layer_post_wait_calls,
                (unsigned long)layer_post_wait_objects,
                (unsigned long)layer_post_wait_active_roles,
                (unsigned long)layer_post_wait_present,
                (unsigned long)layer_post_wait_pending,
                (unsigned long)layer_post_wait_ready,
                (unsigned long)(layer_post_wait_active_roles > layer_post_wait_present ? layer_post_wait_active_roles - layer_post_wait_present : 0),
                layer_post_wait_active_roles > 0 ? 100.0 * (double)layer_post_wait_present / (double)layer_post_wait_active_roles : 0.0,
                layer_post_wait_active_roles > 0 ? 100.0 * (double)layer_post_wait_ready / (double)layer_post_wait_active_roles : 0.0,
                (unsigned long)g_q4_graph_hit_profile.layer_post_wait_full_present_calls[layer].load(std::memory_order_relaxed),
                (unsigned long)g_q4_graph_hit_profile.layer_post_wait_full_ready_calls[layer].load(std::memory_order_relaxed));
        }
    }
}

static void q4_graph_hit_profile_register_once() {
    std::lock_guard<std::mutex> lk(g_q4_graph_hit_profile.mu);
    if (g_q4_graph_hit_profile.report_registered) return;
    std::atexit(q4_graph_hit_profile_report);
    g_q4_graph_hit_profile.report_registered = true;
}

static void q4_graph_record_upgate_candidate(
        bool prompt_mode,
        const char *up_name,
        const char *gate_name,
        batch_vram_cache *cache,
        const int *active_experts,
        int n_active) {
    if (!q4_graph_profile_requested()) return;
    q4_graph_hit_profile_register_once();
    ++g_q4_graph_hit_profile.upgate_calls;
    if (prompt_mode) {
        ++g_q4_graph_hit_profile.prompt_skips;
        return;
    }
    if (!q4_graph_layer_allowed(up_name) || !q4_graph_layer_allowed(gate_name)) {
        ++g_q4_graph_hit_profile.layer_skips;
        return;
    }
    if (n_active <= 0 || n_active > q4_graph_descriptor_max_experts()) {
        ++g_q4_graph_hit_profile.descriptor_overflow;
        return;
    }
    const int up_ready = q4_graph_count_ready_roles(up_name, cache, active_experts, n_active);
    const int gate_ready = q4_graph_count_ready_roles(gate_name, cache, active_experts, n_active);
    const int roles = n_active * 2;
    const int ready = up_ready + gate_ready;
    const int miss_roles = roles - ready;
    const int layer = q4_graph_layer_from_tensor(up_name);
    g_q4_graph_hit_profile.active_roles.fetch_add((uint64_t)roles, std::memory_order_relaxed);
    g_q4_graph_hit_profile.vram_ready_roles.fetch_add((uint64_t)ready, std::memory_order_relaxed);
    g_q4_graph_hit_profile.vram_miss_roles.fetch_add((uint64_t)miss_roles, std::memory_order_relaxed);
    g_q4_graph_hit_profile.upgate_miss_hist[std::min(std::max(miss_roles, 0), 16)].fetch_add(1, std::memory_order_relaxed);
    g_q4_graph_hit_profile.role_active_roles[0].fetch_add((uint64_t)n_active, std::memory_order_relaxed);
    g_q4_graph_hit_profile.role_ready_roles[0].fetch_add((uint64_t)up_ready, std::memory_order_relaxed);
    g_q4_graph_hit_profile.role_active_roles[1].fetch_add((uint64_t)n_active, std::memory_order_relaxed);
    g_q4_graph_hit_profile.role_ready_roles[1].fetch_add((uint64_t)gate_ready, std::memory_order_relaxed);
    if (layer >= 0) {
        g_q4_graph_hit_profile.layer_upgate_calls[layer].fetch_add(1, std::memory_order_relaxed);
        g_q4_graph_hit_profile.layer_active_roles[layer].fetch_add((uint64_t)roles, std::memory_order_relaxed);
        g_q4_graph_hit_profile.layer_ready_roles[layer].fetch_add((uint64_t)ready, std::memory_order_relaxed);
        g_q4_graph_hit_profile.layer_up_active_roles[layer].fetch_add((uint64_t)n_active, std::memory_order_relaxed);
        g_q4_graph_hit_profile.layer_up_ready_roles[layer].fetch_add((uint64_t)up_ready, std::memory_order_relaxed);
        g_q4_graph_hit_profile.layer_gate_active_roles[layer].fetch_add((uint64_t)n_active, std::memory_order_relaxed);
        g_q4_graph_hit_profile.layer_gate_ready_roles[layer].fetch_add((uint64_t)gate_ready, std::memory_order_relaxed);
    }
    char label[160];
    std::snprintf(label, sizeof(label), "q4_graph_upgate_candidate full_hit=%d up_ready=%d/%d gate_ready=%d/%d active=%d",
            ready == roles ? 1 : 0, up_ready, n_active, gate_ready, n_active, n_active);
    moe_nvtx_range nvtx(label);
    if (ready == roles) {
        ++g_q4_graph_hit_profile.full_hit_calls;
        ++g_q4_graph_hit_profile.upgate_full_hit_calls;
        ++g_q4_graph_hit_profile.blocked_host_expanded_slots;
        if (layer >= 0) {
            g_q4_graph_hit_profile.layer_full_hit_calls[layer].fetch_add(1, std::memory_order_relaxed);
            g_q4_graph_hit_profile.layer_upgate_full_hit_calls[layer].fetch_add(1, std::memory_order_relaxed);
        }
    }
}

static void q4_graph_record_down_candidate(
        bool prompt_mode,
        const char *tensor_name,
        batch_vram_cache *cache,
        const int *active_experts,
        int n_active) {
    if (!q4_graph_profile_requested()) return;
    q4_graph_hit_profile_register_once();
    ++g_q4_graph_hit_profile.down_calls;
    if (prompt_mode) {
        ++g_q4_graph_hit_profile.prompt_skips;
        return;
    }
    if (!q4_graph_layer_allowed(tensor_name)) {
        ++g_q4_graph_hit_profile.layer_skips;
        return;
    }
    if (n_active <= 0 || n_active > q4_graph_descriptor_max_experts()) {
        ++g_q4_graph_hit_profile.descriptor_overflow;
        return;
    }
    const int ready = q4_graph_count_ready_roles(tensor_name, cache, active_experts, n_active);
    const int miss_roles = n_active - ready;
    const int layer = q4_graph_layer_from_tensor(tensor_name);
    g_q4_graph_hit_profile.active_roles.fetch_add((uint64_t)n_active, std::memory_order_relaxed);
    g_q4_graph_hit_profile.vram_ready_roles.fetch_add((uint64_t)ready, std::memory_order_relaxed);
    g_q4_graph_hit_profile.vram_miss_roles.fetch_add((uint64_t)miss_roles, std::memory_order_relaxed);
    g_q4_graph_hit_profile.down_miss_hist[std::min(std::max(miss_roles, 0), 8)].fetch_add(1, std::memory_order_relaxed);
    g_q4_graph_hit_profile.role_active_roles[2].fetch_add((uint64_t)n_active, std::memory_order_relaxed);
    g_q4_graph_hit_profile.role_ready_roles[2].fetch_add((uint64_t)ready, std::memory_order_relaxed);
    if (layer >= 0) {
        g_q4_graph_hit_profile.layer_down_calls[layer].fetch_add(1, std::memory_order_relaxed);
        g_q4_graph_hit_profile.layer_active_roles[layer].fetch_add((uint64_t)n_active, std::memory_order_relaxed);
        g_q4_graph_hit_profile.layer_ready_roles[layer].fetch_add((uint64_t)ready, std::memory_order_relaxed);
        g_q4_graph_hit_profile.layer_down_active_roles[layer].fetch_add((uint64_t)n_active, std::memory_order_relaxed);
        g_q4_graph_hit_profile.layer_down_ready_roles[layer].fetch_add((uint64_t)ready, std::memory_order_relaxed);
    }
    char label[160];
    std::snprintf(label, sizeof(label), "q4_graph_down_candidate full_hit=%d ready=%d/%d",
            ready == n_active ? 1 : 0, ready, n_active);
    moe_nvtx_range nvtx(label);
    if (ready == n_active) {
        ++g_q4_graph_hit_profile.full_hit_calls;
        ++g_q4_graph_hit_profile.down_full_hit_calls;
        ++g_q4_graph_hit_profile.blocked_host_expanded_slots;
        if (layer >= 0) {
            g_q4_graph_hit_profile.layer_full_hit_calls[layer].fetch_add(1, std::memory_order_relaxed);
            g_q4_graph_hit_profile.layer_down_full_hit_calls[layer].fetch_add(1, std::memory_order_relaxed);
        }
    }
}

static bool q4_graph_descriptor_buffer_init() {
    if (!q4_graph_descriptor_dry_run_enabled()) return true;
    const size_t capacity = (size_t)q4_graph_descriptor_max_experts() * 3;
    if (g_batch.q4_graph_descriptor_buffer.device) {
        return g_batch.q4_graph_descriptor_buffer.capacity >= capacity;
    }
    if (!ggml_moe_common::device_descriptor_buffer_allocate_fixed(
            g_batch.q4_graph_descriptor_buffer, capacity)) {
        ++g_q4_graph_hit_profile.descriptor_dry_run_failures;
        return false;
    }
    return true;
}

static bool q4_graph_descriptor_dry_run_copy(
        int layer,
        const std::vector<ggml_moe_expert_descriptor> &entries) {
    if (!q4_graph_descriptor_dry_run_enabled()) return true;
    if (entries.empty()) return true;
    const size_t bytes = entries.size() * sizeof(ggml_moe_expert_descriptor);
    if (!q4_graph_descriptor_buffer_init() ||
            g_batch.q4_graph_descriptor_buffer.capacity < entries.size()) {
        ++g_q4_graph_hit_profile.descriptor_dry_run_failures;
        return false;
    }
    const auto copy_start = std::chrono::steady_clock::now();
    char label[160];
    std::snprintf(label, sizeof(label),
            "q4_graph_descriptor_dry_run layer=%d objects=%zu bytes=%zu",
            layer, entries.size() / 3, bytes);
    {
        moe_nvtx_range nvtx(label);
        if (!ggml_moe_common::device_descriptor_buffer_copy_async(
                    g_batch.q4_graph_descriptor_buffer,
                    entries.data(), entries.size(), g_batch.stream)) {
            ++g_q4_graph_hit_profile.descriptor_dry_run_failures;
            return false;
        }
    }
    const uint64_t copy_us = (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now() - copy_start).count();
    ++g_q4_graph_hit_profile.descriptor_dry_run_calls;
    g_q4_graph_hit_profile.descriptor_dry_run_objects.fetch_add(entries.size() / 3, std::memory_order_relaxed);
    g_q4_graph_hit_profile.descriptor_dry_run_bytes.fetch_add(bytes, std::memory_order_relaxed);
    g_q4_graph_hit_profile.descriptor_dry_run_copy_us.fetch_add(copy_us, std::memory_order_relaxed);
    return true;
}

static void q4_graph_record_same_layer_boundary(
        const char *gate_name,
        const char *const role_names[3],
        batch_vram_cache *cache,
        int64_t n_as,
        const int64_t *matrix_row_counts,
        bool post_wait) {
    if (!q4_graph_profile_requested() || !gate_name || !role_names || !cache ||
            n_as <= 0 || !matrix_row_counts) {
        return;
    }
    q4_graph_hit_profile_register_once();
    const int layer = q4_graph_layer_from_tensor(gate_name);
    if (!q4_graph_layer_allowed(gate_name)) {
        ++g_q4_graph_hit_profile.layer_skips;
        return;
    }

    uint64_t objects = 0;
    uint64_t present_roles = 0;
    uint64_t pending_roles = 0;
    uint64_t ready_roles = 0;
    std::vector<ggml_moe_expert_descriptor> descriptors;
    std::vector<uintptr_t> descriptor_keys;
    if (q4_graph_descriptor_dry_run_enabled()) {
        const size_t reserve_objects = (size_t)std::min<int64_t>(
            n_as, q4_graph_descriptor_max_experts());
        descriptors.reserve(reserve_objects * 3);
        descriptor_keys.reserve(reserve_objects * 3);
    }
    for (int64_t expert = 0; expert < n_as; ++expert) {
        if (matrix_row_counts[expert] <= 0) continue;
        ++objects;
        q4_graph_slot_status role_status[3];
        for (size_t role_idx = 0; role_idx < 3; ++role_idx) {
            const char *role_name = role_names[role_idx];
            if (!role_name || !role_name[0]) continue;
            const q4_graph_slot_status status =
                q4_graph_vram_slot_status(cache, batch_key_hash(role_name, (int)expert));
            role_status[role_idx] = status;
            if (status.present) ++present_roles;
            if (status.pending) ++pending_roles;
            if (status.ready) ++ready_roles;
        }
        if (post_wait && q4_graph_descriptor_dry_run_enabled() &&
                role_status[0].ready && role_status[1].ready && role_status[2].ready) {
            ggml_moe_expert_descriptor object_descriptors[3];
            uintptr_t object_keys[3] = {};
            size_t acquired = 0;
            for (size_t role_idx = 0; role_idx < 3; ++role_idx) {
                object_keys[role_idx] = batch_key_hash(role_names[role_idx], (int)expert);
                if (!q4_graph_acquire_descriptor(
                        cache, role_status[role_idx], object_keys[role_idx],
                        static_cast<ggml_moe_common::role>(role_idx), object_descriptors[role_idx])) {
                    break;
                }
                ++acquired;
            }
            if (acquired == 3) {
                descriptors.insert(descriptors.end(), object_descriptors, object_descriptors + 3);
                descriptor_keys.insert(descriptor_keys.end(), object_keys, object_keys + 3);
            } else {
                for (size_t role_idx = 0; role_idx < acquired; ++role_idx) {
                    (void)q4_graph_release_descriptor(
                        cache, object_keys[role_idx], object_descriptors[role_idx], nullptr, false);
                }
            }
        }
    }
    if (objects == 0) return;
    const uint64_t active_roles = objects * 3;
    std::atomic<uint64_t> &calls = post_wait ?
        g_q4_graph_hit_profile.post_wait_calls :
        g_q4_graph_hit_profile.post_provider_calls;
    std::atomic<uint64_t> &active_objects_ctr = post_wait ?
        g_q4_graph_hit_profile.post_wait_active_objects :
        g_q4_graph_hit_profile.post_provider_active_objects;
    std::atomic<uint64_t> &present_roles_ctr = post_wait ?
        g_q4_graph_hit_profile.post_wait_present_roles :
        g_q4_graph_hit_profile.post_provider_present_roles;
    std::atomic<uint64_t> &pending_roles_ctr = post_wait ?
        g_q4_graph_hit_profile.post_wait_pending_roles :
        g_q4_graph_hit_profile.post_provider_pending_roles;
    std::atomic<uint64_t> &ready_roles_ctr = post_wait ?
        g_q4_graph_hit_profile.post_wait_ready_roles :
        g_q4_graph_hit_profile.post_provider_ready_roles;
    std::atomic<uint64_t> &full_present_ctr = post_wait ?
        g_q4_graph_hit_profile.post_wait_full_present_calls :
        g_q4_graph_hit_profile.post_provider_full_present_calls;
    std::atomic<uint64_t> &full_ready_ctr = post_wait ?
        g_q4_graph_hit_profile.post_wait_full_ready_calls :
        g_q4_graph_hit_profile.post_provider_full_ready_calls;
    ++calls;
    active_objects_ctr.fetch_add(objects, std::memory_order_relaxed);
    present_roles_ctr.fetch_add(present_roles, std::memory_order_relaxed);
    pending_roles_ctr.fetch_add(pending_roles, std::memory_order_relaxed);
    ready_roles_ctr.fetch_add(ready_roles, std::memory_order_relaxed);
    if (present_roles == active_roles) ++full_present_ctr;
    if (ready_roles == active_roles) ++full_ready_ctr;
    if (layer >= 0 && layer < 128) {
        std::atomic<uint64_t> *layer_calls = post_wait ?
            g_q4_graph_hit_profile.layer_post_wait_calls :
            g_q4_graph_hit_profile.layer_post_provider_calls;
        std::atomic<uint64_t> *layer_active_objects = post_wait ?
            g_q4_graph_hit_profile.layer_post_wait_active_objects :
            g_q4_graph_hit_profile.layer_post_provider_active_objects;
        std::atomic<uint64_t> *layer_present_roles = post_wait ?
            g_q4_graph_hit_profile.layer_post_wait_present_roles :
            g_q4_graph_hit_profile.layer_post_provider_present_roles;
        std::atomic<uint64_t> *layer_pending_roles = post_wait ?
            g_q4_graph_hit_profile.layer_post_wait_pending_roles :
            g_q4_graph_hit_profile.layer_post_provider_pending_roles;
        std::atomic<uint64_t> *layer_ready_roles = post_wait ?
            g_q4_graph_hit_profile.layer_post_wait_ready_roles :
            g_q4_graph_hit_profile.layer_post_provider_ready_roles;
        std::atomic<uint64_t> *layer_full_present = post_wait ?
            g_q4_graph_hit_profile.layer_post_wait_full_present_calls :
            g_q4_graph_hit_profile.layer_post_provider_full_present_calls;
        std::atomic<uint64_t> *layer_full_ready = post_wait ?
            g_q4_graph_hit_profile.layer_post_wait_full_ready_calls :
            g_q4_graph_hit_profile.layer_post_provider_full_ready_calls;
        ++layer_calls[layer];
        layer_active_objects[layer].fetch_add(objects, std::memory_order_relaxed);
        layer_present_roles[layer].fetch_add(present_roles, std::memory_order_relaxed);
        layer_pending_roles[layer].fetch_add(pending_roles, std::memory_order_relaxed);
        layer_ready_roles[layer].fetch_add(ready_roles, std::memory_order_relaxed);
        if (present_roles == active_roles) ++layer_full_present[layer];
        if (ready_roles == active_roles) ++layer_full_ready[layer];
    }
    if (post_wait && q4_graph_descriptor_dry_run_enabled()) {
        const bool complete = descriptors.size() == objects * 3 &&
            descriptor_keys.size() == descriptors.size();
        const bool copied = complete && q4_graph_descriptor_dry_run_copy(layer, descriptors);
        if (!q4_graph_release_descriptors(
                cache, descriptor_keys, descriptors, g_batch.stream, copied)) {
            ++g_q4_graph_hit_profile.descriptor_dry_run_failures;
        }
        if (!copied) ++g_q4_graph_hit_profile.descriptor_dry_run_failures;
    }
    char label[192];
    std::snprintf(label, sizeof(label),
            "%s layer=%d present=%llu/%llu pending=%llu ready=%llu",
            post_wait ? "q4_graph_post_wait" : "q4_graph_post_provider",
            layer,
            (unsigned long long)present_roles,
            (unsigned long long)active_roles,
            (unsigned long long)pending_roles,
            (unsigned long long)ready_roles);
    moe_nvtx_range nvtx(label);
}

static void q4_graph_record_post_provider_same_layer(
        const char *gate_name,
        const char *const role_names[3],
        batch_vram_cache *cache,
        int64_t n_as,
        const int64_t *matrix_row_counts) {
    q4_graph_record_same_layer_boundary(gate_name, role_names, cache, n_as, matrix_row_counts, false);
}

static void q4_graph_record_post_wait_same_layer(
        const char *gate_name,
        const char *const role_names[3],
        batch_vram_cache *cache,
        int64_t n_as,
        const int64_t *matrix_row_counts) {
    q4_graph_record_same_layer_boundary(gate_name, role_names, cache, n_as, matrix_row_counts, true);
}

static bool q4_colibri_host_object_prefetch_enabled() {
    if (!g_expert_pack.q4_colibri) return false;
    // GLM's accepted lossless path owns a separate compressed staging ring.
    // Kimi uses the generation-aware compressed Host object cache below.
    if (g_expert_pack.glm52_colibri &&
            g_expert_pack.lossless_mode == q4_lossless_transport_mode::cuda) {
        return false;
    }
    return expert_pack_env_bool("GGML_MOE_Q4_HOST_OBJECT_PREFETCH", false);
}

static size_t q4_colibri_host_object_prefetch_slots() {
    // Keep the default small, but allow explicit RAM-cache A/B runs above the
    // original 512-slot cap under the 16GB cgroup gate.
    return expert_pack_env_size("GGML_MOE_Q4_HOST_OBJECT_PREFETCH_SLOTS", 64, 1, 4096);
}

static size_t q4_colibri_host_object_prefetch_queue_limit() {
    return expert_pack_env_size("GGML_MOE_Q4_HOST_OBJECT_PREFETCH_QUEUE", 256, 1, 4096);
}

static bool q4_colibri_host_object_defer_h2d_enabled() {
    if (!g_expert_pack.q4_colibri) return false;
    return expert_pack_env_bool("GGML_MOE_Q4_HOST_OBJECT_DEFER_H2D", false);
}

static size_t q4_colibri_host_object_prefetch_max_bytes() {
    const size_t mib = expert_pack_env_size("GGML_MOE_Q4_HOST_OBJECT_PREFETCH_MAX_MIB", 0, 0, 15360);
    return mib * 1024ULL * 1024ULL;
}

static bool q4_colibri_host_object_pageable_enabled() {
    return expert_pack_env_bool("GGML_MOE_Q4_HOST_OBJECT_PAGEABLE", false);
}

static size_t q4_colibri_host_object_pinned_prefix_slots() {
    return expert_pack_env_size("GGML_MOE_Q4_HOST_OBJECT_PINNED_PREFIX_SLOTS", 0, 0, 4096);
}

static size_t q4_colibri_host_object_register_pageable_after_read_limit() {
    return expert_pack_env_size(
        "GGML_MOE_Q4_HOST_OBJECT_REGISTER_PAGEABLE_AFTER_READ", 0, 0, 4096);
}

static bool q4_colibri_host_object_slot_should_be_pageable(
        const q4_colibri_host_object_slot &slot) {
    if (q4_colibri_host_object_pageable_enabled()) return true;
    const size_t pinned_prefix = q4_colibri_host_object_pinned_prefix_slots();
    if (pinned_prefix == 0 || g_q4_host_object_prefetch.slots.empty()) return false;
    const ptrdiff_t slot_idx = &slot - g_q4_host_object_prefetch.slots.data();
    return slot_idx >= 0 && (size_t)slot_idx >= pinned_prefix;
}

static void q4_colibri_host_object_free(q4_colibri_host_object_slot &slot) {
    ggml_moe_common::object_host_slot_release_memory(slot);
}

static bool q4_colibri_host_object_alloc(q4_colibri_host_object_slot &slot, size_t bytes) {
    return ggml_moe_common::object_host_slot_allocate_memory(
            slot, bytes, q4_colibri_host_object_slot_should_be_pageable(slot), 4096);
}

static size_t q4_colibri_host_object_allocation_bytes(
        ggml_moe_common::object_host_payload_format format,
        size_t raw_bytes) {
    if (format == ggml_moe_common::object_host_payload_format::lossless_sidecar &&
            g_expert_pack.lossless_sidecar.max_physical_bytes > 0 &&
            g_expert_pack.lossless_sidecar.max_physical_bytes <= SIZE_MAX) {
        return static_cast<size_t>(
            g_expert_pack.lossless_sidecar.max_physical_bytes);
    }
    return raw_bytes;
}

static void q4_colibri_host_object_try_register_pageable(
        q4_colibri_host_object_slot &slot) {
    const size_t limit = q4_colibri_host_object_register_pageable_after_read_limit();
    if (limit == 0 || !slot.pageable || slot.host_registered || slot.host_register_attempted ||
            !slot.host || slot.capacity == 0) return;
    if (g_q4_host_object_prefetch.register_pageable_successes.load(std::memory_order_relaxed) >= limit) return;

    ++g_q4_host_object_prefetch.register_pageable_attempts;
    const auto start = std::chrono::steady_clock::now();
    const bool registered = ggml_moe_common::object_host_slot_register_pageable(slot);
    const uint64_t elapsed_us = (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
        std::chrono::steady_clock::now() - start).count();
    g_q4_host_object_prefetch.register_pageable_us.fetch_add(elapsed_us, std::memory_order_relaxed);
    if (registered) {
        ++g_q4_host_object_prefetch.register_pageable_successes;
        g_q4_host_object_prefetch.register_pageable_bytes.fetch_add(slot.capacity, std::memory_order_relaxed);
    } else {
        ++g_q4_host_object_prefetch.register_pageable_failures;
    }
}

