static bool q4_colibri_host_object_admit_layer_allowed(int layer);

static bool q4_colibri_host_object_lookup_layer_allowed(int layer) {
    static bool inited = false;
    static bool has_filter = false;
    static bool allow_all = true;
    static bool allowed[128] = {};
    if (!inited) {
        const char *env = std::getenv("GGML_MOE_Q4_HOST_OBJECT_LOOKUP_LAYERS");
        if (env && env[0]) {
            has_filter = true;
            if (std::strcmp(env, "all") == 0 || std::strcmp(env, "*") == 0) {
                allow_all = true;
            } else {
                allow_all = false;
                char buf[512];
                std::snprintf(buf, sizeof(buf), "%s", env);
                char *save = nullptr;
                for (char *tok = ::strtok_r(buf, ",;:", &save); tok; tok = ::strtok_r(nullptr, ",;:", &save)) {
                    while (*tok == ' ' || *tok == '\t') ++tok;
                    if (!*tok) continue;
                    char *end = nullptr;
                    long lo = std::strtol(tok, &end, 10);
                    long hi = lo;
                    if (end && *end == '-') {
                        char *end2 = nullptr;
                        hi = std::strtol(end + 1, &end2, 10);
                        end = end2;
                    }
                    if (end == tok || lo < 0 || hi < 0) continue;
                    if (hi < lo) std::swap(lo, hi);
                    lo = std::max<long>(0, std::min<long>(lo, 127));
                    hi = std::max<long>(0, std::min<long>(hi, 127));
                    for (long l = lo; l <= hi; ++l) {
                        allowed[l] = true;
                    }
                }
            }
        }
        inited = true;
    }
    if (layer < 0 || layer >= 128) return false;
    if (has_filter) return allow_all || allowed[layer];
    if (q4_colibri_host_object_lookup_admit_layers_only_enabled()) {
        return q4_colibri_host_object_admit_layer_allowed(layer);
    }
    return true;
}

static bool q4_colibri_host_object_admit_layer_allowed(int layer) {
    static bool inited = false;
    static bool allow_all = true;
    static bool allowed[128] = {};
    if (!inited) {
        const char *env = std::getenv("GGML_MOE_Q4_HOST_OBJECT_ADMIT_LAYERS");
        if (env && env[0] && std::strcmp(env, "all") != 0 && std::strcmp(env, "*") != 0) {
            allow_all = false;
            char buf[512];
            std::snprintf(buf, sizeof(buf), "%s", env);
            char *save = nullptr;
            for (char *tok = ::strtok_r(buf, ",;:", &save); tok; tok = ::strtok_r(nullptr, ",;:", &save)) {
                while (*tok == ' ' || *tok == '\t') ++tok;
                if (!*tok) continue;
                char *end = nullptr;
                long lo = std::strtol(tok, &end, 10);
                long hi = lo;
                if (end && *end == '-') {
                    char *end2 = nullptr;
                    hi = std::strtol(end + 1, &end2, 10);
                    end = end2;
                }
                if (end == tok || lo < 0 || hi < 0) continue;
                if (hi < lo) std::swap(lo, hi);
                lo = std::max<long>(0, std::min<long>(lo, 127));
                hi = std::max<long>(0, std::min<long>(hi, 127));
                for (long l = lo; l <= hi; ++l) {
                    allowed[l] = true;
                }
            }
        }
        inited = true;
    }
    if (layer < 0 || layer >= 128) return false;
    return allow_all || allowed[layer];
}

static bool q4_colibri_host_object_admit_pair_allowed(int layer, int expert) {
    static bool inited = false;
    static bool has_filter = false;
    static std::unordered_set<uint64_t> allowed;
    auto key_for = [](int l, int e) -> uint64_t {
        return ((uint64_t)(uint32_t)l << 32) | (uint32_t)e;
    };
    auto parse_pair = [&](const char *text) {
        if (!text || !text[0]) return;
        while (*text == ' ' || *text == '\t') ++text;
        char *end1 = nullptr;
        const long l = std::strtol(text, &end1, 10);
        if (end1 == text || l < 0 || l >= 128) return;
        while (*end1 == ' ' || *end1 == '\t' || *end1 == ':' || *end1 == ',' || *end1 == ';') ++end1;
        char *end2 = nullptr;
        const long e = std::strtol(end1, &end2, 10);
        if (end2 == end1 || e < 0 || e >= 4096) return;
        allowed.insert(key_for((int)l, (int)e));
        has_filter = true;
    };
    if (!inited) {
        const char *inline_env = std::getenv("GGML_MOE_Q4_HOST_OBJECT_ADMIT_OBJECTS");
        if (inline_env && inline_env[0]) {
            char buf[8192];
            std::snprintf(buf, sizeof(buf), "%s", inline_env);
            char *save = nullptr;
            for (char *tok = ::strtok_r(buf, " \t\r\n", &save); tok; tok = ::strtok_r(nullptr, " \t\r\n", &save)) {
                parse_pair(tok);
            }
        }
        const char *path = std::getenv("GGML_MOE_Q4_HOST_OBJECT_ADMIT_OBJECTS_FILE");
        if (path && path[0]) {
            std::ifstream in(path);
            std::string line;
            while (std::getline(in, line)) {
                const size_t comment = line.find('#');
                if (comment != std::string::npos) line.resize(comment);
                parse_pair(line.c_str());
            }
        }
        inited = true;
    }
    if (!has_filter) return true;
    if (layer < 0 || layer >= 128 || expert < 0) return false;
    return allowed.find(key_for(layer, expert)) != allowed.end();
}

struct q4_colibri_layer_set_config {
    bool enabled = false;
    bool allowed[128] = {};
};

static const q4_colibri_layer_set_config & q4_colibri_ram_net_layer_set_config() {
    static q4_colibri_layer_set_config cfg = []() {
        q4_colibri_layer_set_config out;
        const char *env = std::getenv("GGML_MOE_Q4_RAM_NET_LAYER_SET");
        if (!env || !env[0]) return out;
        char buf[4096];
        std::snprintf(buf, sizeof(buf), "%s", env);
        char *save = nullptr;
        for (char *tok = ::strtok_r(buf, ",; \t\r\n", &save); tok; tok = ::strtok_r(nullptr, ",; \t\r\n", &save)) {
            while (*tok == ' ' || *tok == '\t') ++tok;
            if (!*tok) continue;
            char *end = nullptr;
            long lo = std::strtol(tok, &end, 10);
            long hi = lo;
            if (end && *end == '-') {
                char *end2 = nullptr;
                hi = std::strtol(end + 1, &end2, 10);
                end = end2;
            }
            if (end == tok || lo < 0 || hi < 0) continue;
            if (hi < lo) std::swap(lo, hi);
            lo = std::max<long>(0, std::min<long>(lo, 127));
            hi = std::max<long>(0, std::min<long>(hi, 127));
            for (long layer = lo; layer <= hi; ++layer) {
                out.allowed[layer] = true;
                out.enabled = true;
            }
        }
        return out;
    }();
    return cfg;
}

