static uint64_t q4_colibri_host_object_score_admit_margin() {
    return expert_pack_env_size("GGML_MOE_Q4_HOST_OBJECT_SCORE_ADMIT_MARGIN", 0, 0, 1000000000ULL);
}

static uint64_t q4_colibri_host_object_score_admit_margin_for_layer(int layer) {
    struct layer_margin_config {
        bool has_spec = false;
        bool specified[128] = {};
        uint64_t margin[128] = {};
    };
    static const layer_margin_config cfg = []() {
        layer_margin_config out;
        const char *env = std::getenv("GGML_MOE_Q4_HOST_OBJECT_SCORE_ADMIT_MARGIN_LAYERS");
        if (!env || !env[0]) return out;
        char buf[4096];
        std::snprintf(buf, sizeof(buf), "%s", env);
        char *save = nullptr;
        for (char *tok = ::strtok_r(buf, ",; \t\r\n", &save);
                tok;
                tok = ::strtok_r(nullptr, ",; \t\r\n", &save)) {
            while (*tok == ' ' || *tok == '\t') ++tok;
            if (!*tok) continue;
            char *sep = std::strchr(tok, ':');
            if (!sep) sep = std::strchr(tok, '=');
            if (!sep) continue;
            *sep = '\0';
            char *end_layer = nullptr;
            char *end_margin = nullptr;
            const long parsed_layer = std::strtol(tok, &end_layer, 10);
            const unsigned long long parsed_margin = std::strtoull(sep + 1, &end_margin, 10);
            if (end_layer == tok || end_margin == sep + 1 ||
                    parsed_layer < 0 || parsed_layer >= 128) {
                continue;
            }
            out.specified[parsed_layer] = true;
            out.margin[parsed_layer] = std::min<unsigned long long>(parsed_margin, 1000000000ULL);
            out.has_spec = true;
        }
        return out;
    }();
    if (layer >= 0 && layer < 128 && cfg.specified[layer]) {
        return cfg.margin[layer];
    }
    return q4_colibri_host_object_score_admit_margin();
}

