    // Conservative mode: use dynamic layer distance to protect resident
    // victims, but do not give every just-read candidate a current-layer bonus.
    return -1;
}

static bool q4_colibri_host_object_score_layer_hint_enabled(int layer) {
    static bool inited = false;
    static bool allow_all = false;
    static bool allowed[128] = {};
    if (!inited) {
        const char *env = std::getenv("GGML_MOE_Q4_HOST_OBJECT_SCORE_LAYER_HINTS");
        if (env && env[0]) {
            if (std::strcmp(env, "all") == 0 || std::strcmp(env, "*") == 0) {
                allow_all = true;
            } else {
                char buf[512];
                std::snprintf(buf, sizeof(buf), "%s", env);
                char *save = nullptr;
                for (char *tok = ::strtok_r(buf, ",;:", &save); tok; tok = ::strtok_r(nullptr, ",;:", &save)) {
                    while (*tok == ' ' || *tok == '\t') ++tok;
                    if (!*tok) continue;
                    char *endp = nullptr;
                    long lo = std::strtol(tok, &endp, 10);
                    long hi = lo;
                    if (endp && *endp == '-') {
                        char *end2 = nullptr;
                        hi = std::strtol(endp + 1, &end2, 10);
                        endp = end2;
                    }
                    if (endp == tok || lo < 0 || hi < 0) continue;
                    if (hi < lo) std::swap(lo, hi);
                    lo = std::max<long>(0, std::min<long>(lo, 127));
                    hi = std::max<long>(0, std::min<long>(hi, 127));
                    for (long l = lo; l <= hi; ++l) {
                        allowed[l] = true;
                    }
                }
            }
        }
        inited = true;
    }
    if (layer < 0 || layer >= 128) return false;
    return allow_all || allowed[layer];
}

static uint64_t q4_colibri_host_object_score_layer_bonus() {
    return expert_pack_env_size("GGML_MOE_Q4_HOST_OBJECT_SCORE_LAYER_BONUS", 0, 0, 1000000000ULL);
}

struct q4_colibri_layer_score_bonus_config {
    bool enabled = false;
    uint64_t bonus[128] = {};
};

static const q4_colibri_layer_score_bonus_config & q4_colibri_layer_score_bonus_config_get() {
    static const q4_colibri_layer_score_bonus_config cfg = []() {
        q4_colibri_layer_score_bonus_config out;
        const char *env = std::getenv("GGML_MOE_Q4_HOST_OBJECT_LAYER_SCORE_BONUS");
        if (!env || !env[0]) return out;
        char buf[4096];
        std::snprintf(buf, sizeof(buf), "%s", env);
        char *save = nullptr;
        for (char *tok = ::strtok_r(buf, ",; \t\r\n", &save);
                tok;
                tok = ::strtok_r(nullptr, ",; \t\r\n", &save)) {
            while (*tok == ' ' || *tok == '\t') ++tok;
            if (!*tok) continue;
            char *sep = std::strchr(tok, ':');
            if (!sep) sep = std::strchr(tok, '=');
            if (!sep) continue;
            *sep = '\0';
            char *end_layer = nullptr;
            char *end_bonus = nullptr;
            const long layer = std::strtol(tok, &end_layer, 10);
            const unsigned long long parsed_bonus = std::strtoull(sep + 1, &end_bonus, 10);
            if (end_layer == tok || end_bonus == sep + 1 || layer < 0 || layer >= 128) {
                continue;
            }
            out.bonus[layer] = std::min<unsigned long long>(parsed_bonus, 1000000000ULL);
            out.enabled = true;
        }
        return out;
    }();
    return cfg;
}

static bool q4_colibri_layer_score_bonus_enabled() {
    return q4_colibri_layer_score_bonus_config_get().enabled;
}

static uint64_t q4_colibri_layer_score_bonus(int layer) {
    if (layer < 0 || layer >= 128) return 0;
    return q4_colibri_layer_score_bonus_config_get().bonus[layer];
}

static uint64_t q4_colibri_host_object_static_hotness_key(int layer, int expert) {
    return ((uint64_t)(uint32_t)layer << 32) | (uint32_t)expert;
}

struct q4_colibri_static_hotness_state {
    bool enabled = false;
    std::unordered_map<uint64_t, uint64_t> scores;
};

static const q4_colibri_static_hotness_state & q4_colibri_static_hotness_config() {
    static const q4_colibri_static_hotness_state *cfg = []() {
        q4_colibri_static_hotness_state *out = new q4_colibri_static_hotness_state();
        const char *path = std::getenv("GGML_MOE_Q4_HOST_OBJECT_STATIC_HOTNESS_FILE");
        if (!path || !path[0]) return out;
        std::ifstream in(path);
        if (!in.good()) return out;

        const size_t max_entries = expert_pack_env_size(
                "GGML_MOE_Q4_HOST_OBJECT_STATIC_HOTNESS_MAX_ENTRIES", 4096, 1, 1048576);
        const uint64_t max_bonus = expert_pack_env_size(
                "GGML_MOE_Q4_HOST_OBJECT_STATIC_HOTNESS_MAX_BONUS", 250000, 1, 1000000000ULL);
        const uint64_t weight = expert_pack_env_size(
                "GGML_MOE_Q4_HOST_OBJECT_STATIC_HOTNESS_WEIGHT", 1, 0, 1000000ULL);

        std::string line;
        size_t rank = 0;
        while (rank < max_entries && std::getline(in, line)) {
            const char *p = line.c_str();
            while (*p == ' ' || *p == '\t') ++p;
            if (!*p || *p == '#') continue;

            char *end_layer = nullptr;
            const long layer = std::strtol(p, &end_layer, 10);
            if (end_layer == p || layer < 0 || layer >= 128) continue;
            while (*end_layer == ' ' || *end_layer == '\t' || *end_layer == ':' || *end_layer == ',' || *end_layer == ';') {
                ++end_layer;
            }
            char *end_expert = nullptr;
            const long expert = std::strtol(end_layer, &end_expert, 10);
            if (end_expert == end_layer || expert < 0 || expert >= 4096) continue;

            ++rank;
            uint64_t parsed_score = 0;
            const size_t score_pos = line.find("score=");
            if (score_pos != std::string::npos) {
                const char *score_text = line.c_str() + score_pos + 6;
                char *end_score = nullptr;
                const unsigned long long value = std::strtoull(score_text, &end_score, 10);
                if (end_score != score_text) {
                    parsed_score = (uint64_t)value;
                }
            }
            if (parsed_score == 0) {
                parsed_score = (uint64_t)(max_entries - rank + 1);
            }
            uint64_t bonus = parsed_score;
            if (weight > 0 && bonus > UINT64_MAX / weight) {
                bonus = UINT64_MAX;
            } else {
                bonus *= weight;
            }
            bonus = std::min<uint64_t>(bonus, max_bonus);
            out->scores[q4_colibri_host_object_static_hotness_key((int)layer, (int)expert)] = bonus;
        }
        out->enabled = !out->scores.empty();
        return out;
    }();
    return *cfg;
}

static bool q4_colibri_static_hotness_enabled() {
    return q4_colibri_static_hotness_config().enabled;
}

static size_t q4_colibri_static_hotness_entries() {
    return q4_colibri_static_hotness_config().scores.size();
}

static uint64_t q4_colibri_static_hotness_bonus_raw(const q4_colibri_object_marker &marker) {
    if (marker.layer_idx < 0 || marker.expert_idx < 0) return 0;
    const q4_colibri_static_hotness_state &cfg = q4_colibri_static_hotness_config();
    if (!cfg.enabled) return 0;
    const auto it = cfg.scores.find(q4_colibri_host_object_static_hotness_key(marker.layer_idx, marker.expert_idx));
    if (it == cfg.scores.end() || it->second == 0) return 0;
    return it->second;
}

static uint64_t q4_colibri_static_hotness_bonus(const q4_colibri_object_marker &marker) {
    const uint64_t bonus = q4_colibri_static_hotness_bonus_raw(marker);
    if (bonus == 0) return 0;
    ++g_q4_host_object_prefetch.static_hotness_score_hits;
    g_q4_host_object_prefetch.static_hotness_score_bonus.fetch_add(bonus, std::memory_order_relaxed);
    return bonus;
}

static bool q4_object_continuous_score_enabled() {
    return expert_pack_env_bool("GGML_MOE_Q4_OBJECT_CONTINUOUS_SCORE", false) ||
        expert_pack_env_bool("GGML_MOE_Q4_FULL_DISTANCE_SCORE", false) ||
        q4_colibri_flow_score_cache_enabled() ||
        q4_vram_unified_score_enabled();
}

static bool q4_full_distance_score_enabled() {
    return expert_pack_env_bool("GGML_MOE_Q4_FULL_DISTANCE_SCORE", false);
}

static bool q4_score_vram_layer_bias_env_hint_enabled(int layer) {
    static bool inited = false;
    static bool allow_all = false;
    static bool allowed[128] = {};
    if (!inited) {
        const char *env = std::getenv("GGML_MOE_VRAM_CACHE_LAYER_BIAS_LAYERS");
        if (env && env[0]) {
            if (std::strcmp(env, "all") == 0 || std::strcmp(env, "*") == 0) {
                allow_all = true;
            } else {
                char buf[512];
                std::snprintf(buf, sizeof(buf), "%s", env);
                char *save = nullptr;
                for (char *tok = ::strtok_r(buf, ",;:", &save); tok; tok = ::strtok_r(nullptr, ",;:", &save)) {
                    while (*tok == ' ' || *tok == '\t') ++tok;
                    if (!*tok) continue;
                    char *endp = nullptr;
                    long lo = std::strtol(tok, &endp, 10);
                    long hi = lo;
                    if (endp && *endp == '-') {
                        char *end2 = nullptr;
                        hi = std::strtol(endp + 1, &end2, 10);
                        endp = end2;
                    }
                    if (endp == tok || lo < 0 || hi < 0) continue;
                    if (hi < lo) std::swap(lo, hi);
                    lo = std::max<long>(0, std::min<long>(lo, 127));
                    hi = std::max<long>(0, std::min<long>(hi, 127));
                    for (long l = lo; l <= hi; ++l) {
                        allowed[l] = true;
                    }
                }
            }
        }
        inited = true;
    }
    if (layer < 0 || layer >= 128) return false;
    return allow_all || allowed[layer];
}

static uint64_t q4_colibri_host_object_score(
        const q4_colibri_object_marker &marker,
        int current_layer,
        uint32_t freq) {
    const uint64_t freq_weight = expert_pack_env_size(
            "GGML_MOE_Q4_HOST_OBJECT_SCORE_FREQ_WEIGHT", 10000, 1, 1000000);
    if (!q4_object_continuous_score_enabled()) {
        const uint64_t near_weight = expert_pack_env_size(
                "GGML_MOE_Q4_HOST_OBJECT_SCORE_NEAR_WEIGHT", 1000, 0, 1000000);
        const uint64_t past_penalty = expert_pack_env_size(
                "GGML_MOE_Q4_HOST_OBJECT_SCORE_PAST_PENALTY", 2000, 0, 1000000);
        int64_t legacy_score = (int64_t)freq * (int64_t)freq_weight;
        if (current_layer >= 0 && marker.layer_idx >= 0) {
            const int dist = marker.layer_idx - current_layer;
            const int window = q4_colibri_host_object_score_window();
            if (dist >= 0 && dist <= window) {
                legacy_score += (int64_t)(window + 1 - dist) * (int64_t)near_weight;
            } else if (dist < 0) {
                legacy_score -= (int64_t)(-dist) * (int64_t)past_penalty;
            }
        }
        if (q4_colibri_host_object_score_layer_hint_enabled(marker.layer_idx)) {
            legacy_score += (int64_t)q4_colibri_host_object_score_layer_bonus();
        }
        legacy_score += (int64_t)q4_colibri_layer_score_bonus(marker.layer_idx);
        legacy_score += (int64_t)q4_colibri_static_hotness_bonus(marker);
        return legacy_score > 0 ? (uint64_t)legacy_score : 0;
    }

    const uint64_t future_weight = expert_pack_env_size(
            "GGML_MOE_Q4_OBJECT_SCORE_FUTURE_WEIGHT", 120000, 0, 1000000000ULL);
    const uint64_t next_token_weight = expert_pack_env_size(
            "GGML_MOE_Q4_OBJECT_SCORE_NEXT_TOKEN_WEIGHT", 16000, 0, 1000000000ULL);
    const uint64_t current_layer_bonus = expert_pack_env_size(
            "GGML_MOE_Q4_OBJECT_SCORE_CURRENT_BONUS", 120000, 0, 1000000000ULL);
    const uint64_t vram_bias_bonus = expert_pack_env_size(
            "GGML_MOE_Q4_OBJECT_SCORE_VRAM_BIAS_BONUS", 250000, 0, 1000000000ULL);
    const int max_layers = (int)expert_pack_env_size(
            "GGML_MOE_Q4_OBJECT_SCORE_MAX_LAYERS", 64, 1, 1024);
    const bool flow_score = q4_colibri_flow_score_cache_enabled();
    const bool full_distance_score = q4_full_distance_score_enabled();
    const bool dynamic_hotness = !flow_score || q4_colibri_flow_score_dynamic_hotness_enabled();
    int64_t score = dynamic_hotness ? (int64_t)freq * (int64_t)freq_weight : 0;
    if (current_layer >= 0 && marker.layer_idx >= 0) {
        const int dist = marker.layer_idx - current_layer;
        if (full_distance_score) {
            const uint64_t past_penalty = expert_pack_env_size(
                    "GGML_MOE_Q4_FULL_DISTANCE_PAST_PENALTY", 2000, 0, 1000000000ULL);
            if (dist == 0) {
                score += (int64_t)current_layer_bonus;
                score += (int64_t)future_weight;
            } else if (dist > 0) {
                const int clamped = std::min(dist, max_layers);
                const uint64_t numer = (uint64_t)std::max(1, max_layers + 1 - clamped);
                score += (int64_t)(future_weight * numer / (uint64_t)(max_layers + 1));
            } else {
                score -= (int64_t)(uint64_t)(-dist) * (int64_t)past_penalty;
            }
        } else if (flow_score) {
            const int layer_window = (int)expert_pack_env_size(
                    "GGML_MOE_Q4_FLOW_SCORE_LAYER_WINDOW", 8, 1, 128);
            const uint64_t past_penalty = expert_pack_env_size(
                    "GGML_MOE_Q4_FLOW_SCORE_PAST_PENALTY", 2000, 0, 1000000000ULL);
            if (dist == 0) {
                score += (int64_t)current_layer_bonus;
                score += (int64_t)future_weight;
            } else if (dist > 0 && dist <= layer_window) {
                score += (int64_t)(
                        future_weight * (uint64_t)(layer_window + 1 - dist) /
                        (uint64_t)(layer_window + 1));
            } else if (dist > 0) {
                score += (int64_t)(future_weight / (uint64_t)(dist + layer_window + 1));
            } else {
                score -= (int64_t)(uint64_t)(-dist) * (int64_t)past_penalty;
            }
        } else if (dist == 0) {
            score += (int64_t)current_layer_bonus;
            score += (int64_t)future_weight;
        } else if (dist > 0) {
            score += (int64_t)(future_weight / (uint64_t)(1 + dist));
        } else {
            const int wrapped_dist = std::max(1, max_layers + dist);
            score += (int64_t)(next_token_weight / (uint64_t)(1 + wrapped_dist));
        }
    }
    if (q4_colibri_host_object_score_layer_hint_enabled(marker.layer_idx)) {
        score += (int64_t)q4_colibri_host_object_score_layer_bonus();
    }
    if (q4_score_vram_layer_bias_env_hint_enabled(marker.layer_idx)) {
        score += (int64_t)vram_bias_bonus;
    }
    score += (int64_t)q4_colibri_layer_score_bonus(marker.layer_idx);
    score += (int64_t)q4_colibri_static_hotness_bonus(marker);
    return score > 0 ? (uint64_t)score : 0;
}

static bool q4_tier_soft_dedup_ram_vram_enabled() {
    return expert_pack_env_bool("GGML_MOE_Q4_TIER_SOFT_DEDUP_RAM_VRAM", false) ||
        expert_pack_env_bool("GGML_MOE_Q4_FLOW_SCORE_DUP_PENALTY", false);
}

static bool q4_tier_soft_dedup_require_full_vram() {
    return expert_pack_env_bool("GGML_MOE_Q4_TIER_SOFT_DEDUP_REQUIRE_FULL_VRAM", true);
}

static uint64_t q4_tier_soft_dedup_score_penalty() {
    return expert_pack_env_size("GGML_MOE_Q4_TIER_SOFT_DEDUP_SCORE_PENALTY", 1000000000ULL, 0, 1000000000000ULL);
}

static bool q4_colibri_ram_near_victim_enabled() {
    return expert_pack_env_bool("GGML_MOE_Q4_RAM_NEAR_VICTIM", false);
}

static int q4_colibri_ram_near_victim_forward_window() {
    return (int)expert_pack_env_size("GGML_MOE_Q4_RAM_NEAR_FORWARD_WINDOW", 2, 0, 128);
}

static uint32_t q4_colibri_ram_near_victim_hot_freq() {
    return (uint32_t)expert_pack_env_size("GGML_MOE_Q4_RAM_NEAR_HOT_FREQ", 2, 1, 1024);
}

static uint64_t q4_colibri_ram_near_victim_penalty() {
    return expert_pack_env_size("GGML_MOE_Q4_RAM_NEAR_VICTIM_PENALTY", 1000000000ULL, 0, 1000000000000ULL);
}

static bool q4_colibri_ram_near_victim_keep(
        const q4_colibri_host_object_slot &slot,
        int current_layer) {
    if (!q4_colibri_ram_near_victim_enabled() || !slot.ready) return true;
    if (current_layer < 0 || slot.marker.layer_idx < 0) return true;
    ++g_q4_host_object_prefetch.near_victim_candidates;

    const int dist = slot.marker.layer_idx - current_layer;
    const int window = q4_colibri_ram_near_victim_forward_window();
    if (dist >= 0 && dist <= window) {
        ++g_q4_host_object_prefetch.near_victim_protected;
        return true;
    }
    if (slot.freq >= q4_colibri_ram_near_victim_hot_freq()) {
        ++g_q4_host_object_prefetch.near_victim_protected;
        return true;
    }
    if (q4_colibri_static_hotness_bonus_raw(slot.marker) > 0) {
        ++g_q4_host_object_prefetch.near_victim_protected;
        return true;
    }
    return false;
}

static bool q4_tier_ram_object_vram_covered(const q4_colibri_object_marker &marker) {
    if (!q4_tier_soft_dedup_ram_vram_enabled()) return false;
    const int roles = q4_tier_diag_vram_roles_for_object(marker);
    return q4_tier_soft_dedup_require_full_vram() ? roles >= 3 : roles > 0;
}

static uint64_t q4_colibri_host_object_victim_score(
        const q4_colibri_host_object_slot &slot,
        int current_layer,
        bool use_stored_score) {
    uint64_t score = use_stored_score ? slot.score :
        q4_colibri_host_object_score(slot.marker, current_layer, slot.freq);
    if (slot.ready && q4_tier_ram_object_vram_covered(slot.marker)) {
        ++g_q4_tier_overlap_diag.tier_soft_dedup_victim_candidates;
        const uint64_t penalty = q4_tier_soft_dedup_score_penalty();
        score = score > penalty ? score - penalty : 0;
    }
    if (!q4_colibri_ram_near_victim_keep(slot, current_layer)) {
        ++g_q4_host_object_prefetch.near_victim_penalized;
        const uint64_t penalty = q4_colibri_ram_near_victim_penalty();
        score = score > penalty ? score - penalty : 0;
    }
    return score;
}

struct q4_host_slot_selection_context {
    int incoming_layer = -1;
    size_t incoming_occupancy = 0;
    size_t incoming_quota = 0;
    int victim_score_layer = -1;
    bool budget_pressure = false;
    bool use_stored_score = false;
};

static ggml_moe_common::object_host_slot_candidate_state q4_host_classify_slot(
        ggml_moe_common::object_host_cache &cache,
        size_t slot_index,
        void *opaque) {
    q4_host_slot_selection_context &context =
        *static_cast<q4_host_slot_selection_context *>(opaque);
    q4_colibri_host_object_slot &slot = cache.slots[slot_index];
    if (slot.loading || slot.in_use || slot.pending_h2d || slot.pending_d2h ||
            (context.budget_pressure && !slot.ready) ||
            !q4_colibri_host_object_quota_victim_allowed_locked(
                slot,
                context.incoming_layer,
                context.incoming_occupancy,
                context.incoming_quota)) {
        return ggml_moe_common::object_host_slot_candidate_state::excluded;
    }
    return slot.ready ?
        ggml_moe_common::object_host_slot_candidate_state::resident :
        ggml_moe_common::object_host_slot_candidate_state::empty;
}

static uint64_t q4_host_slot_score(
        const ggml_moe_common::object_host_cache &cache,
        size_t slot_index,
        void *opaque) {
    const q4_host_slot_selection_context &context =
        *static_cast<const q4_host_slot_selection_context *>(opaque);
    return q4_colibri_host_object_victim_score(
        cache.slots[slot_index],
        context.victim_score_layer,
        context.use_stored_score);
}

static bool q4_object_score_profile_enabled() {
    return expert_pack_env_bool("GGML_MOE_Q4_OBJECT_SCORE_PROFILE", false);
}

static void q4_score_profile_add_layer(
        std::atomic<uint64_t> (&counters)[128],
        int layer,
        uint64_t value = 1) {
    if (value == 0 || layer < 0 || layer >= 128) return;
    counters[layer].fetch_add(value, std::memory_order_relaxed);
}

static void q4_score_profile_record_ram_candidate(
        int layer,
        uint64_t candidate_score,
        uint64_t victim_score,
        bool has_victim,
        bool admitted) {
    if (!q4_object_score_profile_enabled()) return;
    ++g_q4_tier_overlap_diag.score_profile_ram_candidates;
    g_q4_tier_overlap_diag.score_profile_ram_candidate_score_sum.fetch_add(
            candidate_score, std::memory_order_relaxed);
    q4_score_profile_add_layer(g_q4_tier_overlap_diag.score_profile_layer_ram_candidates, layer);
    q4_score_profile_add_layer(
            g_q4_tier_overlap_diag.score_profile_layer_ram_candidate_score_sum,
            layer,
            candidate_score);
    if (admitted) {
        ++g_q4_tier_overlap_diag.score_profile_ram_admitted;
        q4_score_profile_add_layer(g_q4_tier_overlap_diag.score_profile_layer_ram_admitted, layer);
    } else {
        ++g_q4_tier_overlap_diag.score_profile_ram_rejected;
        q4_score_profile_add_layer(g_q4_tier_overlap_diag.score_profile_layer_ram_rejected, layer);
    }
    if (!has_victim) {
        ++g_q4_tier_overlap_diag.score_profile_ram_empty_slot;
        q4_score_profile_add_layer(g_q4_tier_overlap_diag.score_profile_layer_ram_empty_slot, layer);
        return;
    }
    ++g_q4_tier_overlap_diag.score_profile_ram_victim_events;
    g_q4_tier_overlap_diag.score_profile_ram_victim_score_sum.fetch_add(
            victim_score, std::memory_order_relaxed);
    q4_score_profile_add_layer(g_q4_tier_overlap_diag.score_profile_layer_ram_victim_events, layer);
    q4_score_profile_add_layer(
            g_q4_tier_overlap_diag.score_profile_layer_ram_victim_score_sum,
            layer,
            victim_score);
    if (candidate_score > victim_score) {
        ++g_q4_tier_overlap_diag.score_profile_ram_candidate_gt_victim;
        q4_score_profile_add_layer(g_q4_tier_overlap_diag.score_profile_layer_ram_candidate_gt_victim, layer);
    } else if (candidate_score == victim_score) {
        ++g_q4_tier_overlap_diag.score_profile_ram_candidate_eq_victim;
        q4_score_profile_add_layer(g_q4_tier_overlap_diag.score_profile_layer_ram_candidate_eq_victim, layer);
    } else {
        ++g_q4_tier_overlap_diag.score_profile_ram_candidate_lt_victim;
        q4_score_profile_add_layer(g_q4_tier_overlap_diag.score_profile_layer_ram_candidate_lt_victim, layer);
    }
}

static void q4_score_profile_record_vram_eviction(
        int candidate_layer,
        uint64_t candidate_score,
        uint64_t victim_score) {
    if (!q4_object_score_profile_enabled()) return;
    ++g_q4_tier_overlap_diag.score_profile_vram_evictions;
    g_q4_tier_overlap_diag.score_profile_vram_candidate_score_sum.fetch_add(
            candidate_score, std::memory_order_relaxed);
    g_q4_tier_overlap_diag.score_profile_vram_victim_score_sum.fetch_add(
            victim_score, std::memory_order_relaxed);
    q4_score_profile_add_layer(g_q4_tier_overlap_diag.score_profile_layer_vram_evictions, candidate_layer);
    q4_score_profile_add_layer(
            g_q4_tier_overlap_diag.score_profile_layer_vram_candidate_score_sum,
            candidate_layer,
            candidate_score);
    q4_score_profile_add_layer(
            g_q4_tier_overlap_diag.score_profile_layer_vram_victim_score_sum,
            candidate_layer,
            victim_score);
    if (candidate_score > victim_score) {
        ++g_q4_tier_overlap_diag.score_profile_vram_candidate_gt_victim;
        q4_score_profile_add_layer(g_q4_tier_overlap_diag.score_profile_layer_vram_candidate_gt_victim, candidate_layer);
    } else if (candidate_score == victim_score) {
        ++g_q4_tier_overlap_diag.score_profile_vram_candidate_eq_victim;
        q4_score_profile_add_layer(g_q4_tier_overlap_diag.score_profile_layer_vram_candidate_eq_victim, candidate_layer);
    } else {
        ++g_q4_tier_overlap_diag.score_profile_vram_candidate_lt_victim;
        q4_score_profile_add_layer(g_q4_tier_overlap_diag.score_profile_layer_vram_candidate_lt_victim, candidate_layer);
    }
}

static void q4_tier_record_ram_slot_eviction(const q4_colibri_host_object_slot &slot) {
    if (slot.ready && q4_tier_ram_object_vram_covered(slot.marker)) {
        ++g_q4_tier_overlap_diag.tier_soft_dedup_evictions;
    }
}

static void q4_colibri_host_object_sweep_completed_deletes_locked();
static void q4_colibri_host_object_sweep_completed_d2h_locked();
static bool q4_colibri_host_object_clear_slot_locked(size_t slot_idx, bool count_delete);
static void q4_colibri_host_object_prefetch_shutdown_and_report();

static bool q4_colibri_host_object_prefetch_init_locked() {
    if (g_q4_host_object_prefetch.inited) return g_q4_host_object_prefetch.enabled;
    g_q4_host_object_prefetch.inited = true;
    g_q4_host_object_prefetch.enabled = q4_colibri_host_object_prefetch_enabled();
    if (!g_q4_host_object_prefetch.enabled) return false;
    g_q4_host_object_prefetch.max_slots = q4_colibri_host_object_prefetch_slots();
    g_q4_host_object_prefetch.max_resident_bytes = q4_colibri_host_object_prefetch_max_bytes();
    g_q4_host_object_prefetch.slots.resize(g_q4_host_object_prefetch.max_slots);
    if (!ggml_moe_common::object_host_cache_configure_ownership(
                g_q4_host_object_prefetch, 0)) {
        g_q4_host_object_prefetch.enabled = false;
        return false;
    }
    g_q4_host_object_prefetch.worker = std::thread([]() {
        expert_pack_apply_current_thread_affinity(
                "GGML_MOE_Q4_HOST_OBJECT_CPUSET", "q4_host_cache");
        const bool common_object_staging = common_object_staging_enabled();
        for (;;) {
            q4_colibri_host_object_request req;
            size_t slot_idx = SIZE_MAX;
            size_t allocation_bytes = 0;
            std::string req_key;
            ggml_moe_common::object_host_staging_transaction staging;
            {
                std::unique_lock<std::mutex> lock(g_q4_host_object_prefetch.mu);
                g_q4_host_object_prefetch.cv.wait(lock, []() {
                    return g_q4_host_object_prefetch.stop || !g_q4_host_object_prefetch.queue.empty();
                });
                if (g_q4_host_object_prefetch.stop && g_q4_host_object_prefetch.queue.empty()) break;
                req = g_q4_host_object_prefetch.queue.front();
                g_q4_host_object_prefetch.queue.pop_front();
                allocation_bytes = q4_colibri_host_object_allocation_bytes(
                    req.payload_format, req.marker.bytes);
                req_key = q4_colibri_host_object_key(req.marker);
                g_q4_host_object_prefetch.queued.erase(req_key);

                for (size_t i = 0; i < g_q4_host_object_prefetch.slots.size(); ++i) {
                    q4_colibri_host_object_slot &slot = g_q4_host_object_prefetch.slots[i];
                    if (!slot.loading && !slot.in_use && !slot.ready && !slot.pending_h2d && !slot.pending_d2h) {
                        slot_idx = i;
                        break;
                    }
                }
                bool budget_pressure = false;
                if (slot_idx != SIZE_MAX && q4_colibri_host_object_budget_enabled_locked() &&
                        !q4_colibri_host_object_budget_fits_locked(
                            g_q4_host_object_prefetch.slots[slot_idx], allocation_bytes)) {
                    budget_pressure = true;
                    slot_idx = SIZE_MAX;
                }
                const bool quota_enabled = q4_colibri_host_object_layer_quota_enabled();
                const size_t incoming_quota = q4_colibri_host_object_layer_quota(req.marker.layer_idx);
                const size_t incoming_occupancy = quota_enabled ?
                    q4_colibri_host_object_layer_occupancy_locked(req.marker.layer_idx) : 0;
                if (quota_enabled && incoming_occupancy >= incoming_quota) {
                    slot_idx = SIZE_MAX;
                }
                q4_colibri_host_object_sweep_completed_deletes_locked();
                q4_colibri_host_object_sweep_completed_d2h_locked();
                const bool score_policy = q4_colibri_host_object_score_policy_enabled();
                const bool score_profile = q4_object_score_profile_enabled();
                const int victim_score_layer = q4_colibri_host_object_victim_score_layer(req.marker.layer_idx);
                uint32_t freq = 0;
                uint64_t candidate_score = 0;
                if (score_policy || score_profile) {
                    const std::string req_key_for_score = q4_colibri_host_object_key(req.marker);
                    freq = g_q4_host_object_prefetch.request_freq[req_key_for_score] + 1;
                    candidate_score = q4_colibri_host_object_score(
                            req.marker,
                            q4_colibri_host_object_candidate_score_layer(req.marker.layer_idx),
                            freq);
                }
                uint64_t selected_victim_score = 0;
                bool selected_has_victim = false;
                if (slot_idx == SIZE_MAX) {
                    q4_host_slot_selection_context context;
                    context.incoming_layer = req.marker.layer_idx;
                    context.incoming_occupancy = incoming_occupancy;
                    context.incoming_quota = incoming_quota;
                    context.victim_score_layer = victim_score_layer;
                    context.budget_pressure = budget_pressure;
                    ggml_moe_common::object_host_slot_selection selection;
                    ggml_moe_common::object_host_slot_selection_policy policy;
                    policy.prefer_empty = false;
                    policy.evaluate_score = score_policy || score_profile;
                    policy.select_by_score = score_policy;
                    if (ggml_moe_common::object_host_cache_select_slot(
                                g_q4_host_object_prefetch,
                                policy,
                                q4_host_classify_slot,
                                q4_host_slot_score,
                                &context,
                                selection)) {
                        slot_idx = selection.slot_index;
                        selected_has_victim = !selection.empty;
                        selected_victim_score = selection.score;
                    }
                }
                if (slot_idx == SIZE_MAX) {
                    q4_score_profile_record_ram_candidate(
                            req.marker.layer_idx, candidate_score, 0, false, false);
                    if (quota_enabled) {
                        ++g_q4_host_object_prefetch.layer_quota_protected;
                    }
                    ++g_q4_host_object_prefetch.no_slot;
                    continue;
                }
                q4_colibri_host_object_slot &slot = g_q4_host_object_prefetch.slots[slot_idx];
                if (!q4_colibri_host_object_budget_fits_locked(slot, allocation_bytes)) {
                    q4_score_profile_record_ram_candidate(
                            req.marker.layer_idx, candidate_score, selected_victim_score, selected_has_victim, false);
                    ++g_q4_host_object_prefetch.budget_skips;
                    continue;
                }
                bool reject_score_victim = false;
                if (score_policy && selected_has_victim) {
                    ggml_moe_common::object_host_admission_policy admission;
                    admission.victim_margin =
                        q4_colibri_host_object_score_admit_margin_for_layer(req.marker.layer_idx);
                    admission.compare_victim = admission.victim_margin > 0;
                    reject_score_victim =
                        ggml_moe_common::object_host_cache_evaluate_admission(
                            admission,
                            freq,
                            candidate_score,
                            true,
                            selected_victim_score) ==
                        ggml_moe_common::object_host_admission_decision::reject_victim;
                }
                if (reject_score_victim) {
                    ++g_q4_host_object_prefetch.score_protected_victims;
                    ++g_q4_host_object_prefetch.score_admit_skips;
                    q4_score_profile_record_ram_candidate(
                            req.marker.layer_idx, candidate_score, selected_victim_score, selected_has_victim, false);
                    continue;
                }
                if (budget_pressure) {
                    ++g_q4_host_object_prefetch.budget_pressure_evictions;
                }
                auto record_victim = [&]() {
                    if (!slot.ready) return;
                    if (!selected_has_victim) {
                        selected_has_victim = true;
                        selected_victim_score = score_profile ?
                            q4_colibri_host_object_victim_score(slot, victim_score_layer, false) : 0;
                    }
                    q4_tier_record_ram_slot_eviction(slot);
                    q4_tier_diag_record_ram_eviction(slot.marker);
                    if (quota_enabled) {
                        ++g_q4_host_object_prefetch.layer_quota_evictions;
                    }
                    ++g_q4_host_object_prefetch.evictions;
                    if (score_policy) {
                        ++g_q4_host_object_prefetch.score_evictions;
                    }
                };
                if (common_object_staging) {
                    record_victim();
                    if (!ggml_moe_common::object_host_cache_begin_staging(
                                g_q4_host_object_prefetch, slot_idx, req.marker, staging,
                                allocation_bytes)) {
                        ++g_q4_host_object_prefetch.no_slot;
                        continue;
                    }
                } else {
                    if (!ggml_moe_common::object_host_cache_prepare_slot(
                                g_q4_host_object_prefetch, slot_idx)) {
                        ++g_q4_host_object_prefetch.no_slot;
                        continue;
                    }
                    record_victim();
                    slot.ready = false;
                    slot.loading = true;
                    slot.in_use = false;
                    slot.pending_h2d = false;
                    slot.h2d_recorded = false;
                    slot.pending_d2h = false;
                    slot.delete_after_h2d = false;
                    slot.marker = req.marker;
                }
                slot.pilot_submitted = req.pilot_submitted;
                slot.origin = req.pilot_submitted ?
                    Q4_HOST_OBJECT_ORIGIN_PILOT : Q4_HOST_OBJECT_ORIGIN_PREFETCH;
                slot.read_us = 0;
                slot.payload_format = req.payload_format;
                slot.payload_bytes = req.payload_bytes;
                slot.payload_transport_bytes = req.payload_transport_bytes;
                slot.payload_crc32 = req.payload_crc32;
                slot.payload_record_identity = req.payload_record_identity;
                q4_score_profile_record_ram_candidate(
                        req.marker.layer_idx,
                        candidate_score,
                        selected_victim_score,
                        selected_has_victim,
                        true);
            }

            q4_colibri_host_object_slot *slot_ptr = &g_q4_host_object_prefetch.slots[slot_idx];
            if (slot_ptr->capacity < allocation_bytes) {
                if (slot_ptr->host) {
                    {
                        std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
                        q4_colibri_host_object_account_free_locked(*slot_ptr);
                    }
                    q4_colibri_host_object_free(*slot_ptr);
                }
                if (!q4_colibri_host_object_alloc(*slot_ptr, allocation_bytes)) {
                    std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
                    if (common_object_staging) {
                        (void)ggml_moe_common::object_host_cache_abort_staging(
                            g_q4_host_object_prefetch, staging);
                    } else {
                        slot_ptr->loading = false;
                        slot_ptr->marker = {};
                    }
                    slot_ptr->pilot_submitted = false;
                    slot_ptr->origin = Q4_HOST_OBJECT_ORIGIN_UNKNOWN;
                    ++g_q4_host_object_prefetch.alloc_failures;
                    continue;
                }
                {
                    std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
                    q4_colibri_host_object_account_alloc_locked(
                        *slot_ptr, allocation_bytes);
                }
            }

            bool read_ok = false;
            uint64_t read_us = 0;
            expert_pack_source *request_source = nullptr;
            if (req.payload_format == ggml_moe_common::object_host_payload_format::lossless_sidecar) {
                request_source = &g_expert_pack.lossless_source;
            } else if (req.source_idx >= 0 && (size_t)req.source_idx < g_expert_pack.sources.size()) {
                request_source = &g_expert_pack.sources[(size_t)req.source_idx];
            }
            if (request_source) {
                expert_pack_source &source = *request_source;
                if (source.fd_direct >= 0 && source.direct_required && !source.page_cache) {
                    const auto read_start = std::chrono::steady_clock::now();
                    read_ok = expert_pack_direct_pread_all(source.fd_direct, slot_ptr->host, req.bytes, req.offset);
                    read_us = (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
                            std::chrono::steady_clock::now() - read_start).count();
                    if (!common_object_staging) slot_ptr->read_us = read_us;
                }
            }

            {
                std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
                if (read_ok) {
                    const bool published = common_object_staging ?
                        ggml_moe_common::object_host_cache_publish_staging(
                            g_q4_host_object_prefetch, staging, read_us) :
                        (slot_ptr->loading = false,
                         ggml_moe_common::object_host_cache_publish_slot(
                            g_q4_host_object_prefetch, slot_idx));
                    if (!published) {
                        if (common_object_staging && staging.active) {
                            (void)ggml_moe_common::object_host_cache_abort_staging(
                                g_q4_host_object_prefetch, staging);
                        } else {
                            slot_ptr->marker = {};
                        }
                        slot_ptr->pilot_submitted = false;
                        slot_ptr->origin = Q4_HOST_OBJECT_ORIGIN_UNKNOWN;
                        ++g_q4_host_object_prefetch.read_failures;
                        continue;
                    }
                    const std::string ready_key = q4_colibri_host_object_key(slot_ptr->marker);
                    uint32_t freq = ++g_q4_host_object_prefetch.request_freq[ready_key];
                    if (!common_object_staging) slot_ptr->ready = true;
                    slot_ptr->used = g_q4_host_object_prefetch.clock++;
                    slot_ptr->freq = freq;
                    slot_ptr->score = q4_colibri_host_object_score(
                            slot_ptr->marker,
                            q4_colibri_host_object_score_current_layer(slot_ptr->marker.layer_idx),
                            freq);
                    ++g_q4_host_object_prefetch.completed;
                    g_q4_host_object_prefetch.bytes_read.fetch_add(req.bytes, std::memory_order_relaxed);
                    if (req.payload_format == ggml_moe_common::object_host_payload_format::lossless_sidecar) {
                        ++g_expert_pack.lossless_host_cache_admissions;
                    }
                } else {
                    if (common_object_staging) {
                        (void)ggml_moe_common::object_host_cache_abort_staging(
                            g_q4_host_object_prefetch, staging);
                    } else {
                        slot_ptr->loading = false;
                        slot_ptr->marker = {};
                    }
                    slot_ptr->pilot_submitted = false;
                    slot_ptr->origin = Q4_HOST_OBJECT_ORIGIN_UNKNOWN;
                    ++g_q4_host_object_prefetch.read_failures;
                }
            }
        }
    });
    const size_t pinned_prefix = std::min(
            q4_colibri_host_object_pinned_prefix_slots(),
            g_q4_host_object_prefetch.max_slots);
    std::fprintf(stderr,
            "[moe_stream_batch] q4 host object prefetch: enabled slots=%zu queue_limit=%zu "
            "pageable=%d pinned_prefix_slots=%zu pageable_tail_slots=%zu\n",
            g_q4_host_object_prefetch.max_slots,
            q4_colibri_host_object_prefetch_queue_limit(),
            q4_colibri_host_object_pageable_enabled() ? 1 : 0,
            pinned_prefix,
            pinned_prefix > 0 ? g_q4_host_object_prefetch.max_slots - pinned_prefix : 0);
    std::atexit(q4_colibri_host_object_prefetch_shutdown_and_report);
    return true;
}

static bool q4_colibri_host_object_prefetch_submit(
        const q4_colibri_object_marker &marker,
        int32_t source_idx,
        uint64_t offset,
        size_t bytes,
        bool pilot_submitted = false) {
    if (!q4_colibri_host_object_prefetch_enabled() || bytes == 0) return false;
    if (!q4_colibri_host_object_layer_quota_admit_allowed(marker.layer_idx)) {
        ++g_q4_host_object_prefetch.layer_quota_rejects;
        return false;
    }
    std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
    if (!q4_colibri_host_object_prefetch_init_locked()) return false;
    const std::string key = q4_colibri_host_object_key(marker);
    if (q4_colibri_host_object_find_ready_locked(marker) ||
            g_q4_host_object_prefetch.queued.find(key) != g_q4_host_object_prefetch.queued.end()) {
        ++g_q4_host_object_prefetch.duplicate_skips;
        return false;
    }
    const size_t queue_limit = q4_colibri_host_object_prefetch_queue_limit();
    if (g_q4_host_object_prefetch.queue.size() >= queue_limit) {
        ++g_q4_host_object_prefetch.queue_full;
        ++g_expert_pack.q4_pilot_prefetch_queue_full;
        return false;
    }
    q4_colibri_host_object_request req;
    req.marker = marker;
    req.source_idx = source_idx;
    req.offset = offset;
    req.bytes = bytes;
    req.payload_bytes = bytes;
    req.payload_transport_bytes = bytes;
    if (g_expert_pack.lossless_mode == q4_lossless_transport_mode::cuda) {
        const ggml_moe_common::lossless_object_record *record =
            ggml_moe_common::lossless_sidecar_find(
                g_expert_pack.lossless_sidecar,
                marker.layer_idx,
                marker.expert_idx);
        if (record && record->raw_bytes == marker.bytes &&
                record->payload_bytes <= marker.bytes) {
            req.offset = record->file_offset;
            req.bytes = static_cast<size_t>(record->physical_bytes);
            req.payload_bytes = static_cast<size_t>(record->payload_bytes);
            req.payload_transport_bytes = static_cast<size_t>(record->physical_bytes);
            req.payload_crc32 = record->payload_crc32;
            req.payload_record_identity = record->file_offset;
            req.payload_format = ggml_moe_common::object_host_payload_format::lossless_sidecar;
        } else if (g_expert_pack.lossless_standalone) {
            q4_colibri_fail(
                "standalone lossless prefetch has no complete sidecar object");
        }
    }
    req.pilot_submitted = pilot_submitted;
    g_q4_host_object_prefetch.queue.push_back(req);
    g_q4_host_object_prefetch.queued.insert(key);
    ++g_q4_host_object_prefetch.submitted;
    if (pilot_submitted) {
        ++g_expert_pack.q4_pilot_prefetch_precision_submitted_objects;
        g_expert_pack.q4_pilot_prefetch_precision_submitted_bytes.fetch_add(bytes, std::memory_order_relaxed);
        if (marker.layer_idx >= 0 && marker.layer_idx < 128) {
            ++g_expert_pack.q4_pilot_prefetch_precision_layer_submitted_objects[marker.layer_idx];
            g_expert_pack.q4_pilot_prefetch_precision_layer_submitted_bytes[marker.layer_idx].fetch_add(
                    bytes, std::memory_order_relaxed);
        }
    }
    g_q4_host_object_prefetch.cv.notify_one();
    return true;
}

static bool q4_colibri_host_object_prefetch_admit_from_read(
        const q4_colibri_object_marker &marker,
        const void *host_src,
        size_t payload_bytes,
        uint64_t read_us,
        ggml_moe_common::object_host_payload_format payload_format =
            ggml_moe_common::object_host_payload_format::raw_object,
        size_t payload_transport_bytes = 0,
        uint32_t payload_crc32 = 0,
        uint64_t payload_record_identity = 0) {
    const size_t allocation_bytes = q4_colibri_host_object_allocation_bytes(
        payload_format, marker.bytes);
    if (payload_transport_bytes == 0) payload_transport_bytes = payload_bytes;
    if (!q4_colibri_host_object_admit_on_read_enabled() ||
            !q4_colibri_host_object_prefetch_enabled() || !host_src ||
            payload_bytes == 0 || allocation_bytes == 0 ||
            payload_bytes > allocation_bytes) {
        return false;
    }
    const uint64_t min_read_us = q4_colibri_host_object_admit_min_read_us();
    if (min_read_us > 0 && read_us < min_read_us) {
        ++g_q4_host_object_prefetch.read_admit_min_read_us_skips;
        g_q4_host_object_prefetch.read_admit_min_read_us_skip_sum.fetch_add(read_us, std::memory_order_relaxed);
        return false;
    }
    const bool eligible_layer_profile = q4_colibri_eligible_layer_profile_enabled();
    const bool eligible_layer = eligible_layer_profile ?
        q4_colibri_host_object_ram_eligible_layer(marker.layer_idx) : false;
    if (!q4_colibri_host_object_admit_layer_allowed(marker.layer_idx)) {
        if (eligible_layer_profile) {
            ++g_q4_host_object_prefetch.ineligible_layer_read_rejects;
        }
        return false;
    }
    if (!q4_colibri_ram_net_layer_allowed(marker.layer_idx)) {
        if (eligible_layer_profile) {
            ++g_q4_host_object_prefetch.ineligible_layer_read_rejects;
        }
        ++g_q4_host_object_prefetch.ram_net_read_rejects;
        return false;
    }
    if (q4_colibri_recurrence_read_admission_enabled()) {
        uint64_t eviction_age = 0;
        if (!q4_tier_diag_vram_evicted_age_snapshot(marker, &eviction_age)) {
            ++g_q4_host_object_prefetch.recurrence_read_rejects;
            return false;
        }
        if (eviction_age > (uint64_t)q4_colibri_recurrence_read_admission_max_age_tokens()) {
            ++g_q4_host_object_prefetch.recurrence_read_rejects;
            ++g_q4_host_object_prefetch.recurrence_read_rejects_age;
            return false;
        }
        ++g_q4_host_object_prefetch.recurrence_read_admits;
    }
    if (!q4_colibri_host_object_layer_quota_admit_allowed(marker.layer_idx)) {
        if (eligible_layer_profile) {
            ++g_q4_host_object_prefetch.ineligible_layer_read_rejects;
        }
        ++g_q4_host_object_prefetch.layer_quota_rejects;
        return false;
    }
    if (!q4_colibri_host_object_admit_pair_allowed(marker.layer_idx, marker.expert_idx)) {
        return false;
    }

    std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
    if (!q4_colibri_host_object_prefetch_init_locked()) return false;
    const std::string key = q4_colibri_host_object_key(marker);
    const bool score_policy = q4_colibri_host_object_score_policy_enabled();
    const bool score_profile = q4_object_score_profile_enabled();
    uint32_t freq = 0;
    if (score_policy || score_profile) {
        freq = ++g_q4_host_object_prefetch.request_freq[key];
        ggml_moe_common::object_host_admission_policy admission;
        admission.min_frequency = score_policy ?
            q4_colibri_host_object_score_admit_min_freq() : 0;
        if (score_policy && ggml_moe_common::object_host_cache_evaluate_admission(
                    admission, freq, 0, false, 0) ==
                ggml_moe_common::object_host_admission_decision::reject_frequency) {
            ++g_q4_host_object_prefetch.score_admit_skips;
            q4_score_profile_record_ram_candidate(marker.layer_idx, 0, 0, false, false);
            return false;
        }
    }
    if (q4_colibri_host_object_find_ready_locked(marker) ||
            g_q4_host_object_prefetch.queued.find(key) != g_q4_host_object_prefetch.queued.end()) {
        ++g_q4_host_object_prefetch.duplicate_skips;
        return false;
    }

    q4_colibri_host_object_sweep_completed_deletes_locked();
    q4_colibri_host_object_sweep_completed_d2h_locked();
    size_t slot_idx = SIZE_MAX;
    bool used_empty_slot = false;
    for (size_t i = 0; i < g_q4_host_object_prefetch.slots.size(); ++i) {
        q4_colibri_host_object_slot &slot = g_q4_host_object_prefetch.slots[i];
        if (!slot.loading && !slot.in_use && !slot.ready && !slot.pending_h2d && !slot.pending_d2h) {
            slot_idx = i;
            used_empty_slot = true;
            break;
        }
    }
    bool budget_pressure = false;
    if (slot_idx != SIZE_MAX && q4_colibri_host_object_budget_enabled_locked() &&
            !q4_colibri_host_object_budget_fits_locked(
                g_q4_host_object_prefetch.slots[slot_idx], allocation_bytes)) {
        budget_pressure = true;
        slot_idx = SIZE_MAX;
    }
    const bool quota_enabled = q4_colibri_host_object_layer_quota_enabled();
    const size_t incoming_quota = q4_colibri_host_object_layer_quota(marker.layer_idx);
    const size_t incoming_occupancy = quota_enabled ?
        q4_colibri_host_object_layer_occupancy_locked(marker.layer_idx) : 0;
    if (quota_enabled && incoming_occupancy >= incoming_quota) {
        slot_idx = SIZE_MAX;
    }
    const int victim_score_layer = q4_colibri_host_object_victim_score_layer(marker.layer_idx);
    const uint64_t candidate_score = (score_policy || score_profile) ?
        q4_colibri_host_object_score(
                marker,
                q4_colibri_host_object_candidate_score_layer(marker.layer_idx),
                freq) : 0;
    ggml_moe_common::object_host_admission_policy score_admission;
    score_admission.min_score = score_policy && q4_colibri_flow_score_cache_enabled() ?
        q4_colibri_flow_score_min_admit() : 0;
    if (score_policy && q4_colibri_flow_score_cache_enabled() &&
            ggml_moe_common::object_host_cache_evaluate_admission(
                score_admission, freq, candidate_score, false, 0) ==
            ggml_moe_common::object_host_admission_decision::reject_score) {
        ++g_q4_host_object_prefetch.score_admit_skips;
        q4_score_profile_record_ram_candidate(marker.layer_idx, candidate_score, 0, false, false);
        return false;
    }
    uint64_t selected_victim_score = 0;
    bool selected_has_victim = false;
    if (slot_idx == SIZE_MAX) {
        q4_host_slot_selection_context context;
        context.incoming_layer = marker.layer_idx;
        context.incoming_occupancy = incoming_occupancy;
        context.incoming_quota = incoming_quota;
        context.victim_score_layer = victim_score_layer;
        context.budget_pressure = budget_pressure;
        context.use_stored_score = score_policy &&
            q4_colibri_host_object_compare_stored_score_enabled() &&
            !q4_colibri_host_object_score_dynamic_current_enabled();
        ggml_moe_common::object_host_slot_selection selection;
        ggml_moe_common::object_host_slot_selection_policy policy;
        policy.prefer_empty = false;
        policy.evaluate_score = score_policy || score_profile;
        policy.select_by_score = score_policy;
        if (ggml_moe_common::object_host_cache_select_slot(
                    g_q4_host_object_prefetch,
                    policy,
                    q4_host_classify_slot,
                    q4_host_slot_score,
                    &context,
                    selection)) {
            slot_idx = selection.slot_index;
            selected_has_victim = !selection.empty;
            selected_victim_score = selection.score;
        }
        if ((score_policy || score_profile) && slot_idx != SIZE_MAX) {
            ++g_q4_host_object_prefetch.score_read_eviction_candidates;
            if (candidate_score > selected_victim_score) {
                ++g_q4_host_object_prefetch.score_read_candidate_gt_victim;
            } else if (candidate_score == selected_victim_score) {
                ++g_q4_host_object_prefetch.score_read_candidate_eq_victim;
            } else {
                ++g_q4_host_object_prefetch.score_read_candidate_lt_victim;
            }
        }
        ggml_moe_common::object_host_admission_policy victim_admission;
        victim_admission.compare_victim = score_policy;
        victim_admission.victim_margin =
            q4_colibri_host_object_score_admit_margin_for_layer(marker.layer_idx);
        if (score_policy && slot_idx != SIZE_MAX &&
                ggml_moe_common::object_host_cache_evaluate_admission(
                    victim_admission,
                    freq,
                    candidate_score,
                    true,
                    selected_victim_score) ==
                ggml_moe_common::object_host_admission_decision::reject_victim) {
            ++g_q4_host_object_prefetch.score_protected_victims;
            ++g_q4_host_object_prefetch.score_admit_skips;
            q4_score_profile_record_ram_candidate(
                    marker.layer_idx, candidate_score, selected_victim_score, selected_has_victim, false);
            return false;
        }
    }
    if (slot_idx == SIZE_MAX) {
        if (quota_enabled) {
            ++g_q4_host_object_prefetch.layer_quota_protected;
        }
        ++g_q4_host_object_prefetch.no_slot;
        q4_score_profile_record_ram_candidate(marker.layer_idx, candidate_score, 0, false, false);
        return false;
    }

    q4_colibri_host_object_slot &slot = g_q4_host_object_prefetch.slots[slot_idx];
    if (!q4_colibri_host_object_budget_fits_locked(slot, allocation_bytes)) {
        ++g_q4_host_object_prefetch.budget_skips;
        q4_score_profile_record_ram_candidate(
                marker.layer_idx, candidate_score, selected_victim_score, selected_has_victim, false);
        return false;
    }
    if (budget_pressure) {
        ++g_q4_host_object_prefetch.budget_pressure_evictions;
    }
    const bool common_object_staging = common_object_staging_enabled();
    ggml_moe_common::object_host_staging_transaction staging;
    auto record_victim = [&]() {
        if (!slot.ready) return;
        q4_tier_record_ram_slot_eviction(slot);
        q4_tier_diag_record_ram_eviction(slot.marker);
        if (quota_enabled) {
            ++g_q4_host_object_prefetch.layer_quota_evictions;
        }
        ++g_q4_host_object_prefetch.evictions;
        ++g_expert_pack.q4_host_object_read_admit_evictions;
        if (score_policy) {
            ++g_q4_host_object_prefetch.score_evictions;
        }
    };
    if (common_object_staging) {
        record_victim();
        if (!ggml_moe_common::object_host_cache_begin_staging(
                    g_q4_host_object_prefetch, slot_idx, marker, staging,
                    allocation_bytes)) {
            ++g_q4_host_object_prefetch.no_slot;
            return false;
        }
    } else {
        if (!ggml_moe_common::object_host_cache_prepare_slot(g_q4_host_object_prefetch, slot_idx)) {
            ++g_q4_host_object_prefetch.no_slot;
            return false;
        }
        record_victim();
    }
    if (slot.capacity < allocation_bytes) {
        if (slot.host) {
            q4_colibri_host_object_account_free_locked(slot);
            q4_colibri_host_object_free(slot);
        }
        if (!q4_colibri_host_object_alloc(slot, allocation_bytes)) {
            if (common_object_staging) {
                (void)ggml_moe_common::object_host_cache_abort_staging(
                    g_q4_host_object_prefetch, staging);
            }
            ++g_q4_host_object_prefetch.alloc_failures;
            ++g_expert_pack.q4_host_object_read_admit_alloc_failures;
            return false;
        }
        q4_colibri_host_object_account_alloc_locked(slot, allocation_bytes);
    }

    std::memcpy(slot.host, host_src, payload_bytes);
    if (!common_object_staging) {
        slot.marker = marker;
        slot.ready = true;
        slot.loading = false;
        slot.in_use = false;
        slot.pending_h2d = false;
        slot.h2d_recorded = false;
        slot.pending_d2h = false;
        slot.delete_after_h2d = false;
    }
    slot.pilot_submitted = false;
    slot.origin = Q4_HOST_OBJECT_ORIGIN_READ_ADMIT;
    slot.payload_format = payload_format;
    slot.payload_bytes = payload_bytes;
    slot.payload_transport_bytes = payload_transport_bytes;
    slot.payload_crc32 = payload_crc32;
    slot.payload_record_identity = payload_record_identity;
    slot.used = g_q4_host_object_prefetch.clock++;
    slot.freq = (score_policy || score_profile) ? freq : 0;
    slot.score = q4_colibri_host_object_score(
            marker,
            q4_colibri_host_object_score_current_layer(marker.layer_idx),
            slot.freq);
    const bool published = common_object_staging ?
        ggml_moe_common::object_host_cache_publish_staging(
            g_q4_host_object_prefetch, staging, read_us) :
        (slot.read_us = read_us,
         ggml_moe_common::object_host_cache_publish_slot(g_q4_host_object_prefetch, slot_idx));
    if (!published) {
        if (common_object_staging && staging.active) {
            (void)ggml_moe_common::object_host_cache_abort_staging(
                g_q4_host_object_prefetch, staging);
        } else {
            (void)q4_colibri_host_object_clear_slot_locked(slot_idx, false);
        }
        slot.pilot_submitted = false;
        slot.origin = Q4_HOST_OBJECT_ORIGIN_UNKNOWN;
        ++g_q4_host_object_prefetch.read_failures;
        return false;
    }
    if (score_policy) {
        ++g_q4_host_object_prefetch.score_admissions;
        if (used_empty_slot) {
            ++g_q4_host_object_prefetch.score_read_empty_admissions;
        }
    }
    q4_score_profile_record_ram_candidate(
            marker.layer_idx, candidate_score, selected_victim_score, selected_has_victim, true);
    ++g_expert_pack.q4_host_object_read_admissions;
    if (eligible_layer_profile && eligible_layer) {
        ++g_q4_host_object_prefetch.eligible_layer_read_admits;
    }
    g_expert_pack.q4_host_object_read_admit_bytes.fetch_add(payload_bytes, std::memory_order_relaxed);
    if (payload_format == ggml_moe_common::object_host_payload_format::lossless_sidecar) {
        ++g_expert_pack.lossless_host_cache_admissions;
    }
    return true;
}

static bool q4_direct_host_object_marker_from_entry(
        const expert_pack_entry *entry,
        q4_colibri_object_marker *marker_out) {
    if (!entry || !marker_out || !g_expert_pack.q4_colibri ||
            entry->object_nbytes == 0 || entry->layer_idx < 0 || entry->expert_idx < 0) {
        return false;
    }
    *marker_out = {
        entry->source_idx,
        entry->layer_idx,
        entry->expert_idx,
        g_expert_pack.q4_manifest_generation,
        entry->object_offset,
        (size_t)entry->object_nbytes,
    };
    return true;
}

static bool q4_direct_host_object_copy_h2d(
        const expert_pack_entry *pack_entry,
        void *dst,
        size_t role_bytes,
        cudaStream_t st) {
    q4_colibri_object_marker marker;
    if (!q4_direct_host_object_marker_from_entry(pack_entry, &marker) || !dst ||
            role_bytes == 0 || pack_entry->object_relative_offset + role_bytes > pack_entry->object_nbytes ||
            !q4_colibri_host_object_prefetch_enabled()) {
        return false;
    }

    const bool eligible_layer_profile = q4_colibri_eligible_layer_profile_enabled();
    const bool eligible_layer = eligible_layer_profile ?
        q4_colibri_host_object_ram_eligible_layer(marker.layer_idx) : false;
    q4_colibri_host_object_record_layer_demand(eligible_layer);
    if (!q4_colibri_host_object_lookup_layer_allowed(marker.layer_idx)) {
        ++g_q4_host_object_prefetch.lookup_layer_skips;
        ++g_q4_host_object_prefetch.misses;
        q4_colibri_host_object_record_layer_miss(eligible_layer);
        q4_tier_diag_record_ram_miss(marker);
        return false;
    }

    q4_colibri_host_object_slot *slot_ptr = nullptr;
    size_t slot_idx = SIZE_MAX;
    uint64_t read_us = 0;
    uint8_t hit_origin = Q4_HOST_OBJECT_ORIGIN_UNKNOWN;
    {
        std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
        if (!q4_colibri_host_object_prefetch_init_locked()) return false;
        q4_colibri_host_object_sweep_completed_deletes_locked();
        q4_colibri_host_object_sweep_completed_d2h_locked();
        const std::string key = q4_colibri_host_object_key(marker);
        if (!q4_colibri_host_object_find_ready_locked(marker, &slot_idx)) {
            ++g_q4_host_object_prefetch.misses;
            q4_colibri_host_object_record_layer_miss(eligible_layer);
            q4_tier_diag_record_ram_miss(marker);
            return false;
        }
        q4_colibri_host_object_slot &slot = g_q4_host_object_prefetch.slots[slot_idx];
        if (!slot.ready || slot.loading || !slot.host ||
                !q4_colibri_object_marker_matches(slot.marker, marker)) {
            ++g_q4_host_object_prefetch.misses;
            q4_colibri_host_object_record_layer_miss(eligible_layer);
            q4_tier_diag_record_ram_miss(marker);
            return false;
        }
        if (slot.delete_after_h2d) {
            if (slot.pending_h2d) (void)ggml_moe_common::object_host_cache_synchronize_h2d(
                g_q4_host_object_prefetch, slot_idx);
            q4_colibri_host_object_clear_slot_locked(slot_idx, false);
            ++g_q4_host_object_prefetch.misses;
            q4_colibri_host_object_record_layer_miss(eligible_layer);
            q4_tier_diag_record_ram_miss(marker);
            return false;
        }
        if (slot.pending_h2d) {
            if (ggml_moe_common::object_host_cache_synchronize_h2d(
                        g_q4_host_object_prefetch, slot_idx) !=
                    ggml_moe_common::object_host_completion_state::complete) {
                ++g_q4_host_object_prefetch.misses;
                q4_colibri_host_object_record_layer_miss(eligible_layer);
                q4_tier_diag_record_ram_miss(marker);
                return false;
            }
        }
        if (!ggml_moe_common::object_host_cache_begin_h2d(
                    g_q4_host_object_prefetch, slot_idx)) return false;
        slot.in_use = true;
        slot.used = g_q4_host_object_prefetch.clock++;
        if (q4_colibri_host_object_score_policy_enabled() &&
                q4_colibri_host_object_refresh_score_on_hit_enabled()) {
            uint32_t freq = ++g_q4_host_object_prefetch.request_freq[key];
            if (freq <= slot.freq && slot.freq != UINT32_MAX) {
                freq = slot.freq + 1;
                g_q4_host_object_prefetch.request_freq[key] = freq;
            }
            slot.freq = freq;
            slot.score = q4_colibri_host_object_score(
                    slot.marker,
                    q4_colibri_host_object_score_current_layer(slot.marker.layer_idx),
                    slot.freq);
            ++g_q4_host_object_prefetch.score_hit_refreshes;
        }
        slot_ptr = &slot;
        read_us = slot.read_us;
        hit_origin = slot.origin;
    }

    const void *role_host = (const char *)slot_ptr->host + (size_t)pack_entry->object_relative_offset;
    const auto h2d_start = std::chrono::steady_clock::now();
    const bool enqueue_ok =
        cudaMemcpyAsync(dst, role_host, role_bytes, cudaMemcpyHostToDevice, st) == cudaSuccess;
    if (!enqueue_ok) cudaGetLastError();
    bool completion_ok = false;
    const uint64_t h2d_us = (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now() - h2d_start).count();
    {
        std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
        if (slot_idx < g_q4_host_object_prefetch.slots.size()) {
            q4_colibri_host_object_slot &slot = g_q4_host_object_prefetch.slots[slot_idx];
            completion_ok = enqueue_ok ? ggml_moe_common::object_host_cache_record_h2d(
                g_q4_host_object_prefetch, slot_idx, st) :
                ggml_moe_common::object_host_cache_cancel_h2d(
                    g_q4_host_object_prefetch, slot_idx, st);
            slot.in_use = false;
        }
    }
    if (!enqueue_ok || !completion_ok) return false;

    q4_tier_diag_record_ram_hit(marker);
    ++g_q4_host_object_prefetch.hits;
    q4_colibri_host_object_record_layer_hit(eligible_layer);
    ++g_expert_pack.q4_object_ram_hits;
    g_expert_pack.q4_object_ram_bytes_avoided.fetch_add(role_bytes, std::memory_order_relaxed);
    g_expert_pack.q4_object_ram_wait_us_avoided.fetch_add(read_us, std::memory_order_relaxed);
    if (marker.layer_idx >= 0 && marker.layer_idx < 64) {
        ++g_expert_pack.q4_object_layer_ram_hits[marker.layer_idx];
        q4_object_layer_add(g_expert_pack.q4_object_layer_ram_bytes_avoided, marker.layer_idx, role_bytes);
        q4_object_layer_add(g_expert_pack.q4_object_layer_ram_wait_us_avoided, marker.layer_idx, read_us);
    }
    q4_host_object_origin_record_hit(hit_origin, 1, role_bytes);
    g_q4_host_object_prefetch.h2d_roles.fetch_add(1, std::memory_order_relaxed);
    g_q4_host_object_prefetch.h2d_bytes.fetch_add(role_bytes, std::memory_order_relaxed);
    g_q4_host_object_prefetch.h2d_us.fetch_add(h2d_us, std::memory_order_relaxed);
    g_expert_pack.q4_object_ram_h2d_us.fetch_add(h2d_us, std::memory_order_relaxed);
    g_expert_pack.q4_object_ram_h2d_bytes.fetch_add(role_bytes, std::memory_order_relaxed);
    q4_object_layer_add(g_expert_pack.q4_object_layer_ram_h2d_us, marker.layer_idx, h2d_us);
    q4_object_layer_add(g_expert_pack.q4_object_layer_ram_h2d_bytes, marker.layer_idx, role_bytes);
    q4_layer_io_add(g_expert_pack.q4_layer_io_h2d_us, marker.layer_idx, h2d_us);
    return true;
}

static void q4_direct_host_object_submit_on_read(
        const expert_pack_entry *pack_entry,
        uint64_t read_us) {
    if (!g_expert_pack.glm52_colibri) return;
    q4_colibri_object_marker marker;
    if (!q4_direct_host_object_marker_from_entry(pack_entry, &marker) ||
            !q4_colibri_host_object_admit_on_read_enabled() ||
            !q4_colibri_host_object_prefetch_enabled()) {
        return;
    }
    const uint64_t min_read_us = q4_colibri_host_object_admit_min_read_us();
    if (min_read_us > 0 && read_us < min_read_us) {
        ++g_q4_host_object_prefetch.read_admit_min_read_us_skips;
        g_q4_host_object_prefetch.read_admit_min_read_us_skip_sum.fetch_add(read_us, std::memory_order_relaxed);
        return;
    }
    if (!q4_colibri_host_object_admit_layer_allowed(marker.layer_idx) ||
            !q4_colibri_ram_net_layer_allowed(marker.layer_idx) ||
            !q4_colibri_host_object_admit_pair_allowed(marker.layer_idx, marker.expert_idx)) {
        ++g_q4_host_object_prefetch.ineligible_layer_read_rejects;
        return;
    }
    (void)q4_colibri_host_object_prefetch_submit(
            marker,
            marker.source_idx,
            marker.offset,
            marker.bytes,
            false);
}

static bool q4_colibri_host_object_clear_slot_locked(
        size_t slot_idx,
        bool count_delete) {
    if (slot_idx >= g_q4_host_object_prefetch.slots.size() ||
            !ggml_moe_common::object_host_cache_invalidate_slot(
                g_q4_host_object_prefetch, slot_idx)) {
        return false;
    }
    q4_colibri_host_object_slot &slot = g_q4_host_object_prefetch.slots[slot_idx];
    slot.marker = {};
    slot.ready = false;
    slot.loading = false;
    slot.in_use = false;
    slot.pending_h2d = false;
    slot.h2d_recorded = false;
    slot.pending_d2h = false;
    slot.delete_after_h2d = false;
    slot.used = 0;
    slot.read_us = 0;
    slot.score = 0;
    slot.freq = 0;
    slot.pilot_submitted = false;
    slot.origin = Q4_HOST_OBJECT_ORIGIN_UNKNOWN;
    slot.payload_format = ggml_moe_common::object_host_payload_format::raw_object;
    slot.payload_bytes = 0;
    slot.payload_transport_bytes = 0;
    slot.payload_crc32 = 0;
    slot.payload_record_identity = 0;
    if (count_delete) {
        ++g_q4_tier_overlap_diag.tier_delete_ram_on_h2d;
    }
    return true;
}

static void q4_colibri_host_object_sweep_completed_deletes_locked() {
    for (size_t i = 0; i < g_q4_host_object_prefetch.slots.size(); ++i) {
        q4_colibri_host_object_slot &slot = g_q4_host_object_prefetch.slots[i];
        if (!slot.delete_after_h2d || !slot.pending_h2d || !slot.h2d_done) continue;
        const ggml_moe_common::object_host_completion_state state =
            ggml_moe_common::object_host_cache_query_h2d(g_q4_host_object_prefetch, i);
        if (state == ggml_moe_common::object_host_completion_state::complete ||
                state == ggml_moe_common::object_host_completion_state::failed) {
            (void)q4_colibri_host_object_clear_slot_locked(i, false);
        }
    }
}

static void q4_colibri_host_object_sweep_completed_d2h_locked() {
    for (size_t i = 0; i < g_q4_host_object_prefetch.slots.size(); ++i) {
        q4_colibri_host_object_slot &slot = g_q4_host_object_prefetch.slots[i];
        if (!slot.pending_d2h || !slot.d2h_done) continue;
        const ggml_moe_common::object_host_transfer_status status =
            ggml_moe_common::object_host_slot_query_transfer(
                slot, ggml_moe_common::object_host_transfer::d2h);
        if (status == ggml_moe_common::object_host_transfer_status::complete) {
            slot.pending_d2h = false;
            slot.loading = false;
            slot.in_use = false;
            if (!ggml_moe_common::object_host_cache_publish_slot(g_q4_host_object_prefetch, i)) {
                ++g_q4_tier_overlap_diag.tier_demote_async_event_failures;
                (void)q4_colibri_host_object_clear_slot_locked(i, false);
                continue;
            }
            slot.ready = true;
            slot.used = g_q4_host_object_prefetch.clock++;
            ++g_q4_tier_overlap_diag.tier_demote_success;
            ++g_q4_tier_overlap_diag.tier_demote_async_completed;
            g_q4_tier_overlap_diag.tier_demote_bytes.fetch_add(
                    (uint64_t)slot.marker.bytes, std::memory_order_relaxed);
            g_q4_tier_overlap_diag.tier_demote_async_pending_bytes.fetch_sub(
                    (uint64_t)slot.marker.bytes, std::memory_order_relaxed);
        } else if (status == ggml_moe_common::object_host_transfer_status::error) {
            ++g_q4_tier_overlap_diag.tier_demote_async_event_failures;
            g_q4_tier_overlap_diag.tier_demote_async_pending_bytes.fetch_sub(
                    (uint64_t)slot.marker.bytes, std::memory_order_relaxed);
            q4_colibri_host_object_clear_slot_locked(i, false);
        }
    }
}

static bool q4_colibri_host_object_delete_after_h2d(size_t slot_idx) {
    std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
    if (slot_idx >= g_q4_host_object_prefetch.slots.size()) return false;
    q4_colibri_host_object_slot &slot = g_q4_host_object_prefetch.slots[slot_idx];
    if (slot.in_use || slot.loading || !slot.pending_h2d) return false;
    if (slot.ready) {
        if (!ggml_moe_common::object_host_cache_unpublish_ready_slot(
                    g_q4_host_object_prefetch, slot_idx)) return false;
        slot.ready = false;
    }
    slot.delete_after_h2d = true;
    ++g_q4_tier_overlap_diag.tier_delete_ram_on_h2d;
    q4_colibri_host_object_sweep_completed_deletes_locked();
    q4_colibri_host_object_sweep_completed_d2h_locked();
    return true;
}

static bool q4_colibri_host_object_reserve_slot_for_marker_locked(
        const q4_colibri_object_marker &marker,
        size_t bytes,
        int current_layer,
        size_t *slot_idx_out,
        uint32_t *freq_out) {
    if (!slot_idx_out || bytes == 0 || !q4_colibri_host_object_prefetch_init_locked()) {
        return false;
    }
    const bool demote_quota_enabled = q4_colibri_host_object_layer_quota_enabled() &&
        q4_colibri_host_object_layer_quota_apply_demote_enabled();
    if (demote_quota_enabled && !q4_colibri_host_object_layer_quota_admit_allowed(marker.layer_idx)) {
        ++g_q4_host_object_prefetch.layer_quota_rejects;
        ++g_q4_tier_overlap_diag.tier_demote_skip_no_slot;
        return false;
    }
    const std::string key = q4_colibri_host_object_key(marker);
    q4_colibri_host_object_sweep_completed_deletes_locked();
    q4_colibri_host_object_sweep_completed_d2h_locked();
    if (q4_colibri_host_object_find_ready_locked(marker) ||
            g_q4_host_object_prefetch.queued.find(key) != g_q4_host_object_prefetch.queued.end()) {
        ++g_q4_tier_overlap_diag.tier_demote_skip_already_ram;
        return false;
    }

    const bool score_policy = q4_colibri_host_object_score_policy_enabled();
    const bool score_profile = q4_object_score_profile_enabled();
    uint32_t freq = 0;
    if (score_policy || score_profile) {
        freq = ++g_q4_host_object_prefetch.request_freq[key];
    }
    const uint64_t candidate_score = (score_policy || score_profile) ?
        q4_colibri_host_object_score(
                marker,
                q4_colibri_host_object_candidate_score_layer(marker.layer_idx),
                freq) : 0;
    ggml_moe_common::object_host_admission_policy score_admission;
    score_admission.min_score = score_policy && q4_colibri_flow_score_cache_enabled() ?
        q4_colibri_flow_score_min_admit() : 0;
    if (score_policy && q4_colibri_flow_score_cache_enabled() &&
            ggml_moe_common::object_host_cache_evaluate_admission(
                score_admission, freq, candidate_score, false, 0) ==
            ggml_moe_common::object_host_admission_decision::reject_score) {
        ++g_q4_host_object_prefetch.score_admit_skips;
        ++g_q4_tier_overlap_diag.tier_demote_skip_no_slot;
        q4_score_profile_record_ram_candidate(marker.layer_idx, candidate_score, 0, false, false);
        return false;
    }

    size_t slot_idx = SIZE_MAX;
    bool budget_pressure = false;
    uint64_t selected_victim_score = 0;
    bool selected_has_victim = false;
    for (size_t i = 0; i < g_q4_host_object_prefetch.slots.size(); ++i) {
        q4_colibri_host_object_slot &slot = g_q4_host_object_prefetch.slots[i];
        if (!slot.loading && !slot.in_use && !slot.ready && !slot.pending_h2d && !slot.pending_d2h) {
            slot_idx = i;
            break;
        }
    }
    if (slot_idx != SIZE_MAX && q4_colibri_host_object_budget_enabled_locked() &&
            !q4_colibri_host_object_budget_fits_locked(g_q4_host_object_prefetch.slots[slot_idx], bytes)) {
        budget_pressure = true;
        slot_idx = SIZE_MAX;
    }
    const bool quota_enabled = demote_quota_enabled;
    const size_t incoming_quota = q4_colibri_host_object_layer_quota(marker.layer_idx);
    const size_t incoming_occupancy = quota_enabled ?
        q4_colibri_host_object_layer_occupancy_locked(marker.layer_idx) : 0;
    if (quota_enabled && incoming_occupancy >= incoming_quota) {
        slot_idx = SIZE_MAX;
    }
    if (slot_idx == SIZE_MAX) {
        q4_host_slot_selection_context context;
        context.incoming_layer = marker.layer_idx;
        context.incoming_occupancy = incoming_occupancy;
        context.incoming_quota = incoming_quota;
        context.victim_score_layer = current_layer;
        context.budget_pressure = budget_pressure;
        context.use_stored_score = score_policy &&
            q4_colibri_host_object_compare_stored_score_enabled() &&
            !q4_colibri_host_object_score_dynamic_current_enabled();
        ggml_moe_common::object_host_slot_selection selection;
        ggml_moe_common::object_host_slot_selection_policy policy;
        policy.prefer_empty = false;
        policy.evaluate_score = score_policy || score_profile;
        policy.select_by_score = score_policy;
        if (ggml_moe_common::object_host_cache_select_slot(
                    g_q4_host_object_prefetch,
                    policy,
                    q4_host_classify_slot,
                    q4_host_slot_score,
                    &context,
                    selection)) {
            slot_idx = selection.slot_index;
            selected_has_victim = !selection.empty;
            selected_victim_score = selection.score;
        }
        ggml_moe_common::object_host_admission_policy victim_admission;
        victim_admission.compare_victim = score_policy;
        if (score_policy && slot_idx != SIZE_MAX &&
                ggml_moe_common::object_host_cache_evaluate_admission(
                    victim_admission,
                    freq,
                    candidate_score,
                    true,
                    selected_victim_score) ==
                ggml_moe_common::object_host_admission_decision::reject_victim) {
            ++g_q4_host_object_prefetch.score_protected_victims;
            ++g_q4_tier_overlap_diag.tier_demote_skip_no_slot;
            q4_score_profile_record_ram_candidate(
                    marker.layer_idx, candidate_score, selected_victim_score, selected_has_victim, false);
            return false;
        }
    }
    if (slot_idx == SIZE_MAX) {
        if (quota_enabled) {
            ++g_q4_host_object_prefetch.layer_quota_protected;
        }
        ++g_q4_tier_overlap_diag.tier_demote_skip_no_slot;
        q4_score_profile_record_ram_candidate(
                marker.layer_idx, candidate_score, 0, false, false);
        return false;
    }

    q4_colibri_host_object_slot &slot = g_q4_host_object_prefetch.slots[slot_idx];
    if (!q4_colibri_host_object_budget_fits_locked(slot, bytes)) {
        ++g_q4_tier_overlap_diag.tier_demote_skip_no_slot;
        q4_score_profile_record_ram_candidate(
                marker.layer_idx, candidate_score, selected_victim_score, selected_has_victim, false);
        return false;
    }
    if (!ggml_moe_common::object_host_cache_prepare_slot(g_q4_host_object_prefetch, slot_idx)) {
        ++g_q4_tier_overlap_diag.tier_demote_skip_no_slot;
        return false;
    }
    if (slot.ready) {
        if (!selected_has_victim) {
            selected_has_victim = true;
            selected_victim_score = score_profile ?
                q4_colibri_host_object_victim_score(slot, current_layer, false) : 0;
        }
        q4_tier_record_ram_slot_eviction(slot);
        q4_tier_diag_record_ram_eviction(slot.marker);
        if (quota_enabled) {
            ++g_q4_host_object_prefetch.layer_quota_evictions;
        }
        ++g_q4_host_object_prefetch.evictions;
        if (q4_colibri_host_object_score_policy_enabled()) {
            ++g_q4_host_object_prefetch.score_evictions;
        }
    }
    if (slot.capacity < bytes) {
        if (slot.host) {
            q4_colibri_host_object_account_free_locked(slot);
            q4_colibri_host_object_free(slot);
        }
        if (!q4_colibri_host_object_alloc(slot, bytes)) {
            ++g_q4_host_object_prefetch.alloc_failures;
            ++g_q4_tier_overlap_diag.tier_demote_skip_no_slot;
            return false;
        }
        q4_colibri_host_object_account_alloc_locked(slot, bytes);
    }
    slot.marker = marker;
    slot.ready = false;
    slot.loading = true;
    slot.in_use = true;
    slot.pending_h2d = false;
    slot.h2d_recorded = false;
    slot.pending_d2h = false;
    slot.delete_after_h2d = false;
    slot.pilot_submitted = false;
    slot.origin = Q4_HOST_OBJECT_ORIGIN_DEMOTE;
    slot.payload_format = ggml_moe_common::object_host_payload_format::raw_object;
    slot.payload_bytes = marker.bytes;
    slot.payload_transport_bytes = marker.bytes;
    slot.payload_crc32 = 0;
    slot.payload_record_identity = 0;
    slot.freq = (score_policy || score_profile) ? freq : 0;
    slot.score = q4_colibri_host_object_score(marker, current_layer, slot.freq);
    slot.read_us = 0;
    *slot_idx_out = slot_idx;
    if (freq_out) *freq_out = freq;
    q4_score_profile_record_ram_candidate(
            marker.layer_idx, candidate_score, selected_victim_score, selected_has_victim, true);
    return true;
}

static bool q4_colibri_host_object_demote_from_vram(
        const char *victim_tensor,
        int victim_layer,
        int victim_expert,
        uint32_t victim_hits,
        int current_layer) {
    if (!q4_tier_demote_vram_evict_enabled() ||
            !q4_colibri_host_object_prefetch_enabled() ||
            victim_layer < 0 || victim_expert < 0 || !victim_tensor || !victim_tensor[0]) {
        return false;
    }
    ++g_q4_tier_overlap_diag.tier_demote_attempts;
    if (victim_hits < q4_tier_demote_min_hits()) {
        ++g_q4_tier_overlap_diag.tier_demote_skip_low_value;
        return false;
    }

    std::string gate_name;
    std::string up_name;
    std::string down_name;
    if (!q4_tier_role_family_names(victim_tensor, gate_name, up_name, down_name)) {
        ++g_q4_tier_overlap_diag.tier_demote_skip_incomplete_vram;
        return false;
    }
    const char *role_names[3] = {gate_name.c_str(), up_name.c_str(), down_name.c_str()};
    const expert_pack_entry *entries[3] = {};
    const batch_vram_cache *role_caches[3] = {};
    int role_slots[3] = {-1, -1, -1};
    for (size_t role_idx = 0; role_idx < 3; ++role_idx) {
        const uintptr_t key = batch_key_hash(role_names[role_idx], victim_expert);
        for (int cid = 0; cid < 2; ++cid) {
            const int slot = q4_tier_diag_cache_ready_slot(g_bcaches[cid], key);
            if (slot >= 0) {
                role_caches[role_idx] = &g_bcaches[cid];
                role_slots[role_idx] = slot;
                break;
            }
        }
        if (!role_caches[role_idx]) {
            ++g_q4_tier_overlap_diag.tier_demote_skip_incomplete_vram;
            return false;
        }
        entries[role_idx] = expert_pack_lookup(
                role_names[role_idx],
                victim_expert,
                role_caches[role_idx]->slot_payload_bytes[role_slots[role_idx]]);
        if (!entries[role_idx]) {
            ++g_q4_tier_overlap_diag.tier_demote_skip_incomplete_vram;
            return false;
        }
    }
    const expert_pack_entry *first = entries[0];
    bool same_object = first->object_nbytes > 0;
    for (size_t role_idx = 1; role_idx < 3; ++role_idx) {
        same_object = same_object &&
            entries[role_idx]->source_idx == first->source_idx &&
            entries[role_idx]->object_offset == first->object_offset &&
            entries[role_idx]->object_nbytes == first->object_nbytes;
    }
    if (!same_object) {
        ++g_q4_tier_overlap_diag.tier_demote_skip_incomplete_vram;
        return false;
    }
    const q4_colibri_object_marker marker{
        first->source_idx, first->layer_idx, (int32_t)victim_expert,
        g_expert_pack.q4_manifest_generation, first->object_offset,
        (size_t)first->object_nbytes,
    };
    if (q4_tier_demote_admit_layers_only_enabled() &&
            !q4_colibri_host_object_admit_layer_allowed(victim_layer)) {
        ++g_q4_tier_overlap_diag.tier_demote_skip_low_value;
        return false;
    }
    if (!q4_colibri_ram_net_layer_allowed(victim_layer)) {
        ++g_q4_host_object_prefetch.ram_net_demote_rejects;
        ++g_q4_tier_overlap_diag.tier_demote_skip_low_value;
        return false;
    }
    const uint64_t ram_net_demote_score_min = q4_colibri_ram_net_demote_score_min();
    if (q4_colibri_ram_net_admission_enabled() && ram_net_demote_score_min > 0) {
        const uint64_t demote_score = q4_colibri_host_object_score(marker, current_layer, victim_hits);
        if (demote_score < ram_net_demote_score_min) {
            ++g_q4_host_object_prefetch.ram_net_demote_score_rejects;
            ++g_q4_tier_overlap_diag.tier_demote_skip_low_value;
            return false;
        }
    }


    size_t ram_slot_idx = SIZE_MAX;
    {
        std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
        if (!q4_colibri_host_object_reserve_slot_for_marker_locked(
                    marker, (size_t)first->object_nbytes, current_layer, &ram_slot_idx, nullptr)) {
            return false;
        }
    }
    if (ram_slot_idx >= g_q4_host_object_prefetch.slots.size()) return false;
    q4_colibri_host_object_slot *ram_slot = &g_q4_host_object_prefetch.slots[ram_slot_idx];
    bool ok = true;
    const bool async_d2h = q4_tier_demote_async_d2h_enabled() && g_q4_colibri_pipe.stream != nullptr;
    const auto d2h_start = std::chrono::steady_clock::now();
    if (async_d2h) {
        if (!ggml_moe_common::object_host_slot_ensure_transfer_event(
                    *ram_slot, ggml_moe_common::object_host_transfer::d2h)) {
            ok = false;
            ++g_q4_tier_overlap_diag.tier_demote_async_event_failures;
        }
        for (size_t role_idx = 0; ok && role_idx < 3; ++role_idx) {
            const batch_vram_cache *cache = role_caches[role_idx];
            const int slot = role_slots[role_idx];
            const expert_pack_entry *entry = entries[role_idx];
            const void *src = (const char *)cache->pool + (size_t)slot * cache->slot_sz;
            void *dst = (char *)ram_slot->host + (size_t)entry->object_relative_offset;
            if (cudaMemcpyAsync(dst, src, (size_t)entry->nbytes,
                        cudaMemcpyDeviceToHost, g_q4_colibri_pipe.stream) != cudaSuccess) {
                ok = false;
                ++g_q4_tier_overlap_diag.tier_demote_async_enqueue_failures;
                break;
            }
        }
        if (ok && !ggml_moe_common::object_host_slot_record_transfer(
                    *ram_slot,
                    ggml_moe_common::object_host_transfer::d2h,
                    g_q4_colibri_pipe.stream)) {
            ok = false;
            ++g_q4_tier_overlap_diag.tier_demote_async_event_failures;
        }
    } else {
        for (size_t role_idx = 0; role_idx < 3; ++role_idx) {
            const batch_vram_cache *cache = role_caches[role_idx];
            const int slot = role_slots[role_idx];
            const expert_pack_entry *entry = entries[role_idx];
            const void *src = (const char *)cache->pool + (size_t)slot * cache->slot_sz;
            void *dst = (char *)ram_slot->host + (size_t)entry->object_relative_offset;
            if (cudaMemcpy(dst, src, (size_t)entry->nbytes, cudaMemcpyDeviceToHost) != cudaSuccess) {
                ok = false;
                break;
            }
        }
    }
    const uint64_t d2h_us = (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now() - d2h_start).count();
    {
        std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
        if (ram_slot_idx < g_q4_host_object_prefetch.slots.size()) {
            q4_colibri_host_object_slot &slot = g_q4_host_object_prefetch.slots[ram_slot_idx];
            if (async_d2h && ok) {
                slot.ready = false;
                slot.loading = false;
                slot.in_use = false;
                slot.pending_d2h = true;
                ++g_q4_tier_overlap_diag.tier_demote_async_submitted;
                g_q4_tier_overlap_diag.tier_demote_async_enqueue_us.fetch_add(d2h_us, std::memory_order_relaxed);
                g_q4_tier_overlap_diag.tier_demote_async_pending_bytes.fetch_add(
                        (uint64_t)first->object_nbytes, std::memory_order_relaxed);
            } else {
                slot.loading = false;
                slot.in_use = false;
                if (ok) {
                    if (!ggml_moe_common::object_host_cache_publish_slot(
                                g_q4_host_object_prefetch, ram_slot_idx)) {
                        (void)q4_colibri_host_object_clear_slot_locked(ram_slot_idx, false);
                        return false;
                    }
                    slot.ready = true;
                    slot.used = g_q4_host_object_prefetch.clock++;
                    ++g_q4_tier_overlap_diag.tier_demote_success;
                    g_q4_tier_overlap_diag.tier_demote_bytes.fetch_add(
                            (uint64_t)first->object_nbytes, std::memory_order_relaxed);
                    g_q4_tier_overlap_diag.tier_demote_d2h_us.fetch_add(d2h_us, std::memory_order_relaxed);
                } else {
                    q4_colibri_host_object_clear_slot_locked(ram_slot_idx, false);
                }
            }
        }
    }
    return ok;
}

static pinned_stage_slot *q4_colibri_object_cache_find(const q4_colibri_object_marker &marker) {
    for (pinned_stage_slot &slot : g_q4_colibri_pipe.ring.slots) {
        if (q4_colibri_object_marker_matches(slot.object, marker)) {
            slot.object_used = g_q4_colibri_pipe.object_clock++;
            return &slot;
        }
    }
    return nullptr;
}

static pinned_stage_slot *q4_colibri_object_cache_admit(const q4_colibri_object_marker &marker) {
    pinned_stage_slot *victim = nullptr;
    for (pinned_stage_slot &slot : g_q4_colibri_pipe.ring.slots) {
        if (slot.object.bytes == 0) {
            victim = &slot;
            break;
        }
        if (!victim || slot.object_used < victim->object_used) victim = &slot;
    }
    if (!victim) return nullptr;
    if (victim->pending) {
        if (cudaEventSynchronize(victim->done) != cudaSuccess) return nullptr;
        victim->pending = false;
        ++g_q4_colibri_pipe.ring.waits;
    }
    pinned_stage_collect_timing(g_q4_colibri_pipe.ring, *victim);
    if (victim->object.bytes != 0) {
        ++g_expert_pack.q4_object_ram_evictions;
        ++g_expert_pack.q4_object_ram_demotions;
    }
    victim->object = marker;
    victim->object_used = g_q4_colibri_pipe.object_clock++;
    victim->object_read_us = 0;
    ++g_expert_pack.q4_object_ram_admissions;
    return victim;
}

static bool q4_colibri_pipe_marker_matches(const q4_colibri_pipe_job &job) {
    if (!job.cache || job.slot < 0 || job.slot >= job.cache->n_slots) return false;
    const q4_colibri_slot_marker current{
        job.cache->slot_key[job.slot],
        job.cache->slot_generation[job.slot],
        job.cache->slot_payload_bytes[job.slot],
    };
    if (current.generation != job.marker.generation) {
        ++g_expert_pack.q4_pipe_stale_generation;
        return false;
    }
    if (current.key != job.marker.key) {
        ++g_expert_pack.q4_pipe_key_mismatch;
        return false;
    }
    return q4_colibri_slot_marker_matches(current, job.marker);
}

static bool q4_colibri_object_role_marker_matches(const q4_colibri_object_role_job &role) {
    if (!role.cache || role.slot < 0 || role.slot >= role.cache->n_slots) return false;
    const q4_colibri_slot_marker current{
        role.cache->slot_key[role.slot],
        role.cache->slot_generation[role.slot],
        role.cache->slot_payload_bytes[role.slot],
    };
    if (current.generation != role.marker.generation) {
        ++g_expert_pack.q4_pipe_stale_generation;
        return false;
    }
    if (current.key != role.marker.key) {
        ++g_expert_pack.q4_pipe_key_mismatch;
        return false;
    }
    return q4_colibri_slot_marker_matches(current, role.marker);
}

static bool q4_colibri_object_h2d_batch_enabled() {
    return expert_pack_env_bool("GGML_MOE_Q4_OBJECT_H2D_BATCH", false);
}

static bool q4_colibri_object_h2d_async_refill_enabled() {
    return expert_pack_env_bool("GGML_MOE_Q4_OBJECT_H2D_ASYNC_REFILL", false);
}

static bool q4_colibri_object_adjacent_coalesce_enabled() {
    return expert_pack_env_bool("GGML_MOE_Q4_OBJECT_ADJACENT_COALESCE", false);
}

static bool q4_colibri_object_adjacent_tail_coalesce_enabled() {
    return expert_pack_env_bool("GGML_MOE_Q4_OBJECT_ADJACENT_TAIL_COALESCE", false);
}

static bool q4_colibri_object_adjacent_layer_allowed(int layer) {
    static bool inited = false;
    static bool allow_all = true;
    static bool allowed[128] = {};
    if (!inited) {
        const char *env = std::getenv("GGML_MOE_Q4_OBJECT_ADJACENT_COALESCE_LAYERS");
        if (env && env[0] && std::strcmp(env, "all") != 0 && std::strcmp(env, "*") != 0) {
            allow_all = false;
            char buf[512];
            std::snprintf(buf, sizeof(buf), "%s", env);
            char *save = nullptr;
            for (char *tok = ::strtok_r(buf, ",;:", &save); tok; tok = ::strtok_r(nullptr, ",;:", &save)) {
                while (*tok == ' ' || *tok == '\t') ++tok;
                if (!*tok) continue;
                char *end = nullptr;
                long lo = std::strtol(tok, &end, 10);
                long hi = lo;
                if (end && *end == '-') {
                    char *end2 = nullptr;
                    hi = std::strtol(end + 1, &end2, 10);
                    end = end2;
                }
                if (end == tok || lo < 0 || hi < 0) continue;
                if (hi < lo) std::swap(lo, hi);
                lo = std::max<long>(0, std::min<long>(lo, 127));
                hi = std::max<long>(0, std::min<long>(hi, 127));
                for (long l = lo; l <= hi; ++l) {
                    allowed[l] = true;
                }
            }
        }
        inited = true;
    }
    if (allow_all) return true;
    return layer >= 0 && layer < 128 && allowed[layer];
}

static bool q4_colibri_enqueue_object_role_h2d(
        q4_colibri_object_job &job,
        const void *object_host,
        cudaStream_t stream,
        uint64_t *role_count_out,
        uint64_t *role_bytes_out) {
    if (!object_host || job.role_count == 0 || job.role_count > 3) return false;
    static const bool common_role_h2d =
        expert_pack_env_bool("GGML_MOE_COMMON_ROLE_H2D", false);
    if (!common_role_h2d) {
        uint64_t role_count = 0;
        uint64_t role_bytes = 0;
        for (size_t role_idx = 0; role_idx < job.role_count; ++role_idx) {
            q4_colibri_object_role_job &role = job.roles[role_idx];
            uint64_t role_relative_offset = 0;
            if (!q4_colibri_object_role_marker_matches(role) ||
                    !q4_colibri_role_in_read_span(
                        role, job.offset, job.bytes, &role_relative_offset)) {
                return false;
            }
            const ggml_moe_common::role_cache_view role_view = batch_cache_role_view(role.cache);
            if (!ggml_moe_common::role_cache_ensure_ready_event(role_view, role.slot)) {
                return false;
            }
            role.cache->slot_state[role.slot] = q4_colibri_slot_state::reading;
            const void *role_host = (const char *)object_host + role_relative_offset;
            if (cudaMemcpyAsync(role.dst, role_host, role.entry->nbytes,
                        cudaMemcpyHostToDevice, stream) != cudaSuccess ||
                    !ggml_moe_common::role_cache_record_ready_event(
                        role_view, role.slot, stream)) {
                return false;
            }
            role.cache->slot_ready_marker[role.slot] = role.marker;
            role.cache->slot_state[role.slot] = q4_colibri_slot_state::h2d_ready;
            role.cache->slot_pending[role.slot] = true;
            role.cache->slot_filling[role.slot] = false;
            ++g_q4_colibri_pipe.ring.copies;
            ++g_expert_pack.iouring_h2d_enqueues;
            ++role_count;
            role_bytes += role.entry->nbytes;
        }
        if (role_count_out) *role_count_out += role_count;
        if (role_bytes_out) *role_bytes_out += role_bytes;
        return true;
    }
    ggml_moe_common::role_cache_h2d_copy copies[3];
    for (size_t role_idx = 0; role_idx < job.role_count; ++role_idx) {
        q4_colibri_object_role_job &role = job.roles[role_idx];
        uint64_t role_relative_offset = 0;
        if (!q4_colibri_object_role_marker_matches(role) ||
                !q4_colibri_role_in_read_span(role, job.offset, job.bytes, &role_relative_offset)) {
            return false;
        }
        const ggml_moe_common::role_cache_view role_view = batch_cache_role_view(role.cache);
        const void *role_host = (const char *)object_host + role_relative_offset;
        copies[role_idx] = {
            role_view,
            role.slot,
            role.marker.key,
            role.marker.generation,
            (size_t) role.entry->nbytes,
            role.dst,
            role_host,
            (size_t) role.entry->nbytes,
        };
    }
    ggml_moe_common::role_cache_h2d_stats stats;
    if (!ggml_moe_common::role_cache_copy_h2d_batch_async(
                copies, job.role_count, stream, &stats)) {
        return false;
    }
    g_q4_colibri_pipe.ring.copies += stats.copies;
    g_expert_pack.iouring_h2d_enqueues.fetch_add(stats.copies, std::memory_order_relaxed);
    if (role_count_out) *role_count_out += stats.copies;
    if (role_bytes_out) *role_bytes_out += stats.bytes;
    return true;
}

static void q4_colibri_object_h2d_batch_record(
        bool ram_source,
        uint64_t objects,
        uint64_t roles,
        uint64_t bytes,
        uint64_t enqueue_us) {
    if (objects == 0) return;
    ++g_expert_pack.q4_object_h2d_batches;
    if (ram_source) {
        ++g_expert_pack.q4_object_h2d_ram_batches;
    } else {
        ++g_expert_pack.q4_object_h2d_ssd_batches;
    }
    g_expert_pack.q4_object_h2d_objects.fetch_add(objects, std::memory_order_relaxed);
    g_expert_pack.q4_object_h2d_roles.fetch_add(roles, std::memory_order_relaxed);
    g_expert_pack.q4_object_h2d_bytes.fetch_add(bytes, std::memory_order_relaxed);
    g_expert_pack.q4_object_h2d_enqueue_us.fetch_add(enqueue_us, std::memory_order_relaxed);
}

struct q4_colibri_deferred_host_hit {
    size_t job_idx = 0;
    size_t slot_idx = SIZE_MAX;
    uint64_t read_us = 0;
    bool pilot_submitted_hit = false;
};

static bool q4_colibri_host_object_prefetch_acquire(
        q4_colibri_object_job &job,
        size_t *slot_idx_out,
        uint64_t *read_us_out,
        bool *pilot_submitted_hit_out) {
    if (!q4_colibri_host_object_prefetch_enabled() || job.role_count == 0 || job.role_count > 3) {
        return false;
    }
    const bool eligible_layer_profile = q4_colibri_eligible_layer_profile_enabled();
    const bool eligible_layer = eligible_layer_profile ?
        q4_colibri_host_object_ram_eligible_layer(job.marker.layer_idx) : false;
    q4_colibri_host_object_record_layer_demand(eligible_layer);
    if (!q4_colibri_host_object_lookup_layer_allowed(job.marker.layer_idx)) {
        ++g_q4_host_object_prefetch.lookup_layer_skips;
        ++g_q4_host_object_prefetch.misses;
        q4_colibri_host_object_record_layer_miss(eligible_layer);
        q4_tier_diag_record_ram_miss(job.marker);
        return false;
    }
    const std::string key = q4_colibri_host_object_key(job.marker);
    std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
    if (!q4_colibri_host_object_prefetch_init_locked()) return false;
    q4_colibri_host_object_sweep_completed_deletes_locked();
    q4_colibri_host_object_sweep_completed_d2h_locked();
    size_t slot_idx = SIZE_MAX;
    if (!q4_colibri_host_object_find_ready_locked(job.marker, &slot_idx)) {
        q4_tier_diag_record_ram_miss(job.marker);
        ++g_q4_host_object_prefetch.misses;
        q4_colibri_host_object_record_layer_miss(eligible_layer);
        return false;
    }
    q4_colibri_host_object_slot &slot = g_q4_host_object_prefetch.slots[slot_idx];
    if (!slot.ready || slot.loading || !q4_colibri_object_marker_matches(slot.marker, job.marker)) {
        q4_tier_diag_record_ram_miss(job.marker);
        ++g_q4_host_object_prefetch.misses;
        q4_colibri_host_object_record_layer_miss(eligible_layer);
        return false;
    }
    if (g_expert_pack.lossless_standalone &&
            slot.payload_format !=
                ggml_moe_common::object_host_payload_format::lossless_sidecar) {
        const uint64_t discarded =
            ++g_expert_pack.lossless_standalone_raw_host_discards;
        if (discarded <= 8) {
            std::fprintf(stderr,
                "[moe_stream_batch] standalone lossless discarded raw Host-cache entry: "
                "layer=%d expert=%d origin=%u discard=%lu\n",
                job.marker.layer_idx,
                job.marker.expert_idx,
                static_cast<unsigned>(slot.origin),
                (unsigned long)discarded);
        }
        (void)q4_colibri_host_object_clear_slot_locked(slot_idx, false);
        q4_tier_diag_record_ram_miss(job.marker);
        ++g_q4_host_object_prefetch.misses;
        q4_colibri_host_object_record_layer_miss(eligible_layer);
        return false;
    }
    if (slot.delete_after_h2d) {
        if (slot.pending_h2d) (void)ggml_moe_common::object_host_cache_synchronize_h2d(
            g_q4_host_object_prefetch, slot_idx);
        q4_colibri_host_object_clear_slot_locked(slot_idx, false);
        q4_tier_diag_record_ram_miss(job.marker);
        ++g_q4_host_object_prefetch.misses;
        q4_colibri_host_object_record_layer_miss(eligible_layer);
        return false;
    }
    if (slot.pending_h2d) {
        if (ggml_moe_common::object_host_cache_synchronize_h2d(
                    g_q4_host_object_prefetch, slot_idx) !=
                ggml_moe_common::object_host_completion_state::complete) {
            q4_tier_diag_record_ram_miss(job.marker);
            ++g_q4_host_object_prefetch.misses;
            q4_colibri_host_object_record_layer_miss(eligible_layer);
            return false;
        }
    }
    q4_colibri_host_object_try_register_pageable(slot);
    if (!ggml_moe_common::object_host_cache_begin_h2d(
                g_q4_host_object_prefetch, slot_idx)) return false;
    slot.in_use = true;
    slot.used = g_q4_host_object_prefetch.clock++;
    if (q4_colibri_host_object_score_policy_enabled() &&
            q4_colibri_host_object_refresh_score_on_hit_enabled()) {
        uint32_t freq = ++g_q4_host_object_prefetch.request_freq[key];
        if (freq <= slot.freq && slot.freq != UINT32_MAX) {
            freq = slot.freq + 1;
            g_q4_host_object_prefetch.request_freq[key] = freq;
        }
        slot.freq = freq;
        slot.score = q4_colibri_host_object_score(
                slot.marker,
                q4_colibri_host_object_score_current_layer(slot.marker.layer_idx),
                slot.freq);
        ++g_q4_host_object_prefetch.score_hit_refreshes;
    }
    if (slot_idx_out) *slot_idx_out = slot_idx;
    if (read_us_out) *read_us_out = slot.read_us;
    if (pilot_submitted_hit_out) *pilot_submitted_hit_out = slot.pilot_submitted;
    return true;
}

static bool q4_colibri_host_object_prefetch_release_acquired(
        size_t slot_idx,
        bool enqueue_ok,
        bool pilot_submitted_hit,
        cudaStream_t stream) {
    std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
    if (slot_idx >= g_q4_host_object_prefetch.slots.size()) return false;
    q4_colibri_host_object_slot &slot = g_q4_host_object_prefetch.slots[slot_idx];
    const bool completion_ok = enqueue_ok ?
        ggml_moe_common::object_host_cache_record_h2d(
            g_q4_host_object_prefetch, slot_idx, stream) :
        ggml_moe_common::object_host_cache_cancel_h2d(
            g_q4_host_object_prefetch, slot_idx, stream);
    slot.in_use = false;
    if (enqueue_ok && completion_ok) {
        if (pilot_submitted_hit) {
            slot.pilot_submitted = false;
        }
    }
    return completion_ok;
}

static bool q4_lossless_host_cache_h2d_acquired(
        q4_colibri_object_job &job,
        size_t slot_idx,
        uint64_t read_us,
        bool pilot_submitted_hit);

static bool q4_colibri_host_object_prefetch_h2d_acquired(
        q4_colibri_object_job &job,
        size_t slot_idx,
        uint64_t read_us,
        bool pilot_submitted_hit) {
    if (slot_idx >= g_q4_host_object_prefetch.slots.size()) return false;
    q4_colibri_host_object_slot *slot_ptr = &g_q4_host_object_prefetch.slots[slot_idx];
    if (!slot_ptr->host || !q4_colibri_object_marker_matches(slot_ptr->marker, job.marker)) {
        (void)q4_colibri_host_object_prefetch_release_acquired(
            slot_idx, false, pilot_submitted_hit, g_q4_colibri_pipe.stream);
        return false;
    }
    if (slot_ptr->payload_format ==
            ggml_moe_common::object_host_payload_format::lossless_sidecar) {
        return q4_lossless_host_cache_h2d_acquired(
            job, slot_idx, read_us, pilot_submitted_hit);
    }

    q4_tier_diag_record_ram_hit(job.marker);
    bool ok = true;
    const auto h2d_start = std::chrono::steady_clock::now();
    uint64_t copied_roles = 0;
    uint64_t copied_bytes = 0;
    const uint8_t hit_origin = slot_ptr->origin;
    if (q4_colibri_object_h2d_batch_enabled()) {
        ok = q4_colibri_enqueue_object_role_h2d(
                job, slot_ptr->host, g_q4_colibri_pipe.stream, &copied_roles, &copied_bytes);
    } else {
        for (size_t role_idx = 0; role_idx < job.role_count; ++role_idx) {
            q4_colibri_object_role_job &role = job.roles[role_idx];
            uint64_t role_relative_offset = 0;
            if (!q4_colibri_object_role_marker_matches(role) ||
                    !q4_colibri_role_in_read_span(role, job.offset, job.bytes, &role_relative_offset)) {
                ok = false;
                break;
            }
            const ggml_moe_common::role_cache_view role_view = batch_cache_role_view(role.cache);
            if (!ggml_moe_common::role_cache_ensure_ready_event(role_view, role.slot)) {
                ok = false;
                break;
            }
            role.cache->slot_state[role.slot] = q4_colibri_slot_state::reading;
            const void *role_host = (const char *)slot_ptr->host + role_relative_offset;
            if (cudaMemcpyAsync(role.dst, role_host, role.entry->nbytes,
                        cudaMemcpyHostToDevice, g_q4_colibri_pipe.stream) != cudaSuccess ||
                    !ggml_moe_common::role_cache_record_ready_event(
                        role_view, role.slot, g_q4_colibri_pipe.stream)) {
                ok = false;
                break;
            }
            role.cache->slot_ready_marker[role.slot] = role.marker;
            role.cache->slot_state[role.slot] = q4_colibri_slot_state::h2d_ready;
            role.cache->slot_pending[role.slot] = true;
            role.cache->slot_filling[role.slot] = false;
            ++g_q4_colibri_pipe.ring.copies;
            ++g_expert_pack.iouring_h2d_enqueues;
            ++copied_roles;
            copied_bytes += role.entry->nbytes;
        }
    }
    if (!ok) cudaGetLastError();

    if (!q4_colibri_host_object_prefetch_release_acquired(
                slot_idx, ok, pilot_submitted_hit, g_q4_colibri_pipe.stream)) {
        return false;
    }
    if (ok && q4_tier_delete_ram_on_h2d_enabled()) {
        (void)q4_colibri_host_object_delete_after_h2d(slot_idx);
    }
    if (!ok) return false;

    ++g_q4_host_object_prefetch.hits;
    q4_colibri_host_object_record_layer_hit(
            q4_colibri_host_object_ram_eligible_layer(job.marker.layer_idx));
    if (pilot_submitted_hit) {
        ++g_expert_pack.q4_pilot_prefetch_precision_hit_objects;
        g_expert_pack.q4_pilot_prefetch_precision_hit_roles.fetch_add(job.role_count, std::memory_order_relaxed);
        g_expert_pack.q4_pilot_prefetch_precision_hit_bytes.fetch_add(job.bytes, std::memory_order_relaxed);
        if (job.marker.layer_idx >= 0 && job.marker.layer_idx < 128) {
            ++g_expert_pack.q4_pilot_prefetch_precision_layer_hit_objects[job.marker.layer_idx];
            g_expert_pack.q4_pilot_prefetch_precision_layer_hit_roles[job.marker.layer_idx].fetch_add(
                    job.role_count, std::memory_order_relaxed);
            g_expert_pack.q4_pilot_prefetch_precision_layer_hit_bytes[job.marker.layer_idx].fetch_add(
                    job.bytes, std::memory_order_relaxed);
        }
    }
    ++g_expert_pack.q4_object_ram_hits;
    ++g_expert_pack.q4_object_full_expert_hits;
    g_expert_pack.q4_pilot_prefetch_used_roles.fetch_add(job.role_count, std::memory_order_relaxed);
    g_expert_pack.q4_object_ram_bytes_avoided.fetch_add(job.bytes, std::memory_order_relaxed);
    g_expert_pack.q4_object_ram_wait_us_avoided.fetch_add(read_us, std::memory_order_relaxed);
    if (job.marker.layer_idx >= 0 && job.marker.layer_idx < 64) {
        ++g_expert_pack.q4_object_layer_ram_hits[job.marker.layer_idx];
        q4_object_layer_add(g_expert_pack.q4_object_layer_ram_bytes_avoided, job.marker.layer_idx, job.bytes);
        q4_object_layer_add(g_expert_pack.q4_object_layer_ram_wait_us_avoided, job.marker.layer_idx, read_us);
    }
    const uint64_t h2d_us = (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now() - h2d_start).count();
    if (slot_ptr->host_registered) {
        ++g_q4_host_object_prefetch.registered_pageable_hits;
        g_q4_host_object_prefetch.registered_pageable_h2d_bytes.fetch_add(
            copied_bytes, std::memory_order_relaxed);
        g_q4_host_object_prefetch.registered_pageable_h2d_us.fetch_add(
            h2d_us, std::memory_order_relaxed);
    } else if (slot_ptr->pageable) {
        ++g_q4_host_object_prefetch.pageable_hits;
        g_q4_host_object_prefetch.pageable_h2d_bytes.fetch_add(copied_bytes, std::memory_order_relaxed);
        g_q4_host_object_prefetch.pageable_h2d_us.fetch_add(h2d_us, std::memory_order_relaxed);
    } else {
        ++g_q4_host_object_prefetch.pinned_hits;
        g_q4_host_object_prefetch.pinned_h2d_bytes.fetch_add(copied_bytes, std::memory_order_relaxed);
        g_q4_host_object_prefetch.pinned_h2d_us.fetch_add(h2d_us, std::memory_order_relaxed);
    }
    q4_host_object_origin_record_hit(hit_origin, copied_roles, copied_bytes);
    g_q4_host_object_prefetch.h2d_roles.fetch_add(copied_roles, std::memory_order_relaxed);
    g_q4_host_object_prefetch.h2d_bytes.fetch_add(copied_bytes, std::memory_order_relaxed);
    if (q4_colibri_object_h2d_batch_enabled()) {
        q4_colibri_object_h2d_batch_record(true, 1, copied_roles, copied_bytes, h2d_us);
    }
    g_q4_host_object_prefetch.h2d_us.fetch_add(h2d_us, std::memory_order_relaxed);
    g_expert_pack.q4_object_ram_h2d_us.fetch_add(h2d_us, std::memory_order_relaxed);
    g_expert_pack.q4_object_ram_h2d_bytes.fetch_add(job.bytes, std::memory_order_relaxed);
    q4_object_layer_add(g_expert_pack.q4_object_layer_ram_h2d_us, job.marker.layer_idx, h2d_us);
    q4_object_layer_add(g_expert_pack.q4_object_layer_ram_h2d_bytes, job.marker.layer_idx, job.bytes);
    g_expert_pack.q4_scheduler_h2d_us.fetch_add(h2d_us, std::memory_order_relaxed);
    q4_layer_io_add(g_expert_pack.q4_layer_io_h2d_us, job.marker.layer_idx, h2d_us);
    return true;
}

static bool q4_colibri_host_object_prefetch_try_h2d(q4_colibri_object_job &job) {
    size_t slot_idx = SIZE_MAX;
    uint64_t read_us = 0;
    bool pilot_submitted_hit = false;
    if (!q4_colibri_host_object_prefetch_acquire(job, &slot_idx, &read_us, &pilot_submitted_hit)) {
        return false;
    }
    return q4_colibri_host_object_prefetch_h2d_acquired(job, slot_idx, read_us, pilot_submitted_hit);
}

static void q4_colibri_object_job_fail(q4_colibri_object_job &job) {
    for (size_t role_idx = 0; role_idx < job.role_count; ++role_idx) {
        q4_colibri_object_role_job &role = job.roles[role_idx];
        if (q4_colibri_object_role_marker_matches(role)) {
            role.cache->slot_state[role.slot] = q4_colibri_slot_state::failed;
            role.cache->slot_filling[role.slot] = false;
        }
    }
}

static bool q4_colibri_pipe_h2d_object_from_stage(
        q4_colibri_object_job &job,
        pinned_stage_slot &stage,
        bool ram_hit,
        bool record_object_h2d = true) {
    const auto h2d_start = std::chrono::steady_clock::now();
    if (ram_hit) {
        ++g_expert_pack.q4_object_ram_hits;
        ++g_expert_pack.q4_object_full_expert_hits;
        g_expert_pack.q4_object_ram_bytes_avoided.fetch_add(job.bytes);
        g_expert_pack.q4_object_ram_wait_us_avoided.fetch_add(stage.object_read_us);
        if (job.marker.layer_idx >= 0 && job.marker.layer_idx < 64) {
            ++g_expert_pack.q4_object_layer_ram_hits[job.marker.layer_idx];
            q4_object_layer_add(g_expert_pack.q4_object_layer_ram_bytes_avoided, job.marker.layer_idx, job.bytes);
            q4_object_layer_add(g_expert_pack.q4_object_layer_ram_wait_us_avoided, job.marker.layer_idx, stage.object_read_us);
        }
        g_expert_pack.q4_object_ram_h2d_bytes.fetch_add(job.bytes);
    }
    uint64_t copied_roles = 0;
    uint64_t copied_bytes = 0;
    if (q4_colibri_object_h2d_batch_enabled()) {
        if (!q4_colibri_enqueue_object_role_h2d(
                    job, stage.host, g_q4_colibri_pipe.stream, &copied_roles, &copied_bytes)) {
            return false;
        }
    } else {
        for (size_t role_idx = 0; role_idx < job.role_count; ++role_idx) {
            q4_colibri_object_role_job &role = job.roles[role_idx];
            uint64_t role_relative_offset = 0;
            if (!q4_colibri_object_role_marker_matches(role) ||
                    !q4_colibri_role_in_read_span(role, job.offset, job.bytes, &role_relative_offset)) {
                return false;
            }
            const ggml_moe_common::role_cache_view role_view = batch_cache_role_view(role.cache);
            if (!ggml_moe_common::role_cache_ensure_ready_event(role_view, role.slot)) {
                return false;
            }
            const void *role_host = (const char *)stage.host + role_relative_offset;
            if (cudaMemcpyAsync(role.dst, role_host, role.entry->nbytes,
                        cudaMemcpyHostToDevice, g_q4_colibri_pipe.stream) != cudaSuccess ||
                    !ggml_moe_common::role_cache_record_ready_event(
                        role_view, role.slot, g_q4_colibri_pipe.stream)) {
                return false;
            }
            role.cache->slot_ready_marker[role.slot] = role.marker;
            role.cache->slot_state[role.slot] = q4_colibri_slot_state::h2d_ready;
            role.cache->slot_pending[role.slot] = true;
            role.cache->slot_filling[role.slot] = false;
            ++copied_roles;
            copied_bytes += role.entry->nbytes;
        }
    }
    if (cudaEventRecord(stage.done, g_q4_colibri_pipe.stream) != cudaSuccess) return false;
    stage.pending = true;
    if (!q4_colibri_object_h2d_batch_enabled()) {
        g_q4_colibri_pipe.ring.copies += job.role_count;
    }
    const uint64_t h2d_us = (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now() - h2d_start).count();
    if (record_object_h2d && q4_colibri_object_h2d_batch_enabled()) {
        q4_colibri_object_h2d_batch_record(ram_hit, 1, copied_roles, copied_bytes, h2d_us);
    }
    if (ram_hit) {
        g_expert_pack.q4_object_ram_h2d_us.fetch_add(h2d_us, std::memory_order_relaxed);
        q4_object_layer_add(g_expert_pack.q4_object_layer_ram_h2d_us, job.marker.layer_idx, h2d_us);
        q4_object_layer_add(g_expert_pack.q4_object_layer_ram_h2d_bytes, job.marker.layer_idx, job.bytes);
    }
    g_expert_pack.q4_scheduler_h2d_us.fetch_add(h2d_us, std::memory_order_relaxed);
    q4_layer_io_add(g_expert_pack.q4_layer_io_h2d_us, job.marker.layer_idx, h2d_us);
    return true;
}

static const ggml_moe_common::lossless_object_record *q4_lossless_record_for_job(
        const q4_colibri_object_job &job) {
    if (g_expert_pack.lossless_mode != q4_lossless_transport_mode::cuda ||
            !g_q4_colibri_pipe.lossless_ready || job.partial_span) {
        if (g_expert_pack.lossless_standalone) {
            q4_colibri_fail(
                "standalone lossless transport cannot use a raw or partial object");
        }
        return nullptr;
    }
    ++g_expert_pack.lossless_object_lookups;
    const ggml_moe_common::lossless_object_record *record =
        ggml_moe_common::lossless_sidecar_find(
            g_expert_pack.lossless_sidecar,
            job.marker.layer_idx,
            job.marker.expert_idx);
    if (record) ++g_expert_pack.lossless_object_hits;
    if (!record && g_expert_pack.lossless_standalone) {
        q4_colibri_fail("standalone lossless transport has no object record");
    }
    return record;
}

struct q4_lossless_pending_decode {
    q4_colibri_object_job *job = nullptr;
    const ggml_moe_common::lossless_object_record *object = nullptr;
    pinned_stage_slot *stage = nullptr;
    size_t status_offset = 0;
    size_t status_count = 0;
    size_t crc32_offset = 0;
    size_t object_index = SIZE_MAX;
    bool crc_required = false;
    bool host_cache_processed = false;
    uint64_t read_us = 0;
};

static bool q4_lossless_enqueue_object_from_stage(
        q4_colibri_object_job &job,
        const ggml_moe_common::lossless_object_record &object,
        const void *host_payload,
        size_t host_payload_bytes,
        pinned_stage_slot *stage,
        uint64_t read_us,
        size_t status_offset,
        size_t crc32_offset,
        size_t input_slot,
        bool defer_decode,
        q4_lossless_pending_decode &pending) {
    if (!g_q4_colibri_pipe.lossless_ready || !host_payload ||
            host_payload_bytes < object.payload_bytes ||
            object.payload_bytes > object.physical_bytes ||
            object.payload_bytes > g_q4_colibri_pipe.lossless_device_input_stride ||
            input_slot >= g_q4_colibri_pipe.lossless_device_input_slots ||
            object.raw_bytes != job.bytes || job.role_count == 0 || job.role_count > 3) {
        return false;
    }
    uint8_t *device_input = g_q4_colibri_pipe.lossless_device_input +
        input_slot * g_q4_colibri_pipe.lossless_device_input_stride;
    const ggml_moe_common::lossless_object_record *objects_begin =
        g_expert_pack.lossless_sidecar.objects.data();
    const size_t object_index = static_cast<size_t>(&object - objects_begin);
    if (object_index >= g_expert_pack.lossless_sidecar.objects.size() ||
            object_index >= g_q4_colibri_pipe.lossless_crc_verified.size()) {
        return false;
    }
    const bool crc_required =
        g_q4_colibri_pipe.lossless_crc_verified[object_index] == 0;
    std::vector<ggml_moe_common::lossless_q40_decode_descriptor> descriptors;
    descriptors.reserve(g_expert_pack.lossless_sidecar.chunks_per_role * job.role_count);
    for (size_t job_role_index = 0;
            job_role_index < job.role_count;
            ++job_role_index) {
        q4_colibri_object_role_job &job_role = job.roles[job_role_index];
        const int role_index = q4_lossless_role_index(job_role.tensor);
        if (role_index < 0 || !job_role.entry ||
                !q4_colibri_object_role_marker_matches(job_role)) {
            ++g_expert_pack.lossless_parse_failures;
            return false;
        }
        const ggml_moe_common::lossless_role_record &role = object.roles[role_index];
        if (role.raw_offset != job_role.entry->offset ||
                role.raw_bytes != job_role.entry->nbytes ||
                role.payload_offset + role.payload_bytes > object.payload_bytes) {
            ++g_expert_pack.lossless_parse_failures;
            return false;
        }
        const ggml_moe_common::role_cache_view role_view =
            batch_cache_role_view(job_role.cache);
        if (!ggml_moe_common::role_cache_ensure_ready_event(
                role_view, job_role.slot)) {
            ++g_expert_pack.lossless_cuda_failures;
            ++g_expert_pack.lossless_enqueue_failures[0];
            return false;
        }
        if (role.codec == ggml_moe_common::lossless_role_codec::raw) {
            if (role.payload_bytes != role.raw_bytes) {
                ++g_expert_pack.lossless_parse_failures;
                return false;
            }
            continue;
        }
        if (role.chunks > g_q4_colibri_pipe.lossless_chunks.size() ||
                !ggml_moe_common::lossless_sidecar_parse_chunks(
                    role,
                    static_cast<const uint8_t *>(host_payload),
                    object.payload_bytes,
                    g_q4_colibri_pipe.lossless_chunks.data(),
                    g_q4_colibri_pipe.lossless_chunks.size())) {
            ++g_expert_pack.lossless_parse_failures;
            return false;
        }
        const size_t scale_record_count = role.scale_records;
        if (role.scale_codec ==
                ggml_moe_common::lossless_q40_scale_codec::rans_nibble_planes &&
                (scale_record_count >
                    g_q4_colibri_pipe.lossless_scale_records.size() ||
                 !ggml_moe_common::lossless_sidecar_parse_scale_records(
                    role, static_cast<const uint8_t *>(host_payload),
                    object.payload_bytes,
                    g_q4_colibri_pipe.lossless_scale_records.data(),
                    g_q4_colibri_pipe.lossless_scale_records.size()))) {
            ++g_expert_pack.lossless_parse_failures;
            return false;
        }
        for (uint32_t chunk_index = 0;
                chunk_index < role.chunks;
                ++chunk_index) {
            const ggml_moe_common::lossless_chunk_record &chunk =
                g_q4_colibri_pipe.lossless_chunks[chunk_index];
            ggml_moe_common::lossless_q40_decode_descriptor descriptor;
            descriptor.record =
                device_input +
                role.payload_offset + chunk.record_offset;
            descriptor.record_bytes = chunk.record_bytes;
            descriptor.scales = role.scale_codec ==
                    ggml_moe_common::lossless_q40_scale_codec::raw ?
                device_input + role.payload_offset + role.scales_offset : nullptr;
            descriptor.scale_bytes = role.scale_codec ==
                    ggml_moe_common::lossless_q40_scale_codec::raw ?
                role.scales_bytes : role.scale_raw_bytes;
            bool writes_compressed_scales = false;
            if (role.scale_codec ==
                    ggml_moe_common::lossless_q40_scale_codec::rans_nibble_planes) {
                const uint32_t scale_chunks = role.scale_records /
                    ggml_moe_common::lossless_rans_q40_scale_planes;
                for (uint32_t scale_chunk = 0;
                        scale_chunk < scale_chunks;
                        ++scale_chunk) {
                    if (scale_chunk * role.chunks / scale_chunks != chunk_index) {
                        continue;
                    }
                    const uint64_t scale_values = role.scale_raw_bytes / 2;
                    const uint64_t quotient = scale_values / scale_chunks;
                    const uint64_t remainder = scale_values % scale_chunks;
                    descriptor.scale_value_offset =
                        static_cast<uint64_t>(scale_chunk) * quotient +
                        std::min<uint64_t>(scale_chunk, remainder);
                    descriptor.scale_value_count = quotient +
                        (scale_chunk < remainder ? 1 : 0);
                    const size_t base = static_cast<size_t>(scale_chunk) *
                        ggml_moe_common::lossless_rans_q40_scale_planes;
                    for (size_t scale_plane = 0;
                            scale_plane <
                                ggml_moe_common::lossless_rans_q40_scale_planes;
                            ++scale_plane) {
                        const ggml_moe_common::lossless_scale_record &scale_record =
                            g_q4_colibri_pipe.lossless_scale_records[base + scale_plane];
                        descriptor.scale_records[scale_plane] =
                            device_input + role.payload_offset +
                                scale_record.record_offset;
                        descriptor.scale_record_bytes[scale_plane] =
                            scale_record.record_bytes;
                    }
                    writes_compressed_scales = true;
                    break;
                }
            }
            descriptor.destination = static_cast<uint8_t *>(job_role.dst);
            descriptor.destination_bytes = role.raw_bytes;
            descriptor.quant_byte_offset = chunk.quant_byte_offset;
            descriptor.rows = role.rows;
            descriptor.blocks_per_row = role.blocks_per_row;
            descriptor.scale_layout = role.scale_layout;
            descriptor.scale_codec = role.scale_codec;
            descriptor.write_scales = role.scale_codec ==
                    ggml_moe_common::lossless_q40_scale_codec::raw ?
                (chunk_index == 0 ? 1U : 0U) :
                (writes_compressed_scales ? 1U : 0U);
            descriptors.push_back(descriptor);
        }
    }

    const size_t descriptor_count = descriptors.size();
    if (status_offset > g_q4_colibri_pipe.lossless_status_capacity ||
            descriptor_count >
                g_q4_colibri_pipe.lossless_status_capacity - status_offset) {
        ++g_expert_pack.lossless_cuda_failures;
        ++g_expert_pack.lossless_enqueue_failures[1];
        ++g_expert_pack.lossless_enqueue_h2d_detail[0];
        return false;
    }
    if (crc_required &&
            (crc32_offset > g_q4_colibri_pipe.lossless_crc32_capacity ||
             ggml_moe_common::lossless_crc32_segments >
                g_q4_colibri_pipe.lossless_crc32_capacity - crc32_offset)) {
        ++g_expert_pack.lossless_cuda_failures;
        ++g_expert_pack.lossless_enqueue_failures[1];
        ++g_expert_pack.lossless_enqueue_h2d_detail[1];
        return false;
    }
    if (cudaMemcpyAsync(
            device_input,
            host_payload,
            object.payload_bytes,
            cudaMemcpyHostToDevice,
            q4_lossless_cuda_stream()) != cudaSuccess) {
        ++g_expert_pack.lossless_cuda_failures;
        ++g_expert_pack.lossless_enqueue_failures[1];
        ++g_expert_pack.lossless_enqueue_h2d_detail[2];
        return false;
    }
    if (crc_required) {
        if (!ggml_moe_common::lossless_rans_cuda_crc32_async(
                g_q4_colibri_pipe.lossless_decoder,
                device_input,
                object.payload_bytes,
                q4_lossless_cuda_stream()) ||
                cudaMemcpyAsync(
                    g_q4_colibri_pipe.lossless_crc32_host + crc32_offset,
                    ggml_moe_common::lossless_rans_cuda_crc32_partials_device(
                        g_q4_colibri_pipe.lossless_decoder),
                    ggml_moe_common::lossless_crc32_segments * sizeof(uint32_t),
                    cudaMemcpyDeviceToHost,
                    q4_lossless_cuda_stream()) != cudaSuccess) {
            ++g_expert_pack.lossless_cuda_failures;
            ++g_expert_pack.lossless_enqueue_failures[2];
            return false;
        }
    } else {
        ++g_expert_pack.lossless_crc_reuses;
    }
    for (size_t job_role_index = 0;
            job_role_index < job.role_count;
            ++job_role_index) {
        q4_colibri_object_role_job &job_role = job.roles[job_role_index];
        const int role_index = q4_lossless_role_index(job_role.tensor);
        const ggml_moe_common::lossless_role_record &role = object.roles[role_index];
        if (role.codec == ggml_moe_common::lossless_role_codec::raw &&
                cudaMemcpyAsync(
                    job_role.dst,
                    device_input +
                        role.payload_offset,
                    role.raw_bytes,
                    cudaMemcpyDeviceToDevice,
                    q4_lossless_cuda_stream()) != cudaSuccess) {
            ++g_expert_pack.lossless_cuda_failures;
            ++g_expert_pack.lossless_enqueue_failures[3];
            return false;
        }
    }
    if (descriptor_count > 0) {
        if (defer_decode) {
            if (status_offset != g_q4_colibri_pipe.lossless_descriptors.size()) {
                ++g_expert_pack.lossless_parse_failures;
                return false;
            }
        } else {
            g_q4_colibri_pipe.lossless_descriptors = std::move(descriptors);
            if (!ggml_moe_common::lossless_rans_cuda_decode_q40_async(
                        g_q4_colibri_pipe.lossless_decoder,
                        g_q4_colibri_pipe.lossless_descriptors.data(),
                        descriptor_count,
                        q4_lossless_cuda_stream()) ||
                    cudaMemcpyAsync(
                        g_q4_colibri_pipe.lossless_status_host + status_offset,
                        ggml_moe_common::lossless_rans_cuda_status_device(
                            g_q4_colibri_pipe.lossless_decoder),
                        descriptor_count * sizeof(uint32_t),
                        cudaMemcpyDeviceToHost,
                        q4_lossless_cuda_stream()) != cudaSuccess) {
                ++g_expert_pack.lossless_cuda_failures;
                ++g_expert_pack.lossless_enqueue_failures[4];
                return false;
            }
            ++g_expert_pack.lossless_decode_launches;
            ++g_expert_pack.lossless_decode_objects;
            g_expert_pack.lossless_decode_max_batch.store(
                std::max<uint64_t>(
                    g_expert_pack.lossless_decode_max_batch.load(std::memory_order_relaxed), 1),
                std::memory_order_relaxed);
        }
    }
    if (stage && !defer_decode && !ggml_moe_common::object_stage_slot_record(
            *stage, q4_lossless_cuda_stream())) {
        ++g_expert_pack.lossless_cuda_failures;
        ++g_expert_pack.lossless_enqueue_failures[5];
        return false;
    }
    if (defer_decode && descriptor_count > 0) {
        g_q4_colibri_pipe.lossless_descriptors.insert(
            g_q4_colibri_pipe.lossless_descriptors.end(),
            descriptors.begin(), descriptors.end());
    }
    g_expert_pack.lossless_h2d_bytes.fetch_add(
        object.payload_bytes, std::memory_order_relaxed);
    pending = {
        &job,
        &object,
        stage,
        status_offset,
        descriptor_count,
        crc32_offset,
        object_index,
        crc_required,
        false,
        read_us,
    };
    return true;
}

static bool q4_lossless_finalize_decode_batch(
        size_t object_count,
        size_t status_output_offset = 0) {
    const size_t descriptor_count =
        g_q4_colibri_pipe.lossless_descriptors.size();
    if (object_count == 0 || descriptor_count == 0 ||
            descriptor_count > g_q4_colibri_pipe.lossless_status_capacity ||
            status_output_offset > g_q4_colibri_pipe.lossless_status_capacity ||
            descriptor_count >
                g_q4_colibri_pipe.lossless_status_capacity - status_output_offset ||
            !ggml_moe_common::lossless_rans_cuda_decode_q40_async(
                g_q4_colibri_pipe.lossless_decoder,
                g_q4_colibri_pipe.lossless_descriptors.data(),
                descriptor_count,
                q4_lossless_cuda_stream()) ||
            cudaMemcpyAsync(
                g_q4_colibri_pipe.lossless_status_host + status_output_offset,
                ggml_moe_common::lossless_rans_cuda_status_device(
                    g_q4_colibri_pipe.lossless_decoder),
                descriptor_count * sizeof(uint32_t),
                cudaMemcpyDeviceToHost,
                q4_lossless_cuda_stream()) != cudaSuccess) {
        ++g_expert_pack.lossless_cuda_failures;
        return false;
    }
    ++g_expert_pack.lossless_decode_launches;
    g_expert_pack.lossless_decode_objects.fetch_add(
        object_count, std::memory_order_relaxed);
    uint64_t previous =
        g_expert_pack.lossless_decode_max_batch.load(std::memory_order_relaxed);
    while (previous < object_count &&
            !g_expert_pack.lossless_decode_max_batch.compare_exchange_weak(
                previous, object_count, std::memory_order_relaxed)) {
    }
    return true;
}

static void q4_lossless_invalidate_early_host_admission(
        const q4_colibri_object_marker &marker,
        uint64_t record_identity) {
    std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
    size_t slot_idx = SIZE_MAX;
    if (!q4_colibri_host_object_find_ready_locked(marker, &slot_idx) ||
            slot_idx >= g_q4_host_object_prefetch.slots.size()) {
        return;
    }
    const q4_colibri_host_object_slot &slot =
        g_q4_host_object_prefetch.slots[slot_idx];
    if (slot.payload_format !=
                ggml_moe_common::object_host_payload_format::lossless_sidecar ||
            slot.payload_record_identity != record_identity) {
        return;
    }
    if (q4_colibri_host_object_clear_slot_locked(slot_idx, false)) {
        ++g_expert_pack.lossless_async_cache_invalidations;
    }
}

static bool q4_lossless_publish_decoded(
        const q4_lossless_pending_decode &pending,
        bool validate_status = true) {
    if (!pending.job || !pending.object ||
            pending.status_offset > g_q4_colibri_pipe.lossless_status_capacity ||
            pending.status_count >
                g_q4_colibri_pipe.lossless_status_capacity - pending.status_offset) {
        return false;
    }
    static std::atomic<bool> crc_fault_injected{false};
    if (!validate_status && pending.crc_required) return false;
    const bool inject_crc_failure = validate_status && pending.crc_required &&
        expert_pack_env_bool(
            "GGML_MOE_GLM52_LOSSLESS_TEST_INJECT_CRC_FAILURE", false) &&
        !crc_fault_injected.exchange(true, std::memory_order_relaxed);
    if (validate_status && pending.crc_required) {
        if (pending.object_index >=
                    g_q4_colibri_pipe.lossless_crc_verified.size() ||
                pending.crc32_offset >
                    g_q4_colibri_pipe.lossless_crc32_capacity ||
                ggml_moe_common::lossless_crc32_segments >
                    g_q4_colibri_pipe.lossless_crc32_capacity -
                        pending.crc32_offset ||
                inject_crc_failure ||
                ggml_moe_common::lossless_crc32_combine_segments(
                    g_q4_colibri_pipe.lossless_crc32_host +
                        pending.crc32_offset,
                    pending.object->payload_bytes) !=
                    pending.object->payload_crc32) {
            ++g_expert_pack.lossless_crc_failures;
            return false;
        }
        g_q4_colibri_pipe.lossless_crc_verified[pending.object_index] = 1;
        ++g_expert_pack.lossless_crc_objects;
    }
    if (validate_status) {
        for (size_t descriptor_index = 0;
                descriptor_index < pending.status_count;
                ++descriptor_index) {
            const uint32_t status = g_q4_colibri_pipe.lossless_status_host[
                pending.status_offset + descriptor_index];
            if (status != 0) {
                ++g_expert_pack.lossless_cuda_failures;
                if (status < 6) {
                    ++g_expert_pack.lossless_status_failures[status];
                }
                static std::atomic<uint64_t> reported{0};
                const uint64_t report_index = reported.fetch_add(
                    1, std::memory_order_relaxed);
                if (report_index < 16 && expert_pack_env_bool(
                        "GGML_MOE_LOSSLESS_DEBUG_FAILURES", false)) {
                    std::fprintf(stderr,
                        "[moe_stream_batch] lossless decode failure: "
                        "status=%u descriptor=%zu/%zu layer=%d expert=%d "
                        "sidecar_object=%zu payload=%lu raw=%lu\n",
                        status, descriptor_index, pending.status_count,
                        pending.job ? pending.job->marker.layer_idx : -1,
                        pending.job ? pending.job->marker.expert_idx : -1,
                        pending.object_index,
                        pending.object ?
                            (unsigned long)pending.object->payload_bytes : 0UL,
                        pending.object ?
                            (unsigned long)pending.object->raw_bytes : 0UL);
                }
                return false;
            }
        }
    }
    for (size_t role_index = 0;
            role_index < pending.job->role_count;
            ++role_index) {
        q4_colibri_object_role_job &role = pending.job->roles[role_index];
        const ggml_moe_common::role_cache_view role_view =
            batch_cache_role_view(role.cache);
        if (!q4_colibri_object_role_marker_matches(role) ||
                !ggml_moe_common::role_cache_record_ready_event(
                    role_view, role.slot, q4_lossless_cuda_stream())) {
            ++g_expert_pack.lossless_cuda_failures;
            ++g_expert_pack.lossless_publish_failures;
            return false;
        }
        role.cache->slot_ready_marker[role.slot] = role.marker;
        role.cache->slot_state[role.slot] = q4_colibri_slot_state::h2d_ready;
        role.cache->slot_pending[role.slot] = true;
        role.cache->slot_filling[role.slot] = false;
    }
    g_q4_colibri_pipe.ring.copies += pending.job->role_count;
    g_expert_pack.lossless_decoded_bytes.fetch_add(
        pending.object->raw_bytes, std::memory_order_relaxed);
    return true;
}

static bool q4_lossless_raw_fallback(
        q4_colibri_object_job &job,
        pinned_stage_slot &stage) {
    if (g_expert_pack.lossless_standalone) {
        q4_colibri_fail("standalone lossless transport attempted raw fallback");
    }
    expert_pack_source *source = nullptr;
    for (size_t role_index = 0; role_index < job.role_count; ++role_index) {
        expert_pack_source *candidate =
            expert_pack_source_for_entry(job.roles[role_index].entry);
        if (!candidate || candidate->fd_direct < 0 ||
                (source && source != candidate)) {
            return false;
        }
        source = candidate;
    }
    if (!source || !expert_pack_direct_pread_all(
            source->fd_direct, stage.host, (size_t)job.bytes, job.offset)) {
        return false;
    }
    ++g_expert_pack.lossless_object_fallbacks;
    ++g_expert_pack.q4_object_ssd_reads;
    g_expert_pack.q4_object_ssd_bytes.fetch_add(
        job.bytes, std::memory_order_relaxed);
    g_expert_pack.lossless_raw_fallback_bytes.fetch_add(
        job.bytes, std::memory_order_relaxed);
    return q4_colibri_pipe_h2d_object_from_stage(
        job, stage, false, false);
}

static bool q4_lossless_host_cache_raw_fallback(
        q4_colibri_object_job &job,
        size_t slot_idx,
        bool pilot_submitted_hit,
        const char *reason) {
    if (g_expert_pack.lossless_standalone) {
        q4_colibri_fail(std::string(
            "standalone lossless transport attempted Host-cache raw fallback: ") +
            (reason ? reason : "unknown") + " layer=" +
            std::to_string(job.marker.layer_idx) + " expert=" +
            std::to_string(job.marker.expert_idx));
    }
    expert_pack_source *source = nullptr;
    for (size_t role_index = 0; role_index < job.role_count; ++role_index) {
        expert_pack_source *candidate =
            expert_pack_source_for_entry(job.roles[role_index].entry);
        if (!candidate || candidate->fd_direct < 0 ||
                (source && source != candidate)) {
            return false;
        }
        source = candidate;
    }
    if (!source || slot_idx >= g_q4_host_object_prefetch.slots.size()) return false;

    q4_colibri_host_object_slot *slot_ptr = nullptr;
    {
        std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
        if (slot_idx >= g_q4_host_object_prefetch.slots.size()) return false;
        q4_colibri_host_object_slot &slot = g_q4_host_object_prefetch.slots[slot_idx];
        if (slot.pending_h2d &&
                ggml_moe_common::object_host_cache_synchronize_h2d(
                    g_q4_host_object_prefetch, slot_idx) !=
                ggml_moe_common::object_host_completion_state::complete) {
            return false;
        }
        if (!ggml_moe_common::object_host_cache_prepare_slot(
                g_q4_host_object_prefetch, slot_idx)) {
            return false;
        }
        slot.marker = job.marker;
        slot.ready = false;
        slot.loading = true;
        slot.in_use = true;
        slot.payload_format = ggml_moe_common::object_host_payload_format::raw_object;
        slot.payload_bytes = job.marker.bytes;
        slot.payload_transport_bytes = job.marker.bytes;
        slot.payload_crc32 = 0;
        slot.payload_record_identity = 0;
        slot_ptr = &slot;
    }

    const bool read_ok = expert_pack_direct_pread_all(
        source->fd_direct, slot_ptr->host, (size_t)job.bytes, job.offset);
    {
        std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
        q4_colibri_host_object_slot &slot = g_q4_host_object_prefetch.slots[slot_idx];
        slot.loading = false;
        slot.in_use = false;
        if (!read_ok || !ggml_moe_common::object_host_cache_publish_slot(
                g_q4_host_object_prefetch, slot_idx)) {
            (void)q4_colibri_host_object_clear_slot_locked(slot_idx, false);
            return false;
        }
        slot.ready = true;
        if (!ggml_moe_common::object_host_cache_begin_h2d(
                g_q4_host_object_prefetch, slot_idx)) {
            return false;
        }
        slot.in_use = true;
    }

    uint64_t copied_roles = 0;
    uint64_t copied_bytes = 0;
    const bool enqueue_ok = q4_colibri_enqueue_object_role_h2d(
        job, slot_ptr->host, g_q4_colibri_pipe.stream,
        &copied_roles, &copied_bytes);
    if (!q4_colibri_host_object_prefetch_release_acquired(
            slot_idx, enqueue_ok, pilot_submitted_hit,
            g_q4_colibri_pipe.stream) || !enqueue_ok) {
        return false;
    }
    ++g_expert_pack.lossless_object_fallbacks;
    ++g_expert_pack.lossless_host_cache_fallbacks;
    ++g_expert_pack.q4_object_ssd_reads;
    g_expert_pack.q4_object_ssd_bytes.fetch_add(
        job.bytes, std::memory_order_relaxed);
    g_expert_pack.lossless_raw_fallback_bytes.fetch_add(
        job.bytes, std::memory_order_relaxed);
    return true;
}

static void q4_lossless_host_cache_record_hit(
        q4_colibri_object_job &job,
        const ggml_moe_common::lossless_object_record &object,
        uint64_t read_us,
        bool pilot_submitted_hit,
        uint8_t hit_origin,
        size_t transport_bytes,
        uint64_t h2d_us) {
    q4_tier_diag_record_ram_hit(job.marker);
    ++g_q4_host_object_prefetch.hits;
    q4_colibri_host_object_record_layer_hit(
        q4_colibri_host_object_ram_eligible_layer(job.marker.layer_idx));
    ++g_expert_pack.q4_object_ram_hits;
    ++g_expert_pack.q4_object_full_expert_hits;
    ++g_expert_pack.lossless_host_cache_hits;
    g_expert_pack.lossless_host_cache_ssd_bytes_avoided.fetch_add(
        transport_bytes, std::memory_order_relaxed);
    g_expert_pack.lossless_host_cache_h2d_bytes.fetch_add(
        object.payload_bytes, std::memory_order_relaxed);
    g_expert_pack.q4_object_ram_bytes_avoided.fetch_add(
        job.bytes, std::memory_order_relaxed);
    g_expert_pack.q4_object_ram_wait_us_avoided.fetch_add(
        read_us, std::memory_order_relaxed);
    if (job.marker.layer_idx >= 0 && job.marker.layer_idx < 64) {
        ++g_expert_pack.q4_object_layer_ram_hits[job.marker.layer_idx];
        q4_object_layer_add(
            g_expert_pack.q4_object_layer_ram_bytes_avoided,
            job.marker.layer_idx,
            job.bytes);
        q4_object_layer_add(
            g_expert_pack.q4_object_layer_ram_wait_us_avoided,
            job.marker.layer_idx,
            read_us);
    }
    if (pilot_submitted_hit) {
        ++g_expert_pack.q4_pilot_prefetch_precision_hit_objects;
        g_expert_pack.q4_pilot_prefetch_precision_hit_roles.fetch_add(
            job.role_count, std::memory_order_relaxed);
        g_expert_pack.q4_pilot_prefetch_precision_hit_bytes.fetch_add(
            job.bytes, std::memory_order_relaxed);
    }
    q4_host_object_origin_record_hit(
        hit_origin, job.role_count, object.payload_bytes);
    g_q4_host_object_prefetch.h2d_roles.fetch_add(
        job.role_count, std::memory_order_relaxed);
    g_q4_host_object_prefetch.h2d_bytes.fetch_add(
        object.payload_bytes, std::memory_order_relaxed);
    g_q4_host_object_prefetch.h2d_us.fetch_add(
        h2d_us, std::memory_order_relaxed);
    g_expert_pack.q4_object_ram_h2d_us.fetch_add(
        h2d_us, std::memory_order_relaxed);
    g_expert_pack.q4_object_ram_h2d_bytes.fetch_add(
        object.payload_bytes, std::memory_order_relaxed);
    g_expert_pack.q4_scheduler_h2d_us.fetch_add(
        h2d_us, std::memory_order_relaxed);
    q4_object_layer_add(
        g_expert_pack.q4_object_layer_ram_h2d_us,
        job.marker.layer_idx,
        h2d_us);
    q4_object_layer_add(
        g_expert_pack.q4_object_layer_ram_h2d_bytes,
        job.marker.layer_idx,
        object.payload_bytes);
    q4_layer_io_add(
        g_expert_pack.q4_layer_io_h2d_us,
        job.marker.layer_idx,
        h2d_us);
    if (q4_colibri_object_h2d_batch_enabled()) {
        q4_colibri_object_h2d_batch_record(
            true, 1, job.role_count, object.payload_bytes, h2d_us);
    }
}

static bool q4_lossless_host_cache_h2d_acquired(
        q4_colibri_object_job &job,
        size_t slot_idx,
        uint64_t read_us,
        bool pilot_submitted_hit) {
    if (slot_idx >= g_q4_host_object_prefetch.slots.size()) return false;
    q4_colibri_host_object_slot *slot_ptr =
        &g_q4_host_object_prefetch.slots[slot_idx];
    const ggml_moe_common::lossless_object_record *object =
        ggml_moe_common::lossless_sidecar_find(
            g_expert_pack.lossless_sidecar,
            job.marker.layer_idx,
            job.marker.expert_idx);
    if (!object || !slot_ptr->host ||
            slot_ptr->payload_format !=
                ggml_moe_common::object_host_payload_format::lossless_sidecar ||
            slot_ptr->payload_bytes != object->payload_bytes ||
            slot_ptr->payload_crc32 != object->payload_crc32 ||
            slot_ptr->payload_record_identity != object->file_offset ||
            object->raw_bytes != job.bytes) {
        ++g_expert_pack.lossless_parse_failures;
        (void)q4_colibri_host_object_prefetch_release_acquired(
            slot_idx, false, pilot_submitted_hit,
            g_q4_colibri_pipe.stream);
        return false;
    }

    const uint8_t hit_origin = slot_ptr->origin;
    const size_t transport_bytes = slot_ptr->payload_transport_bytes;
    const auto h2d_start = std::chrono::steady_clock::now();
    q4_lossless_pending_decode pending;
    const bool enqueue_ok = q4_lossless_enqueue_object_from_stage(
        job, *object, slot_ptr->host, slot_ptr->payload_bytes, nullptr,
        read_us, 0, 0, 0, false, pending);
    if (!q4_colibri_host_object_prefetch_release_acquired(
            slot_idx, enqueue_ok, pilot_submitted_hit,
            q4_lossless_cuda_stream())) {
        return false;
    }
    if (!enqueue_ok) {
        return q4_lossless_host_cache_raw_fallback(
            job, slot_idx, pilot_submitted_hit, "single enqueue");
    }
    const bool publish_verified_async = !pending.crc_required &&
        expert_pack_env_bool(
            "GGML_MOE_LOSSLESS_ASYNC_TRUST_VERIFIED", false);
    if (publish_verified_async) {
        if (!q4_lossless_publish_decoded(pending, false)) {
            return q4_lossless_host_cache_raw_fallback(
                job, slot_idx, pilot_submitted_hit, "single async publish");
        }
        ++g_expert_pack.lossless_async_verified_batches;
        ++g_expert_pack.lossless_async_verified_objects;
        const uint64_t h2d_us =
            (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
                std::chrono::steady_clock::now() - h2d_start).count();
        q4_lossless_host_cache_record_hit(
            job, *object, read_us, pilot_submitted_hit, hit_origin,
            transport_bytes, h2d_us);
        return true;
    }
    if (cudaStreamSynchronize(q4_lossless_cuda_stream()) != cudaSuccess) {
        ++g_expert_pack.lossless_cuda_failures;
        return q4_lossless_host_cache_raw_fallback(
            job, slot_idx, pilot_submitted_hit, "single stream sync");
    }
    {
        std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
        if (ggml_moe_common::object_host_cache_synchronize_h2d(
                g_q4_host_object_prefetch, slot_idx) !=
                ggml_moe_common::object_host_completion_state::complete) {
            return false;
        }
    }
    if (!q4_lossless_publish_decoded(pending)) {
        return q4_lossless_host_cache_raw_fallback(
            job, slot_idx, pilot_submitted_hit, "single publish");
    }

    const uint64_t h2d_us = (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
        std::chrono::steady_clock::now() - h2d_start).count();
    q4_lossless_host_cache_record_hit(
        job, *object, read_us, pilot_submitted_hit, hit_origin,
        transport_bytes, h2d_us);
    return true;
}

struct q4_lossless_host_batch_pending {
    q4_colibri_deferred_host_hit hit;
    const ggml_moe_common::lossless_object_record *object = nullptr;
    q4_lossless_pending_decode decode;
    uint8_t hit_origin = Q4_HOST_OBJECT_ORIGIN_UNKNOWN;
    size_t transport_bytes = 0;
};

static bool q4_lossless_host_cache_h2d_batch_chunk(
        q4_colibri_object_batch &batch,
        const std::vector<q4_colibri_deferred_host_hit> &hits) {
    std::vector<q4_lossless_host_batch_pending> pending;
    pending.reserve(hits.size());
    size_t status_cursor = 0;
    size_t crc32_cursor = 0;
    const auto batch_start = std::chrono::steady_clock::now();
    g_q4_colibri_pipe.lossless_descriptors.clear();

    for (const q4_colibri_deferred_host_hit &hit : hits) {
        if (hit.job_idx >= batch.jobs.size() ||
                hit.slot_idx >= g_q4_host_object_prefetch.slots.size()) {
            return false;
        }
        q4_colibri_object_job &job = batch.jobs[hit.job_idx];
        q4_colibri_host_object_slot &slot =
            g_q4_host_object_prefetch.slots[hit.slot_idx];
        if (slot.payload_format !=
                ggml_moe_common::object_host_payload_format::lossless_sidecar) {
            if (g_expert_pack.lossless_standalone) {
                q4_colibri_fail(
                    "standalone lossless transport found a raw Host-cache entry");
            }
            if (!q4_colibri_host_object_prefetch_h2d_acquired(
                    job, hit.slot_idx, hit.read_us,
                    hit.pilot_submitted_hit)) {
                return false;
            }
            continue;
        }

        const ggml_moe_common::lossless_object_record *object =
            ggml_moe_common::lossless_sidecar_find(
                g_expert_pack.lossless_sidecar,
                job.marker.layer_idx,
                job.marker.expert_idx);
        if (!object || !slot.host ||
                slot.payload_bytes != object->payload_bytes ||
                slot.payload_crc32 != object->payload_crc32 ||
                slot.payload_record_identity != object->file_offset ||
                object->raw_bytes != job.bytes) {
            ++g_expert_pack.lossless_parse_failures;
            (void)q4_colibri_host_object_prefetch_release_acquired(
                hit.slot_idx, false, hit.pilot_submitted_hit,
                g_q4_colibri_pipe.stream);
            return false;
        }

        q4_lossless_host_batch_pending item;
        item.hit = hit;
        item.object = object;
        item.hit_origin = slot.origin;
        item.transport_bytes = slot.payload_transport_bytes;
        const bool enqueue_ok = q4_lossless_enqueue_object_from_stage(
            job, *object, slot.host, slot.payload_bytes, nullptr,
            hit.read_us, status_cursor, crc32_cursor, pending.size(), true,
            item.decode);
        if (!q4_colibri_host_object_prefetch_release_acquired(
                hit.slot_idx, enqueue_ok, hit.pilot_submitted_hit,
                q4_lossless_cuda_stream())) {
            return false;
        }
        if (!enqueue_ok) {
            if (!q4_lossless_host_cache_raw_fallback(
                    job, hit.slot_idx, hit.pilot_submitted_hit,
                    "batch enqueue")) {
                return false;
            }
            continue;
        }
        status_cursor += item.decode.status_count;
        if (item.decode.crc_required) {
            crc32_cursor += ggml_moe_common::lossless_crc32_segments;
        }
        pending.push_back(item);
    }

    if (pending.empty()) return true;
    if (!q4_lossless_finalize_decode_batch(pending.size())) return false;
    const bool publish_verified_async = std::all_of(
            pending.begin(), pending.end(),
            [](const q4_lossless_host_batch_pending &item) {
                return !item.decode.crc_required;
            }) &&
        expert_pack_env_bool(
            "GGML_MOE_LOSSLESS_ASYNC_TRUST_VERIFIED", false);
    if (publish_verified_async) {
        const uint64_t batch_us =
            (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
                std::chrono::steady_clock::now() - batch_start).count();
        const uint64_t per_object_us = batch_us / pending.size();
        for (q4_lossless_host_batch_pending &item : pending) {
            q4_colibri_object_job &job = batch.jobs[item.hit.job_idx];
            if (!q4_lossless_publish_decoded(item.decode, false)) {
                return false;
            }
            q4_lossless_host_cache_record_hit(
                job, *item.object, item.hit.read_us,
                item.hit.pilot_submitted_hit, item.hit_origin,
                item.transport_bytes, per_object_us);
        }
        ++g_expert_pack.lossless_async_verified_batches;
        g_expert_pack.lossless_async_verified_objects.fetch_add(
            pending.size(), std::memory_order_relaxed);
        return true;
    }
    const auto wait_start = std::chrono::steady_clock::now();
    if (cudaStreamSynchronize(q4_lossless_cuda_stream()) != cudaSuccess) {
        ++g_expert_pack.lossless_cuda_failures;
        return false;
    }
    g_expert_pack.lossless_decode_us.fetch_add(
        (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now() - wait_start).count(),
        std::memory_order_relaxed);
    const uint64_t batch_us =
        (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now() - batch_start).count();
    const uint64_t per_object_us = batch_us / pending.size();

    for (q4_lossless_host_batch_pending &item : pending) {
        q4_colibri_object_job &job = batch.jobs[item.hit.job_idx];
        {
            std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
            if (ggml_moe_common::object_host_cache_synchronize_h2d(
                    g_q4_host_object_prefetch, item.hit.slot_idx) !=
                    ggml_moe_common::object_host_completion_state::complete) {
                return false;
            }
        }
        if (!q4_lossless_publish_decoded(item.decode)) {
            if (!q4_lossless_host_cache_raw_fallback(
                    job, item.hit.slot_idx,
                    item.hit.pilot_submitted_hit, "batch publish")) {
                return false;
            }
            continue;
        }
        q4_lossless_host_cache_record_hit(
            job, *item.object, item.hit.read_us,
            item.hit.pilot_submitted_hit, item.hit_origin,
            item.transport_bytes, per_object_us);
    }
    return true;
}

static bool q4_lossless_host_cache_h2d_batch(
        q4_colibri_object_batch &batch,
        const std::vector<q4_colibri_deferred_host_hit> &hits) {
    const size_t chunk_size = g_q4_colibri_pipe.lossless_device_input_slots;
    if (chunk_size == 0) return false;
    for (size_t begin = 0; begin < hits.size(); begin += chunk_size) {
        const size_t end = std::min(hits.size(), begin + chunk_size);
        const std::vector<q4_colibri_deferred_host_hit> chunk(
            hits.begin() + begin, hits.begin() + end);
        if (!q4_lossless_host_cache_h2d_batch_chunk(batch, chunk)) {
            return false;
        }
    }
    return true;
}

static bool q4_colibri_pipe_process_object(q4_colibri_object_job &job) {
    if (g_expert_pack.lossless_standalone) {
        q4_colibri_fail(
            "standalone lossless transport reached the synchronous raw reader");
    }
    char nvtx_label[160];
    std::snprintf(nvtx_label, sizeof(nvtx_label),
            "q4_direct_object_read roles=%zu bytes=%llu layer=%d expert=%d",
            job.role_count, (unsigned long long)job.bytes,
            (int)job.marker.layer_idx, (int)job.marker.expert_idx);
    moe_nvtx_range nvtx_scope(nvtx_label);
    if (job.role_count == 0 || job.role_count > 3 || job.source_idx < 0 || job.bytes == 0) return false;
    expert_pack_source *source = nullptr;
    for (size_t role_idx = 0; role_idx < job.role_count; ++role_idx) {
        q4_colibri_object_role_job &role = job.roles[role_idx];
        if (!q4_colibri_object_role_marker_matches(role) || !role.entry ||
                role.entry->source_idx != job.source_idx ||
                !q4_colibri_role_in_read_span(role, job.offset, job.bytes, nullptr)) {
            return false;
        }
        role.cache->slot_state[role.slot] = q4_colibri_slot_state::reading;
        expert_pack_source *role_source = expert_pack_source_for_entry(role.entry);
        if (!role_source || role_source->fd_direct < 0 || (source && source != role_source)) return false;
        source = role_source;
    }
    if (q4_colibri_host_object_prefetch_try_h2d(job)) {
        return true;
    }
    if (!source || !source->direct_required ||
            job.offset % expert_pack_direct_alignment() != 0 ||
            job.bytes % expert_pack_direct_alignment() != 0 ||
            !pinned_stage_ensure(g_q4_colibri_pipe.ring, (size_t)job.bytes, true)) {
        return false;
    }

    const bool object_cache = q4_colibri_object_cache_enabled();
    pinned_stage_slot *stage_ptr = object_cache ? q4_colibri_object_cache_find(job.marker) : nullptr;
    const bool ram_hit = stage_ptr != nullptr;
    if (ram_hit) {
        ++g_expert_pack.q4_object_ram_hits;
        ++g_expert_pack.q4_object_full_expert_hits;
        g_expert_pack.q4_object_ram_bytes_avoided.fetch_add(job.bytes);
        g_expert_pack.q4_object_ram_wait_us_avoided.fetch_add(stage_ptr->object_read_us);
        if (job.marker.layer_idx >= 0 && job.marker.layer_idx < 64) {
            ++g_expert_pack.q4_object_layer_ram_hits[job.marker.layer_idx];
            q4_object_layer_add(g_expert_pack.q4_object_layer_ram_bytes_avoided, job.marker.layer_idx, job.bytes);
            q4_object_layer_add(g_expert_pack.q4_object_layer_ram_wait_us_avoided, job.marker.layer_idx, stage_ptr->object_read_us);
        }
    } else {
        ++g_expert_pack.q4_object_ram_misses;
        if (job.marker.layer_idx >= 0 && job.marker.layer_idx < 64) {
            ++g_expert_pack.q4_object_layer_ram_misses[job.marker.layer_idx];
        }
        stage_ptr = object_cache ? q4_colibri_object_cache_admit(job.marker) :
            &g_q4_colibri_pipe.ring.slots[
                g_q4_colibri_pipe.ring.next++ % g_q4_colibri_pipe.ring.slots.size()];
    }
    if (!stage_ptr) return false;
    pinned_stage_slot &stage = *stage_ptr;
    if (stage.pending) {
        if (cudaEventSynchronize(stage.done) != cudaSuccess) return false;
        stage.pending = false;
        ++g_q4_colibri_pipe.ring.waits;
    }
    pinned_stage_collect_timing(g_q4_colibri_pipe.ring, stage);
    if (!ram_hit) {
        const auto read_start = std::chrono::steady_clock::now();
        const bool read_ok = expert_pack_direct_pread_all(
            source->fd_direct, stage.host, (size_t)job.bytes, job.offset);
        const uint64_t read_us = (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now() - read_start).count();
        stage.object_read_us = read_us;
        g_expert_pack.q4_scheduler_read_us.fetch_add(read_us, std::memory_order_relaxed);
        q4_layer_io_add(g_expert_pack.q4_layer_io_read_us, job.marker.layer_idx, read_us);
        if (!read_ok) {
            stage.object = {};
            ++g_expert_pack.read_failures;
            return false;
        }
        ++g_expert_pack.direct_reads;
        ++g_expert_pack.q4_object_ssd_reads;
        g_expert_pack.q4_object_ssd_bytes.fetch_add(job.bytes);
    }

    const auto h2d_start = std::chrono::steady_clock::now();
    {
        char h2d_label[160];
        std::snprintf(h2d_label, sizeof(h2d_label),
                "q4_h2d_roles roles=%zu bytes=%llu source=%s",
                job.role_count, (unsigned long long)job.bytes, ram_hit ? "ram" : "ssd");
        moe_nvtx_range nvtx_h2d(h2d_label);
        if (ram_hit) {
            if (!stage.copy_start && cudaEventCreate(&stage.copy_start) != cudaSuccess) return false;
            if (!stage.copy_done && cudaEventCreate(&stage.copy_done) != cudaSuccess) return false;
            if (cudaEventRecord(stage.copy_start, g_q4_colibri_pipe.stream) != cudaSuccess) return false;
            stage.object_ram_hit_timing_pending = true;
            stage.object_ram_hit_layer = job.marker.layer_idx;
            stage.object_ram_hit_bytes = job.bytes;
            g_expert_pack.q4_object_ram_h2d_bytes.fetch_add(job.bytes);
        }
        for (size_t role_idx = 0; role_idx < job.role_count; ++role_idx) {
            q4_colibri_object_role_job &role = job.roles[role_idx];
            uint64_t role_relative_offset = 0;
            if (!q4_colibri_object_role_marker_matches(role) ||
                    !q4_colibri_role_in_read_span(role, job.offset, job.bytes, &role_relative_offset)) {
                return false;
            }
            const ggml_moe_common::role_cache_view role_view = batch_cache_role_view(role.cache);
            if (!ggml_moe_common::role_cache_ensure_ready_event(role_view, role.slot)) {
                return false;
            }
            const void *role_host = (const char *)stage.host + role_relative_offset;
            if (cudaMemcpyAsync(role.dst, role_host, role.entry->nbytes,
                        cudaMemcpyHostToDevice, g_q4_colibri_pipe.stream) != cudaSuccess ||
                    !ggml_moe_common::role_cache_record_ready_event(
                        role_view, role.slot, g_q4_colibri_pipe.stream)) {
                return false;
            }
            role.cache->slot_ready_marker[role.slot] = role.marker;
            role.cache->slot_state[role.slot] = q4_colibri_slot_state::h2d_ready;
            role.cache->slot_pending[role.slot] = true;
            role.cache->slot_filling[role.slot] = false;
        }
    }
    if (ram_hit) {
        if (cudaEventRecord(stage.copy_done, g_q4_colibri_pipe.stream) != cudaSuccess) return false;
        stage.timing_pending = true;
    }
    if (cudaEventRecord(stage.done, g_q4_colibri_pipe.stream) != cudaSuccess) return false;
    stage.pending = true;
    g_q4_colibri_pipe.ring.copies += job.role_count;
    const uint64_t h2d_us = (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
        std::chrono::steady_clock::now() - h2d_start).count();
    g_expert_pack.q4_scheduler_h2d_us.fetch_add(h2d_us, std::memory_order_relaxed);
    q4_layer_io_add(g_expert_pack.q4_layer_io_h2d_us, job.marker.layer_idx, h2d_us);
    return true;
}

static bool q4_colibri_pipe_process_object_batch_iouring(q4_colibri_object_batch &batch, bool *attempted) {
#if defined(GGML_MOE_OBJECT_TRANSPORT_HAS_LIBURING) && !defined(_WIN32)
    char nvtx_batch_label[160];
    std::snprintf(nvtx_batch_label, sizeof(nvtx_batch_label),
            "q4_iouring_batch_read batch_jobs=%zu pilot=%d",
            batch.jobs.size(), batch.pilot_prefetch ? 1 : 0);
    moe_nvtx_range nvtx_batch_scope(nvtx_batch_label);
    if (attempted) *attempted = false;
    if (!q4_colibri_batch_iouring_enabled() ||
            (batch.jobs.size() <= 1 && !g_expert_pack.lossless_standalone) ||
            g_expert_pack.io_backend != 2) {
        return false;
    }
    const uint64_t cqe_timeline_batch = q4_cqe_timeline_next_batch();
    uint64_t cqe_timeline_pos = 0;

    struct q4_iouring_plan {
        size_t job_idx = 0;
        expert_pack_source *source = nullptr;
        uint64_t offset = 0;
        size_t bytes = 0;
        const ggml_moe_common::lossless_object_record *lossless = nullptr;
    };
    struct q4_iouring_group_slice {
        size_t plan_idx = 0;
        size_t prefix = 0;
    };
    struct q4_iouring_read_group {
        expert_pack_source *source = nullptr;
        uint64_t offset = 0;
        size_t bytes = 0;
        std::vector<q4_iouring_group_slice> slices;
    };

    const size_t alignment = expert_pack_direct_alignment();
    std::vector<q4_iouring_plan> plans;
    plans.reserve(batch.jobs.size());
    size_t max_read_sz = 0;
    const bool object_cache = q4_colibri_object_cache_enabled();
    const bool object_h2d_batch = q4_colibri_object_h2d_batch_enabled();
    if (g_expert_pack.lossless_standalone && !object_h2d_batch) {
        q4_colibri_fail(
            "standalone lossless transport requires object H2D batching");
    }
    const bool object_h2d_async_refill =
        object_h2d_batch && q4_colibri_object_h2d_async_refill_enabled();
    const int batch_layer = q4_colibri_object_batch_common_layer(batch);
    const bool object_adjacent_coalesce =
        q4_colibri_object_adjacent_coalesce_enabled() && !object_h2d_batch &&
        q4_colibri_object_adjacent_layer_allowed(batch_layer);
    const bool object_adjacent_tail_coalesce =
        object_adjacent_coalesce && q4_colibri_object_adjacent_tail_coalesce_enabled();
    const bool defer_host_h2d = q4_colibri_host_object_defer_h2d_enabled() || object_h2d_batch;
    std::vector<q4_colibri_deferred_host_hit> deferred_host_hits;
    if (defer_host_h2d) {
        deferred_host_hits.reserve(batch.jobs.size());
    }
    batch.readiness.input_jobs = batch.jobs.size();
    for (size_t i = 0; i < batch.jobs.size(); ++i) {
        q4_colibri_object_job &job = batch.jobs[i];
        if (job.role_count == 0 || job.role_count > 3 || job.source_idx < 0 || job.bytes == 0 ||
                job.bytes > (uint64_t)UINT_MAX ||
                job.offset % alignment != 0 || job.bytes % alignment != 0) {
            return false;
        }
        expert_pack_source *source = nullptr;
        for (size_t role_idx = 0; role_idx < job.role_count; ++role_idx) {
            q4_colibri_object_role_job &role = job.roles[role_idx];
            if (!q4_colibri_object_role_marker_matches(role) || !role.entry ||
                    role.entry->source_idx != job.source_idx ||
                    !q4_colibri_role_in_read_span(role, job.offset, job.bytes, nullptr)) {
                return false;
            }
            expert_pack_source *role_source = expert_pack_source_for_entry(role.entry);
            if (!role_source || role_source->fd_direct < 0 || role_source->page_cache ||
                    !role_source->direct_required || (source && source != role_source)) {
                return false;
            }
            source = role_source;
        }
        if (!source) return false;
        if (defer_host_h2d) {
            size_t deferred_slot_idx = SIZE_MAX;
            uint64_t deferred_read_us = 0;
            bool deferred_pilot_hit = false;
            if (q4_colibri_host_object_prefetch_acquire(
                        job, &deferred_slot_idx, &deferred_read_us, &deferred_pilot_hit)) {
                deferred_host_hits.push_back({i, deferred_slot_idx, deferred_read_us, deferred_pilot_hit});
                ++batch.readiness.deferred_host_hits;
                batch.readiness.deferred_host_roles += job.role_count;
                continue;
            }
        } else if (q4_colibri_host_object_prefetch_try_h2d(job)) {
            ++g_expert_pack.q4_pipe_completed;
            continue;
        }
        if (object_cache) {
            pinned_stage_slot *cached = q4_colibri_object_cache_find(job.marker);
            if (cached) {
                if (cached->pending) {
                    if (cudaEventSynchronize(cached->done) != cudaSuccess) return false;
                    cached->pending = false;
                    ++g_q4_colibri_pipe.ring.waits;
                }
                pinned_stage_collect_timing(g_q4_colibri_pipe.ring, *cached);
                if (!q4_colibri_pipe_h2d_object_from_stage(job, *cached, true)) {
                    return false;
                }
                ++g_expert_pack.q4_pipe_completed;
                continue;
            }
        }
        const ggml_moe_common::lossless_object_record *lossless =
            object_h2d_batch ? q4_lossless_record_for_job(job) : nullptr;
        expert_pack_source *transport_source = lossless ?
            &g_expert_pack.lossless_source : source;
        const uint64_t transport_offset = lossless ?
            lossless->file_offset : job.offset;
        const size_t transport_bytes = lossless ?
            static_cast<size_t>(lossless->physical_bytes) :
            static_cast<size_t>(job.bytes);
        plans.push_back({
            i,
            transport_source,
            transport_offset,
            transport_bytes,
            lossless,
        });
        max_read_sz = std::max(
            max_read_sz,
            lossless ? std::max<size_t>(transport_bytes, (size_t)job.bytes) :
                transport_bytes);
    }

    auto process_deferred_host_hits = [&]() -> bool {
        if (!q4_lossless_host_cache_h2d_batch(batch, deferred_host_hits)) {
            return false;
        }
        for (const q4_colibri_deferred_host_hit &hit : deferred_host_hits) {
            ++g_expert_pack.q4_pipe_completed;
        }
        deferred_host_hits.clear();
        return true;
    };

    if (plans.empty()) {
        return process_deferred_host_hits();
    }
    batch.readiness.plans = plans.size();

    std::vector<size_t> order;
    const bool sort_by_offset = expert_pack_env_bool("GGML_MOE_IO_SORT_OFFSET", false) || object_adjacent_coalesce;
    if (plans.size() > 1 && sort_by_offset) {
        order.resize(plans.size());
        for (size_t i = 0; i < plans.size(); ++i) order[i] = i;
        std::stable_sort(order.begin(), order.end(), [&](size_t a, size_t b) {
            if (plans[a].source != plans[b].source) return plans[a].source < plans[b].source;
            return plans[a].offset < plans[b].offset;
        });
    }
    auto ordered_plan_idx = [&](size_t seq_idx) -> size_t {
        return order.empty() ? seq_idx : order[seq_idx];
    };

    const size_t adjacent_max_span = expert_pack_adjacent_max_span();
    const size_t adjacent_max_gap = expert_pack_adjacent_max_gap();
    const size_t adjacent_min_group = expert_pack_adjacent_min_group();
    size_t adjacent_groups = 0;
    size_t adjacent_slices = 0;
    size_t adjacent_extents_saved = 0;
    uint64_t adjacent_physical_bytes = 0;
    uint64_t adjacent_payload_bytes = 0;
    size_t adjacent_max_group_jobs = 0;
    size_t adjacent_max_span_bytes = 0;
    uint64_t adjacent_reject_source = 0;
    uint64_t adjacent_reject_gap = 0;
    uint64_t adjacent_reject_span = 0;

    std::vector<q4_iouring_read_group> read_groups;
    read_groups.reserve(plans.size());
    auto append_single_group = [&](size_t plan_idx) {
        const q4_iouring_plan &plan = plans[plan_idx];
        q4_iouring_read_group group;
        group.source = plan.source;
        group.offset = plan.offset;
        group.bytes = plan.bytes;
        group.slices.push_back({plan_idx, 0});
        read_groups.push_back(std::move(group));
        max_read_sz = std::max(max_read_sz, plan.bytes);
    };
    auto append_slice_span = [&](const std::vector<q4_iouring_group_slice> &span_slices) {
        if (span_slices.empty()) return;
        if (span_slices.size() < adjacent_min_group) {
            for (const q4_iouring_group_slice &slice : span_slices) {
                append_single_group(slice.plan_idx);
            }
            return;
        }
        const q4_iouring_plan &first = plans[span_slices.front().plan_idx];
        const q4_iouring_plan &last = plans[span_slices.back().plan_idx];
        q4_iouring_read_group group;
        group.source = first.source;
        group.offset = first.offset;
        group.bytes = (size_t)((last.offset + last.bytes) - first.offset);
        group.slices.reserve(span_slices.size());
        for (const q4_iouring_group_slice &slice : span_slices) {
            const q4_iouring_plan &plan = plans[slice.plan_idx];
            group.slices.push_back({slice.plan_idx, (size_t)(plan.offset - group.offset)});
        }
        max_read_sz = std::max(max_read_sz, group.bytes);
        read_groups.push_back(std::move(group));
    };

    size_t seq = 0;
    while (seq < plans.size()) {
        const size_t first_idx = ordered_plan_idx(seq);
        const q4_iouring_plan &first = plans[first_idx];
        uint64_t group_start = first.offset;
        uint64_t group_end = first.offset + first.bytes;
        uint64_t group_payload = first.bytes;
        std::vector<q4_iouring_group_slice> slices;
        slices.push_back({first_idx, 0});
        size_t next_seq = seq + 1;
        while (next_seq < plans.size()) {
            const size_t next_idx = ordered_plan_idx(next_seq);
            const q4_iouring_plan &next = plans[next_idx];
            if (next.source != first.source) {
                ++adjacent_reject_source;
                break;
            }
            if (next.offset < group_end || next.offset - group_end > adjacent_max_gap) {
                ++adjacent_reject_gap;
                break;
            }
            const uint64_t next_end = next.offset + next.bytes;
            if (next_end < group_start || next_end - group_start > adjacent_max_span) {
                ++adjacent_reject_span;
                break;
            }
            slices.push_back({next_idx, (size_t)(next.offset - group_start)});
            group_end = next_end;
            group_payload += next.bytes;
            ++next_seq;
        }
        if (slices.size() >= adjacent_min_group) {
            ++adjacent_groups;
            adjacent_slices += slices.size();
            adjacent_extents_saved += slices.size() - 1;
            adjacent_physical_bytes += group_end - group_start;
            adjacent_payload_bytes += group_payload;
            adjacent_max_group_jobs = std::max(adjacent_max_group_jobs, slices.size());
            adjacent_max_span_bytes = std::max<size_t>(adjacent_max_span_bytes, (size_t)(group_end - group_start));
            if (object_adjacent_tail_coalesce) {
                size_t critical_pos = 0;
                size_t critical_plan_idx = SIZE_MAX;
                for (size_t slice_idx = 0; slice_idx < slices.size(); ++slice_idx) {
                    if (slices[slice_idx].plan_idx < critical_plan_idx) {
                        critical_plan_idx = slices[slice_idx].plan_idx;
                        critical_pos = slice_idx;
                    }
                }
                append_single_group(slices[critical_pos].plan_idx);
                if (critical_pos > 0) {
                    std::vector<q4_iouring_group_slice> left(slices.begin(), slices.begin() + critical_pos);
                    append_slice_span(left);
                }
                if (critical_pos + 1 < slices.size()) {
                    std::vector<q4_iouring_group_slice> right(slices.begin() + critical_pos + 1, slices.end());
                    append_slice_span(right);
                }
            } else if (object_adjacent_coalesce) {
                q4_iouring_read_group group;
                group.source = first.source;
                group.offset = group_start;
                group.bytes = (size_t)(group_end - group_start);
                group.slices = std::move(slices);
                max_read_sz = std::max(max_read_sz, group.bytes);
                read_groups.push_back(std::move(group));
            } else {
                for (size_t group_seq = seq; group_seq < next_seq; ++group_seq) {
                    append_single_group(ordered_plan_idx(group_seq));
                }
            }
        } else {
            append_single_group(first_idx);
        }
        seq = next_seq;
    }
    if (adjacent_groups || adjacent_reject_source || adjacent_reject_gap || adjacent_reject_span) {
        g_expert_pack.q4_object_adjacent_groups.fetch_add(adjacent_groups, std::memory_order_relaxed);
        g_expert_pack.q4_object_adjacent_slices.fetch_add(adjacent_slices, std::memory_order_relaxed);
        g_expert_pack.q4_object_adjacent_extents_saved.fetch_add(adjacent_extents_saved, std::memory_order_relaxed);
        g_expert_pack.q4_object_adjacent_physical_bytes.fetch_add(adjacent_physical_bytes, std::memory_order_relaxed);
        g_expert_pack.q4_object_adjacent_payload_bytes.fetch_add(adjacent_payload_bytes, std::memory_order_relaxed);
        expert_pack_atomic_max(g_expert_pack.q4_object_adjacent_max_group_jobs, adjacent_max_group_jobs);
        expert_pack_atomic_max(g_expert_pack.q4_object_adjacent_max_span_bytes, adjacent_max_span_bytes);
        g_expert_pack.q4_object_adjacent_reject_source.fetch_add(adjacent_reject_source, std::memory_order_relaxed);
        g_expert_pack.q4_object_adjacent_reject_gap.fetch_add(adjacent_reject_gap, std::memory_order_relaxed);
        g_expert_pack.q4_object_adjacent_reject_span.fetch_add(adjacent_reject_span, std::memory_order_relaxed);
    }
    batch.readiness.read_groups = read_groups.size();
    const bool common_rolling_refill = common_rolling_refill_enabled();
    const bool common_refill_planner_owns_dispatch =
        common_rolling_refill && common_refill_planner_owns_dispatch_enabled();
    ggml_moe_common::object_pipeline_refill_cursor common_refill_cursor;
    if (common_rolling_refill) {
        if (!ggml_moe_common::object_pipeline_refill_reset(common_refill_cursor, read_groups.size())) {
            ++g_expert_pack.q4_common_refill_failures;
            return false;
        }
        ++g_expert_pack.q4_common_refill_batches;
    }

    if (io_read_trace_enabled()) {
        const char *path = std::getenv("GGML_MOE_IO_READ_TRACE_OUT");
        static std::mutex trace_mu;
        static bool header_written = false;
        const uint64_t io_batch_seq = io_read_trace_next_batch_seq();
        std::lock_guard<std::mutex> lk(trace_mu);
        FILE *f = std::fopen(path, "a");
        if (f) {
            if (!header_written) {
                std::fprintf(f,
                        "batch_seq,batch_pos,op,jobs,read_jobs,tensor,expert_idx,"
                        "source_idx,offset,nbytes\n");
                header_written = true;
            }
            size_t batch_pos = 0;
            const char *op = batch.pilot_prefetch ? "q4_pilot_object_iouring" : "q4_same_layer_object_iouring";
            for (const q4_iouring_read_group &group : read_groups) {
                for (const q4_iouring_group_slice &slice : group.slices) {
                    if (slice.plan_idx >= plans.size()) continue;
                    const q4_iouring_plan &plan = plans[slice.plan_idx];
                    if (plan.job_idx >= batch.jobs.size()) continue;
                    const q4_colibri_object_job &job = batch.jobs[plan.job_idx];
                    const char *tensor = job.role_count > 0 ? job.roles[0].tensor : "";
                    std::fprintf(f,
                            "%lu,%zu,%s,%zu,%zu,%s,%d,%d,%lu,%lu\n",
                            (unsigned long)io_batch_seq,
                            batch_pos++,
                            op,
                            batch.jobs.size(),
                            read_groups.size(),
                            tensor ? tensor : "",
                            job.marker.expert_idx,
                            job.source_idx,
                            (unsigned long)plan.offset,
                            (unsigned long)plan.bytes);
                }
            }
            std::fclose(f);
        }
    }

    const bool use_adjacent_split_ring =
        q4_object_adjacent_split_ring_enabled() && object_adjacent_coalesce && adjacent_extents_saved > 0;
    pinned_stage_ring &ring = use_adjacent_split_ring ?
        g_q4_colibri_pipe.coalesce_ring : g_q4_colibri_pipe.ring;
    const bool stage_ready = use_adjacent_split_ring ?
        pinned_stage_ensure_slots(
            ring, max_read_sz, true, q4_object_adjacent_split_ring_slots()) :
        pinned_stage_ensure(ring, max_read_sz, true);
    if (!stage_ready) {
        return false;
    }
    const size_t depth = std::min(expert_pack_io_depth(), ring.slots.size());
    if (depth == 0) return false;
    batch.readiness.depth = depth;

    const unsigned int flags = expert_pack_env_bool("GGML_MOE_IO_SQPOLL", false) ?
        ggml_moe_common::object_io_sqpoll_setup_flag() : 0;
    if (!ggml_moe_common::object_io_ring_ensure(
                ring, depth, flags, "GGML_MOE_Q4_COLIBRI_SQPOLL_CPU")) {
        ++g_expert_pack.io_stats.fallbacks;
        return false;
    }
    struct pending_job {
        size_t group_idx = 0;
        size_t slot_idx = 0;
        size_t bytes = 0;
        std::chrono::steady_clock::time_point read_start;
    };
    struct completed_read {
        size_t pending_idx = 0;
        size_t group_idx = 0;
        size_t slot_idx = 0;
        uint64_t read_us = 0;
    };

    std::vector<pending_job> pending(depth);
    std::vector<ggml_moe_common::object_io_window_slot> io_window(depth);
    const bool common_object_cqe = common_object_cqe_enabled();
    std::vector<size_t> free_pending;
    free_pending.reserve(depth);
    for (size_t i = 0; i < depth; ++i) {
        free_pending.push_back(depth - 1 - i);
    }
    std::vector<size_t> free_slots;
    std::vector<uint8_t> slot_available;
    if (object_h2d_async_refill) {
        free_slots.reserve(ring.slots.size());
        slot_available.assign(ring.slots.size(), 1);
        for (size_t i = 0; i < ring.slots.size(); ++i) {
            free_slots.push_back(ring.slots.size() - 1 - i);
        }
    }

    auto collect_async_h2d_slots = [&](bool block_one) -> bool {
        if (!object_h2d_async_refill) return true;
        for (size_t i = 0; i < ring.slots.size(); ++i) {
            if (slot_available[i] || !ring.slots[i].pending || !ring.slots[i].done) continue;
            const cudaError_t query = cudaEventQuery(ring.slots[i].done);
            if (query == cudaSuccess) {
                ggml_moe_common::object_stage_slot_publish_ready(ring.slots[i]);
                pinned_stage_collect_timing(ring, ring.slots[i]);
                slot_available[i] = 1;
                free_slots.push_back(i);
            }
        }
        if (!block_one || !free_slots.empty()) return true;
        for (size_t i = 0; i < ring.slots.size(); ++i) {
            if (slot_available[i] || !ring.slots[i].pending || !ring.slots[i].done) continue;
            const auto h2d_slot_wait_start = std::chrono::steady_clock::now();
            if (cudaEventSynchronize(ring.slots[i].done) != cudaSuccess) return false;
            batch.readiness.h2d_slot_wait_us +=
                (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
                    std::chrono::steady_clock::now() - h2d_slot_wait_start).count();
            ring.slots[i].pending = false;
            ++ring.waits;
            pinned_stage_collect_timing(ring, ring.slots[i]);
            slot_available[i] = 1;
            free_slots.push_back(i);
            return true;
        }
        return true;
    };

    auto acquire_submit_slot = [&]() -> size_t {
        if (!object_h2d_async_refill) {
            return ring.next++ % ring.slots.size();
        }
        if (!collect_async_h2d_slots(false)) return SIZE_MAX;
        if (free_slots.empty() && (!collect_async_h2d_slots(true) || free_slots.empty())) {
            return SIZE_MAX;
        }
        const size_t slot_idx = free_slots.back();
        free_slots.pop_back();
        if (slot_idx >= slot_available.size()) return SIZE_MAX;
        slot_available[slot_idx] = 0;
        return slot_idx;
    };

    auto submit_one = [&](size_t group_idx, size_t slot_idx, size_t pending_idx) -> bool {
        const q4_iouring_read_group &group = read_groups[group_idx];
        pinned_stage_slot &slot = ring.slots[slot_idx];
        if (slot.pending) {
            const auto read_slot_wait_start = std::chrono::steady_clock::now();
            if (!ggml_moe_common::object_stage_slot_synchronize(ring, slot)) return false;
            batch.readiness.read_slot_wait_us +=
                (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
                    std::chrono::steady_clock::now() - read_slot_wait_start).count();
        }
        pinned_stage_collect_timing(ring, slot);

        pending[pending_idx] = {group_idx, slot_idx, group.bytes, std::chrono::steady_clock::now()};
        bool read_prepared = false;
        if (common_object_cqe) {
            const ggml_moe_common::object_io_window_request request{
                group.source->fd_direct,
                slot.host,
                group.bytes,
                group.offset,
                group_idx,
                false,
            };
            read_prepared = ggml_moe_common::object_io_window_prepare_read(
                ring, io_window.data(), io_window.size(), pending_idx, request);
        } else {
            read_prepared = ggml_moe_common::object_io_ring_prepare_read(
                ring, group.source->fd_direct, slot.host, group.bytes, group.offset,
                (uint64_t)pending_idx + 1);
        }
        if (!read_prepared) {
            return false;
        }

        for (const q4_iouring_group_slice &slice : group.slices) {
            const q4_iouring_plan &plan = plans[slice.plan_idx];
            q4_colibri_object_job &job = batch.jobs[plan.job_idx];
            for (size_t role_idx = 0; role_idx < job.role_count; ++role_idx) {
                job.roles[role_idx].cache->slot_state[job.roles[role_idx].slot] = q4_colibri_slot_state::reading;
            }
            ++g_expert_pack.q4_object_ram_misses;
            if (job.marker.layer_idx >= 0 && job.marker.layer_idx < 64) {
                ++g_expert_pack.q4_object_layer_ram_misses[job.marker.layer_idx];
            }
        }
        return true;
    };

    expert_pack_record_iouring_batch(read_groups.size());
    ring.iouring_batches += 1;
    ring.iouring_jobs += read_groups.size();
    const size_t bucket = expert_pack_iouring_batch_bucket(read_groups.size());
    if (bucket < 6) {
        ring.iouring_batch_hist[bucket] += 1;
    }
    if (stage_granularity_profile_enabled()) {
        ++ring.granularity_calls;
        ring.granularity_total_jobs += batch.jobs.size();
        ring.granularity_read_jobs += read_groups.size();
        ring.granularity_depth_sum += depth;
        ring.granularity_slots_sum += ring.slots.size();
        ring.granularity_max_jobs = std::max<uint64_t>(ring.granularity_max_jobs, (uint64_t)batch.jobs.size());
        ring.granularity_max_read_jobs = std::max<uint64_t>(ring.granularity_max_read_jobs, (uint64_t)read_groups.size());
        ring.granularity_max_depth = std::max<uint64_t>(ring.granularity_max_depth, (uint64_t)depth);
    }

    const auto batch_read_start = std::chrono::steady_clock::now();
    const auto initial_submit_start = std::chrono::steady_clock::now();
    batch.readiness.initial_submit_start = initial_submit_start;
    size_t next_plan = 0;
    size_t inflight = 0;
    const size_t refill_batch = std::min(expert_pack_io_refill_batch(), depth);
    const bool eager_refill = expert_pack_io_eager_refill_enabled();
    batch.readiness.refill_batch = refill_batch;
    struct reusable_pending {
        size_t pending_idx = 0;
        size_t slot_idx = 0;
    };
    std::vector<reusable_pending> reusable_pending_slots;
    reusable_pending_slots.reserve(depth);
    std::vector<completed_read> ready_reads;
    ready_reads.reserve(depth);
    ggml_moe_common::object_pipeline_dispatch_plan common_initial_plan;
    if (common_rolling_refill) {
        ggml_moe_common::object_pipeline_policy initial_policy =
            expert_pack_pipeline_policy_config().policy;
        initial_policy.io_depth = depth;
        initial_policy.initial_batch = std::min(
            initial_policy.initial_batch, depth);
        initial_policy.refill_batch = std::min(
            initial_policy.refill_batch, depth);
        initial_policy.min_flush_batch = std::min(
            initial_policy.min_flush_batch, depth);
        initial_policy.max_inflight_h2d = std::max<size_t>(1, ring.slots.size());
        common_initial_plan = ggml_moe_common::object_pipeline_refill_plan_ready(
            common_refill_cursor, initial_policy, 0, 0, true);
    }
    size_t initial_submit_limit = depth;
    if (common_refill_planner_owns_dispatch) {
        if (common_initial_plan.submit_count > 0) {
            initial_submit_limit = common_initial_plan.submit_count;
            ++g_expert_pack.q4_common_refill_owned_dispatches;
        } else {
            ++g_expert_pack.q4_common_refill_owner_fallbacks;
        }
    }

    {
        char nvtx_submit_label[160];
        std::snprintf(nvtx_submit_label, sizeof(nvtx_submit_label),
                "q4_iouring_submit_initial groups=%zu plans=%zu depth=%zu", read_groups.size(), plans.size(), depth);
        moe_nvtx_range nvtx_submit(nvtx_submit_label);
        while (next_plan < read_groups.size() && inflight < depth &&
                batch.readiness.initial_submitted < initial_submit_limit) {
            const size_t pending_idx = free_pending.back();
            free_pending.pop_back();
            const size_t slot_idx = acquire_submit_slot();
            if (slot_idx == SIZE_MAX) {
                ++g_expert_pack.io_stats.fallbacks;
                return false;
            }
            if (!submit_one(next_plan, slot_idx, pending_idx)) {
                ++g_expert_pack.io_stats.fallbacks;
                return false;
            }
            ++next_plan;
            ++inflight;
            ++batch.readiness.initial_submitted;
        }
        if (!ggml_moe_common::object_io_ring_submit(ring)) {
            ++g_expert_pack.io_stats.fallbacks;
            return false;
        }
        if (common_rolling_refill) {
            if (!ggml_moe_common::object_pipeline_refill_record_submit(
                        common_refill_cursor, batch.readiness.initial_submitted)) {
                ++g_expert_pack.q4_common_refill_failures;
                return false;
            }
            ++g_expert_pack.q4_common_refill_submit_rounds;
            g_expert_pack.q4_common_refill_submitted.fetch_add(
                batch.readiness.initial_submitted, std::memory_order_relaxed);
            ++g_expert_pack.q4_common_refill_plan_checks;
            if (common_initial_plan.submit_count == batch.readiness.initial_submitted) {
                ++g_expert_pack.q4_common_refill_plan_matches;
            } else {
                ++g_expert_pack.q4_common_refill_plan_mismatches;
            }
        }
    }
    if (attempted) *attempted = true;
    ++g_expert_pack.io_stats.submit_calls;
    batch.readiness.initial_submit_done = std::chrono::steady_clock::now();
    g_expert_pack.io_stats.submit_us.fetch_add(
        (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now() - initial_submit_start).count(), std::memory_order_relaxed);

    if (!process_deferred_host_hits()) {
        ++g_expert_pack.io_stats.fallbacks;
        return false;
    }

    size_t completed = 0;
    size_t lossless_status_cursor = 0;
    size_t lossless_status_output_cursor = 0;
    size_t lossless_crc32_cursor = 0;
    const bool async_lossless_decode =
        !g_expert_pack.glm52_colibri &&
        expert_pack_env_bool(
            "GGML_MOE_LOSSLESS_ASYNC_DECODE_PIPELINE", true);
    size_t lossless_decode_flush_objects =
        g_q4_colibri_pipe.lossless_device_input_slots;
    if (const char *env = std::getenv(
            "GGML_MOE_LOSSLESS_DECODE_FLUSH_OBJECTS")) {
        const long value = std::atol(env);
        if (value > 0) {
            lossless_decode_flush_objects = std::min<size_t>(
                static_cast<size_t>(value),
                g_q4_colibri_pipe.lossless_device_input_slots);
        }
    }
    std::vector<q4_lossless_pending_decode> lossless_pending_decodes;
    lossless_pending_decodes.reserve(
        g_q4_colibri_pipe.lossless_device_input_slots);
    std::vector<q4_lossless_pending_decode> lossless_queued_decodes;
    lossless_queued_decodes.reserve(plans.size());
    struct lossless_async_abort_guard {
        bool armed = false;
        std::vector<q4_lossless_pending_decode> *pending = nullptr;

        ~lossless_async_abort_guard() {
            if (!armed || !pending || pending->empty()) return;
            (void)cudaStreamSynchronize(q4_lossless_cuda_stream());
            for (const q4_lossless_pending_decode &decode : *pending) {
                if (decode.host_cache_processed && decode.job && decode.object) {
                    q4_lossless_invalidate_early_host_admission(
                        decode.job->marker, decode.object->file_offset);
                }
            }
        }
    } async_abort_guard {
        async_lossless_decode,
        &lossless_queued_decodes,
    };
    g_q4_colibri_pipe.lossless_descriptors.clear();
    auto flush_lossless_pending = [&]() -> bool {
        if (lossless_pending_decodes.empty()) return true;
        if (async_lossless_decode) {
            const size_t status_output_offset =
                lossless_pending_decodes.front().status_offset;
            if (!q4_lossless_finalize_decode_batch(
                        lossless_pending_decodes.size(),
                        status_output_offset)) {
                return false;
            }
            ++g_expert_pack.lossless_async_decode_batches;
            lossless_queued_decodes.insert(
                lossless_queued_decodes.end(),
                lossless_pending_decodes.begin(),
                lossless_pending_decodes.end());
            lossless_pending_decodes.clear();
            lossless_status_cursor = 0;
            g_q4_colibri_pipe.lossless_descriptors.clear();
            return true;
        }
        const auto decode_wait_start = std::chrono::steady_clock::now();
        if (!q4_lossless_finalize_decode_batch(
                    lossless_pending_decodes.size())) {
            return false;
        }
        for (const q4_lossless_pending_decode &pending_decode :
                lossless_pending_decodes) {
            if (pending_decode.stage &&
                    !ggml_moe_common::object_stage_slot_record(
                        *pending_decode.stage, q4_lossless_cuda_stream())) {
                ++g_expert_pack.lossless_cuda_failures;
                return false;
            }
        }
        if (cudaStreamSynchronize(q4_lossless_cuda_stream()) != cudaSuccess) {
            ++g_expert_pack.lossless_cuda_failures;
            return false;
        }
        g_expert_pack.lossless_decode_us.fetch_add(
            (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
                std::chrono::steady_clock::now() - decode_wait_start).count(),
            std::memory_order_relaxed);
        for (const q4_lossless_pending_decode &pending_decode :
                lossless_pending_decodes) {
            if (q4_lossless_publish_decoded(pending_decode)) {
                if (pending_decode.job && pending_decode.object &&
                        pending_decode.stage) {
                    (void)q4_colibri_host_object_prefetch_admit_from_read(
                        pending_decode.job->marker,
                        pending_decode.stage->host,
                        static_cast<size_t>(pending_decode.object->payload_bytes),
                        pending_decode.read_us,
                        ggml_moe_common::object_host_payload_format::lossless_sidecar,
                        static_cast<size_t>(pending_decode.object->physical_bytes),
                        pending_decode.object->payload_crc32,
                        pending_decode.object->file_offset);
                }
            } else if (!pending_decode.job || !pending_decode.stage ||
                    !q4_lossless_raw_fallback(
                        *pending_decode.job, *pending_decode.stage)) {
                return false;
            }
        }
        lossless_pending_decodes.clear();
        lossless_status_cursor = 0;
        lossless_crc32_cursor = 0;
        g_q4_colibri_pipe.lossless_descriptors.clear();
        return true;
    };
    auto handle_cqe = [&](const ggml_moe_common::object_io_completion &completion) -> bool {
        size_t pending_idx = SIZE_MAX;
        ggml_moe_common::object_io_completion_status status;
        if (common_object_cqe) {
            ggml_moe_common::object_io_window_completion resolved;
            status = ggml_moe_common::object_io_window_resolve(
                ring, io_window.data(), io_window.size(), completion, resolved);
            pending_idx = resolved.window_slot;
            if (status == ggml_moe_common::object_io_completion_status::complete &&
                    (pending_idx >= pending.size() ||
                     resolved.request_id != pending[pending_idx].group_idx)) {
                status = ggml_moe_common::object_io_completion_status::invalid_user_data;
            }
        } else {
            const uint64_t data = completion.user_data;
            pending_idx = data == 0 ? SIZE_MAX : (size_t)data - 1;
            const bool pending_valid = pending_idx < pending.size();
            const size_t expected_bytes = pending_valid ? pending[pending_idx].bytes : 0;
            status = ggml_moe_common::object_io_completion_validate(
                ring, completion, pending_valid, expected_bytes);
        }
        if (status != ggml_moe_common::object_io_completion_status::complete) {
            ++g_expert_pack.io_stats.fallbacks;
            return false;
        }
        if (common_rolling_refill) {
            if (!ggml_moe_common::object_pipeline_refill_record_io_completion(common_refill_cursor)) {
                ++g_expert_pack.q4_common_refill_failures;
                return false;
            }
            ++g_expert_pack.q4_common_refill_completions;
        }
        const pending_job done = pending[pending_idx];
        const auto cqe_now = std::chrono::steady_clock::now();
        if (batch.readiness.first_cqe == std::chrono::steady_clock::time_point{}) {
            batch.readiness.first_cqe = cqe_now;
        }
        batch.readiness.last_cqe = cqe_now;
        const uint64_t done_read_us = done.read_start == std::chrono::steady_clock::time_point{} ? 0 :
            (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
                cqe_now - done.read_start).count();
        const q4_iouring_read_group &group = read_groups[done.group_idx];
        if (cqe_timeline_batch != 0) {
            int first_expert = -1;
            if (!group.slices.empty() && group.slices[0].plan_idx < plans.size()) {
                const q4_iouring_plan &first_plan = plans[group.slices[0].plan_idx];
                if (first_plan.job_idx < batch.jobs.size()) {
                    first_expert = batch.jobs[first_plan.job_idx].marker.expert_idx;
                }
            }
            q4_cqe_timeline_record(
                cqe_timeline_batch,
                ++cqe_timeline_pos,
                q4_colibri_object_batch_common_layer(batch),
                batch.pilot_prefetch,
                done.group_idx,
                group.slices.size(),
                first_expert,
                group.bytes,
                q4_scheduler_readiness_tp_us(cqe_now),
                q4_scheduler_readiness_delta_us(cqe_now, batch.readiness.initial_submit_done),
                done_read_us);
        }
        pinned_stage_slot &slot = ring.slots[done.slot_idx];
        ++g_expert_pack.io_stats.cqes;
        if (object_h2d_batch) {
            ready_reads.push_back({pending_idx, done.group_idx, done.slot_idx, done_read_us});
            if (object_h2d_async_refill) {
                free_pending.push_back(pending_idx);
            }
            --inflight;
            return true;
        }

        const auto h2d_start = std::chrono::steady_clock::now();
        if (batch.readiness.first_h2d_start == std::chrono::steady_clock::time_point{}) {
            batch.readiness.first_h2d_start = h2d_start;
        }
        uint64_t copied_roles = 0;
        uint64_t copied_bytes = 0;
        {
            char nvtx_h2d_label[160];
            std::snprintf(nvtx_h2d_label, sizeof(nvtx_h2d_label),
                    "q4_h2d_group objects=%zu bytes=%zu", group.slices.size(), group.bytes);
            moe_nvtx_range nvtx_h2d(nvtx_h2d_label);
            for (const q4_iouring_group_slice &slice : group.slices) {
                if (slice.plan_idx >= plans.size()) return false;
                const q4_iouring_plan &plan = plans[slice.plan_idx];
                q4_colibri_object_job &job = batch.jobs[plan.job_idx];
                if (slice.prefix + job.bytes > group.bytes) return false;
                const char *object_host = (const char *)slot.host + slice.prefix;
                (void)q4_colibri_host_object_prefetch_admit_from_read(
                        job.marker, object_host, (size_t)job.bytes, done_read_us);
                for (size_t role_idx = 0; role_idx < job.role_count; ++role_idx) {
                    q4_colibri_object_role_job &role = job.roles[role_idx];
                    uint64_t role_relative_offset = 0;
                    if (!q4_colibri_object_role_marker_matches(role) ||
                            !q4_colibri_role_in_read_span(role, job.offset, job.bytes, &role_relative_offset)) {
                        return false;
                    }
                    if (slice.prefix + role_relative_offset + role.entry->nbytes > group.bytes) return false;
                    const ggml_moe_common::role_cache_view role_view = batch_cache_role_view(role.cache);
                    if (!ggml_moe_common::role_cache_ensure_ready_event(role_view, role.slot)) {
                        return false;
                    }
                    const void *role_host = object_host + role_relative_offset;
                    if (cudaMemcpyAsync(role.dst, role_host, role.entry->nbytes,
                                cudaMemcpyHostToDevice, g_q4_colibri_pipe.stream) != cudaSuccess ||
                            !ggml_moe_common::role_cache_record_ready_event(
                                role_view, role.slot, g_q4_colibri_pipe.stream)) {
                        return false;
                    }
                    role.cache->slot_ready_marker[role.slot] = role.marker;
                    role.cache->slot_state[role.slot] = q4_colibri_slot_state::h2d_ready;
                    role.cache->slot_pending[role.slot] = true;
                    role.cache->slot_filling[role.slot] = false;
                    ++ring.copies;
                    ++g_expert_pack.iouring_h2d_enqueues;
                    ++copied_roles;
                    copied_bytes += role.entry->nbytes;
                }
            }
        }
        if (!ggml_moe_common::object_stage_slot_record(slot, g_q4_colibri_pipe.stream)) return false;
        const uint64_t h2d_us = (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now() - h2d_start).count();
        batch.readiness.last_h2d_done = std::chrono::steady_clock::now();
        batch.readiness.inline_h2d_us += h2d_us;
        g_expert_pack.q4_scheduler_h2d_us.fetch_add(h2d_us, std::memory_order_relaxed);
        q4_layer_io_add(g_expert_pack.q4_layer_io_h2d_us, q4_colibri_object_batch_common_layer(batch), h2d_us);

        ++g_expert_pack.io_stats.reads;
        g_expert_pack.io_stats.bytes.fetch_add(group.bytes);
        for (const q4_iouring_group_slice &slice : group.slices) {
            const q4_iouring_plan &plan = plans[slice.plan_idx];
            q4_colibri_object_job &job = batch.jobs[plan.job_idx];
            ++g_expert_pack.q4_object_ssd_reads;
            g_expert_pack.q4_object_ssd_bytes.fetch_add(job.bytes);
            ++g_expert_pack.q4_pipe_completed;
            ++completed;
        }
        --inflight;
        reusable_pending_slots.push_back({pending_idx, done.slot_idx});
        return true;
    };

    auto process_ready_reads = [&]() -> bool {
        if (!object_h2d_batch || ready_reads.empty()) return true;
        const auto h2d_batch_start = std::chrono::steady_clock::now();
        if (batch.readiness.first_h2d_start == std::chrono::steady_clock::time_point{}) {
            batch.readiness.first_h2d_start = h2d_batch_start;
        }
        uint64_t batch_roles = 0;
        uint64_t batch_bytes = 0;
        {
            char nvtx_h2d_label[160];
            std::snprintf(nvtx_h2d_label, sizeof(nvtx_h2d_label),
                    "q4_h2d_object_batch objects=%zu", ready_reads.size());
            moe_nvtx_range nvtx_h2d(nvtx_h2d_label);
            for (const completed_read &done : ready_reads) {
                if (done.group_idx >= read_groups.size() || done.slot_idx >= ring.slots.size()) return false;
                const q4_iouring_read_group &group = read_groups[done.group_idx];
                if (group.slices.size() != 1 || group.slices[0].plan_idx >= plans.size()) return false;
                const q4_iouring_plan &plan = plans[group.slices[0].plan_idx];
                q4_colibri_object_job &job = batch.jobs[plan.job_idx];
                pinned_stage_slot &slot = ring.slots[done.slot_idx];
                if (object_cache && !plan.lossless) {
                    if (slot.object.bytes != 0 && !q4_colibri_object_marker_matches(slot.object, job.marker)) {
                        ++g_expert_pack.q4_object_ram_evictions;
                        ++g_expert_pack.q4_object_ram_demotions;
                    }
                    slot.object = job.marker;
                    slot.object_used = g_q4_colibri_pipe.object_clock++;
                    slot.object_read_us = done.read_us;
                    ++g_expert_pack.q4_object_ram_admissions;
                } else if (plan.lossless) {
                    slot.object = {};
                }
                if (!plan.lossless) {
                    (void)q4_colibri_host_object_prefetch_admit_from_read(
                            job.marker, slot.host, (size_t)job.bytes, done.read_us);
                }
                uint64_t job_role_bytes = 0;
                for (size_t role_idx = 0; role_idx < job.role_count; ++role_idx) {
                    job_role_bytes += job.roles[role_idx].entry ? job.roles[role_idx].entry->nbytes : 0;
                }
                if (plan.lossless) {
                    if (lossless_pending_decodes.size() >=
                            lossless_decode_flush_objects &&
                            !flush_lossless_pending()) {
                        return false;
                    }
                    q4_lossless_pending_decode pending_decode;
                    if (q4_lossless_enqueue_object_from_stage(
                            job, *plan.lossless,
                            slot.host, slot.host_capacity, &slot,
                            done.read_us,
                            lossless_status_cursor, lossless_crc32_cursor,
                            lossless_pending_decodes.size(), true,
                            pending_decode)) {
                        if (async_lossless_decode) {
                            pending_decode.status_offset =
                                lossless_status_output_cursor;
                            lossless_status_output_cursor +=
                                pending_decode.status_count;
                            pending_decode.host_cache_processed = true;
                            (void)q4_colibri_host_object_prefetch_admit_from_read(
                                pending_decode.job->marker,
                                pending_decode.stage->host,
                                static_cast<size_t>(
                                    pending_decode.object->payload_bytes),
                                pending_decode.read_us,
                                ggml_moe_common::object_host_payload_format::lossless_sidecar,
                                static_cast<size_t>(
                                    pending_decode.object->physical_bytes),
                                pending_decode.object->payload_crc32,
                                pending_decode.object->file_offset);
                            if (!ggml_moe_common::object_stage_slot_record(
                                        *pending_decode.stage,
                                        q4_lossless_cuda_stream())) {
                                ++g_expert_pack.lossless_cuda_failures;
                                return false;
                            }
                            ++g_expert_pack.lossless_async_stage_releases;
                        }
                        lossless_status_cursor += pending_decode.status_count;
                        if (pending_decode.crc_required) {
                            lossless_crc32_cursor +=
                                ggml_moe_common::lossless_crc32_segments;
                        }
                        lossless_pending_decodes.push_back(pending_decode);
                        if (lossless_pending_decodes.size() >=
                                lossless_decode_flush_objects &&
                                !flush_lossless_pending()) {
                            return false;
                        }
                    } else if (!q4_lossless_raw_fallback(job, slot)) {
                        return false;
                    }
                    batch_bytes += plan.lossless->payload_bytes;
                    g_expert_pack.lossless_ssd_bytes.fetch_add(
                        plan.bytes, std::memory_order_relaxed);
                    g_expert_pack.lossless_raw_bytes.fetch_add(
                        plan.lossless->raw_bytes, std::memory_order_relaxed);
                    // A compressed object cannot be published as a raw Host
                    // cache entry. Re-reading the raw object duplicates SSD
                    // traffic and previously raced Host-cache slot reuse.
                    if (q4_lossless_raw_host_refill_enabled()) {
                        ++g_expert_pack.lossless_raw_host_refill_requests;
                        q4_direct_host_object_submit_on_read(
                            job.roles[0].entry, done.read_us);
                    } else {
                        ++g_expert_pack.lossless_raw_host_refill_skips;
                    }
                } else {
                    if (!q4_colibri_pipe_h2d_object_from_stage(
                            job, slot, false, false)) {
                        return false;
                    }
                    batch_bytes += job_role_bytes;
                }
                batch_roles += job.role_count;
                ++g_expert_pack.io_stats.reads;
                g_expert_pack.io_stats.bytes.fetch_add(plan.bytes);
                ++g_expert_pack.q4_object_ssd_reads;
                g_expert_pack.q4_object_ssd_bytes.fetch_add(plan.bytes);
                ++g_expert_pack.q4_pipe_completed;
                ++completed;
                if (!object_h2d_async_refill) {
                    reusable_pending_slots.push_back({done.pending_idx, done.slot_idx});
                }
            }
            if (completed == plans.size() && !flush_lossless_pending()) {
                return false;
            }
        }
        const uint64_t h2d_batch_us = (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
                std::chrono::steady_clock::now() - h2d_batch_start).count();
        q4_colibri_object_h2d_batch_record(false, ready_reads.size(), batch_roles, batch_bytes, h2d_batch_us);
        ++batch.readiness.object_h2d_batches;
        batch.readiness.object_h2d_objects += ready_reads.size();
        batch.readiness.object_h2d_roles += batch_roles;
        batch.readiness.object_h2d_bytes += batch_bytes;
        batch.readiness.inline_h2d_us += h2d_batch_us;
        batch.readiness.last_h2d_done = std::chrono::steady_clock::now();
        ready_reads.clear();
        return true;
    };

    auto refill_pending = [&]() -> bool {
        ggml_moe_common::object_pipeline_dispatch_plan common_refill_plan;
        if (common_rolling_refill) {
            ggml_moe_common::object_pipeline_policy refill_policy =
                expert_pack_pipeline_policy_config().policy;
            refill_policy.io_depth = depth;
            refill_policy.initial_batch = refill_batch;
            refill_policy.refill_batch = refill_batch;
            refill_policy.min_flush_batch = std::min(
                refill_policy.min_flush_batch, depth);
            refill_policy.max_inflight_h2d = std::max<size_t>(1, ring.slots.size());
            common_refill_plan = ggml_moe_common::object_pipeline_refill_plan_ready(
                common_refill_cursor, refill_policy, 0, 0, true);
        }
        size_t refill_submit_limit = refill_batch;
        if (common_refill_planner_owns_dispatch) {
            if (common_refill_plan.submit_count > 0) {
                refill_submit_limit = common_refill_plan.submit_count;
                ++g_expert_pack.q4_common_refill_owned_dispatches;
            } else if (next_plan < read_groups.size()) {
                ++g_expert_pack.q4_common_refill_owner_fallbacks;
            }
        }
        size_t submitted = 0;
        while (next_plan < read_groups.size() && inflight < depth &&
                submitted < refill_submit_limit) {
            size_t pending_idx = SIZE_MAX;
            size_t slot_idx = SIZE_MAX;
            if (object_h2d_async_refill) {
                if (free_pending.empty()) break;
                pending_idx = free_pending.back();
                free_pending.pop_back();
                slot_idx = acquire_submit_slot();
                if (slot_idx == SIZE_MAX) {
                    free_pending.push_back(pending_idx);
                    break;
                }
            } else {
                if (reusable_pending_slots.empty()) break;
                const reusable_pending reusable = reusable_pending_slots.back();
                reusable_pending_slots.pop_back();
                pending_idx = reusable.pending_idx;
                slot_idx = reusable.slot_idx;
            }
            if (!submit_one(next_plan, slot_idx, pending_idx)) {
                ++g_expert_pack.io_stats.fallbacks;
                return false;
            }
            ++next_plan;
            ++inflight;
            ++submitted;
        }
        if (submitted > 0) {
            const auto submit_start = std::chrono::steady_clock::now();
            char nvtx_refill_label[160];
            std::snprintf(nvtx_refill_label, sizeof(nvtx_refill_label),
                    "q4_iouring_submit_refill submitted=%zu inflight=%zu", submitted, inflight);
            moe_nvtx_range nvtx_refill(nvtx_refill_label);
            if (!ggml_moe_common::object_io_ring_submit(ring)) {
                ++g_expert_pack.io_stats.fallbacks;
                return false;
            }
            if (common_rolling_refill) {
                if (!ggml_moe_common::object_pipeline_refill_record_submit(
                            common_refill_cursor, submitted)) {
                    ++g_expert_pack.q4_common_refill_failures;
                    return false;
                }
                ++g_expert_pack.q4_common_refill_submit_rounds;
                g_expert_pack.q4_common_refill_submitted.fetch_add(
                    submitted, std::memory_order_relaxed);
            }
            ++g_expert_pack.io_stats.submit_calls;
            ++batch.readiness.refill_submit_calls;
            batch.readiness.refill_submitted += submitted;
            g_expert_pack.io_stats.submit_us.fetch_add(
                (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
                    std::chrono::steady_clock::now() - submit_start).count(), std::memory_order_relaxed);
        }
        if (common_rolling_refill) {
            ++g_expert_pack.q4_common_refill_plan_checks;
            if (common_refill_plan.submit_count == submitted) {
                ++g_expert_pack.q4_common_refill_plan_matches;
            } else {
                ++g_expert_pack.q4_common_refill_plan_mismatches;
            }
        }
        return true;
    };

    while (completed < plans.size()) {
        g_expert_pack.io_stats.inflight_sum.fetch_add(inflight, std::memory_order_relaxed);
        ++g_expert_pack.io_stats.inflight_samples;
        expert_pack_atomic_max(g_expert_pack.io_stats.inflight_max, inflight);
        batch.readiness.inflight_sum += inflight;
        ++batch.readiness.inflight_samples;
        batch.readiness.max_inflight = std::max<uint64_t>(batch.readiness.max_inflight, inflight);
        ring.iouring_inflight_sum += inflight;
        ++ring.iouring_inflight_samples;
        if (ring.iouring_inflight_max < inflight) {
            ring.iouring_inflight_max = inflight;
        }

        ggml_moe_common::object_io_completion completion;
        ++g_expert_pack.io_stats.wait_calls;
        ++batch.readiness.wait_calls;
        if (inflight == 0) {
            ++batch.readiness.wait_no_inflight;
        } else {
            ++batch.readiness.wait_with_inflight;
        }
        const auto wait_start = std::chrono::steady_clock::now();
        char nvtx_wait_label[160];
        std::snprintf(nvtx_wait_label, sizeof(nvtx_wait_label),
                "q4_iouring_wait_cqe inflight=%zu completed=%zu/%zu",
                inflight, completed, plans.size());
        bool wait_ok = false;
        {
            moe_nvtx_range nvtx_wait(nvtx_wait_label);
            wait_ok = ggml_moe_common::object_io_ring_wait(ring, completion);
        }
        g_expert_pack.io_stats.wait_us.fetch_add(
            (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
                std::chrono::steady_clock::now() - wait_start).count(), std::memory_order_relaxed);
        if (!wait_ok) {
            ++g_expert_pack.io_stats.fallbacks;
            return false;
        }
        if (!handle_cqe(completion)) return false;
        if (!object_h2d_batch && (refill_batch == 1 || eager_refill) && !refill_pending()) return false;

        while (completed < plans.size() && inflight > 0) {
            ggml_moe_common::object_io_completion extra_completion;
            const ggml_moe_common::object_io_poll_result peek_result =
                ggml_moe_common::object_io_ring_peek(ring, extra_completion);
            if (peek_result != ggml_moe_common::object_io_poll_result::ready) break;
            if (!handle_cqe(extra_completion)) return false;
            if (!object_h2d_batch && (refill_batch == 1 || eager_refill) && !refill_pending()) return false;
        }
        if (object_h2d_batch && !process_ready_reads()) return false;
        if (object_h2d_async_refill && !collect_async_h2d_slots(false)) return false;
        if ((object_h2d_batch || (refill_batch > 1 && !eager_refill)) && !refill_pending()) return false;
    }
    if (!flush_lossless_pending()) return false;
    if (async_lossless_decode && !lossless_queued_decodes.empty()) {
        const bool all_crc_verified = std::none_of(
            lossless_queued_decodes.begin(),
            lossless_queued_decodes.end(),
            [](const q4_lossless_pending_decode &decode) {
                return decode.crc_required;
            });
        const bool publish_verified_async = all_crc_verified &&
            expert_pack_env_bool(
                "GGML_MOE_LOSSLESS_ASYNC_TRUST_VERIFIED", false);
        if (publish_verified_async) {
            for (const q4_lossless_pending_decode &pending_decode :
                    lossless_queued_decodes) {
                if (!q4_lossless_publish_decoded(
                            pending_decode, false)) {
                    return false;
                }
            }
            ++g_expert_pack.lossless_async_verified_batches;
            g_expert_pack.lossless_async_verified_objects.fetch_add(
                lossless_queued_decodes.size(), std::memory_order_relaxed);
        } else {
            const auto sync_start = std::chrono::steady_clock::now();
            if (cudaStreamSynchronize(q4_lossless_cuda_stream()) != cudaSuccess) {
                ++g_expert_pack.lossless_cuda_failures;
                return false;
            }
            const uint64_t sync_us =
                (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
                    std::chrono::steady_clock::now() - sync_start).count();
            ++g_expert_pack.lossless_async_decode_syncs;
            g_expert_pack.lossless_async_decode_sync_us.fetch_add(
                sync_us, std::memory_order_relaxed);
            g_expert_pack.lossless_decode_us.fetch_add(
                sync_us, std::memory_order_relaxed);
            for (const q4_lossless_pending_decode &pending_decode :
                    lossless_queued_decodes) {
                if (!q4_lossless_publish_decoded(pending_decode)) {
                    if (pending_decode.host_cache_processed &&
                            pending_decode.job && pending_decode.object) {
                        q4_lossless_invalidate_early_host_admission(
                            pending_decode.job->marker,
                            pending_decode.object->file_offset);
                    }
                    if (!pending_decode.job || !pending_decode.stage ||
                            !q4_lossless_raw_fallback(
                                *pending_decode.job, *pending_decode.stage)) {
                        return false;
                    }
                }
            }
        }
        lossless_queued_decodes.clear();
    }
    async_abort_guard.armed = false;

    const uint64_t batch_read_us = (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
        std::chrono::steady_clock::now() - batch_read_start).count();
    if (common_object_cqe) {
        ggml_moe_common::object_io_window_reset(io_window.data(), io_window.size());
    }
    if (common_rolling_refill) {
        if (!ggml_moe_common::object_pipeline_refill_done(common_refill_cursor)) {
            ++g_expert_pack.q4_common_refill_failures;
            return false;
        }
        ++g_expert_pack.q4_common_refill_completed_batches;
    }
    g_expert_pack.q4_scheduler_read_us.fetch_add(batch_read_us, std::memory_order_relaxed);
    q4_layer_io_add(g_expert_pack.q4_layer_io_read_us, q4_colibri_object_batch_common_layer(batch), batch_read_us);
    return true;
#else
    (void)batch;
    if (attempted) *attempted = false;
    return false;
#endif
}

static bool q4_colibri_pipe_process_object_batch(q4_colibri_object_batch &batch) {
    if (q4_colibri_batch_iouring_enabled()) {
        bool attempted = false;
        if (q4_colibri_pipe_process_object_batch_iouring(batch, &attempted)) {
            return true;
        }
        if (attempted) {
            for (q4_colibri_object_job &job : batch.jobs) {
                q4_colibri_object_job_fail(job);
            }
            g_expert_pack.q4_pipe_failed.fetch_add(batch.jobs.size(), std::memory_order_relaxed);
            g_expert_pack.q4_scheduler_failures.fetch_add(batch.jobs.size(), std::memory_order_relaxed);
            q4_layer_io_add(g_expert_pack.q4_layer_io_failures,
                    q4_colibri_object_batch_common_layer(batch), (uint64_t)batch.jobs.size());
            return false;
        }
    }
    bool success = true;
    for (q4_colibri_object_job &job : batch.jobs) {
        const bool object_ok = q4_colibri_pipe_process_object(job);
        if (object_ok) {
            ++g_expert_pack.q4_pipe_completed;
        } else {
            q4_colibri_object_job_fail(job);
            ++g_expert_pack.q4_pipe_failed;
            ++g_expert_pack.q4_scheduler_failures;
            q4_layer_io_add(g_expert_pack.q4_layer_io_failures, job.marker.layer_idx, 1);
            success = false;
        }
    }
    return success;
}

static void q4_colibri_pipe_finish(q4_colibri_pipe_job &job, bool success) {
    if (!job.completion) return;
    {
        std::lock_guard<std::mutex> lock(job.completion->mu);
        job.completion->success = success;
        job.completion->done = true;
    }
    job.completion->cv.notify_one();
}

static bool q4_colibri_pipe_process_object_work(q4_colibri_object_batch *object_batch) {
    if (!object_batch) return false;
    const auto worker_start = std::chrono::steady_clock::now();
    object_batch->readiness.worker_start = worker_start;
    g_expert_pack.q4_pipe_queue_wait_us.fetch_add(
        (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
            worker_start - object_batch->queued_at).count(), std::memory_order_relaxed);
    bool success = q4_colibri_pipe_process_object_batch(*object_batch);
    success = q4_colibri_common_engine_complete(*object_batch, success) && success;
    object_batch->readiness.provider_done = std::chrono::steady_clock::now();
    if (object_batch->pilot_prefetch) {
        if (success) {
            g_expert_pack.q4_pilot_prefetch_completed_objects.fetch_add(
                object_batch->jobs.size(), std::memory_order_relaxed);
        } else {
            g_expert_pack.q4_pilot_prefetch_failed_objects.fetch_add(
                object_batch->jobs.size(), std::memory_order_relaxed);
        }
    }
    g_expert_pack.q4_pipe_worker_us.fetch_add(
        (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now() - worker_start).count(), std::memory_order_relaxed);
    q4_colibri_pipe_job completion_job;
    completion_job.completion = object_batch->completion;
    q4_colibri_pipe_finish(completion_job, success);
    if (object_batch->heap_owned) delete object_batch;
    return success;
}

static bool q4_colibri_pipe_process_single_work(q4_colibri_pipe_job &job) {
    if (g_expert_pack.lossless_standalone) {
        q4_colibri_fail(
            "standalone lossless transport reached the legacy single-role reader");
    }
    const auto worker_start = std::chrono::steady_clock::now();
    g_expert_pack.q4_pipe_queue_wait_us.fetch_add(
        (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
            worker_start - job.queued_at).count(), std::memory_order_relaxed);
    bool success = q4_colibri_pipe_marker_matches(job);
    if (success) {
        job.cache->slot_state[job.slot] = q4_colibri_slot_state::reading;
        batch_copy_trace trace;
        success = batch_cache_copy_h2d(
            g_q4_colibri_pipe.ring, job.dst, nullptr, job.marker.bytes,
            g_q4_colibri_pipe.stream, job.entry, &trace,
            "q4_colibri_pipe", job.tensor, job.expert_idx);
    }
    if (success && q4_colibri_pipe_marker_matches(job)) {
        const ggml_moe_common::role_cache_view role_view = batch_cache_role_view(job.cache);
        if (!ggml_moe_common::role_cache_ensure_ready_event(role_view, job.slot)) {
            success = false;
        }
        if (success && !ggml_moe_common::role_cache_record_ready_event(
                    role_view, job.slot, g_q4_colibri_pipe.stream)) {
            success = false;
        }
    }
    if (success && q4_colibri_pipe_marker_matches(job)) {
        job.cache->slot_ready_marker[job.slot] = job.marker;
        job.cache->slot_state[job.slot] = q4_colibri_slot_state::h2d_ready;
        job.cache->slot_pending[job.slot] = true;
        job.cache->slot_filling[job.slot] = false;
        ++g_expert_pack.q4_pipe_completed;
        g_expert_pack.q4_pipe_ready_latency_us.fetch_add(
            (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
                std::chrono::steady_clock::now() - job.queued_at).count(), std::memory_order_relaxed);
    } else {
        if (job.cache && job.slot >= 0 && job.slot < job.cache->n_slots &&
                q4_colibri_pipe_marker_matches(job)) {
            job.cache->slot_state[job.slot] = q4_colibri_slot_state::failed;
            job.cache->slot_filling[job.slot] = false;
        }
        ++g_expert_pack.q4_pipe_failed;
    }
    g_expert_pack.q4_pipe_worker_us.fetch_add(
        (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
            std::chrono::steady_clock::now() - worker_start).count(), std::memory_order_relaxed);
    q4_colibri_pipe_finish(job, success);
    return success;
}

static bool q4_colibri_common_worker_init(void *) {
    return cudaSetDevice(0) == cudaSuccess;
}

static bool q4_colibri_common_worker_process(void *, void *context, uint32_t kind) {
    if (kind == 0) {
        return q4_colibri_pipe_process_object_work(
            static_cast<q4_colibri_object_batch *>(context));
    }
    if (kind == 1) {
        return q4_colibri_pipe_process_single_work(
            *static_cast<q4_colibri_pipe_job *>(context));
    }
    return false;
}

static void q4_colibri_pipe_worker() {
    expert_pack_apply_current_thread_affinity("GGML_MOE_Q4_PIPE_CPUSET", "q4_pipe");
    const bool device_ok = cudaSetDevice(0) == cudaSuccess;
    {
        std::lock_guard<std::mutex> lock(g_q4_colibri_pipe.mu);
        g_q4_colibri_pipe.failed = !device_ok;
        g_q4_colibri_pipe.started = true;
    }
    g_q4_colibri_pipe.cv.notify_all();
    if (!device_ok) {
        return;
    }
    for (;;) {
        q4_colibri_pipe_job job;
        q4_colibri_object_batch *object_batch = nullptr;
        {
            std::unique_lock<std::mutex> lock(g_q4_colibri_pipe.mu);
            g_q4_colibri_pipe.cv.wait(lock, [] {
                return g_q4_colibri_pipe.stop || q4_colibri_object_queue_pending() ||
                    !g_q4_colibri_pipe.jobs.empty();
            });
            if (g_q4_colibri_pipe.stop && !q4_colibri_object_queue_pending() &&
                    g_q4_colibri_pipe.jobs.empty()) break;
            if (q4_colibri_object_queue_pending()) {
                object_batch = q4_colibri_object_queue_take();
            } else {
                job = g_q4_colibri_pipe.jobs.front();
                g_q4_colibri_pipe.jobs.pop_front();
            }
        }

        if (object_batch) {
            (void)q4_colibri_pipe_process_object_work(object_batch);
            continue;
        }
        (void)q4_colibri_pipe_process_single_work(job);
    }
}

static void q4_colibri_host_object_freq_dump() {
    const char *path = std::getenv("GGML_MOE_Q4_HOST_OBJECT_FREQ_DUMP");
    if (!path || !path[0]) return;
    std::vector<std::pair<std::string, uint32_t>> rows;
    rows.reserve(g_q4_host_object_prefetch.request_freq.size());
    for (const auto &kv : g_q4_host_object_prefetch.request_freq) {
        rows.push_back(kv);
    }
    std::sort(rows.begin(), rows.end(), [](const auto &a, const auto &b) {
        if (a.second != b.second) return a.second > b.second;
        return a.first < b.first;
    });
    std::ofstream out(path);
    if (!out) {
        std::fprintf(stderr, "[moe_stream_batch] q4 host object freq dump failed: path=%s\n", path);
        return;
    }
    out << "freq\tsource\tlayer\texpert\tmanifest_generation\toffset\tbytes\tkey\n";
    for (const auto &row : rows) {
        int source = -1;
        int layer = -1;
        int expert = -1;
        unsigned long manifest = 0;
        unsigned long offset = 0;
        size_t bytes = 0;
        const int parsed = std::sscanf(row.first.c_str(), "%d:%d:%d:%lx:%lu:%zu",
                &source, &layer, &expert, &manifest, &offset, &bytes);
        if (parsed == 6) {
            out << row.second << '\t' << source << '\t' << layer << '\t' << expert << '\t'
                << std::hex << manifest << std::dec << '\t' << offset << '\t' << bytes << '\t'
                << row.first << '\n';
        } else {
            out << row.second << "\t-1\t-1\t-1\t0\t0\t0\t" << row.first << '\n';
        }
    }
    std::fprintf(stderr,
            "[moe_stream_batch] q4 host object freq dump: path=%s rows=%zu\n",
            path, rows.size());
}

static void q4_colibri_layer_cache_summary_dump(
        const uint64_t *layer_ram_ready_objects,
        const uint64_t *layer_ram_vram_full_overlap_objects,
        const uint64_t *layer_ram_vram_any_overlap_objects,
        const uint64_t *layer_ram_vram_partial_overlap_roles) {
    const char *path = std::getenv("GGML_MOE_Q4_LAYER_CACHE_SUMMARY_OUT");
    if (!path || !path[0]) return;

    std::ofstream out(path);
    if (!out) {
        std::fprintf(stderr, "[moe_stream_batch] q4 layer cache summary dump failed: path=%s\n", path);
        return;
    }

    out << "layer"
        << ",object_demands,active_experts,requested_objects"
        << ",vram_full_hits,vram_full_misses,vram_full_hit_rate"
        << ",ram_hits,ram_misses,ram_hit_rate"
        << ",ram_bytes_avoided,ram_wait_us_avoided,ram_h2d_us,ram_h2d_bytes,ram_net_us"
        << ",physical_jobs,role_slices,physical_bytes,logical_bytes,overread_bytes"
        << ",wait_us,read_us,h2d_us,failures"
        << ",ram_ready,ram_vram_full_overlap,ram_vram_any_partial,ram_vram_partial_roles"
        << ",vram_evictions,vram_evicted_reused_within_window"
        << ",ram_hits_after_vram_eviction,ram_hits_after_vram_eviction_within_window"
        << ",covered_ram_evictions,covered_ram_eviction_misses_within_window"
        << ",locality_samples,vram_roles,vram_near_roles,vram_near_role_rate"
        << ",vram_full_objects,vram_near_full_objects,vram_near_full_rate"
        << ",ram_objects,ram_near_objects,ram_near_rate"
        << ",locality_ram_vram_full_overlap,locality_ram_vram_any_overlap"
        << ",locality_ram_vram_partial_roles\n";

    size_t rows = 0;
    for (int layer = 0; layer < 128; ++layer) {
        const uint64_t object_demands = g_q4_tier_overlap_diag.tier_layer_object_demands[layer].load();
        const uint64_t active = g_expert_pack.q4_layer_io_active_experts[layer].load();
        const uint64_t requested = g_expert_pack.q4_layer_io_requested_objects[layer].load();
        const uint64_t vram_hits = layer < 64 ? g_expert_pack.q4_object_layer_vram_hits[layer].load() : 0;
        const uint64_t vram_misses = layer < 64 ? g_expert_pack.q4_object_layer_vram_misses[layer].load() : 0;
        const uint64_t ram_hits = layer < 64 ? g_expert_pack.q4_object_layer_ram_hits[layer].load() : 0;
        const uint64_t ram_misses = layer < 64 ? g_expert_pack.q4_object_layer_ram_misses[layer].load() : 0;
        const uint64_t ram_bytes_avoided = layer < 64 ? g_expert_pack.q4_object_layer_ram_bytes_avoided[layer].load() : 0;
        const uint64_t ram_wait_us_avoided = layer < 64 ? g_expert_pack.q4_object_layer_ram_wait_us_avoided[layer].load() : 0;
        const uint64_t ram_h2d_us = layer < 64 ? g_expert_pack.q4_object_layer_ram_h2d_us[layer].load() : 0;
        const uint64_t ram_h2d_bytes = layer < 64 ? g_expert_pack.q4_object_layer_ram_h2d_bytes[layer].load() : 0;
        const uint64_t physical_jobs = g_expert_pack.q4_layer_io_physical_jobs[layer].load();
        const uint64_t role_slices = g_expert_pack.q4_layer_io_role_slices[layer].load();
        const uint64_t physical_bytes = g_expert_pack.q4_layer_io_physical_bytes[layer].load();
        const uint64_t logical_bytes = g_expert_pack.q4_layer_io_logical_bytes[layer].load();
        const uint64_t wait_us = g_expert_pack.q4_layer_io_wait_us[layer].load();
        const uint64_t read_us = g_expert_pack.q4_layer_io_read_us[layer].load();
        const uint64_t h2d_us = g_expert_pack.q4_layer_io_h2d_us[layer].load();
        const uint64_t failures = g_expert_pack.q4_layer_io_failures[layer].load();
        const uint64_t vram_evictions = g_q4_tier_overlap_diag.tier_layer_vram_evictions[layer].load();
        const uint64_t vram_reused = g_q4_tier_overlap_diag.tier_layer_vram_evicted_reused_within_window[layer].load();
        const uint64_t ram_hits_after_vram =
            g_q4_tier_overlap_diag.tier_layer_ram_hits_after_vram_eviction[layer].load();
        const uint64_t ram_hits_after_vram_w =
            g_q4_tier_overlap_diag.tier_layer_ram_hits_after_vram_eviction_within_window[layer].load();
        const uint64_t covered_ram_evictions = g_q4_tier_overlap_diag.tier_layer_covered_ram_evictions[layer].load();
        const uint64_t covered_ram_misses =
            g_q4_tier_overlap_diag.tier_layer_covered_ram_eviction_misses_within_window[layer].load();
        const uint64_t locality_samples = g_q4_tier_overlap_diag.cache_locality_layer_samples[layer].load();
        const uint64_t locality_vram_roles = g_q4_tier_overlap_diag.cache_locality_layer_vram_roles[layer].load();
        const uint64_t locality_vram_near_roles =
            g_q4_tier_overlap_diag.cache_locality_layer_vram_near_roles[layer].load();
        const uint64_t locality_vram_full =
            g_q4_tier_overlap_diag.cache_locality_layer_vram_full_objects[layer].load();
        const uint64_t locality_vram_near_full =
            g_q4_tier_overlap_diag.cache_locality_layer_vram_near_full_objects[layer].load();
        const uint64_t locality_ram = g_q4_tier_overlap_diag.cache_locality_layer_ram_objects[layer].load();
        const uint64_t locality_ram_near =
            g_q4_tier_overlap_diag.cache_locality_layer_ram_near_objects[layer].load();
        const uint64_t locality_ram_vram_full =
            g_q4_tier_overlap_diag.cache_locality_layer_ram_vram_full_overlap[layer].load();
        const uint64_t locality_ram_vram_any =
            g_q4_tier_overlap_diag.cache_locality_layer_ram_vram_any_overlap[layer].load();
        const uint64_t locality_ram_vram_partial_roles =
            g_q4_tier_overlap_diag.cache_locality_layer_ram_vram_partial_roles[layer].load();

        if (object_demands == 0 && active == 0 && requested == 0 && vram_hits == 0 && vram_misses == 0 &&
                ram_hits == 0 && ram_misses == 0 && physical_jobs == 0 && wait_us == 0 &&
                layer_ram_ready_objects[layer] == 0 && locality_samples == 0) {
            continue;
        }

        const uint64_t overread = physical_bytes > logical_bytes ? physical_bytes - logical_bytes : 0;
        const long long ram_net_us = (long long)ram_wait_us_avoided - (long long)ram_h2d_us;
        const double vram_hit_rate = (vram_hits + vram_misses) > 0 ?
            100.0 * (double)vram_hits / (double)(vram_hits + vram_misses) : 0.0;
        const double ram_hit_rate = (ram_hits + ram_misses) > 0 ?
            100.0 * (double)ram_hits / (double)(ram_hits + ram_misses) : 0.0;
        const double locality_vram_near_role_rate = locality_vram_roles > 0 ?
            100.0 * (double)locality_vram_near_roles / (double)locality_vram_roles : 0.0;
        const double locality_vram_near_full_rate = locality_vram_full > 0 ?
            100.0 * (double)locality_vram_near_full / (double)locality_vram_full : 0.0;
        const double locality_ram_near_rate = locality_ram > 0 ?
            100.0 * (double)locality_ram_near / (double)locality_ram : 0.0;

        out << layer
            << ',' << object_demands
            << ',' << active
            << ',' << requested
            << ',' << vram_hits
            << ',' << vram_misses
            << ',' << vram_hit_rate
            << ',' << ram_hits
            << ',' << ram_misses
            << ',' << ram_hit_rate
            << ',' << ram_bytes_avoided
            << ',' << ram_wait_us_avoided
            << ',' << ram_h2d_us
            << ',' << ram_h2d_bytes
            << ',' << ram_net_us
            << ',' << physical_jobs
            << ',' << role_slices
            << ',' << physical_bytes
            << ',' << logical_bytes
            << ',' << overread
            << ',' << wait_us
            << ',' << read_us
            << ',' << h2d_us
            << ',' << failures
            << ',' << layer_ram_ready_objects[layer]
            << ',' << layer_ram_vram_full_overlap_objects[layer]
            << ',' << layer_ram_vram_any_overlap_objects[layer]
            << ',' << layer_ram_vram_partial_overlap_roles[layer]
            << ',' << vram_evictions
            << ',' << vram_reused
            << ',' << ram_hits_after_vram
            << ',' << ram_hits_after_vram_w
            << ',' << covered_ram_evictions
            << ',' << covered_ram_misses
            << ',' << locality_samples
            << ',' << locality_vram_roles
            << ',' << locality_vram_near_roles
            << ',' << locality_vram_near_role_rate
            << ',' << locality_vram_full
            << ',' << locality_vram_near_full
            << ',' << locality_vram_near_full_rate
            << ',' << locality_ram
            << ',' << locality_ram_near
            << ',' << locality_ram_near_rate
            << ',' << locality_ram_vram_full
            << ',' << locality_ram_vram_any
            << ',' << locality_ram_vram_partial_roles
            << '\n';
        ++rows;
    }

    std::fprintf(stderr,
            "[moe_stream_batch] q4 layer cache summary dump: path=%s rows=%zu\n",
            path, rows);
}

static void q4_colibri_host_object_prefetch_shutdown_and_report() {
    if (!g_q4_host_object_prefetch.inited) return;
    static std::atomic<bool> reported{false};
    bool expected = false;
    if (!reported.compare_exchange_strong(expected, true)) return;
    {
        std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
        g_q4_host_object_prefetch.stop = true;
    }
    g_q4_host_object_prefetch.cv.notify_all();
    if (g_q4_host_object_prefetch.worker.joinable()) {
        g_q4_host_object_prefetch.worker.join();
    }
    {
        std::lock_guard<std::mutex> lock(g_q4_host_object_prefetch.mu);
        q4_colibri_host_object_sweep_completed_deletes_locked();
        q4_colibri_host_object_sweep_completed_d2h_locked();
    }
    const size_t resident_capacity_at_shutdown = g_q4_host_object_prefetch.resident_capacity_bytes;
    uint64_t ram_ready_objects = 0;
    uint64_t ram_vram_full_overlap_objects = 0;
    uint64_t ram_vram_any_overlap_objects = 0;
    uint64_t ram_vram_partial_overlap_roles = 0;
    uint64_t ram_origin_resident[Q4_HOST_OBJECT_ORIGIN_COUNT] = {};
    uint64_t layer_ram_ready_objects[128] = {};
    uint64_t layer_ram_vram_full_overlap_objects[128] = {};
    uint64_t layer_ram_vram_any_overlap_objects[128] = {};
    uint64_t layer_ram_vram_partial_overlap_roles[128] = {};
    for (const q4_colibri_host_object_slot &slot : g_q4_host_object_prefetch.slots) {
        if (!slot.ready) continue;
        ++ram_ready_objects;
        ++ram_origin_resident[q4_host_object_origin_normalize(slot.origin)];
        const int layer = slot.marker.layer_idx;
        if (layer >= 0 && layer < 128) {
            ++layer_ram_ready_objects[layer];
        }
        const int vram_roles = q4_tier_diag_vram_roles_for_object(slot.marker);
        if (vram_roles == 3) {
            ++ram_vram_full_overlap_objects;
            if (layer >= 0 && layer < 128) {
                ++layer_ram_vram_full_overlap_objects[layer];
            }
        } else if (vram_roles > 0) {
            ++ram_vram_any_overlap_objects;
            ram_vram_partial_overlap_roles += (uint64_t)vram_roles;
            if (layer >= 0 && layer < 128) {
                ++layer_ram_vram_any_overlap_objects[layer];
                layer_ram_vram_partial_overlap_roles[layer] += (uint64_t)vram_roles;
            }
        }
    }
    uint64_t tier_diag_epoch = 0;
    size_t tracked_vram_evictions = 0;
    size_t tracked_covered_ram_evictions = 0;
    {
        std::lock_guard<std::mutex> lock(g_q4_tier_overlap_diag.mu);
        tier_diag_epoch = g_q4_tier_overlap_diag.token_epoch;
        tracked_vram_evictions = g_q4_tier_overlap_diag.vram_evicted_epoch.size();
        tracked_covered_ram_evictions = g_q4_tier_overlap_diag.covered_ram_evicted_epoch.size();
    }
    std::fprintf(stderr,
        "[moe_stream_batch] q4 tier overlap diag: window_tokens=%d token_epoch=%lu object_demands=%lu "
        "ram_ready=%lu ram_vram_full_overlap=%lu ram_vram_any_partial=%lu ram_vram_partial_roles=%lu "
        "vram_evictions=%lu vram_evicted_reused_within_window=%lu tracked_vram_evictions=%zu "
        "vram_reuse_protect_marks=%lu vram_reuse_protect_layer_skips=%lu "
        "vram_reuse_protect_penalized=%lu "
        "vram_reuse_protect_selected=%lu vram_reuse_protect_expired=%lu "
        "vram_static_hotness_protect=%d vram_static_hotness_ticks=%lu "
        "vram_static_hotness_protected=%lu vram_static_hotness_selected=%lu "
        "ram_hits_after_vram_eviction=%lu ram_hits_after_vram_eviction_within_window=%lu "
        "ram_hit_vram_full_overlap=%lu ram_hit_vram_partial_roles=%lu "
        "covered_ram_evictions=%lu covered_ram_eviction_misses_within_window=%lu tracked_covered_ram_evictions=%zu "
        "tier_delete_ram_on_h2d=%lu tier_demote_attempts=%lu tier_demote_success=%lu "
        "tier_demote_skip_incomplete_vram=%lu tier_demote_skip_already_ram=%lu tier_demote_skip_no_slot=%lu "
        "tier_demote_skip_low_value=%lu tier_demote_bytes=%lu tier_demote_d2h_us=%lu "
        "tier_demote_async_submitted=%lu tier_demote_async_completed=%lu "
        "tier_demote_async_enqueue_failures=%lu tier_demote_async_event_failures=%lu "
        "tier_demote_async_pending_bytes=%lu tier_demote_async_enqueue_us=%lu "
        "tier_vram_score_victim_selections=%lu "
        "tier_soft_dedup_victim_candidates=%lu tier_soft_dedup_evictions=%lu\n",
        q4_tier_diag_window_tokens(),
        (unsigned long)tier_diag_epoch,
        (unsigned long)g_q4_tier_overlap_diag.object_demands.load(),
        (unsigned long)ram_ready_objects,
        (unsigned long)ram_vram_full_overlap_objects,
        (unsigned long)ram_vram_any_overlap_objects,
        (unsigned long)ram_vram_partial_overlap_roles,
        (unsigned long)g_q4_tier_overlap_diag.vram_evictions.load(),
        (unsigned long)g_q4_tier_overlap_diag.vram_evicted_reused_within_window.load(),
        tracked_vram_evictions,
        (unsigned long)g_q4_tier_overlap_diag.vram_reuse_protect_marks.load(),
        (unsigned long)g_q4_tier_overlap_diag.vram_reuse_protect_layer_skips.load(),
        (unsigned long)g_q4_tier_overlap_diag.vram_reuse_protect_penalized.load(),
        (unsigned long)g_q4_tier_overlap_diag.vram_reuse_protect_selected.load(),
        (unsigned long)g_q4_tier_overlap_diag.vram_reuse_protect_expired.load(),
        q4_vram_static_hotness_protect_enabled() ? 1 : 0,
        (unsigned long)q4_vram_static_hotness_protect_ticks(),
        (unsigned long)g_q4_tier_overlap_diag.vram_static_hotness_protected.load(),
        (unsigned long)g_q4_tier_overlap_diag.vram_static_hotness_selected.load(),
        (unsigned long)g_q4_tier_overlap_diag.ram_hits_after_vram_eviction.load(),
        (unsigned long)g_q4_tier_overlap_diag.ram_hits_after_vram_eviction_within_window.load(),
        (unsigned long)g_q4_tier_overlap_diag.ram_hit_vram_full_overlap.load(),
        (unsigned long)g_q4_tier_overlap_diag.ram_hit_vram_partial_overlap_roles.load(),
        (unsigned long)g_q4_tier_overlap_diag.covered_ram_evictions.load(),
        (unsigned long)g_q4_tier_overlap_diag.covered_ram_eviction_misses_within_window.load(),
        tracked_covered_ram_evictions,
        (unsigned long)g_q4_tier_overlap_diag.tier_delete_ram_on_h2d.load(),
        (unsigned long)g_q4_tier_overlap_diag.tier_demote_attempts.load(),
        (unsigned long)g_q4_tier_overlap_diag.tier_demote_success.load(),
        (unsigned long)g_q4_tier_overlap_diag.tier_demote_skip_incomplete_vram.load(),
        (unsigned long)g_q4_tier_overlap_diag.tier_demote_skip_already_ram.load(),
        (unsigned long)g_q4_tier_overlap_diag.tier_demote_skip_no_slot.load(),
        (unsigned long)g_q4_tier_overlap_diag.tier_demote_skip_low_value.load(),
        (unsigned long)g_q4_tier_overlap_diag.tier_demote_bytes.load(),
        (unsigned long)g_q4_tier_overlap_diag.tier_demote_d2h_us.load(),
        (unsigned long)g_q4_tier_overlap_diag.tier_demote_async_submitted.load(),
        (unsigned long)g_q4_tier_overlap_diag.tier_demote_async_completed.load(),
        (unsigned long)g_q4_tier_overlap_diag.tier_demote_async_enqueue_failures.load(),
        (unsigned long)g_q4_tier_overlap_diag.tier_demote_async_event_failures.load(),
        (unsigned long)g_q4_tier_overlap_diag.tier_demote_async_pending_bytes.load(),
        (unsigned long)g_q4_tier_overlap_diag.tier_demote_async_enqueue_us.load(),
        (unsigned long)g_q4_tier_overlap_diag.tier_vram_score_victim_selections.load(),
        (unsigned long)g_q4_tier_overlap_diag.tier_soft_dedup_victim_candidates.load(),
        (unsigned long)g_q4_tier_overlap_diag.tier_soft_dedup_evictions.load());
    if (q4_tier_reuse_window_profile_enabled()) {
        std::fprintf(stderr,
            "[moe_stream_batch] q4 tier reuse windows: k1=%lu k2=%lu k4=%lu k8=%lu k16=%lu k32=%lu k64=%lu k128=%lu\n",
            (unsigned long)g_q4_tier_overlap_diag.vram_evicted_reused_by_window[0].load(),
            (unsigned long)g_q4_tier_overlap_diag.vram_evicted_reused_by_window[1].load(),
            (unsigned long)g_q4_tier_overlap_diag.vram_evicted_reused_by_window[2].load(),
            (unsigned long)g_q4_tier_overlap_diag.vram_evicted_reused_by_window[3].load(),
            (unsigned long)g_q4_tier_overlap_diag.vram_evicted_reused_by_window[4].load(),
            (unsigned long)g_q4_tier_overlap_diag.vram_evicted_reused_by_window[5].load(),
            (unsigned long)g_q4_tier_overlap_diag.vram_evicted_reused_by_window[6].load(),
            (unsigned long)g_q4_tier_overlap_diag.vram_evicted_reused_by_window[7].load());
    }
    if (q4_object_score_profile_enabled()) {
        const uint64_t ram_candidates = g_q4_tier_overlap_diag.score_profile_ram_candidates.load();
        const uint64_t ram_victims = g_q4_tier_overlap_diag.score_profile_ram_victim_events.load();
        const uint64_t vram_evictions = g_q4_tier_overlap_diag.score_profile_vram_evictions.load();
        std::fprintf(stderr,
            "[moe_stream_batch] q4 score profile: enabled=1 "
            "ram_candidates=%lu ram_admitted=%lu ram_rejected=%lu ram_empty_slot=%lu "
            "ram_victim_events=%lu ram_candidate_gt_victim=%lu ram_candidate_eq_victim=%lu "
            "ram_candidate_lt_victim=%lu ram_candidate_score_avg=%.1f ram_victim_score_avg=%.1f "
            "vram_evictions=%lu vram_candidate_gt_victim=%lu vram_candidate_eq_victim=%lu "
            "vram_candidate_lt_victim=%lu vram_candidate_score_avg=%.1f vram_victim_score_avg=%.1f\n",
            (unsigned long)ram_candidates,
            (unsigned long)g_q4_tier_overlap_diag.score_profile_ram_admitted.load(),
            (unsigned long)g_q4_tier_overlap_diag.score_profile_ram_rejected.load(),
            (unsigned long)g_q4_tier_overlap_diag.score_profile_ram_empty_slot.load(),
            (unsigned long)ram_victims,
            (unsigned long)g_q4_tier_overlap_diag.score_profile_ram_candidate_gt_victim.load(),
            (unsigned long)g_q4_tier_overlap_diag.score_profile_ram_candidate_eq_victim.load(),
            (unsigned long)g_q4_tier_overlap_diag.score_profile_ram_candidate_lt_victim.load(),
            ram_candidates > 0 ?
                (double)g_q4_tier_overlap_diag.score_profile_ram_candidate_score_sum.load() / (double)ram_candidates : 0.0,
            ram_victims > 0 ?
                (double)g_q4_tier_overlap_diag.score_profile_ram_victim_score_sum.load() / (double)ram_victims : 0.0,
            (unsigned long)vram_evictions,
            (unsigned long)g_q4_tier_overlap_diag.score_profile_vram_candidate_gt_victim.load(),
            (unsigned long)g_q4_tier_overlap_diag.score_profile_vram_candidate_eq_victim.load(),
            (unsigned long)g_q4_tier_overlap_diag.score_profile_vram_candidate_lt_victim.load(),
            vram_evictions > 0 ?
                (double)g_q4_tier_overlap_diag.score_profile_vram_candidate_score_sum.load() / (double)vram_evictions : 0.0,
            vram_evictions > 0 ?
                (double)g_q4_tier_overlap_diag.score_profile_vram_victim_score_sum.load() / (double)vram_evictions : 0.0);
        for (int layer = 0; layer < 128; ++layer) {
            const uint64_t layer_ram_candidates =
                g_q4_tier_overlap_diag.score_profile_layer_ram_candidates[layer].load();
            const uint64_t layer_ram_victims =
                g_q4_tier_overlap_diag.score_profile_layer_ram_victim_events[layer].load();
            const uint64_t layer_vram_evictions =
                g_q4_tier_overlap_diag.score_profile_layer_vram_evictions[layer].load();
            if (layer_ram_candidates == 0 && layer_vram_evictions == 0) continue;
            std::fprintf(stderr,
                "[moe_stream_batch] q4 score profile layer: layer=%d "
                "ram_candidates=%lu ram_admitted=%lu ram_rejected=%lu ram_empty_slot=%lu "
                "ram_victim_events=%lu ram_candidate_gt_victim=%lu ram_candidate_eq_victim=%lu "
                "ram_candidate_lt_victim=%lu ram_candidate_score_avg=%.1f ram_victim_score_avg=%.1f "
                "vram_evictions=%lu vram_candidate_gt_victim=%lu vram_candidate_eq_victim=%lu "
                "vram_candidate_lt_victim=%lu vram_candidate_score_avg=%.1f vram_victim_score_avg=%.1f\n",
                layer,
                (unsigned long)layer_ram_candidates,
                (unsigned long)g_q4_tier_overlap_diag.score_profile_layer_ram_admitted[layer].load(),
                (unsigned long)g_q4_tier_overlap_diag.score_profile_layer_ram_rejected[layer].load(),
                (unsigned long)g_q4_tier_overlap_diag.score_profile_layer_ram_empty_slot[layer].load(),
                (unsigned long)layer_ram_victims,
                (unsigned long)g_q4_tier_overlap_diag.score_profile_layer_ram_candidate_gt_victim[layer].load(),
                (unsigned long)g_q4_tier_overlap_diag.score_profile_layer_ram_candidate_eq_victim[layer].load(),
                (unsigned long)g_q4_tier_overlap_diag.score_profile_layer_ram_candidate_lt_victim[layer].load(),
                layer_ram_candidates > 0 ?
                    (double)g_q4_tier_overlap_diag.score_profile_layer_ram_candidate_score_sum[layer].load() /
                        (double)layer_ram_candidates : 0.0,
                layer_ram_victims > 0 ?
                    (double)g_q4_tier_overlap_diag.score_profile_layer_ram_victim_score_sum[layer].load() /
                        (double)layer_ram_victims : 0.0,
                (unsigned long)layer_vram_evictions,
                (unsigned long)g_q4_tier_overlap_diag.score_profile_layer_vram_candidate_gt_victim[layer].load(),
                (unsigned long)g_q4_tier_overlap_diag.score_profile_layer_vram_candidate_eq_victim[layer].load(),
                (unsigned long)g_q4_tier_overlap_diag.score_profile_layer_vram_candidate_lt_victim[layer].load(),
                layer_vram_evictions > 0 ?
                    (double)g_q4_tier_overlap_diag.score_profile_layer_vram_candidate_score_sum[layer].load() /
                        (double)layer_vram_evictions : 0.0,
                layer_vram_evictions > 0 ?
                    (double)g_q4_tier_overlap_diag.score_profile_layer_vram_victim_score_sum[layer].load() /
                        (double)layer_vram_evictions : 0.0);
        }
    }
    if (q4_tier_layer_profile_enabled()) {
        for (int layer = 0; layer < 128; ++layer) {
            const uint64_t object_demands =
                g_q4_tier_overlap_diag.tier_layer_object_demands[layer].load();
            const uint64_t vram_evictions =
                g_q4_tier_overlap_diag.tier_layer_vram_evictions[layer].load();
            const uint64_t vram_reused =
                g_q4_tier_overlap_diag.tier_layer_vram_evicted_reused_within_window[layer].load();
            const uint64_t ram_hits_after_vram =
                g_q4_tier_overlap_diag.tier_layer_ram_hits_after_vram_eviction[layer].load();
            const uint64_t ram_hits_after_vram_w =
                g_q4_tier_overlap_diag.tier_layer_ram_hits_after_vram_eviction_within_window[layer].load();
            const uint64_t ram_hit_full_overlap =
                g_q4_tier_overlap_diag.tier_layer_ram_hit_vram_full_overlap[layer].load();
            const uint64_t ram_hit_partial_roles =
                g_q4_tier_overlap_diag.tier_layer_ram_hit_vram_partial_overlap_roles[layer].load();
            const uint64_t covered_ram_evictions =
                g_q4_tier_overlap_diag.tier_layer_covered_ram_evictions[layer].load();
            const uint64_t covered_ram_misses =
                g_q4_tier_overlap_diag.tier_layer_covered_ram_eviction_misses_within_window[layer].load();
            if (object_demands == 0 && vram_evictions == 0 && vram_reused == 0 &&
                    ram_hits_after_vram == 0 && ram_hit_full_overlap == 0 &&
                    ram_hit_partial_roles == 0 && covered_ram_evictions == 0 &&
                    covered_ram_misses == 0 && layer_ram_ready_objects[layer] == 0) {
                continue;
            }
            std::fprintf(stderr,
                "[moe_stream_batch] q4 tier layer: layer=%d object_demands=%lu "
                "ram_ready=%lu ram_vram_full_overlap=%lu ram_vram_any_partial=%lu "
                "ram_vram_partial_roles=%lu vram_evictions=%lu "
                "vram_evicted_reused_within_window=%lu "
                "ram_hits_after_vram_eviction=%lu "
                "ram_hits_after_vram_eviction_within_window=%lu "
                "ram_hit_vram_full_overlap=%lu ram_hit_vram_partial_roles=%lu "
                "covered_ram_evictions=%lu "
                "covered_ram_eviction_misses_within_window=%lu\n",
                layer,
                (unsigned long)object_demands,
                (unsigned long)layer_ram_ready_objects[layer],
                (unsigned long)layer_ram_vram_full_overlap_objects[layer],
                (unsigned long)layer_ram_vram_any_overlap_objects[layer],
                (unsigned long)layer_ram_vram_partial_overlap_roles[layer],
                (unsigned long)vram_evictions,
                (unsigned long)vram_reused,
                (unsigned long)ram_hits_after_vram,
                (unsigned long)ram_hits_after_vram_w,
                (unsigned long)ram_hit_full_overlap,
                (unsigned long)ram_hit_partial_roles,
                (unsigned long)covered_ram_evictions,
                (unsigned long)covered_ram_misses);
            if (q4_tier_reuse_window_profile_enabled()) {
                std::fprintf(stderr,
                    "[moe_stream_batch] q4 tier reuse layer: layer=%d "
                    "vram_evicted_reused_k1=%lu vram_evicted_reused_k2=%lu "
                    "vram_evicted_reused_k4=%lu vram_evicted_reused_k8=%lu "
                    "vram_evicted_reused_k16=%lu vram_evicted_reused_k32=%lu "
                    "vram_evicted_reused_k64=%lu vram_evicted_reused_k128=%lu\n",
                    layer,
                    (unsigned long)g_q4_tier_overlap_diag.tier_layer_vram_evicted_reused_by_window[0][layer].load(),
                    (unsigned long)g_q4_tier_overlap_diag.tier_layer_vram_evicted_reused_by_window[1][layer].load(),
                    (unsigned long)g_q4_tier_overlap_diag.tier_layer_vram_evicted_reused_by_window[2][layer].load(),
                    (unsigned long)g_q4_tier_overlap_diag.tier_layer_vram_evicted_reused_by_window[3][layer].load(),
                    (unsigned long)g_q4_tier_overlap_diag.tier_layer_vram_evicted_reused_by_window[4][layer].load(),
                    (unsigned long)g_q4_tier_overlap_diag.tier_layer_vram_evicted_reused_by_window[5][layer].load(),
                    (unsigned long)g_q4_tier_overlap_diag.tier_layer_vram_evicted_reused_by_window[6][layer].load(),
                    (unsigned long)g_q4_tier_overlap_diag.tier_layer_vram_evicted_reused_by_window[7][layer].load());
            }
        }
    }
    const uint64_t locality_samples = g_q4_tier_overlap_diag.cache_locality_samples.load();
    if (locality_samples > 0) {
        std::fprintf(stderr,
            "[moe_stream_batch] q4 cache locality summary: samples=%lu skipped_lock=%lu sample_period=%lu near_buckets=current,next1,next2 distance=%s\n",
            (unsigned long)locality_samples,
            (unsigned long)g_q4_tier_overlap_diag.cache_locality_skipped_lock.load(),
            (unsigned long)q4_cache_locality_sample_period(),
            q4_cache_locality_wrap_past_enabled() ? "forward_next_use" : "raw_layer_delta");
        for (int bucket = 0; bucket < Q4_CACHE_LOCALITY_BUCKETS; ++bucket) {
            const uint64_t vram_roles = g_q4_tier_overlap_diag.cache_locality_vram_roles[bucket].load();
            const uint64_t vram_full = g_q4_tier_overlap_diag.cache_locality_vram_full_objects[bucket].load();
            const uint64_t ram_objects = g_q4_tier_overlap_diag.cache_locality_ram_objects[bucket].load();
            if (vram_roles == 0 && vram_full == 0 && ram_objects == 0) continue;
            std::fprintf(stderr,
                "[moe_stream_batch] q4 cache locality bucket: bucket=%s vram_roles=%lu vram_full_objects=%lu ram_objects=%lu\n",
                q4_cache_locality_bucket_name(bucket),
                (unsigned long)vram_roles,
                (unsigned long)vram_full,
                (unsigned long)ram_objects);
        }
        for (int layer = 0; layer < 128; ++layer) {
            const uint64_t samples = g_q4_tier_overlap_diag.cache_locality_layer_samples[layer].load();
            if (samples == 0) continue;
            const uint64_t vram_roles = g_q4_tier_overlap_diag.cache_locality_layer_vram_roles[layer].load();
            const uint64_t vram_near_roles = g_q4_tier_overlap_diag.cache_locality_layer_vram_near_roles[layer].load();
            const uint64_t vram_full = g_q4_tier_overlap_diag.cache_locality_layer_vram_full_objects[layer].load();
            const uint64_t vram_near_full = g_q4_tier_overlap_diag.cache_locality_layer_vram_near_full_objects[layer].load();
            const uint64_t ram_objects = g_q4_tier_overlap_diag.cache_locality_layer_ram_objects[layer].load();
            const uint64_t ram_near_objects = g_q4_tier_overlap_diag.cache_locality_layer_ram_near_objects[layer].load();
            std::fprintf(stderr,
                "[moe_stream_batch] q4 cache locality layer: layer=%d samples=%lu vram_roles=%lu vram_near_roles=%lu vram_near_role_rate=%.1f%% vram_full_objects=%lu vram_near_full_objects=%lu vram_near_full_rate=%.1f%% ram_objects=%lu ram_near_objects=%lu ram_near_rate=%.1f%%\n",
                layer,
                (unsigned long)samples,
                (unsigned long)vram_roles,
                (unsigned long)vram_near_roles,
                vram_roles > 0 ? 100.0 * (double)vram_near_roles / (double)vram_roles : 0.0,
                (unsigned long)vram_full,
                (unsigned long)vram_near_full,
                vram_full > 0 ? 100.0 * (double)vram_near_full / (double)vram_full : 0.0,
                (unsigned long)ram_objects,
                (unsigned long)ram_near_objects,
                ram_objects > 0 ? 100.0 * (double)ram_near_objects / (double)ram_objects : 0.0);
        }
    }
    size_t pinned_ready = 0;
    size_t pinned_capacity = 0;
    size_t pageable_ready = 0;
    size_t pageable_capacity = 0;
    size_t registered_pageable_ready = 0;
    size_t registered_pageable_capacity = 0;
    for (size_t slot_idx = 0; slot_idx < g_q4_host_object_prefetch.slots.size(); ++slot_idx) {
        q4_colibri_host_object_slot &slot = g_q4_host_object_prefetch.slots[slot_idx];
        if (slot.host) {
            if (slot.pageable) {
                pageable_capacity += slot.capacity;
                if (slot.ready) ++pageable_ready;
                if (slot.host_registered) {
                    registered_pageable_capacity += slot.capacity;
                    if (slot.ready) ++registered_pageable_ready;
                }
            } else {
                pinned_capacity += slot.capacity;
                if (slot.ready) ++pinned_ready;
            }
        }
        if (slot.pending_h2d) (void)ggml_moe_common::object_host_cache_synchronize_h2d(
            g_q4_host_object_prefetch, slot_idx);
        if (slot.pending_d2h && slot.d2h_done) {
            cudaEventSynchronize(slot.d2h_done);
            slot.pending_d2h = false;
        }
        if (slot.h2d_done) {
            cudaEventDestroy(slot.h2d_done);
            slot.h2d_done = nullptr;
        }
        if (slot.d2h_done) {
            cudaEventDestroy(slot.d2h_done);
            slot.d2h_done = nullptr;
        }
        (void)ggml_moe_common::object_host_cache_invalidate_slot(
                g_q4_host_object_prefetch, slot_idx);
        if (slot.host) {
            q4_colibri_host_object_account_free_locked(slot);
            q4_colibri_host_object_free(slot);
        }
    }
    const uint64_t hits = g_q4_host_object_prefetch.hits.load();
    const uint64_t misses = g_q4_host_object_prefetch.misses.load();
    const ggml_moe_common::object_host_completion_counters &completion =
        g_q4_host_object_prefetch.completion;
    const uint64_t common_lease_acquires =
        completion.h2d_lease_acquires.load(std::memory_order_relaxed);
    const uint64_t common_lease_releases =
        completion.h2d_lease_releases.load(std::memory_order_relaxed);
    const ggml_moe_common::object_host_staging_counters &staging =
        g_q4_host_object_prefetch.staging;
    std::fprintf(stderr,
        "[moe_stream_batch] q4 host object common staging: begins=%lu publishes=%lu "
        "aborts=%lu failures=%lu outstanding=%lu\n",
        (unsigned long)staging.begins.load(std::memory_order_relaxed),
        (unsigned long)staging.publishes.load(std::memory_order_relaxed),
        (unsigned long)staging.aborts.load(std::memory_order_relaxed),
        (unsigned long)staging.failures.load(std::memory_order_relaxed),
        (unsigned long)(staging.begins.load(std::memory_order_relaxed) >=
            staging.publishes.load(std::memory_order_relaxed) +
                staging.aborts.load(std::memory_order_relaxed) ?
            staging.begins.load(std::memory_order_relaxed) -
                staging.publishes.load(std::memory_order_relaxed) -
                staging.aborts.load(std::memory_order_relaxed) : 0));
    std::fprintf(stderr,
        "[moe_stream_batch] q4 host object common H2D: begins=%lu records=%lu "
        "completions=%lu cancels=%lu failures=%lu lease_acquires=%lu "
        "lease_releases=%lu lease_outstanding=%lu stream_waits=%lu\n",
        (unsigned long)completion.h2d_begins.load(std::memory_order_relaxed),
        (unsigned long)completion.h2d_records.load(std::memory_order_relaxed),
        (unsigned long)completion.h2d_completions.load(std::memory_order_relaxed),
        (unsigned long)completion.h2d_cancels.load(std::memory_order_relaxed),
        (unsigned long)completion.h2d_failures.load(std::memory_order_relaxed),
        (unsigned long)common_lease_acquires,
        (unsigned long)common_lease_releases,
        (unsigned long)(common_lease_acquires >= common_lease_releases ?
            common_lease_acquires - common_lease_releases : 0),
        (unsigned long)completion.h2d_stream_waits.load(std::memory_order_relaxed));
    std::fprintf(stderr,
        "[moe_stream_batch] q4 host object memory classes: pinned_ready=%zu pinned_bytes=%zu "
        "pinned_hits=%lu pinned_h2d_bytes=%lu pinned_h2d_us=%lu "
        "pageable_ready=%zu pageable_bytes=%zu pageable_hits=%lu "
        "pageable_h2d_bytes=%lu pageable_h2d_us=%lu "
        "registered_pageable_ready=%zu registered_pageable_bytes=%zu "
        "registered_pageable_hits=%lu registered_pageable_h2d_bytes=%lu "
        "registered_pageable_h2d_us=%lu register_attempts=%lu register_successes=%lu "
        "register_failures=%lu register_bytes=%lu register_us=%lu\n",
        pinned_ready, pinned_capacity,
        (unsigned long)g_q4_host_object_prefetch.pinned_hits.load(),
        (unsigned long)g_q4_host_object_prefetch.pinned_h2d_bytes.load(),
        (unsigned long)g_q4_host_object_prefetch.pinned_h2d_us.load(),
        pageable_ready, pageable_capacity,
        (unsigned long)g_q4_host_object_prefetch.pageable_hits.load(),
        (unsigned long)g_q4_host_object_prefetch.pageable_h2d_bytes.load(),
        (unsigned long)g_q4_host_object_prefetch.pageable_h2d_us.load(),
        registered_pageable_ready, registered_pageable_capacity,
        (unsigned long)g_q4_host_object_prefetch.registered_pageable_hits.load(),
        (unsigned long)g_q4_host_object_prefetch.registered_pageable_h2d_bytes.load(),
        (unsigned long)g_q4_host_object_prefetch.registered_pageable_h2d_us.load(),
        (unsigned long)g_q4_host_object_prefetch.register_pageable_attempts.load(),
        (unsigned long)g_q4_host_object_prefetch.register_pageable_successes.load(),
        (unsigned long)g_q4_host_object_prefetch.register_pageable_failures.load(),
        (unsigned long)g_q4_host_object_prefetch.register_pageable_bytes.load(),
        (unsigned long)g_q4_host_object_prefetch.register_pageable_us.load());
    std::fprintf(stderr,
        "[moe_stream_batch] q4 host object prefetch: enabled=%d slots=%zu submitted=%lu completed=%lu "
        "hits=%lu misses=%lu hit_rate=%.1f%% lookup_layer_skips=%lu "
        "duplicate_skips=%lu queue_full=%lu no_slot=%lu "
        "evictions=%lu alloc_failures=%lu read_failures=%lu budget_skips=%lu budget_pressure_evictions=%lu "
        "resident_bytes=%zu resident_peak_bytes=%zu max_resident_bytes=%zu bytes_read=%lu bytes_avoided=%lu "
        "h2d_roles=%lu h2d_bytes=%lu h2d_us=%lu pending_queue=%zu ready=%zu "
        "eligible_layer_profile=%d "
        "eligible_layer_demands=%lu eligible_layer_hits=%lu eligible_layer_misses=%lu "
        "ineligible_layer_demands=%lu ineligible_layer_hits=%lu ineligible_layer_misses=%lu "
        "eligible_layer_read_admits=%lu ineligible_layer_read_rejects=%lu "
        "read_admit_min_read_us=%lu read_admit_min_read_us_skips=%lu "
        "read_admit_min_read_us_skip_avg=%lu "
        "preload_candidates=%lu preload_submitted=%lu preload_missing=%lu preload_bad_lines=%lu preload_us=%lu "
        "admit_on_read=%d read_admissions=%lu read_admit_bytes=%lu "
        "read_admit_evictions=%lu read_admit_alloc_failures=%lu "
        "score_policy=%d score_admit_margin=%lu score_admit_margin_layer_spec=%d "
        "score_admit_skips=%lu score_admissions=%lu "
        "score_evictions=%lu score_protected_victims=%lu "
        "score_read_empty_admissions=%lu score_read_eviction_candidates=%lu "
        "score_read_candidate_gt_victim=%lu score_read_candidate_eq_victim=%lu "
        "score_read_candidate_lt_victim=%lu score_entries=%zu dynamic_current=%d "
        "dynamic_victims_only=%d "
        "score_protect_victims_only=%d "
        "flow_score_cache=%d flow_score_layer_window=%lu flow_score_dynamic_hotness=%d "
        "flow_score_min_admit=%lu flow_score_dup_penalty=%d "
        "full_distance_score=%d full_distance_past_penalty=%lu "
        "layer_score_bonus=%d "
        "layer_quota_enabled=%d layer_quota_configured=%d layer_quota_max_demands=%lu "
        "layer_quota_expired=%d layer_quota_apply_demote=%d "
        "layer_quota_rejects=%lu layer_quota_evictions=%lu "
        "layer_quota_protected=%lu "
        "score_hit_refresh=%d score_hit_refreshes=%lu "
        "static_hotness=%d static_hotness_entries=%zu "
        "static_hotness_score_hits=%lu static_hotness_score_bonus=%lu "
        "ram_near_victim=%d ram_near_forward_window=%d ram_near_hot_freq=%u "
        "ram_near_victim_penalty=%lu ram_near_victim_candidates=%lu "
        "ram_near_victim_protected=%lu ram_near_victim_penalized=%lu "
        "ram_net_admission=%d ram_net_layer_set=%d ram_net_demote_score_min=%lu "
        "ram_net_read_rejects=%lu ram_net_demote_rejects=%lu "
        "ram_net_demote_score_rejects=%lu recurrence_read_admission=%d "
        "recurrence_read_max_age=%d recurrence_read_admits=%lu "
        "recurrence_read_rejects=%lu recurrence_read_rejects_age=%lu "
        "origin_hits=%s:%lu,%s:%lu,%s:%lu,%s:%lu,%s:%lu "
        "origin_h2d_roles=%s:%lu,%s:%lu,%s:%lu,%s:%lu,%s:%lu "
        "origin_h2d_bytes=%s:%lu,%s:%lu,%s:%lu,%s:%lu,%s:%lu "
        "origin_resident=%s:%lu,%s:%lu,%s:%lu,%s:%lu,%s:%lu\n",
        g_q4_host_object_prefetch.enabled ? 1 : 0,
        g_q4_host_object_prefetch.max_slots,
        (unsigned long)g_q4_host_object_prefetch.submitted.load(),
        (unsigned long)g_q4_host_object_prefetch.completed.load(),
        (unsigned long)hits,
        (unsigned long)misses,
        hits + misses > 0 ? 100.0 * (double)hits / (double)(hits + misses) : 0.0,
        (unsigned long)g_q4_host_object_prefetch.lookup_layer_skips.load(),
        (unsigned long)g_q4_host_object_prefetch.duplicate_skips.load(),
        (unsigned long)g_q4_host_object_prefetch.queue_full.load(),
        (unsigned long)g_q4_host_object_prefetch.no_slot.load(),
        (unsigned long)g_q4_host_object_prefetch.evictions.load(),
        (unsigned long)g_q4_host_object_prefetch.alloc_failures.load(),
        (unsigned long)g_q4_host_object_prefetch.read_failures.load(),
        (unsigned long)g_q4_host_object_prefetch.budget_skips.load(),
        (unsigned long)g_q4_host_object_prefetch.budget_pressure_evictions.load(),
        resident_capacity_at_shutdown,
        g_q4_host_object_prefetch.resident_capacity_peak_bytes,
        g_q4_host_object_prefetch.max_resident_bytes,
        (unsigned long)g_q4_host_object_prefetch.bytes_read.load(),
        (unsigned long)g_q4_host_object_prefetch.bytes_avoided.load(),
        (unsigned long)g_q4_host_object_prefetch.h2d_roles.load(),
        (unsigned long)g_q4_host_object_prefetch.h2d_bytes.load(),
        (unsigned long)g_q4_host_object_prefetch.h2d_us.load(),
        g_q4_host_object_prefetch.queue.size(),
        ggml_moe_common::object_host_cache_ready_count(g_q4_host_object_prefetch),
        q4_colibri_eligible_layer_profile_enabled() ? 1 : 0,
        (unsigned long)g_q4_host_object_prefetch.eligible_layer_demands.load(),
        (unsigned long)g_q4_host_object_prefetch.eligible_layer_hits.load(),
        (unsigned long)g_q4_host_object_prefetch.eligible_layer_misses.load(),
        (unsigned long)g_q4_host_object_prefetch.ineligible_layer_demands.load(),
        (unsigned long)g_q4_host_object_prefetch.ineligible_layer_hits.load(),
        (unsigned long)g_q4_host_object_prefetch.ineligible_layer_misses.load(),
        (unsigned long)g_q4_host_object_prefetch.eligible_layer_read_admits.load(),
        (unsigned long)g_q4_host_object_prefetch.ineligible_layer_read_rejects.load(),
        (unsigned long)q4_colibri_host_object_admit_min_read_us(),
