static void q4_colibri_pipe_shutdown() {
    if (!g_q4_colibri_pipe.inited) return;
    {
        std::lock_guard<std::mutex> lock(g_q4_colibri_pipe.mu);
        g_q4_colibri_pipe.stop = true;
        g_expert_pack.q4_pipe_shutdown_drain.fetch_add(
            g_q4_colibri_pipe.jobs.size() + q4_colibri_object_queue_size(), std::memory_order_relaxed);
    }
    if (ggml_moe_common::object_engine_enforcing()) {
        ggml_moe_common::object_engine_stop_worker();
    } else {
        g_q4_colibri_pipe.cv.notify_all();
        if (g_q4_colibri_pipe.worker.joinable()) g_q4_colibri_pipe.worker.join();
    }
    if (g_q4_colibri_pipe.lossless_stream) {
        cudaStreamSynchronize(g_q4_colibri_pipe.lossless_stream);
    }
    if (g_q4_colibri_pipe.stream) {
        cudaStreamSynchronize(g_q4_colibri_pipe.stream);
        if (g_q4_colibri_pipe.lossless_status_host) {
            cudaFreeHost(g_q4_colibri_pipe.lossless_status_host);
            g_q4_colibri_pipe.lossless_status_host = nullptr;
        }
        if (g_q4_colibri_pipe.lossless_crc32_host) {
            cudaFreeHost(g_q4_colibri_pipe.lossless_crc32_host);
            g_q4_colibri_pipe.lossless_crc32_host = nullptr;
        }
        cudaFree(g_q4_colibri_pipe.lossless_device_input);
        g_q4_colibri_pipe.lossless_device_input = nullptr;
        g_q4_colibri_pipe.lossless_device_input_bytes = 0;
        g_q4_colibri_pipe.lossless_device_input_stride = 0;
        g_q4_colibri_pipe.lossless_device_input_slots = 0;
        g_q4_colibri_pipe.lossless_crc_verified.clear();
        ggml_moe_common::lossless_rans_cuda_destroy(
            g_q4_colibri_pipe.lossless_decoder);
        g_q4_colibri_pipe.lossless_decoder = nullptr;
        cudaStreamDestroy(g_q4_colibri_pipe.stream);
        g_q4_colibri_pipe.stream = nullptr;
    }
    if (g_q4_colibri_pipe.lossless_stream) {
        cudaStreamDestroy(g_q4_colibri_pipe.lossless_stream);
        g_q4_colibri_pipe.lossless_stream = nullptr;
    }
    q4_colibri_host_object_prefetch_shutdown_and_report();
    pinned_stage_report_ring(" q4_pipe", g_q4_colibri_pipe.ring);
    pinned_stage_report_ring(" q4_pipe_coalesce", g_q4_colibri_pipe.coalesce_ring);
    pinned_stage_release(g_q4_colibri_pipe.ring);
    pinned_stage_release(g_q4_colibri_pipe.coalesce_ring);
    std::fprintf(stderr,
        "[moe_stream_batch] %s lossless transport: mode=%u ready=%d lookups=%lu hits=%lu "
        "fallbacks=%lu ssd_bytes=%lu raw_bytes=%lu h2d_bytes=%lu decoded_bytes=%lu "
        "decode_us=%lu decode_launches=%lu decode_objects=%lu decode_max_batch=%lu "
        "async_decode_batches=%lu async_decode_syncs=%lu async_decode_sync_us=%lu "
        "async_stage_releases=%lu async_cache_invalidations=%lu "
        "async_verified_batches=%lu async_verified_objects=%lu "
        "offline_trusted_records=%lu standalone_single_role_bridges=%lu "
        "crc_objects=%lu crc_reuses=%lu "
        "crc_failures=%lu parse_failures=%lu cuda_failures=%lu "
        "raw_fallback_bytes=%lu raw_host_refill_requests=%lu raw_host_refill_skips=%lu "
        "host_cache_admissions=%lu host_cache_hits=%lu "
        "host_cache_ssd_bytes_avoided=%lu host_cache_h2d_bytes=%lu "
        "host_cache_fallbacks=%lu\n",
        g_expert_pack.glm52_colibri ? "GLM52" : "Kimi",
        (unsigned)g_expert_pack.lossless_mode,
        g_q4_colibri_pipe.lossless_ready ? 1 : 0,
        (unsigned long)g_expert_pack.lossless_object_lookups.load(),
        (unsigned long)g_expert_pack.lossless_object_hits.load(),
        (unsigned long)g_expert_pack.lossless_object_fallbacks.load(),
        (unsigned long)g_expert_pack.lossless_ssd_bytes.load(),
        (unsigned long)g_expert_pack.lossless_raw_bytes.load(),
        (unsigned long)g_expert_pack.lossless_h2d_bytes.load(),
        (unsigned long)g_expert_pack.lossless_decoded_bytes.load(),
        (unsigned long)g_expert_pack.lossless_decode_us.load(),
        (unsigned long)g_expert_pack.lossless_decode_launches.load(),
        (unsigned long)g_expert_pack.lossless_decode_objects.load(),
        (unsigned long)g_expert_pack.lossless_decode_max_batch.load(),
        (unsigned long)g_expert_pack.lossless_async_decode_batches.load(),
        (unsigned long)g_expert_pack.lossless_async_decode_syncs.load(),
        (unsigned long)g_expert_pack.lossless_async_decode_sync_us.load(),
        (unsigned long)g_expert_pack.lossless_async_stage_releases.load(),
        (unsigned long)g_expert_pack.lossless_async_cache_invalidations.load(),
        (unsigned long)g_expert_pack.lossless_async_verified_batches.load(),
        (unsigned long)g_expert_pack.lossless_async_verified_objects.load(),
        (unsigned long)g_expert_pack.lossless_offline_trusted_records.load(),
        (unsigned long)g_expert_pack.lossless_standalone_single_role_bridges.load(),
        (unsigned long)g_expert_pack.lossless_crc_objects.load(),
        (unsigned long)g_expert_pack.lossless_crc_reuses.load(),
        (unsigned long)g_expert_pack.lossless_crc_failures.load(),
        (unsigned long)g_expert_pack.lossless_parse_failures.load(),
        (unsigned long)g_expert_pack.lossless_cuda_failures.load(),
        (unsigned long)g_expert_pack.lossless_raw_fallback_bytes.load(),
        (unsigned long)g_expert_pack.lossless_raw_host_refill_requests.load(),
        (unsigned long)g_expert_pack.lossless_raw_host_refill_skips.load(),
        (unsigned long)g_expert_pack.lossless_host_cache_admissions.load(),
        (unsigned long)g_expert_pack.lossless_host_cache_hits.load(),
        (unsigned long)g_expert_pack.lossless_host_cache_ssd_bytes_avoided.load(),
        (unsigned long)g_expert_pack.lossless_host_cache_h2d_bytes.load(),
        (unsigned long)g_expert_pack.lossless_host_cache_fallbacks.load());
    std::fprintf(stderr,
        "[moe_stream_batch] %s lossless failure detail: "
        "status_1=%lu status_2=%lu status_3=%lu status_4=%lu status_5=%lu "
        "publish=%lu enqueue_ready=%lu enqueue_h2d=%lu enqueue_crc=%lu "
        "enqueue_raw=%lu enqueue_decode=%lu enqueue_stage=%lu "
        "h2d_status_capacity=%lu h2d_crc_capacity=%lu h2d_copy=%lu\n",
        g_expert_pack.glm52_colibri ? "GLM52" : "Kimi",
        (unsigned long)g_expert_pack.lossless_status_failures[1].load(),
        (unsigned long)g_expert_pack.lossless_status_failures[2].load(),
        (unsigned long)g_expert_pack.lossless_status_failures[3].load(),
        (unsigned long)g_expert_pack.lossless_status_failures[4].load(),
        (unsigned long)g_expert_pack.lossless_status_failures[5].load(),
        (unsigned long)g_expert_pack.lossless_publish_failures.load(),
        (unsigned long)g_expert_pack.lossless_enqueue_failures[0].load(),
        (unsigned long)g_expert_pack.lossless_enqueue_failures[1].load(),
        (unsigned long)g_expert_pack.lossless_enqueue_failures[2].load(),
        (unsigned long)g_expert_pack.lossless_enqueue_failures[3].load(),
        (unsigned long)g_expert_pack.lossless_enqueue_failures[4].load(),
        (unsigned long)g_expert_pack.lossless_enqueue_failures[5].load(),
        (unsigned long)g_expert_pack.lossless_enqueue_h2d_detail[0].load(),
        (unsigned long)g_expert_pack.lossless_enqueue_h2d_detail[1].load(),
        (unsigned long)g_expert_pack.lossless_enqueue_h2d_detail[2].load());
    std::fprintf(stderr,
        "[moe_stream_batch] q4 colibri pipe: submitted=%lu completed=%lu failed=%lu queue_full=%lu "
        "queue_wait_us=%lu worker_us=%lu ready_latency_us=%lu stale_generation=%lu key_mismatch=%lu "
        "shutdown_drain=%lu pending=%zu clean_shutdown=1\n",
        (unsigned long)g_expert_pack.q4_pipe_submitted.load(),
        (unsigned long)g_expert_pack.q4_pipe_completed.load(),
        (unsigned long)g_expert_pack.q4_pipe_failed.load(),
        (unsigned long)g_expert_pack.q4_pipe_queue_full.load(),
        (unsigned long)g_expert_pack.q4_pipe_queue_wait_us.load(),
        (unsigned long)g_expert_pack.q4_pipe_worker_us.load(),
        (unsigned long)g_expert_pack.q4_pipe_ready_latency_us.load(),
        (unsigned long)g_expert_pack.q4_pipe_stale_generation.load(),
        (unsigned long)g_expert_pack.q4_pipe_key_mismatch.load(),
        (unsigned long)g_expert_pack.q4_pipe_shutdown_drain.load(),
        g_q4_colibri_pipe.jobs.size() + q4_colibri_object_queue_size());
    std::fprintf(stderr,
        "[moe_stream_batch] q4 common rolling refill: enabled=%d batches=%lu submit_rounds=%lu "
        "submitted=%lu completions=%lu completed_batches=%lu failures=%lu "
        "plan_checks=%lu plan_matches=%lu plan_mismatches=%lu owner=%d "
        "owned_dispatches=%lu owner_fallbacks=%lu\n",
        common_rolling_refill_enabled() ? 1 : 0,
        (unsigned long)g_expert_pack.q4_common_refill_batches.load(),
        (unsigned long)g_expert_pack.q4_common_refill_submit_rounds.load(),
        (unsigned long)g_expert_pack.q4_common_refill_submitted.load(),
        (unsigned long)g_expert_pack.q4_common_refill_completions.load(),
        (unsigned long)g_expert_pack.q4_common_refill_completed_batches.load(),
        (unsigned long)g_expert_pack.q4_common_refill_failures.load(),
        (unsigned long)g_expert_pack.q4_common_refill_plan_checks.load(),
        (unsigned long)g_expert_pack.q4_common_refill_plan_matches.load(),
        (unsigned long)g_expert_pack.q4_common_refill_plan_mismatches.load(),
        common_rolling_refill_enabled() && common_refill_planner_owns_dispatch_enabled() ? 1 : 0,
        (unsigned long)g_expert_pack.q4_common_refill_owned_dispatches.load(),
        (unsigned long)g_expert_pack.q4_common_refill_owner_fallbacks.load());
    const ggml_moe_common::object_pipeline_mode_config & pipeline_mode =
        expert_pack_pipeline_mode_config();
    const ggml_moe_common::object_pipeline_policy_config & pipeline_policy =
        expert_pack_pipeline_policy_config();
    std::fprintf(stderr,
        "[moe_stream_batch] q4 common pipeline config: mode=%s source=%s valid=%d "
        "policy_valid=%d overrides=0x%x invalid=0x%x io_depth=%zu initial=%zu "
        "refill=%zu min_flush=%zu timeout_us=%lu max_h2d=%zu active=%d owner=%d\n",
