            h_x_ids[j] = cache_slot;
            if (slots_out) slots_out[j] = cache_slot;
            batch_route_profile_hit(key_name, active_experts[j], expert_bytes);
        }
        return true;
    };

    auto copy_stage_jobs = [&](const std::vector<stage_copy_job> &jobs, cudaStream_t run_stream, pinned_stage_ring &ring) -> bool {
        if (cudaSetDevice(0) != cudaSuccess) return false;
        auto synchronize_copy_streams = [&](bool per_job_streams) {
            bool ok = !run_stream || cudaStreamSynchronize(run_stream) == cudaSuccess;
            if (!per_job_streams) return ok;
            for (size_t i = 0; i < jobs.size(); ++i) {
                cudaStream_t job_stream = jobs[i].stream;
                if (!job_stream || job_stream == run_stream) continue;
                bool seen = false;
                for (size_t j = 0; j < i; ++j) {
                    if (jobs[j].stream == job_stream) {
                        seen = true;
                        break;
                    }
                }
                if (!seen && cudaStreamSynchronize(job_stream) != cudaSuccess) ok = false;
            }
            return ok;
        };
        auto fail_after_copy = [&](bool per_job_streams) {
            (void)synchronize_copy_streams(per_job_streams);
            return false;
        };
        auto publish_jobs = [&](bool per_job_streams) {
            for (const stage_copy_job &job : jobs) {
                cudaStream_t copy_stream = per_job_streams && job.stream ? job.stream : run_stream;
                if (!batch_cache_publish_slot_ready(
                            cache, job.slot, job.key, job.generation,
                            job.nbytes, copy_stream)) {
                    return false;
                }
            }
            return true;
        };
        if (g_expert_pack.lossless_standalone) {
            for (const stage_copy_job &job : jobs) {
                if (job.slot < 0 || job.slot >= cache->n_slots || job.key == 0 ||
                        job.generation == 0 || job.nbytes == 0 || !job.pack_entry ||
                        cache->slot_key[job.slot] != job.key ||
                        cache->slot_generation[job.slot] != job.generation ||
                        cache->slot_payload_bytes[job.slot] != job.nbytes ||
                        !cache->slot_filling[job.slot]) {
                    return fail_after_copy(true);
                }
                cudaStream_t copy_stream = job.stream ? job.stream : run_stream;
                if (!q4_colibri_pipe_copy(
                        cache, job.slot, job.generation, job.key, job.dst,
                        job.pack_entry, job.nbytes, copy_stream,
                        job.tensor, job.expert_idx)) {
                    return fail_after_copy(true);
                }
            }
            return true;
        }
        for (const stage_copy_job &job : jobs) {
            if (job.slot < 0 || job.slot >= cache->n_slots || job.key == 0 ||
                    job.generation == 0 || job.nbytes == 0 ||
                    cache->slot_key[job.slot] != job.key ||
                    cache->slot_generation[job.slot] != job.generation ||
                    cache->slot_payload_bytes[job.slot] != job.nbytes ||
                    !cache->slot_filling[job.slot]) {
                return fail_after_copy(false);
            }
            cache->slot_state[job.slot] = q4_colibri_slot_state::reading;
        }
        size_t copy_bytes = src0_bytes;
        bool uniform_bytes = true;
        if (!jobs.empty() && jobs[0].nbytes != 0) {
            copy_bytes = jobs[0].nbytes;
            for (const stage_copy_job &job : jobs) {
                if (job.nbytes != 0 && job.nbytes != copy_bytes) {
                    uniform_bytes = false;
                    break;
                }
            }
        }
        if (uniform_bytes && expert_pack_iouring_copy_jobs(jobs, copy_bytes, run_stream, ring, "runtime_load")) {
            if (cudaGetLastError() != cudaSuccess || !publish_jobs(false)) {
                return fail_after_copy(false);
            }
            return true;
        }
        if (!uniform_bytes &&
                expert_pack_env_bool("GGML_MOE_MIXED_UP_GATE_VARIABLE_BATCH", false) &&
                expert_pack_iouring_copy_jobs_varbytes(jobs, run_stream, ring, "runtime_load")) {
            if (cudaGetLastError() != cudaSuccess || !publish_jobs(true)) {
                return fail_after_copy(true);
            }
            return true;
        }
        const std::vector<stage_copy_job> *fallback_jobs = &jobs;
        std::vector<stage_copy_job> partial_iouring_jobs;
        std::vector<stage_copy_job> partial_fallback_jobs;
        if (uniform_bytes && !jobs.empty() && g_expert_pack.io_backend == 2) {
            partial_iouring_jobs.reserve(jobs.size());
            partial_fallback_jobs.reserve(jobs.size());
            for (const stage_copy_job &job : jobs) {
                if (expert_pack_iouring_job_eligible(job, copy_bytes)) {
                    partial_iouring_jobs.push_back(job);
                } else {
                    partial_fallback_jobs.push_back(job);
                }
            }
            if (!partial_iouring_jobs.empty() && partial_iouring_jobs.size() < jobs.size() &&
                    expert_pack_iouring_copy_jobs(partial_iouring_jobs, copy_bytes, run_stream, ring, "runtime_load")) {
                if (cudaGetLastError() != cudaSuccess) return fail_after_copy(false);
                fallback_jobs = &partial_fallback_jobs;
            }
        }
        for (const stage_copy_job &job : *fallback_jobs) {
            const size_t job_bytes = job.nbytes != 0 ? job.nbytes : src0_bytes;
            batch_copy_trace copy_trace;
            const auto copy_start = batch_ttft_trace_enabled() ? std::chrono::steady_clock::now() : std::chrono::steady_clock::time_point{};
            if (!batch_cache_copy_h2d(ring, job.dst, job.host_data, job_bytes, run_stream, job.pack_entry, &copy_trace,
                        "runtime_load", job.tensor, job.expert_idx)) {
                if (!job.pack_entry ||
                        !batch_cache_copy_h2d(ring, job.dst, job.host_data, job_bytes, run_stream, nullptr, &copy_trace,
                            "runtime_load", job.tensor, job.expert_idx)) {
                    return fail_after_copy(false);
                }
            }
            if (cudaGetLastError() != cudaSuccess) {
                return fail_after_copy(false);
            }
            if (copy_start != std::chrono::steady_clock::time_point{}) {
                const auto copy_end = std::chrono::steady_clock::now();
                batch_ttft_trace_record(
                    "runtime_load",
                    job.tensor,
                    job.expert_idx,
                    job_bytes,
                    false,
                    copy_trace.pack_hit,
                    copy_trace.ram_hit,
                    std::chrono::duration<double, std::milli>(copy_end - copy_start).count());
            }
        }
        if (!publish_jobs(false)) return fail_after_copy(false);
        return true;
    };

    auto clear_stage_jobs_for_cache = [&](batch_vram_cache *job_cache, const std::vector<stage_copy_job> &jobs) {
        if (!job_cache) return;
        for (const stage_copy_job &job : jobs) {
            batch_cache_clear_slot(job_cache, job.slot);
        }
    };

    std::thread current_down_overlap_thread;
    bool current_down_overlap_ok = true;
    bool current_down_overlap_started = false;
    auto join_current_down_overlap = [&]() -> bool {
        if (current_down_overlap_thread.joinable()) {
            current_down_overlap_thread.join();
        }
        return current_down_overlap_ok;
    };

    auto start_current_down_overlap = [&]() {
        if (!current_down_overlap_enabled() || prompt_mode || !bc.prefetch_stream) return;
        if (current_down_overlap_started) return;
        current_down_overlap_started = true;
        ++g_current_down_overlap.calls;

        char down_name[128] = {};
        if (!down_name_for_up_gate(src0_up_name, down_name, sizeof(down_name))) {
            ++g_current_down_overlap.missing_tensor;
            current_down_overlap_tensor_profile_record(src0_up_name, 1, 0, 0, 1, 0, 0);
            return;
        }

        registered_tensor rt;
        bool found = false;
        {
            std::lock_guard<std::mutex> rlk(g_registered_mu);
            for (const registered_tensor &t : g_registered_tensors) {
                if (std::strcmp(t.name, down_name) == 0) {
                    rt = t;
                    found = true;
                    break;
                }
            }
        }
        if (!found || !rt.data || rt.expert_bytes == 0) {
            ++g_current_down_overlap.missing_tensor;
            current_down_missing_profile_record("registered_missing", down_name, active_experts, n_active);
            current_down_overlap_tensor_profile_record(down_name, 1, 0, 0, 1, 0, 0);
            return;
        }

        batch_vram_cache *down_cache = batch_cache_get(rt.expert_bytes);
        if (!down_cache) {
            ++g_current_down_overlap.missing_tensor;
            current_down_missing_profile_record("cache_unavailable", down_name, active_experts, n_active);
            current_down_overlap_tensor_profile_record(down_name, 1, 0, 0, 1, 0, 0);
            return;
        }

        struct current_down_v2_job {
            int slot = -1;
            uintptr_t key = 0;
            uint64_t generation = 0;
            void *dst = nullptr;
            const expert_pack_v2_entry *entry = nullptr;
            int expert_idx = -1;
            char tensor[128] = {};
            char logical_tensor[128] = {};
        };

        if (expert_pack_v2_full_cover_down_enabled() &&
                expert_pack_v2_full_cover_down_overlap_enabled()) {
            expert_pack_v2_full_cover_down_state &v2_state = g_expert_pack_v2_full_cover_down;
            v2_state.overlap_calls.fetch_add(1, std::memory_order_relaxed);
            if (!v2_state.report_registered.exchange(true)) {
                std::atexit(expert_pack_v2_full_cover_down_report);
            }

            bool v2_overlap_ok = true;
            const expert_pack_v2_entry *v2_first = nullptr;
            const expert_pack_v2_entry *v2_entries[MOE_STREAM_MAX_ACTIVE] = {};
            for (int j = 0; j < n_active; ++j) {
                const int expert = active_experts[j];
                if (expert < 0 || expert >= rt.n_as) {
                    v2_state.overlap_reject_bad_expert.fetch_add(1, std::memory_order_relaxed);
                    v2_overlap_ok = false;
                    break;
                }
                const expert_pack_v2_entry *entry = expert_pack_v2_lookup(rt.name, expert);
                if (!entry) {
                    v2_state.overlap_reject_no_entry.fetch_add(1, std::memory_order_relaxed);
                    v2_overlap_ok = false;
                    break;
                }
                if (!expert_pack_v2_packed_type_supported(entry->packed_type)) {
                    v2_state.overlap_reject_unsupported.fetch_add(1, std::memory_order_relaxed);
                    v2_overlap_ok = false;
                    break;
                }
                if ((size_t)entry->nbytes == 0 || (size_t)entry->nbytes >= rt.expert_bytes ||
                        (size_t)entry->nbytes > down_cache->slot_sz) {
                    v2_state.overlap_reject_not_smaller.fetch_add(1, std::memory_order_relaxed);
                    v2_overlap_ok = false;
                    break;
                }
                if (entry->nb01 == 0) {
                    v2_state.overlap_reject_shape.fetch_add(1, std::memory_order_relaxed);
                    v2_overlap_ok = false;
                    break;
                }
                if (!v2_first) {
                    v2_first = entry;
                } else if (entry->packed_type != v2_first->packed_type ||
                        entry->nbytes != v2_first->nbytes ||
                        entry->ne00 != v2_first->ne00 ||
                        entry->ne01 != v2_first->ne01 ||
                        entry->nb01 != v2_first->nb01) {
                    v2_state.overlap_reject_homogeneous.fetch_add(1, std::memory_order_relaxed);
                    v2_overlap_ok = false;
                    break;
                }
                v2_entries[j] = entry;
            }

            if (v2_overlap_ok && v2_first) {
                char v2_down_name[128] = {};
                const int name_len = std::snprintf(v2_down_name, sizeof(v2_down_name), "%s:v2full", rt.name);
                if (name_len <= 0 || (size_t)name_len >= sizeof(v2_down_name)) {
                    v2_state.overlap_reject_bad_cache_key.fetch_add(1, std::memory_order_relaxed);
                    v2_overlap_ok = false;
                } else {
                    const size_t v2_nbytes = (size_t)v2_first->nbytes;
                    uint64_t local_v2_cache_hits = 0;
                    std::vector<current_down_v2_job> v2_jobs;
                    v2_jobs.reserve((size_t)n_active);
                    for (int j = 0; j < n_active; ++j) {
                        const int expert = active_experts[j];
                        const uintptr_t v2_key = batch_key_hash(v2_down_name, expert);
                        if (batch_cache_find_slot(down_cache, v2_key) >= 0) {
                            ++local_v2_cache_hits;
                            expert_pack_v2_shadow_profile_record(
                                    "current_down_overlap_v2", rt.name, expert, rt.type,
                                    rt.expert_bytes, "v2_cache_hit");
                            continue;
                        }
                        expert_pack_v2_shadow_profile_record(
                                "current_down_overlap_v2", rt.name, expert, rt.type,
                                rt.expert_bytes, "v2_cache_miss");
                        const int slot = batch_cache_insert_slot(
                                down_cache, v2_key, nullptr, v2_nbytes, bc.prefetch_stream,
                                true, true, nullptr, 0, false, v2_down_name, expert, true);
                        if (slot < 0) {
                            continue;
                        }
                        current_down_v2_job job;
                        job.slot = slot;
                        job.key = v2_key;
                        job.generation = down_cache->slot_generation[slot];
                        job.dst = (char *)down_cache->pool + (size_t)slot * down_cache->slot_sz;
                        job.entry = v2_entries[j];
                        job.expert_idx = expert;
                        std::snprintf(job.tensor, sizeof(job.tensor), "%s", v2_down_name);
                        std::snprintf(job.logical_tensor, sizeof(job.logical_tensor), "%s", rt.name);
                        down_cache->slot_filling[slot] = true;
                        v2_jobs.push_back(job);
                    }

                    v2_state.overlap_cache_hits.fetch_add(local_v2_cache_hits, std::memory_order_relaxed);
                    v2_state.overlap_cache_misses.fetch_add((uint64_t)v2_jobs.size(), std::memory_order_relaxed);
                    if (v2_jobs.empty()) {
                        v2_state.overlap_accepted.fetch_add(1, std::memory_order_relaxed);
                        current_down_overlap_tensor_profile_record(v2_down_name, 1, 0, local_v2_cache_hits, 0, 0, 0);
                        return;
                    }

                    v2_state.overlap_accepted.fetch_add(1, std::memory_order_relaxed);
                    current_down_overlap_record_batch(v2_jobs.size());
                    current_down_overlap_tensor_profile_record(
                            v2_down_name, 1, v2_jobs.size(), local_v2_cache_hits, 0, 0, 0);
                    static std::atomic<int> first_current_down_overlap_v2{0};
                    if (first_current_down_overlap_v2.fetch_add(1) == 0) {
                        std::fprintf(stderr,
                                "[moe_stream_batch] current down v2 overlap active: tensor=%s jobs=%zu bytes=%.2f MiB\n",
                                v2_down_name, v2_jobs.size(), v2_nbytes / (1024.0 * 1024.0));
                    }

                    current_down_overlap_thread = std::thread([&, down_cache, v2_jobs = std::move(v2_jobs), v2_nbytes]() {
                        const auto worker_start = std::chrono::steady_clock::now();
                        bool copied = true;
                        uint64_t local_read_us = 0;
                        uint64_t local_h2d_enqueue_us = 0;
                        {
                            expert_pack_v2_full_cover_down_state &v2_global = g_expert_pack_v2_full_cover_down;
                            std::lock_guard<std::mutex> v2_lk(v2_global.overlap_mu);
                            const size_t host_need = v2_nbytes * v2_jobs.size();
                            if (host_need == 0 ||
                                    !ensure_host_pinned(v2_global.overlap_host, v2_global.overlap_host_sz, host_need)) {
                                copied = false;
                            }
                            for (size_t i = 0; copied && i < v2_jobs.size(); ++i) {
                                const current_down_v2_job &job = v2_jobs[i];
                                char *host_slot = (char *)v2_global.overlap_host + i * v2_nbytes;
                                const auto read_t0 = std::chrono::steady_clock::now();
                                const expert_pack_v2_shadow_read_result read_result =
                                    expert_pack_v2_shadow_read_entry_to_host(
                                            job.entry, job.logical_tensor, job.expert_idx,
                                            host_slot, v2_nbytes);
                                const auto read_t1 = std::chrono::steady_clock::now();
                                local_read_us += (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
                                        read_t1 - read_t0).count();
                                if (!read_result.ok || read_result.nread != v2_nbytes) {
                                    copied = false;
                                    break;
                                }
                                const auto h2d_t0 = std::chrono::steady_clock::now();
                                if (cudaMemcpyAsync(job.dst, host_slot, v2_nbytes,
                                            cudaMemcpyHostToDevice, bc.prefetch_stream) != cudaSuccess) {
                                    copied = false;
                                    break;
                                }
                                const auto h2d_t1 = std::chrono::steady_clock::now();
                                local_h2d_enqueue_us += (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
                                        h2d_t1 - h2d_t0).count();
                            }
                            if (copied && cudaStreamSynchronize(bc.prefetch_stream) != cudaSuccess) {
                                copied = false;
                            }
                        }

                        if (copied) {
                            for (const current_down_v2_job &job : v2_jobs) {
                                if (!batch_cache_publish_slot_ready(
                                            down_cache, job.slot, job.key, job.generation,
                                            v2_nbytes, bc.prefetch_stream)) {
                                    copied = false;
                                    break;
                                }
                            }
                        }

                        if (!copied) {
                            cudaStreamSynchronize(bc.prefetch_stream);
                            for (const current_down_v2_job &job : v2_jobs) {
                                batch_cache_clear_slot(down_cache, job.slot);
                            }
                            g_expert_pack_v2_full_cover_down.overlap_failures.fetch_add(1, std::memory_order_relaxed);
                        } else {
                            g_current_down_overlap.completed_jobs.fetch_add(v2_jobs.size());
                            current_down_overlap_tensor_profile_record(
                                    v2_jobs.empty() ? "" : v2_jobs[0].tensor,
                                    0, 0, 0, 0, 0, v2_jobs.size());
                            g_expert_pack_v2_full_cover_down.overlap_copied_entries.fetch_add((uint64_t)v2_jobs.size(), std::memory_order_relaxed);
                            g_expert_pack_v2_full_cover_down.overlap_copied_bytes.fetch_add(
                                    (uint64_t)v2_nbytes * (uint64_t)v2_jobs.size(),
                                    std::memory_order_relaxed);
                        }
                        g_expert_pack_v2_full_cover_down.overlap_read_us.fetch_add(local_read_us, std::memory_order_relaxed);
                        g_expert_pack_v2_full_cover_down.overlap_h2d_enqueue_us.fetch_add(local_h2d_enqueue_us, std::memory_order_relaxed);

                        const auto worker_end = std::chrono::steady_clock::now();
                        const uint64_t worker_us = (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
                                worker_end - worker_start).count();
                        g_expert_pack_v2_full_cover_down.overlap_worker_us.fetch_add(worker_us, std::memory_order_relaxed);
                        g_current_down_overlap.worker_us.fetch_add(worker_us);
                    });
                    return;
                }
            }
            if (!v2_overlap_ok) {
                v2_state.overlap_rejected.fetch_add(1, std::memory_order_relaxed);
            }
        }

        uint64_t local_cache_hits = 0;
        uint64_t local_missing_pack = 0;
        std::vector<stage_copy_job> down_jobs;
        down_jobs.reserve((size_t)n_active);
        for (int j = 0; j < n_active; ++j) {
            const int expert = active_experts[j];
            if (expert < 0 || expert >= rt.n_as) continue;
            const uintptr_t key = batch_key_hash(rt.name, expert);
            if (batch_cache_find_slot(down_cache, key) >= 0) {
                expert_pack_v2_shadow_profile_record(
                        "current_down_overlap", rt.name, expert, rt.type,
                        rt.expert_bytes, "cache_hit");
                ++g_current_down_overlap.cache_hits;
                ++local_cache_hits;
                continue;
            }
            expert_pack_v2_shadow_profile_record(
                    "current_down_overlap", rt.name, expert, rt.type,
                    rt.expert_bytes, "cache_miss");
            const char *expert_host = (const char *)rt.data + (size_t)expert * rt.nb02;
            const int slot = batch_cache_insert_slot(
                down_cache, key, expert_host, rt.expert_bytes, bc.prefetch_stream,
                true, true, nullptr, 0, false, rt.name, expert, true);
            if (slot < 0) continue;

            stage_copy_job job;
            job.slot = slot;
            job.key = key;
            job.generation = down_cache->slot_generation[slot];
            job.dst = (char *)down_cache->pool + (size_t)slot * down_cache->slot_sz;
            job.host_data = expert_host;
            job.pack_entry = expert_pack_lookup(rt.name, expert, rt.expert_bytes);
            job.nbytes = rt.expert_bytes;
            if (!job.pack_entry) {
                ++g_current_down_overlap.missing_pack;
                ++local_missing_pack;
            }
            job.expert_idx = expert;
            std::snprintf(job.tensor, sizeof(job.tensor), "%s", rt.name);
            down_cache->slot_filling[slot] = true;
            down_jobs.push_back(job);
        }
        if (down_jobs.empty()) {
            current_down_overlap_tensor_profile_record(rt.name, 1, 0, local_cache_hits, 0, local_missing_pack, 0);
            return;
        }

        current_down_overlap_record_batch(down_jobs.size());
        current_down_overlap_tensor_profile_record(
            rt.name, 1, down_jobs.size(), local_cache_hits, 0, local_missing_pack, 0);
        static std::atomic<int> first_current_down_overlap{0};
        if (first_current_down_overlap.fetch_add(1) == 0) {
            std::fprintf(stderr,
                "[moe_stream_batch] current down overlap active: tensor=%s jobs=%zu bytes=%.2f MiB\n",
                rt.name, down_jobs.size(), rt.expert_bytes / (1024.0 * 1024.0));
        }
        pinned_stage_ring *down_stage_ring = current_down_overlap_dedicated_ring_enabled() ?
            &bc.stage_ring_down_aux : &bc.stage_ring;
        static std::atomic<int> first_current_down_dedicated_ring{0};
        if (down_stage_ring == &bc.stage_ring_down_aux &&
                first_current_down_dedicated_ring.fetch_add(1) == 0) {
            std::fprintf(stderr,
                "[moe_stream_batch] current down overlap dedicated staging ring active\n");
        }

        current_down_overlap_thread = std::thread([&, down_cache, down_stage_ring, down_jobs = std::move(down_jobs), expert_bytes = rt.expert_bytes]() {
            const auto worker_start = std::chrono::steady_clock::now();
            bool copied = expert_pack_iouring_copy_jobs(down_jobs, expert_bytes, bc.prefetch_stream,
                    *down_stage_ring, "current_down_overlap");
            if (!copied) {
                copied = true;
                for (const stage_copy_job &job : down_jobs) {
                    batch_copy_trace copy_trace;
                    if (!batch_cache_copy_h2d(*down_stage_ring, job.dst, job.host_data, expert_bytes,
                            bc.prefetch_stream, job.pack_entry, &copy_trace,
                            "current_down_overlap", job.tensor, job.expert_idx)) {
                        copied = false;
                        break;
                    }
                }
            }

            if (copied) {
                for (const stage_copy_job &job : down_jobs) {
                    if (!batch_cache_publish_slot_ready(
                                down_cache, job.slot, job.key, job.generation,
                                expert_bytes, bc.prefetch_stream)) {
                        copied = false;
                        ++g_current_down_overlap.mark_failed;
                        break;
                    }
                }
            }

            if (!copied) {
                cudaStreamSynchronize(bc.prefetch_stream);
                clear_stage_jobs_for_cache(down_cache, down_jobs);
                ++g_current_down_overlap.failed_batches;
                current_down_overlap_ok = false;
            } else {
                g_current_down_overlap.completed_jobs.fetch_add(down_jobs.size());
                current_down_overlap_tensor_profile_record(
                    down_jobs.empty() ? "" : down_jobs[0].tensor, 0, 0, 0, 0, 0, down_jobs.size());
            }

            const auto worker_end = std::chrono::steady_clock::now();
            g_current_down_overlap.worker_us.fetch_add(
                (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(worker_end - worker_start).count());
        });
    };

    auto split_stage_jobs = [&](const std::vector<stage_copy_job> &jobs,
            std::vector<stage_copy_job> &a, std::vector<stage_copy_job> &b) {
        a.clear();
        b.clear();
        a.reserve((jobs.size() + 1) / 2);
        b.reserve(jobs.size() / 2);
        for (size_t i = 0; i < jobs.size(); ++i) {
            if (i & 1) {
                b.push_back(jobs[i]);
            } else {
                a.push_back(jobs[i]);
            }
        }
    };

    auto submit_planned_host_prefetch = [&](const std::vector<stage_copy_job> &jobs) {
        for (const stage_copy_job &job : jobs) {
            if (job.pack_entry && job.tensor[0] && job.expert_idx >= 0) {
                host_prefetch_submit_planned(job.tensor, job.expert_idx, src0_bytes);
            }
        }
    };

    auto launch_tensor = [&](
            const char *key_name, ggml_moe_common::role kind,
            void *d_out, cudaStream_t run_stream, int32_t *d_x_ids, void *d_src1_q8,
            int32_t *h_x_ids) -> bool {
        if (cudaMemsetAsync(d_out, 0, dst_bytes, run_stream) != cudaSuccess) return false;
        if (cudaMemcpyAsync(d_x_ids, h_x_ids, ids_bytes, cudaMemcpyHostToDevice, run_stream) != cudaSuccess) return false;
        return batch_cache_launch_with_role_leases(
            cache, key_name, kind, active_experts, h_x_ids, n_active, run_stream, [&]() {
                return ggml_cuda_moe_stream_mmvq_batch_dev(
                    src0_type, cache->pool, ne01, ne00,
                    (const float *)bc.d_src1_f32, d_src1_q8,
                    (float *)d_out, d_x_ids, n_active, cache->slot_sz, run_stream);
            });
    };

    auto launch_compact_tensor = [&](
            const char *key_name, ggml_moe_common::role kind, ggml_type logical_type,
            size_t logical_nb01, const int32_t *h_x_ids,
            void *d_src1_q8, void *d_out, cudaStream_t run_stream) -> bool {
        return batch_cache_launch_with_role_leases(
            cache, key_name, kind, active_experts, h_x_ids, n_active, run_stream, [&]() {
                return launch_moe_mmvq_compact_batch(
                    logical_type,
                    (const char *)cache->pool, h_x_ids, cache->slot_sz,
                    ne00, ne01, logical_nb01, (const float *)bc.d_src1_f32,
                    ne00, nullptr, d_src1_q8, (float *)d_out, n_active, run_stream);
            });
    };

    for (int j = 0; j < n_active; ++j) {
        const char *src1_base = (const char *)src1_f32;
        const char *src_row = src1_base + (size_t)token_ids[j] * src1_nb2;
        std::memcpy((char *)bc.h_src1 + (size_t)j * ne00 * sizeof(float), src_row, (size_t)ne00 * sizeof(float));
        bc.h_ids_src1[j] = j;
        bc.h_ids_dst[j] = flat_dst_ids[j];
        bc.h_up_gate_ids_dst[j] = j;
        bc.h_bounds[j] = j;
    }
    bc.h_bounds[n_active] = n_active;

    const char *src1_dump_env = std::getenv("GGML_MOE_STREAM_FUSED_UP_GATE_SRC1_DUMP");
    const bool src1_dump = src1_dump_env && src1_dump_env[0] && src1_dump_env[0] != '0';
    static std::atomic<int> src1_dump_count{0};
    if (src1_dump && src1_dump_count.fetch_add(1) == 0) {
        moe_stream_dump_f32_rows("src1", (const float *)bc.h_src1, n_active, ne00);
    }
    for (int j = 0; j < n_active; ++j) {
        const float *row = (const float *)bc.h_src1 + (size_t)j * (size_t)ne00;
        moe_activation_dump_record(
                "up",
                prompt_mode ? "prompt" : "decode",
                route_detail_call,
                src0_up_name,
                src0_up_type_int,
                active_experts[j],
                j,
                flat_dst_ids[j],
                token_ids[j],
                ne00,
                ne01,
                up_expert_bytes,
                row);
        moe_activation_dump_record(
                "gate",
                prompt_mode ? "prompt" : "decode",
                route_detail_call,
                src0_gate_name,
                src0_gate_type_int,
                active_experts[j],
                j,
                flat_dst_ids[j],
                token_ids[j],
                ne00,
                ne01,
                gate_expert_bytes,
                row);
    }

    if (cudaMemcpyAsync(bc.d_src1_f32, bc.h_src1, src1_f32_bytes, cudaMemcpyHostToDevice, st) != cudaSuccess) return false;
    if (cudaMemcpyAsync(bc.d_ids_src1, bc.h_ids_src1, ids_bytes, cudaMemcpyHostToDevice, st) != cudaSuccess) return false;
    if (cudaMemcpyAsync(bc.d_ids_dst, bc.h_up_gate_ids_dst, ids_bytes, cudaMemcpyHostToDevice, st) != cudaSuccess) return false;
    if (cudaMemcpyAsync(bc.d_bounds, bc.h_bounds, bounds_bytes, cudaMemcpyHostToDevice, st) != cudaSuccess) return false;
    if (profile) cudaEventRecord(bc.ev_stage, st);

    if (exact_prompt_q8k) {
        if (ne00 % QK_K != 0) return false;
        const int nblocks = (int)(n_active * (ne00 / QK_K));
        moe_quantize_row_q8_k_kernel<<<nblocks, 1, 0, st>>>((const float *)bc.d_src1_f32, (block_q8_K *)bc.d_src1_q8k, nblocks);
        if (cudaGetLastError() != cudaSuccess) return false;
    } else if (fused_mmq_up_gate) {
        const int64_t ne00_padded = GGML_PAD(ne00, MATRIX_ROW_PADDING);
        quantize_mmq_q8_1_cuda((const float *)bc.d_src1_f32, bc.d_ids_src1, bc.d_src1_q8,
            src0_type, ne00, ne00, (int64_t)n_active * ne00, (int64_t)n_active * ne00,
            ne00_padded, n_active, 1, 1, st);
        if (cudaGetLastError() != cudaSuccess) return false;
    }
    if (profile) cudaEventRecord(bc.ev_quant, st);

    float * fused_d = use_handoff ? (float *)bc.d_handoff : (float *)bc.d_dst;
    const char *skip_nonresident_env = std::getenv("GGML_MOE_SKIP_NONRESIDENT");
    const bool skip_nonresident = skip_nonresident_env && skip_nonresident_env[0] && skip_nonresident_env[0] != '0';
    if (skip_nonresident) {
        if (cudaMemsetAsync(fused_d, 0, dst_bytes, st) != cudaSuccess) return false;
    }
    int up_stage_jobs_count = 0;
    int gate_stage_jobs_count = 0;
    const char *point_tensor_env = std::getenv("GGML_MOE_STREAM_FUSED_UP_GATE_POINT_TENSOR");
    const bool point_dump = point_tensor_env && point_tensor_env[0] &&
        src0_up_name && std::strstr(src0_up_name, point_tensor_env);
    const int point_active = point_dump && std::getenv("GGML_MOE_STREAM_FUSED_UP_GATE_POINT_ACTIVE") ?
        std::atoi(std::getenv("GGML_MOE_STREAM_FUSED_UP_GATE_POINT_ACTIVE")) : -1;
    const int point_flat = point_dump && std::getenv("GGML_MOE_STREAM_FUSED_UP_GATE_POINT_FLAT") ?
        std::atoi(std::getenv("GGML_MOE_STREAM_FUSED_UP_GATE_POINT_FLAT")) : -1;
    const int point_col = point_dump && std::getenv("GGML_MOE_STREAM_FUSED_UP_GATE_POINT_COL") ?
        std::atoi(std::getenv("GGML_MOE_STREAM_FUSED_UP_GATE_POINT_COL")) : -1;

    if (mixed_types) {
        static std::atomic<int> first_mixed_up_gate{0};
        if (first_mixed_up_gate.fetch_add(1) == 0) {
            std::fprintf(stderr,
                "[moe_stream] mixed-type up/gate compact path active: up_type=%d gate_type=%d up_bytes=%zu gate_bytes=%zu rows=%d\n",
                (int)src0_type, (int)gate_type, up_expert_bytes, gate_expert_bytes, n_active);
        }
        const bool mixed_variable_batch_stage =
            expert_pack_env_bool("GGML_MOE_MIXED_UP_GATE_VARIABLE_BATCH", false) &&
            bc.up_stream && bc.gate_stream && bc.ev_stage_ready && bc.ev_up_copy_aux_done &&
            bc.ev_up_done && bc.ev_gate_done;
        const bool mixed_parallel_stage =
            !mixed_variable_batch_stage &&
            expert_pack_env_bool("GGML_MOE_MIXED_UP_GATE_PARALLEL_STAGE", false) &&
            bc.up_stream && bc.gate_stream && bc.ev_stage_ready && bc.ev_up_done && bc.ev_gate_done;
        static std::atomic<int> first_mixed_variable_batch_stage{0};
        if (mixed_variable_batch_stage && first_mixed_variable_batch_stage.fetch_add(1) == 0) {
            std::fprintf(stderr, "[moe_stream] mixed-type up/gate variable-size batch stage active\n");
        }
        static std::atomic<int> first_mixed_parallel_stage{0};
        if (mixed_parallel_stage && first_mixed_parallel_stage.fetch_add(1) == 0) {
            std::fprintf(stderr, "[moe_stream] mixed-type up/gate parallel stage active\n");
        }
        int up_slots[MOE_STREAM_MAX_ACTIVE] = {};
        const bool early_current_down_overlap = current_down_overlap_early_enabled();
        if (early_current_down_overlap) {
            start_current_down_overlap();
        }
        auto mixed_overlap_fail = [&](const char *reason) -> bool {
            (void)join_current_down_overlap();
            return decline(reason);
        };
        if (mixed_variable_batch_stage || mixed_parallel_stage) {
            if (cudaEventRecord(bc.ev_stage_ready, st) != cudaSuccess) {
                return mixed_overlap_fail("mixed_record_stage_ready");
            }
            if (cudaStreamWaitEvent(bc.up_stream, bc.ev_stage_ready, 0) != cudaSuccess ||
                    cudaStreamWaitEvent(bc.gate_stream, bc.ev_stage_ready, 0) != cudaSuccess) {
                return mixed_overlap_fail("mixed_wait_stage_ready");
            }
            if (profile && bc.ev_up_start) cudaEventRecord(bc.ev_up_start, bc.up_stream);
            if (profile && bc.ev_gate_work_start) cudaEventRecord(bc.ev_gate_work_start, bc.gate_stream);

            std::vector<stage_copy_job> up_jobs;
            std::vector<stage_copy_job> gate_jobs;
            if (!plan_tensor_sized(
                    up_key_name, src0_up_data, src0_type, up_nb02, up_expert_bytes,
                    bc.h_x_ids_up, up_slots, nullptr, 0, up_jobs)) {
                clear_stage_jobs(up_jobs);
                return mixed_overlap_fail("mixed_plan_up");
            }
            if (!plan_tensor_sized(
                    gate_key_name, src0_gate_data, gate_type, gate_nb02, gate_expert_bytes,
                    bc.h_x_ids_gate, nullptr, up_slots, n_active, gate_jobs)) {
                clear_stage_jobs(up_jobs);
                clear_stage_jobs(gate_jobs);
                return mixed_overlap_fail("mixed_plan_gate");
            }
            up_stage_jobs_count = (int)up_jobs.size();
            gate_stage_jobs_count = (int)gate_jobs.size();
            submit_planned_host_prefetch(up_jobs);
            submit_planned_host_prefetch(gate_jobs);

            if (mixed_variable_batch_stage) {
                std::vector<stage_copy_job> combined_jobs;
                combined_jobs.reserve(up_jobs.size() + gate_jobs.size());
                for (stage_copy_job job : up_jobs) {
                    job.stream = bc.up_stream;
                    combined_jobs.push_back(job);
                }
                for (stage_copy_job job : gate_jobs) {
                    job.stream = bc.gate_stream;
                    combined_jobs.push_back(job);
                }

                if (!copy_stage_jobs(combined_jobs, bc.up_stream, bc.stage_ring)) {
                    clear_stage_jobs(up_jobs);
                    clear_stage_jobs(gate_jobs);
                    return mixed_overlap_fail("mixed_varbytes_copy");
                }
                if (cudaEventRecord(bc.ev_up_copy_aux_done, bc.up_stream) != cudaSuccess) {
                    clear_stage_jobs(up_jobs);
                    clear_stage_jobs(gate_jobs);
                    return mixed_overlap_fail("mixed_varbytes_record_copy");
                }
                if (profile && bc.ev_gate_start) cudaEventRecord(bc.ev_gate_start, bc.gate_stream);
                predictive_host_prefetch_on_upgate(
                    prompt_mode,
                    up_key_name,
                    gate_key_name,
                    down_shadow_name,
                    up_expert_bytes,
                    gate_expert_bytes,
                    active_experts,
                    n_active);
                if (profile && bc.ev_up_compute_start) cudaEventRecord(bc.ev_up_compute_start, bc.up_stream);
                if (cudaMemsetAsync(bc.d_up, 0, (size_t)n_active * (size_t)ne01 * sizeof(float), bc.up_stream) != cudaSuccess) {
                    return mixed_overlap_fail("mixed_varbytes_memset_up");
                }
                if (!launch_compact_tensor(
                        up_key_name, ggml_moe_common::role::up, src0_type, up_nb01,
                        bc.h_x_ids_up, bc.d_src1_q8_up, bc.d_up, bc.up_stream)) {
                    return mixed_overlap_fail("mixed_varbytes_launch_up");
                }
                if (profile) cudaEventRecord(bc.ev_up, bc.up_stream);

                if (profile && bc.ev_gate_compute_start) cudaEventRecord(bc.ev_gate_compute_start, bc.gate_stream);
                if (cudaMemsetAsync(bc.d_gate, 0, (size_t)n_active * (size_t)ne01 * sizeof(float), bc.gate_stream) != cudaSuccess) {
                    return mixed_overlap_fail("mixed_varbytes_memset_gate");
                }
                if (!launch_compact_tensor(
                        gate_key_name, ggml_moe_common::role::gate, gate_type, gate_nb01,
                        bc.h_x_ids_gate, bc.d_src1_q8_gate, bc.d_gate, bc.gate_stream)) {
                    return mixed_overlap_fail("mixed_varbytes_launch_gate");
                }
                if (profile) cudaEventRecord(bc.ev_gate, bc.gate_stream);
                if (cudaEventRecord(bc.ev_up_done, bc.up_stream) != cudaSuccess ||
                        cudaEventRecord(bc.ev_gate_done, bc.gate_stream) != cudaSuccess ||
                        cudaStreamWaitEvent(st, bc.ev_up_done, 0) != cudaSuccess ||
                        cudaStreamWaitEvent(st, bc.ev_gate_done, 0) != cudaSuccess) {
                    return mixed_overlap_fail("mixed_varbytes_wait_done");
                }
            } else {
            bool up_copy_ok = true;
            bool gate_copy_ok = true;
            std::thread up_thread([&]() {
                up_copy_ok = copy_stage_jobs(up_jobs, bc.up_stream, bc.stage_ring);
            });
            std::thread gate_thread([&]() {
                gate_copy_ok = copy_stage_jobs(gate_jobs, bc.gate_stream, bc.stage_ring_gate);
            });

            up_thread.join();
            if (!up_copy_ok) {
                gate_thread.join();
                clear_stage_jobs(up_jobs);
                clear_stage_jobs(gate_jobs);
                return mixed_overlap_fail("mixed_copy_up");
            }
            if (profile && bc.ev_up_compute_start) cudaEventRecord(bc.ev_up_compute_start, bc.up_stream);
            if (cudaMemsetAsync(bc.d_up, 0, (size_t)n_active * (size_t)ne01 * sizeof(float), bc.up_stream) != cudaSuccess) {
                gate_thread.join();
                return mixed_overlap_fail("mixed_memset_up");
            }
            if (!launch_compact_tensor(
                    up_key_name, ggml_moe_common::role::up, src0_type, up_nb01,
                    bc.h_x_ids_up, bc.d_src1_q8_up, bc.d_up, bc.up_stream)) {
                gate_thread.join();
                return mixed_overlap_fail("mixed_launch_up");
            }
            if (profile) cudaEventRecord(bc.ev_up, bc.up_stream);

            if (profile && bc.ev_gate_start) cudaEventRecord(bc.ev_gate_start, bc.gate_stream);
            gate_thread.join();
            if (!gate_copy_ok) {
                clear_stage_jobs(up_jobs);
                clear_stage_jobs(gate_jobs);
                return mixed_overlap_fail("mixed_copy_gate");
            }
            predictive_host_prefetch_on_upgate(
                prompt_mode,
                up_key_name,
                gate_key_name,
                down_shadow_name,
                up_expert_bytes,
                gate_expert_bytes,
                active_experts,
                n_active);
            if (profile && bc.ev_gate_compute_start) cudaEventRecord(bc.ev_gate_compute_start, bc.gate_stream);
            if (cudaMemsetAsync(bc.d_gate, 0, (size_t)n_active * (size_t)ne01 * sizeof(float), bc.gate_stream) != cudaSuccess) {
                return mixed_overlap_fail("mixed_memset_gate");
            }
            if (!launch_compact_tensor(
                    gate_key_name, ggml_moe_common::role::gate, gate_type, gate_nb01,
                    bc.h_x_ids_gate, bc.d_src1_q8_gate, bc.d_gate, bc.gate_stream)) {
                return mixed_overlap_fail("mixed_launch_gate");
            }
            if (profile) cudaEventRecord(bc.ev_gate, bc.gate_stream);
            if (cudaEventRecord(bc.ev_up_done, bc.up_stream) != cudaSuccess ||
                    cudaEventRecord(bc.ev_gate_done, bc.gate_stream) != cudaSuccess ||
                    cudaStreamWaitEvent(st, bc.ev_up_done, 0) != cudaSuccess ||
                    cudaStreamWaitEvent(st, bc.ev_gate_done, 0) != cudaSuccess) {
                return mixed_overlap_fail("mixed_wait_done");
            }
            }
        } else {
            if (!stage_tensor_slots_only_sized(
                    up_key_name, src0_up_data, src0_type, up_nb02, up_expert_bytes, st,
                    bc.d_x_ids_up, bc.h_x_ids_up, up_slots, nullptr, 0)) {
                return decline("mixed_stage_up");
            }
            if (!stage_tensor_slots_only_sized(
                    gate_key_name, src0_gate_data, gate_type, gate_nb02, gate_expert_bytes, st,
                    bc.d_x_ids_gate, bc.h_x_ids_gate, nullptr, up_slots, n_active)) {
                return decline("mixed_stage_gate");
            }
            if (cudaMemsetAsync(bc.d_up, 0, (size_t)n_active * (size_t)ne01 * sizeof(float), st) != cudaSuccess) {
                return early_current_down_overlap ? mixed_overlap_fail("mixed_memset_up") : decline("mixed_memset_up");
            }
            if (cudaMemsetAsync(bc.d_gate, 0, (size_t)n_active * (size_t)ne01 * sizeof(float), st) != cudaSuccess) {
                return early_current_down_overlap ? mixed_overlap_fail("mixed_memset_gate") : decline("mixed_memset_gate");
            }
            if (!launch_compact_tensor(
                    up_key_name, ggml_moe_common::role::up, src0_type, up_nb01,
                    bc.h_x_ids_up, bc.d_src1_q8_up, bc.d_up, st)) {
                return early_current_down_overlap ? mixed_overlap_fail("mixed_launch_up") : decline("mixed_launch_up");
            }
            if (profile) cudaEventRecord(bc.ev_up, st);
            if (!launch_compact_tensor(
                    gate_key_name, ggml_moe_common::role::gate, gate_type, gate_nb01,
                    bc.h_x_ids_gate, bc.d_src1_q8_gate, bc.d_gate, st)) {
                return early_current_down_overlap ? mixed_overlap_fail("mixed_launch_gate") : decline("mixed_launch_gate");
            }
            if (profile) cudaEventRecord(bc.ev_gate, st);
        }
        if (!early_current_down_overlap) {
            start_current_down_overlap();
        }
        for (int j = 0; j < n_active; ++j) {
            bc.h_ids_dst[j] = flat_dst_ids[j];
        }
        if (cudaMemcpyAsync(bc.d_ids_dst, bc.h_ids_dst, ids_bytes, cudaMemcpyHostToDevice, st) != cudaSuccess) {
            return mixed_overlap_fail("mixed_copy_dst_ids");
        }
        if (cudaMemsetAsync(fused_d, 0, dst_bytes, st) != cudaSuccess) {
            return mixed_overlap_fail("mixed_memset_fused");
        }
        dim3 block(256);
        dim3 grid((unsigned int)((ne01 + block.x - 1) / block.x), (unsigned int)n_active);
        moe_stream_up_gate_fuse_kernel<<<grid, block, 0, st>>>(
            (const float *)bc.d_up, (const float *)bc.d_gate, fused_d,
            bc.d_ids_dst, n_active, ne01, unary_op, limit, true);
        if (cudaGetLastError() != cudaSuccess) {
            return mixed_overlap_fail("mixed_launch_fuse");
        }
        if (profile) cudaEventRecord(bc.ev_kernel, st);
        if (!g_expert_pack.glm52_colibri) {
            if (cudaMemcpyAsync(bc.h_dst, fused_d, dst_bytes, cudaMemcpyDeviceToHost, st) != cudaSuccess) {
                return mixed_overlap_fail("mixed_copy_d2h");
            }
            if (profile) cudaEventRecord(bc.ev_d2h, st);
        }
        if (cudaStreamSynchronize(st) != cudaSuccess) {
            return mixed_overlap_fail("mixed_sync");
        }
        (void)join_current_down_overlap();
        const float *tmp = (const float *)bc.h_dst;
        const auto scatter_start = profile ? std::chrono::steady_clock::now() : std::chrono::steady_clock::time_point{};
        for (int j = 0; j < n_active; ++j) {
            float *dst_row = (float *)((char *)dst + (size_t)dst_ids[j] * dst_nb1 + (size_t)token_ids[j] * dst_nb2);
            if (g_expert_pack.glm52_colibri) {
                const float *src_row = fused_d + (size_t)flat_dst_ids[j] * ne01;
                if (cudaMemcpyAsync(dst_row, src_row, (size_t)ne01 * sizeof(float), cudaMemcpyDeviceToDevice, st) != cudaSuccess) {
                    return mixed_overlap_fail("mixed_scatter_d2d");
                }
            } else {
                std::memcpy(dst_row, tmp + (size_t)flat_dst_ids[j] * ne01, (size_t)ne01 * sizeof(float));
            }
        }
        if (g_expert_pack.glm52_colibri && cudaStreamSynchronize(st) != cudaSuccess) {
            return mixed_overlap_fail("mixed_scatter_sync");
        }
        if (profile) {
            float stage_ms = 0.0f;
            float quant_ms = 0.0f;
            float up_ms = 0.0f;
            float gate_ms = 0.0f;
            float up_wait_ms = 0.0f;
            float gate_wait_ms = 0.0f;
            float up_compute_ms = 0.0f;
            float gate_compute_ms = 0.0f;
            float fuse_ms = 0.0f;
            float kernel_ms = 0.0f;
            float d2h_ms = 0.0f;
            cudaEventElapsedTime(&stage_ms, bc.ev_start, bc.ev_stage);
            cudaEventElapsedTime(&quant_ms, bc.ev_stage, bc.ev_quant);
            if ((mixed_parallel_stage || mixed_variable_batch_stage) && bc.ev_up_start && bc.ev_gate_start) {
                cudaEventElapsedTime(&up_ms, bc.ev_up_start, bc.ev_up);
                cudaEventElapsedTime(&gate_ms, bc.ev_gate_start, bc.ev_gate);
                if (bc.ev_gate_work_start && bc.ev_up_compute_start && bc.ev_gate_compute_start) {
                    cudaEventElapsedTime(&up_wait_ms, bc.ev_up_start, bc.ev_up_compute_start);
                    cudaEventElapsedTime(&gate_wait_ms, bc.ev_gate_work_start, bc.ev_gate_compute_start);
                    cudaEventElapsedTime(&up_compute_ms, bc.ev_up_compute_start, bc.ev_up);
                    cudaEventElapsedTime(&gate_compute_ms, bc.ev_gate_compute_start, bc.ev_gate);
                }
            } else {
                cudaEventElapsedTime(&up_ms, bc.ev_quant, bc.ev_up);
                cudaEventElapsedTime(&gate_ms, bc.ev_up, bc.ev_gate);
            }
            cudaEventElapsedTime(&fuse_ms, bc.ev_gate, bc.ev_kernel);
            cudaEventElapsedTime(&kernel_ms, bc.ev_quant, bc.ev_kernel);
            cudaEventElapsedTime(&d2h_ms, bc.ev_kernel, bc.ev_d2h);
            const auto scatter_end = std::chrono::steady_clock::now();
            const double scatter_ms = std::chrono::duration<double, std::milli>(scatter_end - scatter_start).count();
            const double wall_ms = std::chrono::duration<double, std::milli>(scatter_end - wall_start).count();
            up_gate_profile_add(
                g_uprof,
                (uint64_t)n_active,
                (uint64_t)up_stage_jobs_count,
                (uint64_t)gate_stage_jobs_count,
                stage_ms,
                quant_ms,
                up_ms,
                gate_ms,
                up_wait_ms,
                gate_wait_ms,
                up_compute_ms,
                gate_compute_ms,
                fuse_ms,
                kernel_ms,
                d2h_ms,
                scatter_ms,
                wall_ms);
            up_gate_type_profile_add(
                prompt_mode,
                src0_type,
                gate_type,
                (uint64_t)n_active,
                (uint64_t)up_stage_jobs_count,
                (uint64_t)gate_stage_jobs_count,
                stage_ms,
                quant_ms,
                up_ms,
                gate_ms,
                up_wait_ms,
                gate_wait_ms,
                up_compute_ms,
                gate_compute_ms,
                fuse_ms,
                kernel_ms,
                d2h_ms,
                scatter_ms,
                wall_ms);
            up_gate_layer_profile_add(
                prompt_mode,
                up_key_name,
                gate_key_name,
                src0_type,
                gate_type,
                (uint64_t)n_active,
                (uint64_t)up_stage_jobs_count,
                (uint64_t)gate_stage_jobs_count,
                stage_ms,
                quant_ms,
                up_ms,
                gate_ms,
                up_wait_ms,
                gate_wait_ms,
                up_compute_ms,
                gate_compute_ms,
                fuse_ms,
                kernel_ms,
                d2h_ms,
                scatter_ms,
                wall_ms);
            up_gate_profile_csv_record(
                prompt_mode,
                up_key_name,
                gate_key_name,
                src0_type,
                gate_type,
                n_active,
                n_active - up_stage_jobs_count,
                up_stage_jobs_count,
                n_active - gate_stage_jobs_count,
                gate_stage_jobs_count,
                up_stage_jobs_count,
                gate_stage_jobs_count,
                stage_ms,
                quant_ms,
                up_ms,
                gate_ms,
                up_wait_ms,
                gate_wait_ms,
                up_compute_ms,
                gate_compute_ms,
                fuse_ms,
                kernel_ms,
                d2h_ms,
                scatter_ms,
                wall_ms,
                use_handoff,
                false,
                mixed_parallel_stage);
        }
        return true;
    }

    if (exact_prompt_q8k && n_active * 2 > cache->n_slots) {
        const bool exact_debug = []() {
            const char *env = std::getenv("GGML_MOE_STREAM_EXACT_PROMPT_DEBUG");
            return env && env[0] && env[0] != '0';
        }();
        auto exact_fail = [&](const char *where) -> bool {
            if (exact_debug) {
                std::fprintf(stderr,
                    "[moe_stream] exact prompt chunked staging failed: %s tensor=%s routes=%d cache_slots=%d\n",
                    where, src0_up_name ? src0_up_name : "", n_active, cache->n_slots);
            }
            return false;
        };
        const int evictable_slots = cache->n_slots > (int)cache->pinned ? cache->n_slots - (int)cache->pinned : 0;
        if (evictable_slots < 2) return exact_fail("evictable_slots_lt_2");
        const int chunk_routes = std::max(1, std::min(MOE_STREAM_MAX_ACTIVE, evictable_slots / 2));
        static std::atomic<int> first_chunked_exact{0};
        if (first_chunked_exact.fetch_add(1) == 0) {
            std::fprintf(stderr,
                "[moe_stream] exact prompt Q8_K chunked staging active: routes=%d cache_slots=%d chunk=%d\n",
                n_active, cache->n_slots, chunk_routes);
        }
        if (cudaMemsetAsync(bc.d_up, 0, dst_bytes, st) != cudaSuccess) return exact_fail("memset_up");
        if (cudaMemsetAsync(bc.d_gate, 0, dst_bytes, st) != cudaSuccess) return exact_fail("memset_gate");
        if (cudaMemsetAsync(fused_d, 0, dst_bytes, st) != cudaSuccess) return exact_fail("memset_fused");

        auto stage_exact_chunk = [&](
                const char *key_name,
                ggml_moe_common::role kind,
                const void *host_base,
                int first,
                int count,
                int32_t *d_x_ids,
                int32_t *h_x_ids,
                int *slots_out,
                const int *avoid_slots,
                int n_avoid_slots,
                float *d_out) -> bool {
            for (int jj = 0; jj < count; ++jj) {
                const int j = first + jj;
                const char *expert_host = (const char *)host_base + (size_t)active_experts[j] * nb02;
                const uintptr_t cache_key = batch_key_hash(key_name, active_experts[j]);
                int effective_avoid[MOE_STREAM_MAX_ACTIVE * 2] = {};
                int n_effective_avoid = 0;
                for (int ia = 0; ia < n_avoid_slots && n_effective_avoid < (int)(sizeof(effective_avoid) / sizeof(effective_avoid[0])); ++ia) {
                    effective_avoid[n_effective_avoid++] = avoid_slots[ia];
                }
                if (slots_out) {
                    for (int ia = 0; ia < jj && n_effective_avoid < (int)(sizeof(effective_avoid) / sizeof(effective_avoid[0])); ++ia) {
                        effective_avoid[n_effective_avoid++] = slots_out[ia];
                    }
                }
                const int cache_slot = batch_cache_insert_slot(
                    cache, cache_key, expert_host, src0_bytes, st, true, false,
                    effective_avoid, n_effective_avoid, true, key_name, active_experts[j],
                    false, false);
                if (cache_slot < 0) return exact_fail("cache_insert");
                h_x_ids[jj] = cache_slot;
                if (slots_out) slots_out[jj] = cache_slot;
                batch_route_profile_hit(key_name, active_experts[j], src0_bytes);
            }
            if (cudaMemcpyAsync(d_x_ids, h_x_ids, (size_t)count * sizeof(int32_t), cudaMemcpyHostToDevice, st) != cudaSuccess) return exact_fail("copy_x_ids");
            if (!batch_cache_launch_with_role_leases(
                    cache, key_name, kind, active_experts + first, h_x_ids, count, st, [&]() {
                        return launch_moe_iq3_xxs_q8k_batch(
                            src0_type, (const char *)cache->pool,
                            (const block_q8_K *)bc.d_src1_q8k + (size_t)first * (ne00 / QK_K),
                            bc.d_ids_dst, d_x_ids, d_out,
                            ne00, ne01, nb01, cache->slot_sz, count, dst_cols,
                            src0_type == GGML_TYPE_IQ2_S &&
                                exact_prompt_q8k_iq2_direct_probe_enabled(),
                            st);
                    })) {
                return exact_fail("launch_q8k_batch");
            }
            return true;
        };

        dim3 block(256);
        dim3 grid_x((unsigned int)((ne01 + block.x - 1) / block.x));
        for (int first = 0; first < n_active; first += chunk_routes) {
            const int count = std::min(chunk_routes, n_active - first);
            int up_slots[MOE_STREAM_MAX_ACTIVE] = {};
            int gate_slots[MOE_STREAM_MAX_ACTIVE] = {};
            for (int jj = 0; jj < count; ++jj) {
                bc.h_ids_dst[jj] = jj;
            }
            if (cudaMemcpyAsync(bc.d_ids_dst, bc.h_ids_dst, (size_t)count * sizeof(int32_t), cudaMemcpyHostToDevice, st) != cudaSuccess) {
                return exact_fail("copy_chunk_dst_ids");
            }
            if (!stage_exact_chunk(up_key_name, ggml_moe_common::role::up, src0_up_data, first, count,
                    bc.d_x_ids_up, bc.h_x_ids_up, up_slots, nullptr, 0, (float *)bc.d_up)) {
                return exact_fail("stage_up_chunk");
            }
            if (!stage_exact_chunk(gate_key_name, ggml_moe_common::role::gate, src0_gate_data, first, count,
                    bc.d_x_ids_gate, bc.h_x_ids_gate, gate_slots, up_slots, count, (float *)bc.d_gate)) {
                return exact_fail("stage_gate_chunk");
            }
            if (point_dump && point_active >= first && point_active < first + count &&
                    point_col >= 0 && point_col < ne01) {
                const int local = point_active - first;
                float up_point = 0.0f;
                float gate_point = 0.0f;
                if (cudaMemcpyAsync(&up_point, (const float *)bc.d_up + (size_t)local * ne01 + point_col,
                            sizeof(float), cudaMemcpyDeviceToHost, st) != cudaSuccess) return exact_fail("copy_point_up");
                if (cudaMemcpyAsync(&gate_point, (const float *)bc.d_gate + (size_t)local * ne01 + point_col,
                            sizeof(float), cudaMemcpyDeviceToHost, st) != cudaSuccess) return exact_fail("copy_point_gate");
                if (cudaStreamSynchronize(st) != cudaSuccess) return exact_fail("sync_point");
                std::fprintf(stderr,
                    "[moe_stream] exact chunk point prefuse: tensor=%s active=%d local=%d expert=%d token=%d dst=%d flat=%d col=%d up=%g gate=%g chunk_first=%d chunk_count=%d\n",
                    src0_up_name, point_active, local, active_experts[point_active],
                    token_ids[point_active], dst_ids[point_active], flat_dst_ids[point_active],
                    point_col, (double)up_point, (double)gate_point, first, count);
            }
            dim3 grid(grid_x.x, (unsigned int)count);
            moe_stream_up_gate_fuse_kernel<<<grid, block, 0, st>>>(
                (const float *)bc.d_up, (const float *)bc.d_gate, fused_d,
                bc.d_ids_dst, count, ne01, unary_op, limit, true);
            if (cudaGetLastError() != cudaSuccess) return exact_fail("launch_fuse");
            const size_t chunk_bytes = (size_t)count * (size_t)ne01 * sizeof(float);
            if (cudaMemcpyAsync(bc.h_dst, fused_d, chunk_bytes, cudaMemcpyDeviceToHost, st) != cudaSuccess) return exact_fail("copy_chunk_d2h");
            if (cudaStreamSynchronize(st) != cudaSuccess) return exact_fail("sync_chunk");
            const float *tmp = (const float *)bc.h_dst;
            if (point_dump && point_active >= first && point_active < first + count &&
                    point_col >= 0 && point_col < ne01) {
                const int local = point_active - first;
                std::fprintf(stderr,
                    "[moe_stream] exact chunk point fused: tensor=%s active=%d local=%d flat=%d col=%d fused=%g\n",
                    src0_up_name, point_active, local, point_flat, point_col,
                    (double)tmp[(size_t)local * ne01 + point_col]);
            }
            for (int jj = 0; jj < count; ++jj) {
                const int j = first + jj;
                float *dst_row = (float *)((char *)dst + (size_t)dst_ids[j] * dst_nb1 + (size_t)token_ids[j] * dst_nb2);
                std::memcpy(dst_row, tmp + (size_t)jj * ne01, (size_t)ne01 * sizeof(float));
            }
        }
        return true;
    }

    if (fused_mmq_up_gate) {
        int up_slots[MOE_STREAM_MAX_ACTIVE] = {};
        if (!stage_tensor_slots_only(
                up_key_name, src0_up_data, src0_type, st,
                bc.d_x_ids_up, bc.h_x_ids_up, up_slots, nullptr, 0)) {
            return false;
        }
        if (!stage_tensor_slots_only(
                gate_key_name, src0_gate_data, gate_type, st,
                bc.d_x_ids_gate, bc.h_x_ids_gate, nullptr, up_slots, n_active)) {
            return false;
        }

        for (int j = 0; j < n_active; ++j) {
            bc.h_ids_dst[j] = j;
        }
        if (cudaMemcpyAsync(bc.d_ids_dst, bc.h_ids_dst, ids_bytes, cudaMemcpyHostToDevice, st) != cudaSuccess) return false;
        if (cudaMemsetAsync(bc.d_up, 0, (size_t)n_active * (size_t)ne01 * sizeof(float), st) != cudaSuccess) return false;
        if (cudaMemsetAsync(bc.d_gate, 0, (size_t)n_active * (size_t)ne01 * sizeof(float), st) != cudaSuccess) return false;
        if (!batch_cache_launch_with_role_leases(
                cache, up_key_name, ggml_moe_common::role::up, active_experts, bc.h_x_ids_up,
                n_active, st, [&]() {
                    return launch_moe_mmq_slot_batch(
                        src0_type, (const char *)cache->pool, (const int *)bc.d_src1_q8,
                        bc.d_ids_dst, bc.d_bounds, bc.d_x_ids_up, (float *)bc.d_up,
                        ne00, ne01, nb01, cache->slot_sz, n_active, n_active, st);
                })) {
            return false;
        }
        if (profile) cudaEventRecord(bc.ev_up, st);
        if (!batch_cache_launch_with_role_leases(
                cache, gate_key_name, ggml_moe_common::role::gate, active_experts, bc.h_x_ids_gate,
                n_active, st, [&]() {
                    return launch_moe_mmq_slot_batch(
                        src0_type, (const char *)cache->pool, (const int *)bc.d_src1_q8,
                        bc.d_ids_dst, bc.d_bounds, bc.d_x_ids_gate, (float *)bc.d_gate,
                        ne00, ne01, nb01, cache->slot_sz, n_active, n_active, st);
                })) {
            return false;
        }
        if (profile) cudaEventRecord(bc.ev_gate, st);

        static std::atomic<int> mmq_compare_count{0};
        const int compare_call = mmq_compare ? mmq_compare_count.fetch_add(1) : INT_MAX;
        if (mmq_compare && compare_call < 4) {
            void *compare_buf = use_handoff ? bc.d_dst : bc.d_handoff;
            if (!use_handoff && !ensure_dev(bc.d_handoff, bc.d_handoff_sz, dst_bytes)) {
                return false;
            }
            compare_buf = use_handoff ? bc.d_dst : bc.d_handoff;
            const size_t compact_bytes = (size_t)n_active * (size_t)ne01 * sizeof(float);
            if (cudaMemsetAsync(compare_buf, 0, compact_bytes, st) != cudaSuccess) return false;
            if (!launch_compact_tensor(
                    up_key_name, ggml_moe_common::role::up, src0_type, up_nb01,
                    bc.h_x_ids_up, bc.d_src1_q8_up, compare_buf, st)) {
                return false;
            }
            if (!moe_stream_compare_device_rows(
                    "up", (const float *)bc.d_up, (const float *)compare_buf,
                    bc.h_dst, bc.h_dst_sz, n_active, ne01, st)) {
                return false;
            }
            if (cudaMemsetAsync(compare_buf, 0, compact_bytes, st) != cudaSuccess) return false;
            if (!launch_compact_tensor(
                    gate_key_name, ggml_moe_common::role::gate, src0_type, gate_nb01,
                    bc.h_x_ids_gate, bc.d_src1_q8_gate, compare_buf, st)) {
                return false;
            }
            if (!moe_stream_compare_device_rows(
                    "gate", (const float *)bc.d_gate, (const float *)compare_buf,
                    bc.h_dst, bc.h_dst_sz, n_active, ne01, st)) {
                return false;
            }
        }

        for (int j = 0; j < n_active; ++j) {
            bc.h_ids_dst[j] = flat_dst_ids[j];
        }
        if (cudaMemcpyAsync(bc.d_ids_dst, bc.h_ids_dst, ids_bytes, cudaMemcpyHostToDevice, st) != cudaSuccess) return false;
        if (cudaMemsetAsync(fused_d, 0, dst_bytes, st) != cudaSuccess) return false;
    } else if (parallel_up_gate) {
        if (cudaEventRecord(bc.ev_stage_ready, st) != cudaSuccess) return false;
        if (cudaStreamWaitEvent(bc.up_stream, bc.ev_stage_ready, 0) != cudaSuccess) return false;
        if (cudaStreamWaitEvent(bc.gate_stream, bc.ev_stage_ready, 0) != cudaSuccess) return false;
        if (bc.up_copy_stream && cudaStreamWaitEvent(bc.up_copy_stream, bc.ev_stage_ready, 0) != cudaSuccess) return false;
        if (bc.gate_copy_stream && cudaStreamWaitEvent(bc.gate_copy_stream, bc.ev_stage_ready, 0) != cudaSuccess) return false;
        if (profile && bc.ev_up_start) cudaEventRecord(bc.ev_up_start, bc.up_stream);
        if (profile && bc.ev_gate_work_start) cudaEventRecord(bc.ev_gate_work_start, bc.gate_stream);
        auto parallel_fail = [&]() -> bool {
            cudaStreamSynchronize(bc.up_stream);
            cudaStreamSynchronize(bc.gate_stream);
            if (bc.up_copy_stream) cudaStreamSynchronize(bc.up_copy_stream);
            if (bc.gate_copy_stream) cudaStreamSynchronize(bc.gate_copy_stream);
            return false;
        };

        int up_slots[MOE_STREAM_MAX_ACTIVE] = {};
        if (parallel_stage) {
            std::vector<stage_copy_job> up_jobs;
            std::vector<stage_copy_job> gate_jobs;
            if (!plan_tensor(up_key_name, src0_up_data, src0_type, bc.h_x_ids_up, up_slots, nullptr, 0, up_jobs)) {
                clear_stage_jobs(up_jobs);
                return parallel_fail();
            }
            if (!plan_tensor(gate_key_name, src0_gate_data, gate_type, bc.h_x_ids_gate, nullptr, up_slots, n_active, gate_jobs)) {
                clear_stage_jobs(up_jobs);
                clear_stage_jobs(gate_jobs);
                return parallel_fail();
            }
            up_stage_jobs_count = (int)up_jobs.size();
            gate_stage_jobs_count = (int)gate_jobs.size();
            submit_planned_host_prefetch(up_jobs);
            submit_planned_host_prefetch(gate_jobs);

            const char *stage_split_env = std::getenv("GGML_MOE_STREAM_UP_GATE_STAGE_SPLIT");
            if (!stage_split_env || !stage_split_env[0]) {
                stage_split_env = std::getenv("GGML_MOE_STREAM_UP_GATE_SPLIT_STAGE");
            }
            const bool stage_split = stage_split_env && stage_split_env[0] && stage_split_env[0] != '0' &&
                bc.up_copy_stream && bc.gate_copy_stream && bc.ev_up_copy_aux_done && bc.ev_gate_copy_aux_done;
            static std::atomic<int> first_stage_split{0};
            if (stage_split && first_stage_split.fetch_add(1) == 0) {
                std::fprintf(stderr, "[moe_stream] up/gate split CPU staging active\n");
            }
            const bool combined_stage = !stage_split &&
                expert_pack_env_bool("GGML_MOE_UP_GATE_COMBINED_STAGE", false) &&
                bc.ev_up_copy_aux_done;
            static std::atomic<int> first_combined_stage{0};
            if (combined_stage && first_combined_stage.fetch_add(1) == 0) {
                std::fprintf(stderr, "[moe_stream] up/gate combined staging active\n");
            }

            if (stage_split) {
                std::vector<stage_copy_job> up_jobs_a;
                std::vector<stage_copy_job> up_jobs_b;
                std::vector<stage_copy_job> gate_jobs_a;
                std::vector<stage_copy_job> gate_jobs_b;
                split_stage_jobs(up_jobs, up_jobs_a, up_jobs_b);
                split_stage_jobs(gate_jobs, gate_jobs_a, gate_jobs_b);

                bool up_a_ok = true;
                bool up_b_ok = true;
                bool gate_a_ok = true;
                bool gate_b_ok = true;
                std::thread up_a_thread([&]() {
                    up_a_ok = copy_stage_jobs(up_jobs_a, bc.up_stream, bc.stage_ring);
                });
                std::thread up_b_thread([&]() {
                    up_b_ok = copy_stage_jobs(up_jobs_b, bc.up_copy_stream, bc.stage_ring_up_aux);
                });
                std::thread gate_a_thread([&]() {
                    gate_a_ok = copy_stage_jobs(gate_jobs_a, bc.gate_stream, bc.stage_ring_gate);
                });
                std::thread gate_b_thread([&]() {
                    gate_b_ok = copy_stage_jobs(gate_jobs_b, bc.gate_copy_stream, bc.stage_ring_gate_aux);
                });

                up_a_thread.join();
                up_b_thread.join();
                if (!up_a_ok || !up_b_ok) {
                    gate_a_thread.join();
                    gate_b_thread.join();
                    clear_stage_jobs(up_jobs);
                    clear_stage_jobs(gate_jobs);
                    return parallel_fail();
                }
                if (cudaEventRecord(bc.ev_up_copy_aux_done, bc.up_copy_stream) != cudaSuccess ||
                        cudaStreamWaitEvent(bc.up_stream, bc.ev_up_copy_aux_done, 0) != cudaSuccess) {
                    gate_a_thread.join();
                    gate_b_thread.join();
                    return parallel_fail();
                }
                if (profile && bc.ev_up_compute_start) cudaEventRecord(bc.ev_up_compute_start, bc.up_stream);
                if (!launch_tensor(up_key_name, ggml_moe_common::role::up,
                        bc.d_up, bc.up_stream, bc.d_x_ids_up, bc.d_src1_q8_up, bc.h_x_ids_up)) {
                    gate_a_thread.join();
                    gate_b_thread.join();
                    return parallel_fail();
                }
                if (profile) cudaEventRecord(bc.ev_up, bc.up_stream);

                if (profile && bc.ev_gate_start) cudaEventRecord(bc.ev_gate_start, bc.gate_stream);
                gate_a_thread.join();
                gate_b_thread.join();
                if (!gate_a_ok || !gate_b_ok) {
                    clear_stage_jobs(up_jobs);
                    clear_stage_jobs(gate_jobs);
                    return parallel_fail();
                }
                if (cudaEventRecord(bc.ev_gate_copy_aux_done, bc.gate_copy_stream) != cudaSuccess ||
                        cudaStreamWaitEvent(bc.gate_stream, bc.ev_gate_copy_aux_done, 0) != cudaSuccess) {
                    return parallel_fail();
                }
                if (profile && bc.ev_gate_compute_start) cudaEventRecord(bc.ev_gate_compute_start, bc.gate_stream);
                if (!launch_tensor(gate_key_name, ggml_moe_common::role::gate,
                        bc.d_gate, bc.gate_stream, bc.d_x_ids_gate, bc.d_src1_q8_gate, bc.h_x_ids_gate)) {
                    return parallel_fail();
                }
            } else if (combined_stage) {
                std::vector<stage_copy_job> combined_jobs;
                combined_jobs.reserve(up_jobs.size() + gate_jobs.size());
                combined_jobs.insert(combined_jobs.end(), up_jobs.begin(), up_jobs.end());
                combined_jobs.insert(combined_jobs.end(), gate_jobs.begin(), gate_jobs.end());
                if (!copy_stage_jobs(combined_jobs, bc.up_stream, bc.stage_ring)) {
                    clear_stage_jobs(up_jobs);
                    clear_stage_jobs(gate_jobs);
                    return parallel_fail();
                }
                if (cudaEventRecord(bc.ev_up_copy_aux_done, bc.up_stream) != cudaSuccess ||
                        cudaStreamWaitEvent(bc.gate_stream, bc.ev_up_copy_aux_done, 0) != cudaSuccess) {
                    clear_stage_jobs(up_jobs);
                    clear_stage_jobs(gate_jobs);
                    return parallel_fail();
                }
                if (profile && bc.ev_up_compute_start) cudaEventRecord(bc.ev_up_compute_start, bc.up_stream);
                if (!launch_tensor(up_key_name, ggml_moe_common::role::up,
                        bc.d_up, bc.up_stream, bc.d_x_ids_up, bc.d_src1_q8_up, bc.h_x_ids_up)) {
                    return parallel_fail();
                }
                if (profile) cudaEventRecord(bc.ev_up, bc.up_stream);

                if (profile && bc.ev_gate_start) cudaEventRecord(bc.ev_gate_start, bc.gate_stream);
                if (profile && bc.ev_gate_compute_start) cudaEventRecord(bc.ev_gate_compute_start, bc.gate_stream);
                if (!launch_tensor(gate_key_name, ggml_moe_common::role::gate,
                        bc.d_gate, bc.gate_stream, bc.d_x_ids_gate, bc.d_src1_q8_gate, bc.h_x_ids_gate)) {
                    return parallel_fail();
                }
            } else {
                bool up_copy_ok = true;
                bool gate_copy_ok = true;
                std::thread up_thread([&]() {
                    up_copy_ok = copy_stage_jobs(up_jobs, bc.up_stream, bc.stage_ring);
                });
                std::thread gate_thread([&]() {
                    gate_copy_ok = copy_stage_jobs(gate_jobs, bc.gate_stream, bc.stage_ring_gate);
                });

                up_thread.join();
                if (!up_copy_ok) {
                    gate_thread.join();
                    clear_stage_jobs(up_jobs);
                    clear_stage_jobs(gate_jobs);
                    return parallel_fail();
                }
                if (profile && bc.ev_up_compute_start) cudaEventRecord(bc.ev_up_compute_start, bc.up_stream);
                if (!launch_tensor(up_key_name, ggml_moe_common::role::up,
                        bc.d_up, bc.up_stream, bc.d_x_ids_up, bc.d_src1_q8_up, bc.h_x_ids_up)) {
                    gate_thread.join();
                    return parallel_fail();
                }
                if (profile) cudaEventRecord(bc.ev_up, bc.up_stream);

                if (profile && bc.ev_gate_start) cudaEventRecord(bc.ev_gate_start, bc.gate_stream);
                gate_thread.join();
                if (!gate_copy_ok) {
                    clear_stage_jobs(up_jobs);
                    clear_stage_jobs(gate_jobs);
                    return parallel_fail();
                }
                if (profile && bc.ev_gate_compute_start) cudaEventRecord(bc.ev_gate_compute_start, bc.gate_stream);
                if (!launch_tensor(gate_key_name, ggml_moe_common::role::gate,
                        bc.d_gate, bc.gate_stream, bc.d_x_ids_gate, bc.d_src1_q8_gate, bc.h_x_ids_gate)) {
                    return parallel_fail();
                }
            }
        } else {
            if (!stage_tensor(
                    up_key_name, ggml_moe_common::role::up, src0_up_data, bc.d_up, bc.up_stream,
                    bc.d_x_ids_up, bc.d_src1_q8_up, bc.h_x_ids_up, up_slots, nullptr, 0)) {
                return parallel_fail();
            }
            if (profile) cudaEventRecord(bc.ev_up, bc.up_stream);
            if (profile && bc.ev_gate_start) cudaEventRecord(bc.ev_gate_start, bc.gate_stream);
            if (!stage_tensor(
                    gate_key_name, ggml_moe_common::role::gate, src0_gate_data, bc.d_gate, bc.gate_stream,
                    bc.d_x_ids_gate, bc.d_src1_q8_gate, bc.h_x_ids_gate, nullptr, up_slots, n_active)) {
                return parallel_fail();
            }
        }
        if (profile) cudaEventRecord(bc.ev_gate, bc.gate_stream);
        if (cudaEventRecord(bc.ev_up_done, bc.up_stream) != cudaSuccess) return parallel_fail();
        if (cudaEventRecord(bc.ev_gate_done, bc.gate_stream) != cudaSuccess) return parallel_fail();
        if (cudaStreamWaitEvent(st, bc.ev_up_done, 0) != cudaSuccess) return parallel_fail();
        if (cudaStreamWaitEvent(st, bc.ev_gate_done, 0) != cudaSuccess) return parallel_fail();
    } else {
        if (serial_stage_batch) {
            std::vector<stage_copy_job> up_jobs;
            std::vector<stage_copy_job> gate_jobs;
            if (!plan_tensor(up_key_name, src0_up_data, src0_type, bc.h_x_ids, nullptr, nullptr, 0, up_jobs)) {
                clear_stage_jobs(up_jobs);
                return false;
            }
            up_stage_jobs_count = (int)up_jobs.size();
            if (!copy_stage_jobs(up_jobs, st, bc.stage_ring)) {
                clear_stage_jobs(up_jobs);
                return false;
            }
            if (!launch_tensor(up_key_name, ggml_moe_common::role::up,
                    bc.d_up, st, bc.d_x_ids, bc.d_src1_q8, bc.h_x_ids)) {
                return false;
            }
            if (profile) cudaEventRecord(bc.ev_up, st);

            if (!plan_tensor(gate_key_name, src0_gate_data, gate_type, bc.h_x_ids, nullptr, nullptr, 0, gate_jobs)) {
                clear_stage_jobs(gate_jobs);
                return false;
            }
            gate_stage_jobs_count = (int)gate_jobs.size();
            if (!copy_stage_jobs(gate_jobs, st, bc.stage_ring)) {
                clear_stage_jobs(gate_jobs);
                return false;
            }
            if (!launch_tensor(gate_key_name, ggml_moe_common::role::gate,
                    bc.d_gate, st, bc.d_x_ids, bc.d_src1_q8, bc.h_x_ids)) {
                return false;
            }
        } else {
            if (!stage_tensor(
                    up_key_name, ggml_moe_common::role::up, src0_up_data, bc.d_up, st,
                    bc.d_x_ids, bc.d_src1_q8, bc.h_x_ids, nullptr, nullptr, 0)) {
                return false;
            }
            if (profile) cudaEventRecord(bc.ev_up, st);
            if (!stage_tensor(
                    gate_key_name, ggml_moe_common::role::gate, src0_gate_data, bc.d_gate, st,
                    bc.d_x_ids, bc.d_src1_q8, bc.h_x_ids, nullptr, nullptr, 0)) {
                return false;
            }
        }
        if (profile) cudaEventRecord(bc.ev_gate, st);
    }

    if (current_down_overlap_all_paths_enabled()) {
        start_current_down_overlap();
    }
    auto fail_after_current_down_overlap = [&]() -> bool {
        (void)join_current_down_overlap();
        return false;
    };

    const char *prefuse_env = std::getenv("GGML_MOE_STREAM_FUSED_UP_GATE_PREFUSE_DUMP");
    const bool prefuse_dump = prefuse_env && prefuse_env[0] && prefuse_env[0] != '0';
    static std::atomic<int> prefuse_dump_count{0};
    if (prefuse_dump && prefuse_dump_count.fetch_add(1) == 0) {
        if (cudaMemcpyAsync(bc.h_dst, bc.d_up, dst_bytes, cudaMemcpyDeviceToHost, st) != cudaSuccess) return fail_after_current_down_overlap();
        if (cudaStreamSynchronize(st) != cudaSuccess) return fail_after_current_down_overlap();
        moe_stream_dump_prefuse_rows("up", (const float *)bc.h_dst, n_active, ne01);
        if (cudaMemcpyAsync(bc.h_dst, bc.d_gate, dst_bytes, cudaMemcpyDeviceToHost, st) != cudaSuccess) return fail_after_current_down_overlap();
        if (cudaStreamSynchronize(st) != cudaSuccess) return fail_after_current_down_overlap();
        moe_stream_dump_prefuse_rows("gate", (const float *)bc.h_dst, n_active, ne01);
    }

    if (point_dump && point_active >= 0 && point_active < n_active && point_col >= 0 && point_col < ne01) {
        if (cudaMemcpyAsync(bc.h_dst, bc.d_up, dst_bytes, cudaMemcpyDeviceToHost, st) != cudaSuccess) return fail_after_current_down_overlap();
        if (cudaStreamSynchronize(st) != cudaSuccess) return fail_after_current_down_overlap();
        const float *point_tmp = (const float *)bc.h_dst;
        const float up_active = point_tmp[(size_t)point_active * (size_t)ne01 + (size_t)point_col];
        const float up_flat = point_flat >= 0 && point_flat < dst_cols ?
            point_tmp[(size_t)point_flat * (size_t)ne01 + (size_t)point_col] : 0.0f;
        if (cudaMemcpyAsync(bc.h_dst, bc.d_gate, dst_bytes, cudaMemcpyDeviceToHost, st) != cudaSuccess) return fail_after_current_down_overlap();
        if (cudaStreamSynchronize(st) != cudaSuccess) return fail_after_current_down_overlap();
        point_tmp = (const float *)bc.h_dst;
        const float gate_active = point_tmp[(size_t)point_active * (size_t)ne01 + (size_t)point_col];
        const float gate_flat = point_flat >= 0 && point_flat < dst_cols ?
            point_tmp[(size_t)point_flat * (size_t)ne01 + (size_t)point_col] : 0.0f;
        std::fprintf(stderr,
            "[moe_stream] up/gate point prefuse: tensor=%s active=%d active_expert=%d active_token=%d active_dst=%d active_flat=%d flat=%d col=%d up_active=%g gate_active=%g up_flat=%g gate_flat=%g prompt_mode=%d\n",
            src0_up_name, point_active,
            active_experts[point_active], token_ids[point_active], dst_ids[point_active], flat_dst_ids[point_active],
            point_flat, point_col, up_active, gate_active, up_flat, gate_flat, prompt_mode ? 1 : 0);
    }

    for (int j = 0; j < n_active; ++j) {
        bc.h_ids_dst[j] = prompt_mode ? j : flat_dst_ids[j];
    }
    if (cudaMemcpyAsync(bc.d_ids_dst, bc.h_ids_dst, ids_bytes, cudaMemcpyHostToDevice, st) != cudaSuccess) return fail_after_current_down_overlap();

    dim3 block(256);
    dim3 grid((unsigned int)((ne01 + block.x - 1) / block.x), (unsigned int)n_active);
    moe_stream_up_gate_fuse_kernel<<<grid, block, 0, st>>>(
        (const float *)bc.d_up, (const float *)bc.d_gate, fused_d,
        bc.d_ids_dst, n_active, ne01, unary_op, limit, true);
    if (cudaGetLastError() != cudaSuccess) return fail_after_current_down_overlap();
    if (profile) cudaEventRecord(bc.ev_kernel, st);

    if (use_handoff) {
        const char *handoff_sync_env = std::getenv("GGML_MOE_GPU_HANDOFF_SYNC");
        const bool sync_handoff = profile ||
            (handoff_sync_env && handoff_sync_env[0] && handoff_sync_env[0] != '0');
        if (sync_handoff && cudaStreamSynchronize(st) != cudaSuccess) return fail_after_current_down_overlap();
        g_handoff.host_ptr = dst;
        g_handoff.d_data = fused_d;
        g_handoff.bytes = dst_bytes;
        g_handoff.ne01 = ne01;
        g_handoff.dst_cols = dst_cols;
        ++g_handoff.serial;
        if (profile) {
            float stage_ms = 0.0f;
            float quant_ms = 0.0f;
            float up_ms = 0.0f;
            float gate_ms = 0.0f;
            float up_wait_ms = 0.0f;
            float gate_wait_ms = 0.0f;
            float up_compute_ms = 0.0f;
            float gate_compute_ms = 0.0f;
            float fuse_ms = 0.0f;
            float kernel_ms = 0.0f;
            cudaEventElapsedTime(&stage_ms, bc.ev_start, bc.ev_stage);
            cudaEventElapsedTime(&quant_ms, bc.ev_stage, bc.ev_quant);
            if (parallel_up_gate && bc.ev_up_start && bc.ev_gate_start) {
                cudaEventElapsedTime(&up_ms, bc.ev_up_start, bc.ev_up);
                cudaEventElapsedTime(&gate_ms, bc.ev_gate_start, bc.ev_gate);
                if (parallel_stage && bc.ev_gate_work_start && bc.ev_up_compute_start && bc.ev_gate_compute_start) {
                    cudaEventElapsedTime(&up_wait_ms, bc.ev_up_start, bc.ev_up_compute_start);
                    cudaEventElapsedTime(&gate_wait_ms, bc.ev_gate_work_start, bc.ev_gate_compute_start);
                    cudaEventElapsedTime(&up_compute_ms, bc.ev_up_compute_start, bc.ev_up);
                    cudaEventElapsedTime(&gate_compute_ms, bc.ev_gate_compute_start, bc.ev_gate);
                }
            } else {
                cudaEventElapsedTime(&up_ms, bc.ev_quant, bc.ev_up);
                cudaEventElapsedTime(&gate_ms, bc.ev_up, bc.ev_gate);
            }
            cudaEventElapsedTime(&fuse_ms, bc.ev_gate, bc.ev_kernel);
            cudaEventElapsedTime(&kernel_ms, bc.ev_quant, bc.ev_kernel);
            up_gate_profile_add(
                g_uprof,
                (uint64_t)n_active,
                (uint64_t)up_stage_jobs_count,
                (uint64_t)gate_stage_jobs_count,
                stage_ms,
                quant_ms,
                up_ms,
                gate_ms,
                up_wait_ms,
                gate_wait_ms,
                up_compute_ms,
                gate_compute_ms,
                fuse_ms,
                kernel_ms,
                0.0,
                0.0,
                0.0);
            up_gate_type_profile_add(
                prompt_mode,
                src0_type,
                gate_type,
                (uint64_t)n_active,
                (uint64_t)up_stage_jobs_count,
                (uint64_t)gate_stage_jobs_count,
                stage_ms,
                quant_ms,
                up_ms,
                gate_ms,
                up_wait_ms,
                gate_wait_ms,
                up_compute_ms,
                gate_compute_ms,
                fuse_ms,
                kernel_ms,
                0.0,
                0.0,
                0.0);
            up_gate_layer_profile_add(
                prompt_mode,
                up_key_name,
                gate_key_name,
                src0_type,
                gate_type,
                (uint64_t)n_active,
                (uint64_t)up_stage_jobs_count,
                (uint64_t)gate_stage_jobs_count,
                stage_ms,
                quant_ms,
                up_ms,
                gate_ms,
                up_wait_ms,
                gate_wait_ms,
                up_compute_ms,
                gate_compute_ms,
                fuse_ms,
                kernel_ms,
                0.0,
                0.0,
                0.0);
            up_gate_profile_csv_record(
                prompt_mode,
                up_key_name,
                gate_key_name,
                src0_type,
                gate_type,
                n_active,
                n_active - up_stage_jobs_count,
                up_stage_jobs_count,
                n_active - gate_stage_jobs_count,
                gate_stage_jobs_count,
                up_stage_jobs_count,
                gate_stage_jobs_count,
                stage_ms,
                quant_ms,
                up_ms,
                gate_ms,
                up_wait_ms,
                gate_wait_ms,
                up_compute_ms,
                gate_compute_ms,
                fuse_ms,
                kernel_ms,
                0.0,
                0.0,
                0.0,
                use_handoff,
                parallel_up_gate,
                parallel_stage);
        }
        (void)join_current_down_overlap();
        return true;
    }

    if (!g_expert_pack.glm52_colibri) {
        if (cudaMemcpyAsync(bc.h_dst, bc.d_dst, dst_bytes, cudaMemcpyDeviceToHost, st) != cudaSuccess) return fail_after_current_down_overlap();
        if (profile) cudaEventRecord(bc.ev_d2h, st);
    }
    if (cudaStreamSynchronize(st) != cudaSuccess) return fail_after_current_down_overlap();

    if (point_dump && point_active >= 0 && point_active < n_active && point_col >= 0 && point_col < ne01) {
        const float *point_tmp = (const float *)bc.h_dst;
        const float fused_active = point_tmp[(size_t)point_active * (size_t)ne01 + (size_t)point_col];
        const float fused_flat = point_flat >= 0 && point_flat < dst_cols ?
            point_tmp[(size_t)point_flat * (size_t)ne01 + (size_t)point_col] : 0.0f;
        std::fprintf(stderr,
            "[moe_stream] up/gate point fused: tensor=%s active=%d active_expert=%d active_token=%d active_dst=%d active_flat=%d flat=%d col=%d fused_active=%g fused_flat=%g prompt_mode=%d\n",
            src0_up_name, point_active,
            active_experts[point_active], token_ids[point_active], dst_ids[point_active], flat_dst_ids[point_active],
            point_flat, point_col, fused_active, fused_flat, prompt_mode ? 1 : 0);
    }

    float stage_ms = 0.0f;
    float quant_ms = 0.0f;
    float up_ms = 0.0f;
    float gate_ms = 0.0f;
    float up_wait_ms = 0.0f;
    float gate_wait_ms = 0.0f;
    float up_compute_ms = 0.0f;
    float gate_compute_ms = 0.0f;
    float fuse_ms = 0.0f;
    float kernel_ms = 0.0f;
    float d2h_ms = 0.0f;
    if (profile) {
        cudaEventElapsedTime(&stage_ms, bc.ev_start, bc.ev_stage);
        cudaEventElapsedTime(&quant_ms, bc.ev_stage, bc.ev_quant);
        if (parallel_up_gate && bc.ev_up_start && bc.ev_gate_start) {
            cudaEventElapsedTime(&up_ms, bc.ev_up_start, bc.ev_up);
            cudaEventElapsedTime(&gate_ms, bc.ev_gate_start, bc.ev_gate);
            if (parallel_stage && bc.ev_gate_work_start && bc.ev_up_compute_start && bc.ev_gate_compute_start) {
                cudaEventElapsedTime(&up_wait_ms, bc.ev_up_start, bc.ev_up_compute_start);
                cudaEventElapsedTime(&gate_wait_ms, bc.ev_gate_work_start, bc.ev_gate_compute_start);
                cudaEventElapsedTime(&up_compute_ms, bc.ev_up_compute_start, bc.ev_up);
                cudaEventElapsedTime(&gate_compute_ms, bc.ev_gate_compute_start, bc.ev_gate);
            }
        } else {
            cudaEventElapsedTime(&up_ms, bc.ev_quant, bc.ev_up);
            cudaEventElapsedTime(&gate_ms, bc.ev_up, bc.ev_gate);
        }
        cudaEventElapsedTime(&fuse_ms, bc.ev_gate, bc.ev_kernel);
        cudaEventElapsedTime(&kernel_ms, bc.ev_quant, bc.ev_kernel);
        cudaEventElapsedTime(&d2h_ms, bc.ev_kernel, bc.ev_d2h);
    }

    const float *tmp = (const float *)bc.h_dst;
    const auto scatter_start = std::chrono::steady_clock::now();
    for (int j = 0; j < n_active; ++j) {
        float *dst_row = (float *)((char *)dst + (size_t)dst_ids[j] * dst_nb1 + (size_t)token_ids[j] * dst_nb2);
        const int32_t src_row = prompt_mode ? j : flat_dst_ids[j];
        if (g_expert_pack.glm52_colibri) {
            const float *device_src_row = (const float *)bc.d_dst + (size_t)src_row * ne01;
            if (cudaMemcpyAsync(dst_row, device_src_row, (size_t)ne01 * sizeof(float), cudaMemcpyDeviceToDevice, st) != cudaSuccess) {
                return fail_after_current_down_overlap();
            }
        } else {
            std::memcpy(dst_row, tmp + (size_t)src_row * ne01, (size_t)ne01 * sizeof(float));
        }
    }
    if (g_expert_pack.glm52_colibri && cudaStreamSynchronize(st) != cudaSuccess) return fail_after_current_down_overlap();
    if (profile) {
        const auto scatter_end = std::chrono::steady_clock::now();
        const double scatter_ms = std::chrono::duration<double, std::milli>(scatter_end - scatter_start).count();
        const double wall_ms = std::chrono::duration<double, std::milli>(scatter_end - wall_start).count();
        up_gate_profile_add(
            g_uprof,
            (uint64_t)n_active,
            (uint64_t)up_stage_jobs_count,
            (uint64_t)gate_stage_jobs_count,
            stage_ms,
            quant_ms,
            up_ms,
            gate_ms,
            up_wait_ms,
            gate_wait_ms,
            up_compute_ms,
            gate_compute_ms,
            fuse_ms,
            kernel_ms,
            d2h_ms,
            scatter_ms,
            wall_ms);
        up_gate_type_profile_add(
            prompt_mode,
            src0_type,
            gate_type,
            (uint64_t)n_active,
            (uint64_t)up_stage_jobs_count,
            (uint64_t)gate_stage_jobs_count,
            stage_ms,
            quant_ms,
            up_ms,
            gate_ms,
            up_wait_ms,
            gate_wait_ms,
            up_compute_ms,
            gate_compute_ms,
            fuse_ms,
            kernel_ms,
            d2h_ms,
            scatter_ms,
            wall_ms);
        up_gate_layer_profile_add(
            prompt_mode,
            up_key_name,
            gate_key_name,
            src0_type,
            gate_type,
            (uint64_t)n_active,
            (uint64_t)up_stage_jobs_count,
            (uint64_t)gate_stage_jobs_count,
            stage_ms,
            quant_ms,
            up_ms,
            gate_ms,
            up_wait_ms,
            gate_wait_ms,
            up_compute_ms,
            gate_compute_ms,
            fuse_ms,
            kernel_ms,
            d2h_ms,
            scatter_ms,
            wall_ms);
        up_gate_profile_csv_record(
            prompt_mode,
            up_key_name,
            gate_key_name,
            src0_type,
            gate_type,
            n_active,
            n_active - up_stage_jobs_count,
            up_stage_jobs_count,
            n_active - gate_stage_jobs_count,
            gate_stage_jobs_count,
            up_stage_jobs_count,
            gate_stage_jobs_count,
            stage_ms,
            quant_ms,
            up_ms,
            gate_ms,
            up_wait_ms,
            gate_wait_ms,
            up_compute_ms,
            gate_compute_ms,
            fuse_ms,
            kernel_ms,
            d2h_ms,
            scatter_ms,
            wall_ms,
            use_handoff,
            parallel_up_gate,
            parallel_stage);
    }
    (void)join_current_down_overlap();
    batch_prompt_mmap_dontneed(
            src0_up_data, (size_t)(n_as - 1) * up_nb02 + up_expert_bytes, rows_stride > 1);
    batch_prompt_mmap_dontneed(
            src0_gate_data, (size_t)(n_as - 1) * gate_nb02 + gate_expert_bytes, rows_stride > 1);
    return true;
}

extern "C" bool ggml_cuda_moe_stream_batch(
    int  src0_type_int,
    const char *src0_name,
    const void *src0_data,
    int64_t n_as,
    int64_t ne01,
    int64_t ne00,
    size_t nb01,
    size_t nb02,
    const float *src1_f32,
    int64_t src1_ne1,
    size_t src1_nb1, size_t src1_nb2,
    const void *src1_q8_0,
    size_t src1_q8_0_row_size,
    int64_t src1_q8_0_ne1,
    float *dst,
    size_t dst_nb1, size_t dst_nb2,
    const int64_t *matrix_row_counts,
    const ggml_moe_row_mapping *matrix_rows,
    int64_t rows_stride) {
    char nvtx_label[192];
    std::snprintf(nvtx_label, sizeof(nvtx_label),
            "down_compute tensor=%s n_as=%ld ne00=%ld ne01=%ld bytes=%zu",
            src0_name ? src0_name : "", (long)n_as, (long)ne00, (long)ne01, (size_t)ne01 * nb01);
    moe_nvtx_range nvtx_scope(nvtx_label);
    ggml_type src0_type = (ggml_type)src0_type_int;
    const bool decline_debug = []() {
        const char *env = std::getenv("GGML_MOE_STREAM_DECLINE_DEBUG");
        return env && env[0] && env[0] != '0';
    }();
    int active_experts[MOE_STREAM_MAX_ACTIVE];
    int32_t dst_ids[MOE_STREAM_MAX_ACTIVE];
    int32_t token_ids[MOE_STREAM_MAX_ACTIVE];
    int n_active = 0;
    int max_dst_id = -1;
    bool cross_role_call = common_cross_role_expected_tensor(src0_name);
    auto decline = [&](const char *reason) -> bool {
        if (cross_role_call) common_cross_role_fail(reason);
        if (decline_debug) {
            std::fprintf(stderr,
                "[moe_stream_batch] down batch declined: reason=%s tensor=%s rows_stride=%ld type=%d active=%d ne01=%ld ne00=%ld\n",
                reason, src0_name ? src0_name : "", (long)rows_stride, src0_type_int,
                n_active, (long)ne01, (long)ne00);
        }
        return false;
    };
    if (!init_batch_once()) return decline("init_batch_once");
    const bool prompt_multirow = rows_stride > 8;
    const char *prompt_matmul_env = std::getenv("GGML_MOE_PROMPT_MATMUL_ID_BATCH");
    const char *prompt_matmul_roles = std::getenv("GGML_MOE_PROMPT_MATMUL_ID_BATCH_ROLES");
    const bool is_prompt_up = src0_name && std::strstr(src0_name, "ffn_up_exps");
    const bool is_prompt_gate = src0_name && std::strstr(src0_name, "ffn_gate_exps");
    const bool is_down = src0_name && std::strstr(src0_name, "ffn_down_exps");
    const bool prompt_matmul_role_allowed =
        !prompt_matmul_roles || !prompt_matmul_roles[0] ||
        std::strcmp(prompt_matmul_roles, "all") == 0 ||
        (is_prompt_up && std::strstr(prompt_matmul_roles, "up")) ||
        (is_prompt_gate && std::strstr(prompt_matmul_roles, "gate"));
    const bool prompt_matmul_id =
        prompt_multirow &&
        prompt_matmul_env && prompt_matmul_env[0] && prompt_matmul_env[0] != '0' &&
        prompt_matmul_role_allowed &&
        (is_prompt_up || is_prompt_gate);
    const bool q4_parity_candidate = q4_down_parity_candidate(src0_name, src0_type);
    const bool q4_route_profile_candidate = q4_down_route_profile_candidate(src0_name, src0_type);
    const bool q4_batch_candidate = q4_down_batch_candidate(src0_name, src0_type);
    const bool is_mxfp4_type = src0_type == GGML_TYPE_MXFP4;
    const bool is_lowbit_probe_type =
        src0_type == GGML_TYPE_IQ2_XS || src0_type == GGML_TYPE_IQ1_S ||
        src0_type == GGML_TYPE_IQ1_M || src0_type == GGML_TYPE_Q2_K;
    const bool mxfp4_probe_candidate = is_mxfp4_type && mxfp4_down_probe_candidate(src0_name, src0_type);
    const bool mxfp4_q80_compat_candidate = is_mxfp4_type && mxfp4_down_q80_compat_candidate(src0_name, src0_type);
    const bool lowbit_probe_candidate = is_lowbit_probe_type && lowbit_down_probe_candidate(src0_name, src0_type);
    if (!src0_name || (!is_down && !prompt_matmul_id && !mxfp4_q80_compat_candidate)) {
        return decline("not_down_tensor");
    }
    if (src0_type == GGML_TYPE_MXFP4 && mxfp4_down_q80_debug_enabled()) {
        static std::atomic<int> q80_candidate_debug_count{0};
        const int dbg = q80_candidate_debug_count.fetch_add(1);
        if (dbg < 64) {
            const char *env = std::getenv("GGML_MOE_STREAM_DOWN_Q80_COMPAT_BATCH");
            const char *target = std::getenv("GGML_MOE_STREAM_DOWN_Q80_COMPAT_TENSOR");
            std::fprintf(stderr,
                    "[moe_stream_batch] q80_candidate_debug idx=%d tensor=%s type=%d env=%s target=%s candidate=%d\n",
                    dbg, src0_name ? src0_name : "", src0_type_int,
                    env ? env : "", target ? target : "", mxfp4_q80_compat_candidate ? 1 : 0);
        }
    }
    if (!moe_stream_type_supported(src0_type) && !q4_parity_candidate && !q4_route_profile_candidate && !q4_batch_candidate && !mxfp4_probe_candidate && !mxfp4_q80_compat_candidate && !lowbit_probe_candidate) return decline("unsupported_type");
    if (mxfp4_down_q80_compat_forces_mxfp4(src0_name, src0_type) && !mxfp4_q80_compat_candidate) return decline("q80_not_target");
    if (!src1_f32) return decline("missing_src1");
    if (mxfp4_q80_compat_candidate && (!src1_q8_0 || src1_q8_0_row_size == 0 || src1_q8_0_ne1 <= 0)) return decline("missing_src1_q8_0");
    ggml_cuda_moe_stream_register_tensor(src0_type_int, src0_name, src0_data, n_as, nb02, (size_t)ne01 * nb01);

    if (prompt_multirow && !prompt_matmul_id && !prompt_down_batch_enabled()) {
        return decline("prompt_multirow_disabled");
    }
    if (prompt_multirow && !prompt_matmul_id && !prompt_down_batch_type_allowed(src0_type)) {
        return decline("prompt_type_disabled");
    }

    for (int64_t e = 0; e < n_as; ++e) {
        if (matrix_row_counts[e] <= 0) {
            continue;
        }
        const ggml_moe_row_mapping * r = matrix_rows + e*rows_stride;
        for (int64_t row = 0; row < matrix_row_counts[e]; ++row) {
            if (n_active >= MOE_STREAM_MAX_ACTIVE) return decline("too_many_active_routes");
            active_experts[n_active] = (int)e;
            dst_ids[n_active] = r[row].i1;
            token_ids[n_active] = r[row].i2;
            if (dst_ids[n_active] < 0 || token_ids[n_active] < 0) return decline("bad_route_row");
            if (dst_ids[n_active] > max_dst_id) max_dst_id = dst_ids[n_active];
            ++n_active;
        }
    }
    if (n_active <= 0 || max_dst_id < 0) return decline("no_active_routes");
    const int min_active = down_batch_min_active();
    if (min_active > 0 && n_active < min_active) return decline("down_min_active");
    static std::atomic<int> q4_route_profile_calls{0};
    if (q4_route_profile_candidate) {
        const int q4_route_call = q4_route_profile_calls.fetch_add(1, std::memory_order_relaxed);
        q4_down_route_profile_record(
                src0_name, q4_route_call, active_experts, dst_ids, token_ids,
                n_active, ne01, ne00);
        if (q4_route_call == 0) {
            std::fprintf(stderr,
                    "[moe_stream_batch] q4_down_route_profile active tensor=%s active=%d ne01=%ld ne00=%ld\n",
                    src0_name ? src0_name : "", n_active, (long)ne01, (long)ne00);
        }
        return false;
    }
    bool q4_parity_run = false;
    int q4_parity_call = -1;
    if (q4_parity_candidate) {
        if (q4_down_parity_once_per_tensor()) {
            std::lock_guard<std::mutex> q4_lk(g_q4_down_parity_seen_mu);
            if (g_q4_down_parity_seen_tensors.find(src0_name) != g_q4_down_parity_seen_tensors.end()) {
                return decline("q4_parity_seen_tensor");
            }
            g_q4_down_parity_seen_tensors.insert(src0_name);
        }
        q4_parity_call = g_q4_down_parity_calls.fetch_add(1, std::memory_order_relaxed);
        if (q4_parity_call >= q4_down_parity_max_calls()) return decline("q4_parity_limit");
        q4_parity_run = true;
        std::fprintf(stderr,
                "[moe_stream_batch] q4_down_parity active tensor=%s call=%d active=%d ne01=%ld ne00=%ld\n",
                src0_name ? src0_name : "", q4_parity_call, n_active, (long)ne01, (long)ne00);
    }
    bool mxfp4_probe_run = false;
    int mxfp4_probe_call = -1;
    if (mxfp4_probe_candidate) {
        static std::atomic<int> first_mxfp4_down_probe{0};
        if (first_mxfp4_down_probe.fetch_add(1, std::memory_order_relaxed) == 0) {
            std::fprintf(stderr, "[moe_stream_batch] MXFP4 down batch probe active mode=%s\n",
                    mxfp4_down_probe_mode() ? mxfp4_down_probe_mode() : "");
        }
        mxfp4_probe_call = g_mxfp4_down_probe_calls.fetch_add(1, std::memory_order_relaxed);
        if (mxfp4_probe_call >= mxfp4_down_probe_max_calls()) return decline("mxfp4_probe_limit");
        if (mxfp4_down_probe_parity_mode()) {
            mxfp4_probe_run = true;
        }
        std::fprintf(stderr,
                "[moe_stream_batch] mxfp4_down_probe active tensor=%s call=%d active=%d ne01=%ld ne00=%ld\n",
                src0_name ? src0_name : "", mxfp4_probe_call, n_active, (long)ne01, (long)ne00);
    }
    if (mxfp4_q80_compat_candidate && mxfp4_down_q80_debug_enabled()) {
        std::fprintf(stderr,
                "[moe_stream_batch] q80_debug candidate tensor=%s active=%d ne01=%ld ne00=%ld "
                "row_size=%zu ne1=%ld rows_stride=%ld\n",
                src0_name ? src0_name : "", n_active, (long)ne01, (long)ne00,
                src1_q8_0_row_size, (long)src1_q8_0_ne1, (long)rows_stride);
        for (int j = 0; j < n_active && j < 16; ++j) {
            std::fprintf(stderr,
                    "[moe_stream_batch] q80_debug route j=%d expert=%d dst_id=%d token_id=%d\n",
                    j, active_experts[j], (int)dst_ids[j], (int)token_ids[j]);
        }
    }

    static std::atomic<int> first_batch{0};
    const int batch_call = first_batch.fetch_add(1);
    static std::atomic<int> first_q4_down_batch{0};
    if (q4_batch_candidate && first_q4_down_batch.fetch_add(1) == 0) {
        std::fprintf(stderr,
                "[moe_stream_batch] Q4_0 down batch candidate active tensor=%s active=%d ne01=%ld ne00=%ld\n",
                src0_name ? src0_name : "", n_active, (long)ne01, (long)ne00);
    }
    const char *trace_env = std::getenv("GGML_MOE_BATCH_TRACE");
    if (batch_call == 0) {
        std::fprintf(stderr, "[moe_stream] batched decode path active: experts=%d ne01=%ld ne00=%ld\n",
                     n_active, (long)ne01, (long)ne00);
    }
    if (trace_env && trace_env[0] && trace_env[0] != '0' && batch_call < 64) {
        std::fprintf(stderr, "[moe_stream_batch] trace call=%d tensor=%s experts=%d ne01=%ld ne00=%ld\n",
                     batch_call, src0_name ? src0_name : "(null)", n_active, (long)ne01, (long)ne00);
    }
    const char *batch_mode = rows_stride > 8 ? "prompt" : "decode";
    const char *batch_kind = is_prompt_up ? "up" : (is_prompt_gate ? "gate" : (is_down ? "down" : ""));
    batch_route_detail_record(
        batch_mode,
        (uint64_t)batch_call,
        src0_name,
        src0_type_int,
        active_experts,
        dst_ids,
        nullptr,
        token_ids,
        n_active,
        (size_t)ne01 * nb01,
        ne01,
        ne00);

    std::lock_guard<std::mutex> lk(g_batch_mu);
    batch_ctx &bc = g_batch;
    cudaStream_t st = bc.stream;
    if (down_prefetch_enabled() && bc.prefetch_stream) {
        cudaStreamSynchronize(bc.prefetch_stream);
    }
    const bool profile = g_bprof.enabled && bc.ev_start && bc.ev_stage && bc.ev_quant && bc.ev_kernel && bc.ev_d2h;
    const auto wall_start = profile ? std::chrono::steady_clock::now() : std::chrono::steady_clock::time_point{};
    const char *down_parallel_stage_env = std::getenv("GGML_MOE_DOWN_PARALLEL_STAGE");
    const bool down_parallel_stage =
        down_parallel_stage_env && down_parallel_stage_env[0] && down_parallel_stage_env[0] != '0' &&
        bc.up_stream && bc.gate_stream && bc.ev_stage_ready && bc.ev_up_done && bc.ev_gate_done;
    const bool down_stage_single_ring = down_parallel_stage &&
        expert_pack_env_bool("GGML_MOE_DOWN_STAGE_SINGLE_RING", false);
    static std::atomic<int> first_down_parallel_stage{0};
    if (down_parallel_stage && first_down_parallel_stage.fetch_add(1) == 0) {
        std::fprintf(stderr, "[moe_stream_batch] down parallel CPU staging active\n");
    }
    static std::atomic<int> first_down_stage_single_ring{0};
    if (down_stage_single_ring && first_down_stage_single_ring.fetch_add(1) == 0) {
        std::fprintf(stderr, "[moe_stream_batch] down single-ring staging probe active\n");
    }

    const size_t src0_bytes = (size_t)ne01 * nb01;
    const size_t src0_all_bytes = (size_t)n_active * src0_bytes;
    batch_ttft_call_scope ttft_scope("call_down", src0_name, n_active, src0_bytes);
    const size_t src1_f32_bytes = (size_t)n_active * ne00 * sizeof(float);
    const size_t src1_q8_bytes = (size_t)n_active * moe_stream_q8_1_row_bytes(ne00);
    const size_t src1_q80_bytes = mxfp4_q80_compat_candidate ? (size_t)n_active * src1_q8_0_row_size : 0;
    const size_t src1_q8_alloc_bytes = std::max(src1_q8_bytes, src1_q80_bytes);
    const char *down_q8k_env = std::getenv("GGML_MOE_STREAM_DOWN_Q8K");
    const char *down_q8k_types_env = std::getenv("GGML_MOE_STREAM_DOWN_Q8K_TYPES");
    const char *down_q8k_layer_range = std::getenv("GGML_MOE_STREAM_DOWN_Q8K_LAYER_RANGE");
    const bool down_q8k_type_allowed =
        !down_q8k_types_env || !down_q8k_types_env[0] ||
        std::strcmp(down_q8k_types_env, "all") == 0 ||
        (std::strcmp(down_q8k_types_env, "q3") == 0 && src0_type == GGML_TYPE_Q3_K) ||
        (std::strcmp(down_q8k_types_env, "iq4") == 0 && src0_type == GGML_TYPE_IQ4_XS);
    const bool down_q8k_candidate =
        down_q8k_env && down_q8k_env[0] && down_q8k_env[0] != '0' &&
        (src0_type == GGML_TYPE_Q3_K || src0_type == GGML_TYPE_IQ4_XS) &&
        down_q8k_type_allowed &&
        (!src0_name || std::strstr(src0_name, ".ffn_down_exps.") || std::strstr(src0_name, "ffn_down_exps")) &&
        moe_tensor_layer_in_simple_range(src0_name, down_q8k_layer_range);
    const int64_t dst_cols = std::max<int64_t>(max_dst_id + 1, n_active);
    const bool use_handoff =
        gpu_handoff_enabled() &&
        g_handoff.host_ptr == src1_f32 &&
        g_handoff.d_data &&
        g_handoff.ne01 == ne00 &&
        g_handoff.dst_cols >= dst_cols;
    const bool shadow_error = down_act_shadow_error_enabled();
    const bool mxfp4_f32_exact_candidate = mxfp4_probe_candidate && mxfp4_down_probe_f32_mode();
    const bool down_q8k_requested = down_q8k_candidate && !use_handoff;
    const size_t src1_q8k_bytes = down_q8k_requested ? (size_t)n_active * (ne00 / QK_K) * sizeof(block_q8_K) : 0;
    const int64_t dst_rows = down_q8k_requested ? dst_cols : n_active;
    const size_t dst_bytes = (size_t)dst_rows * ne01 * sizeof(float);
    const size_t ids_bytes = (size_t)n_active * sizeof(int32_t);
    const size_t bounds_bytes = (size_t)(n_active + 1) * sizeof(int32_t);

    int down_profile_cache_hits = 0;
    int down_profile_cache_misses = 0;
    const auto mxfp4_stage_trace_t0 = mxfp4_probe_candidate ?
        std::chrono::steady_clock::now() : std::chrono::steady_clock::time_point{};
    auto mxfp4_stage_elapsed_ms = [&]() -> double {
        if (!mxfp4_probe_candidate) return 0.0;
        return std::chrono::duration<double, std::milli>(
                std::chrono::steady_clock::now() - mxfp4_stage_trace_t0).count();
    };
    auto mxfp4_stage_trace = [&](const char *stage) {
        if (mxfp4_probe_candidate) {
            mxfp4_down_stage_trace_write(
                    src0_name, mxfp4_probe_call, stage, n_active, ne01, ne00,
                    src0_all_bytes, src1_f32_bytes, src1_q8_bytes, dst_bytes,
                    down_profile_cache_hits, down_profile_cache_misses,
                    use_handoff, down_q8k_requested, mxfp4_stage_elapsed_ms());
        }
    };
    mxfp4_stage_trace("sizes");
    const bool need_src0_all_stage = mxfp4_probe_candidate || mxfp4_q80_compat_candidate || lowbit_probe_candidate;

    bool ok = (!need_src0_all_stage || ensure_dev(bc.d_src0, bc.d_src0_sz, src0_all_bytes))
        && ((use_handoff && !shadow_error) || mxfp4_q80_compat_candidate || ensure_dev(bc.d_src1_f32, bc.d_src1_f32_sz, src1_f32_bytes))
        && ensure_dev(bc.d_src1_q8, bc.d_src1_q8_sz, src1_q8_alloc_bytes)
        && (!down_q8k_requested || ensure_dev(bc.d_src1_q8k, bc.d_src1_q8k_sz, src1_q8k_bytes))
        && ensure_dev(bc.d_dst, bc.d_dst_sz, dst_bytes)
        && ensure_dev((void *&)bc.d_ids_src1, bc.d_ids_src1_sz, ids_bytes)
        && ensure_dev((void *&)bc.d_ids_dst, bc.d_ids_dst_sz, ids_bytes)
        && ensure_dev((void *&)bc.d_x_ids, bc.d_x_ids_sz, ids_bytes)
        && ensure_dev((void *&)bc.d_bounds, bc.d_bounds_sz, bounds_bytes)
        && ((use_handoff && !shadow_error) || ensure_host_pinned(bc.h_src1, bc.h_src1_sz, std::max(src1_f32_bytes, src1_q80_bytes)))
        && ensure_host_pinned(bc.h_dst, bc.h_dst_sz, dst_bytes)
        && (!shadow_error || ensure_host_pinned(bc.h_src1_shadow, bc.h_src1_shadow_sz, src1_f32_bytes))
        && (!shadow_error || ensure_host_pinned(bc.h_dst_shadow, bc.h_dst_shadow_sz, dst_bytes));
    if (!ok) {
        mxfp4_stage_trace("ensure_buffers_fail");
        return decline("ensure_buffers");
    }
    mxfp4_stage_trace("ensure_buffers_ok");
    static std::atomic<int> first_down_q8k{0};
    if (down_q8k_requested && first_down_q8k.fetch_add(1) == 0) {
        std::fprintf(stderr, "[moe_stream_batch] down Q3_K/IQ4_XS Q8_K-reference batch path active\n");
    }

    batch_vram_cache *cache = batch_cache_get(src0_bytes);
    if (!cache) {
        mxfp4_stage_trace("cache_get_fail");
        return decline("cache_get");
    }
    mxfp4_stage_trace("cache_get_ok");
    q4_graph_record_down_candidate(rows_stride > 8, src0_name, cache, active_experts, n_active);
    updown_pair_profile_predict_down(src0_name, src0_bytes, cache, active_experts, n_active);
    const bool updown_paired_read = expert_pack_env_bool("GGML_MOE_UPDOWN_PAIRED_READ", false) &&
        src0_name && std::strstr(src0_name, ".ffn_up_exps.");
    char updown_paired_down_name[128] = {};
    const bool updown_paired_down_name_ok =
        updown_paired_read && down_name_for_up_gate(src0_name, updown_paired_down_name, sizeof(updown_paired_down_name));
    preload_profile_for_tensor(src0_name, src0_data, n_as, nb02, src0_bytes, st);
    expert_pack_v2_call_coverage_record(
        rows_stride > 8 ? "prompt_batch" : "decode_down",
        is_prompt_up ? "up" : (is_prompt_gate ? "gate" : "down"),
        src0_name,
        src0_type_int,
        src0_bytes,
        ne00,
        ne01,
        nb01,
        cache,
        active_experts,
        n_active);
    expert_pack_v2_override_preflight_record(
        rows_stride > 8 ? "prompt_batch" : "decode_down",
        is_prompt_up ? "up" : (is_prompt_gate ? "gate" : "down"),
        src0_name,
        src0_type_int,
        src0_bytes,
        ne00,
        ne01,
        nb01,
        cache,
        active_experts,
        n_active);
    expert_pack_v2_partial_split_plan_record(
        rows_stride > 8 ? "prompt_batch" : "decode_down",
        is_prompt_up ? "up" : (is_prompt_gate ? "gate" : "down"),
        src0_name,
        src0_type_int,
        src0_bytes,
        ne00,
        ne01,
        nb01,
        cache,
        active_experts,
        dst_ids,
        nullptr,
        n_active);
    expert_pack_v2_shadow_stage_record(
        rows_stride > 8 ? "prompt_batch" : "decode_down",
        is_prompt_up ? "up" : (is_prompt_gate ? "gate" : "down"),
        src0_name,
        src0_type_int,
        src0_bytes,
        ne00,
        ne01,
        nb01,
        cache,
        active_experts,
        n_active,
        st);

    if (profile) cudaEventRecord(bc.ev_start, st);

    const bool down_hit_only = down_batch_hit_only_enabled();
    const bool down_demand_prefill = down_hit_only && down_batch_demand_prefill_enabled();
    if (down_demand_prefill) {
        static std::unordered_map<uintptr_t, uint32_t> down_demand_seen;
        const int demand_min_seen = down_batch_demand_min_seen();
        const bool demand_queue = down_batch_demand_queue_enabled();
        int demand_prefills = 0;
        int demand_seen_skips = 0;
        cudaStream_t prefill_stream = bc.prefetch_stream ? bc.prefetch_stream : st;
        for (int j = 0; j < n_active; ++j) {
            const uintptr_t cache_key = batch_key_hash(src0_name, active_experts[j]);
            if (batch_cache_find_slot(cache, cache_key) >= 0) {
                continue;
            }
            uint32_t &seen = down_demand_seen[cache_key];
            if (seen != UINT32_MAX) {
                ++seen;
            }
            if ((int)seen < demand_min_seen) {
                ++demand_seen_skips;
                continue;
            }
            const char *expert_host = (const char *)src0_data + (size_t)active_experts[j] * nb02;
            if (demand_queue) {
                if (down_demand_prefill_enqueue(cache, cache_key, expert_host, src0_bytes,
                            src0_name, active_experts[j], prefill_stream)) {
                    ++demand_prefills;
                }
            } else {
                const int slot = batch_cache_insert_slot(cache, cache_key, expert_host, src0_bytes, prefill_stream,
                        true, true, nullptr, 0, true, src0_name, active_experts[j],
                        true, true, true);
                if (slot >= 0) {
                    ++demand_prefills;
                }
            }
        }
        if (demand_prefills > 0) {
            static std::atomic<int> first_demand_prefill{0};
            if (first_demand_prefill.fetch_add(1) == 0) {
                std::fprintf(stderr,
                        "[moe_stream_batch] down demand prefill active: tensor=%s prefills=%d active=%d min_seen=%d seen_skips=%d queue=%d\n",
                        src0_name ? src0_name : "", demand_prefills, n_active, demand_min_seen, demand_seen_skips,
                        demand_queue ? 1 : 0);
            }
            return decline(demand_queue ? "down_demand_prefill_queue" : "down_demand_prefill");
        }
    }

    bool v2_full_down_active = false;
    int v2_full_down_packed_type = -1;
    size_t v2_full_down_nbytes = 0;
    int64_t v2_full_down_nb01 = 0;
    char v2_full_down_cache_name[128] = {};
    const expert_pack_v2_entry *v2_full_down_entries[MOE_STREAM_MAX_ACTIVE] = {};
    int v2_full_down_slots[MOE_STREAM_MAX_ACTIVE];
    std::fill_n(v2_full_down_slots, MOE_STREAM_MAX_ACTIVE, -1);
    std::vector<char> v2_full_down_host;

    auto v2_full_down_profile_reject = [&](std::atomic<uint64_t> &counter, const char *reason) {
        counter.fetch_add(1, std::memory_order_relaxed);
        expert_pack_v2_full_cover_down_profile_record(
                "reject",
                reason,
                src0_name,
                src0_type_int,
                -1,
                n_active,
                src0_bytes,
                0,
                0,
                0,
                0,
                0,
                0,
                0,
                0,
                0);
    };

    if (expert_pack_v2_full_cover_down_enabled()) {
        expert_pack_v2_full_cover_down_state &v2_state = g_expert_pack_v2_full_cover_down;
        v2_state.calls.fetch_add(1, std::memory_order_relaxed);
        if (!v2_state.report_registered.exchange(true)) {
            std::atexit(expert_pack_v2_full_cover_down_report);
        }

        if (!(rows_stride <= 8 && is_down && !is_prompt_up && !is_prompt_gate)) {
            v2_full_down_profile_reject(v2_state.rejected_not_decode_down, "not_decode_down");
        } else if (down_hit_only || q4_parity_run || mxfp4_probe_run || mxfp4_q80_compat_candidate ||
                mxfp4_f32_exact_candidate || down_q8k_requested || shadow_error) {
            v2_full_down_profile_reject(v2_state.rejected_special_path, "special_path");
        } else {
            const int cache_name_len = std::snprintf(
                    v2_full_down_cache_name, sizeof(v2_full_down_cache_name),
                    "%s:v2full", src0_name ? src0_name : "");
            if (cache_name_len <= 0 || (size_t)cache_name_len >= sizeof(v2_full_down_cache_name)) {
                v2_full_down_profile_reject(v2_state.rejected_bad_cache_key, "bad_cache_key");
            } else {
                bool v2_plan_ok = true;
                const expert_pack_v2_entry *first_entry = nullptr;
                for (int j = 0; j < n_active; ++j) {
                    const int expert_idx = active_experts[j];
                    const expert_pack_v2_entry *entry = expert_pack_v2_lookup(src0_name, expert_idx);
                    if (!entry) {
                        v2_full_down_profile_reject(v2_state.rejected_no_entry, "no_entry");
                        v2_plan_ok = false;
                        break;
                    }
                    if (!expert_pack_v2_packed_type_supported(entry->packed_type)) {
                        v2_full_down_profile_reject(v2_state.rejected_unsupported, "unsupported_type");
                        v2_plan_ok = false;
                        break;
                    }
                    if (entry->ne00 != ne00 || entry->ne01 != ne01 || entry->nb01 == 0) {
                        v2_full_down_profile_reject(v2_state.rejected_shape, "shape_mismatch");
                        v2_plan_ok = false;
                        break;
                    }
                    if ((size_t)entry->nbytes == 0 || (size_t)entry->nbytes >= src0_bytes ||
                            (size_t)entry->nbytes > cache->slot_sz) {
                        v2_full_down_profile_reject(v2_state.rejected_not_smaller, "not_smaller");
                        v2_plan_ok = false;
                        break;
                    }
                    if (!first_entry) {
                        first_entry = entry;
                    } else if (entry->packed_type != first_entry->packed_type ||
                            entry->nbytes != first_entry->nbytes ||
                            entry->ne00 != first_entry->ne00 ||
                            entry->ne01 != first_entry->ne01 ||
                            entry->nb01 != first_entry->nb01) {
                        v2_full_down_profile_reject(v2_state.rejected_homogeneous, "not_homogeneous");
                        v2_plan_ok = false;
                        break;
                    }
                    v2_full_down_entries[j] = entry;
                }
                if (v2_plan_ok && first_entry) {
                    v2_full_down_active = true;
                    v2_full_down_packed_type = first_entry->packed_type;
                    v2_full_down_nbytes = (size_t)first_entry->nbytes;
                    v2_full_down_nb01 = first_entry->nb01;
                    if (!expert_pack_v2_full_cover_down_iouring_enabled()) {
                        v2_full_down_host.resize(v2_full_down_nbytes * (size_t)n_active);
                    }
                    v2_state.accepted_calls.fetch_add(1, std::memory_order_relaxed);
                    v2_state.saved_bytes.fetch_add(
                            (uint64_t)(src0_bytes - v2_full_down_nbytes) * (uint64_t)n_active,
                            std::memory_order_relaxed);
                }
            }
        }
    }

    struct down_stage_copy_job {
        int slot = -1;
        uintptr_t key = 0;
        uint64_t generation = 0;
        void *dst = nullptr;
        const void *host_data = nullptr;
        const expert_pack_entry *pack_entry = nullptr;
        int expert_idx = -1;
        char tensor[128] = {};
    };

    auto clear_down_stage_jobs = [&](const std::vector<down_stage_copy_job> &jobs) {
        for (const down_stage_copy_job &job : jobs) {
            batch_cache_clear_slot(cache, job.slot);
        }
    };

    auto copy_down_stage_jobs = [&](const std::vector<down_stage_copy_job> &jobs, cudaStream_t run_stream, pinned_stage_ring &ring) -> bool {
        if (cudaSetDevice(0) != cudaSuccess) return false;
        auto publish_jobs = [&]() {
            for (const down_stage_copy_job &job : jobs) {
                if (!batch_cache_publish_slot_ready(
                            cache, job.slot, job.key, job.generation,
                            src0_bytes, run_stream)) {
                    return false;
                }
            }
            return true;
        };
        if (g_expert_pack.lossless_standalone) {
            for (const down_stage_copy_job &job : jobs) {
                if (job.slot < 0 || job.slot >= cache->n_slots || job.key == 0 ||
                        job.generation == 0 || src0_bytes == 0 || !job.pack_entry ||
                        cache->slot_key[job.slot] != job.key ||
                        cache->slot_generation[job.slot] != job.generation ||
                        cache->slot_payload_bytes[job.slot] != src0_bytes ||
                        !cache->slot_filling[job.slot]) {
                    return false;
                }
                if (!q4_colibri_pipe_copy(
                        cache, job.slot, job.generation, job.key, job.dst,
                        job.pack_entry, src0_bytes, run_stream,
                        job.tensor, job.expert_idx)) {
                    return false;
                }
            }
            return true;
        }
        if (expert_pack_iouring_copy_jobs(jobs, src0_bytes, run_stream, ring, "runtime_load")) {
            return cudaGetLastError() == cudaSuccess && publish_jobs();
        }
        const std::vector<down_stage_copy_job> *fallback_jobs = &jobs;
        std::vector<down_stage_copy_job> partial_iouring_jobs;
        std::vector<down_stage_copy_job> partial_fallback_jobs;
        if (!jobs.empty() && g_expert_pack.io_backend == 2) {
            partial_iouring_jobs.reserve(jobs.size());
            partial_fallback_jobs.reserve(jobs.size());
            for (const down_stage_copy_job &job : jobs) {
                if (expert_pack_iouring_job_eligible(job, src0_bytes)) {
                    partial_iouring_jobs.push_back(job);
                } else {
                    partial_fallback_jobs.push_back(job);
                }
            }
            if (!partial_iouring_jobs.empty() && partial_iouring_jobs.size() < jobs.size() &&
                    expert_pack_iouring_copy_jobs(partial_iouring_jobs, src0_bytes, run_stream, ring, "runtime_load")) {
                if (cudaGetLastError() != cudaSuccess) return false;
                fallback_jobs = &partial_fallback_jobs;
            }
        }
        for (const down_stage_copy_job &job : *fallback_jobs) {
            batch_copy_trace copy_trace;
            const auto copy_start = batch_ttft_trace_enabled() ? std::chrono::steady_clock::now() : std::chrono::steady_clock::time_point{};
            if (!batch_cache_copy_h2d(ring, job.dst, job.host_data, src0_bytes, run_stream, job.pack_entry, &copy_trace,
                        "runtime_load", job.tensor, job.expert_idx)) {
                if (!job.pack_entry ||
                        !batch_cache_copy_h2d(ring, job.dst, job.host_data, src0_bytes, run_stream, nullptr, &copy_trace,
                            "runtime_load", job.tensor, job.expert_idx)) {
                    return false;
                }
            }
            if (cudaGetLastError() != cudaSuccess) {
                return false;
            }
            if (copy_start != std::chrono::steady_clock::time_point{}) {
                const auto copy_end = std::chrono::steady_clock::now();
                batch_ttft_trace_record(
                    "runtime_load",
                    job.tensor,
                    job.expert_idx,
                    src0_bytes,
                    false,
                    copy_trace.pack_hit,
                    copy_trace.ram_hit,
                    std::chrono::duration<double, std::milli>(copy_end - copy_start).count());
            }
        }
        return publish_jobs();
    };

    std::vector<down_stage_copy_job> down_jobs_a;
    std::vector<down_stage_copy_job> down_jobs_b;
    int v2_full_down_cache_hits = 0;
    int v2_full_down_cache_misses = 0;
    int v2_full_down_copied_entries = 0;
    uint64_t v2_full_down_copied_bytes = 0;
    uint64_t v2_full_down_read_us = 0;
    uint64_t v2_full_down_h2d_enqueue_us = 0;
    std::vector<expert_pack_v2_iouring_copy_job> v2_full_down_iouring_jobs;
    const auto v2_full_down_total_t0 = v2_full_down_active ?
        std::chrono::steady_clock::now() : std::chrono::steady_clock::time_point{};

    auto clear_v2_full_down_slots = [&]() {
        for (int j = 0; j < n_active; ++j) {
            if (v2_full_down_slots[j] >= 0) {
                batch_cache_clear_slot(cache, v2_full_down_slots[j]);
                v2_full_down_slots[j] = -1;
            }
        }
    };

    for (int j = 0; j < n_active; ++j) {
        const char *expert_host = (const char *)src0_data + (size_t)active_experts[j] * nb02;
        const char *cache_name = v2_full_down_active ? v2_full_down_cache_name : src0_name;
        const size_t cache_bytes = v2_full_down_active ? v2_full_down_nbytes : src0_bytes;
        const uintptr_t cache_key = batch_key_hash(cache_name, active_experts[j]);
        batch_route_profile_hit(src0_name, active_experts[j], src0_bytes);
        int cache_slot = batch_cache_lookup_slot(cache, cache_key);
        const bool cache_hit = cache_slot >= 0;
        expert_pack_v2_shadow_profile_record(
                "down", src0_name, active_experts[j], src0_type_int,
                src0_bytes,
                v2_full_down_active ?
                    (cache_hit ? "v2full_cache_hit" : "v2full_cache_miss") :
                    (cache_hit ? "cache_hit" : "cache_miss"));
        if (cache_slot < 0) {
            if (down_hit_only) {
                return decline("down_cache_miss_hit_only");
            }
            ++down_profile_cache_misses;
            if (v2_full_down_active) {
                ++v2_full_down_cache_misses;
                cache_slot = batch_cache_insert_slot(cache, cache_key, nullptr, cache_bytes, st, true, false,
                        nullptr, 0, false, cache_name, active_experts[j]);
                if (cache_slot < 0) {
                    g_expert_pack_v2_full_cover_down.insert_failures.fetch_add(1, std::memory_order_relaxed);
                    clear_v2_full_down_slots();
                    return decline("v2_full_cover_down_cache_insert");
                }
                v2_full_down_slots[j] = cache_slot;
                void *dst_slot = (char *)cache->pool + (size_t)cache_slot * cache->slot_sz;
                if (expert_pack_v2_full_cover_down_iouring_enabled()) {
                    expert_pack_v2_iouring_copy_job job;
                    job.slot = cache_slot;
                    job.dst = dst_slot;
                    job.entry = v2_full_down_entries[j];
                    job.expert_idx = active_experts[j];
                    std::snprintf(job.tensor, sizeof(job.tensor), "%s", cache_name);
                    std::snprintf(job.logical_tensor, sizeof(job.logical_tensor), "%s", src0_name ? src0_name : "");
                    v2_full_down_iouring_jobs.push_back(job);
                } else {
                    char *host_slot = v2_full_down_host.data() + (size_t)j * v2_full_down_nbytes;
                    const auto read_t0 = std::chrono::steady_clock::now();
                    const expert_pack_v2_shadow_read_result read_result =
                        expert_pack_v2_shadow_read_entry_to_host(
                                v2_full_down_entries[j], src0_name, active_experts[j],
                                host_slot, v2_full_down_nbytes);
                    const auto read_t1 = std::chrono::steady_clock::now();
                    v2_full_down_read_us += (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(read_t1 - read_t0).count();
                    if (!read_result.ok || read_result.nread != v2_full_down_nbytes) {
                        g_expert_pack_v2_full_cover_down.read_failures.fetch_add(1, std::memory_order_relaxed);
                        clear_v2_full_down_slots();
                        return decline("v2_full_cover_down_read");
                    }
                    const auto h2d_t0 = std::chrono::steady_clock::now();
                    if (cudaMemcpyAsync(dst_slot, host_slot, v2_full_down_nbytes, cudaMemcpyHostToDevice, st) != cudaSuccess) {
                        g_expert_pack_v2_full_cover_down.h2d_failures.fetch_add(1, std::memory_order_relaxed);
                        clear_v2_full_down_slots();
                        return decline("v2_full_cover_down_h2d");
                    }
                    const auto h2d_t1 = std::chrono::steady_clock::now();
                    v2_full_down_h2d_enqueue_us += (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(h2d_t1 - h2d_t0).count();
                    ++v2_full_down_copied_entries;
                    v2_full_down_copied_bytes += (uint64_t)v2_full_down_nbytes;
                }
            } else {
                cache_slot = batch_cache_insert_slot(cache, cache_key, expert_host, src0_bytes, st, true, false,
                        nullptr, 0, !down_parallel_stage, src0_name, active_experts[j]);
            }
            if (!v2_full_down_active && down_parallel_stage && cache_slot >= 0) {
                const expert_pack_entry *pack_entry = expert_pack_lookup(src0_name, active_experts[j], src0_bytes);
                void *dst_slot = (char *)cache->pool + (size_t)cache_slot * cache->slot_sz;
                down_stage_copy_job job;
                job.slot = cache_slot;
                job.key = cache_key;
                job.generation = cache->slot_generation[cache_slot];
                job.dst = dst_slot;
                job.host_data = expert_host;
                job.pack_entry = pack_entry;
                job.expert_idx = active_experts[j];
                std::snprintf(job.tensor, sizeof(job.tensor), "%s", src0_name ? src0_name : "");
                cache->slot_filling[cache_slot] = true;
                if (down_stage_single_ring) {
                    down_jobs_a.push_back(job);
                } else if ((int)(down_jobs_a.size() + down_jobs_b.size()) & 1) {
                    down_jobs_b.push_back(job);
                } else {
                    down_jobs_a.push_back(job);
                }
            }
        } else {
            ++down_profile_cache_hits;
            if (v2_full_down_active) {
                ++v2_full_down_cache_hits;
            }
            batch_ttft_trace_record("cache_hit", src0_name, active_experts[j], src0_bytes, true, false, false, 0.0);
        }
        if (cache_slot < 0) return decline("cache_insert");
        bc.h_x_ids[j] = cache_slot;

        const int32_t src1_id = src1_ne1 > 0 ? (int32_t)(dst_ids[j] % src1_ne1) : dst_ids[j];
        const char *src1_base = (const char *)src1_f32;
        const char *src_row = src1_base + (size_t)src1_id * src1_nb1 + (size_t)token_ids[j] * src1_nb2;
        if (!mxfp4_q80_compat_candidate) {
            if (down_act_sparsity_profile_enabled()) {
                down_act_sparsity_profile_record(
                        (uint64_t)batch_call,
                        src0_name,
                        src0_type,
                        j,
                        active_experts[j],
                        dst_ids[j],
                        token_ids[j],
                        (const float *)src_row,
                        ne00);
            }
            moe_activation_dump_record(
                    batch_kind,
                    batch_mode,
                    (uint64_t)batch_call,
                    src0_name,
                    src0_type_int,
                    active_experts[j],
                    j,
                    dst_ids[j],
                    token_ids[j],
                    ne00,
                    ne01,
                    src0_bytes,
                    (const float *)src_row);
        }
        if (mxfp4_q80_compat_candidate) {
            const int64_t q80_i11 = ((int64_t)dst_ids[j] % src1_q8_0_ne1 + src1_q8_0_ne1) % src1_q8_0_ne1;
            const int64_t q80_i12 = (int64_t)token_ids[j];
            if (q80_i12 < 0) return decline("bad_q80_row");
            if (q80_i12 * src1_q8_0_ne1 + q80_i11 >= rows_stride) return decline("q80_row_oob");
            const char *q80_row = (const char *)src1_q8_0 + (size_t)(q80_i11 + q80_i12 * src1_q8_0_ne1) * src1_q8_0_row_size;
            std::memcpy((char *)bc.h_src1 + (size_t)j * src1_q8_0_row_size, q80_row, src1_q8_0_row_size);
        } else if (!use_handoff || shadow_error) {
            std::memcpy((char *)bc.h_src1 + (size_t)j * ne00 * sizeof(float), src_row, (size_t)ne00 * sizeof(float));
        }
        bc.h_ids_src1[j] = j;
        bc.h_ids_dst[j] = dst_ids[j];
        bc.h_bounds[j] = j;
    }
    if (v2_full_down_active && !v2_full_down_iouring_jobs.empty()) {
        uint64_t local_read_us = 0;
        uint64_t local_h2d_enqueue_us = 0;
        if (!expert_pack_v2_iouring_copy_jobs(
                    v2_full_down_iouring_jobs,
                    v2_full_down_nbytes,
                    st,
                    bc.stage_ring,
                    "v2_full_cover_down",
                    &local_read_us,
                    &local_h2d_enqueue_us)) {
            g_expert_pack_v2_full_cover_down.read_failures.fetch_add(1, std::memory_order_relaxed);
            clear_v2_full_down_slots();
            return decline("v2_full_cover_down_iouring");
        }
        v2_full_down_read_us += local_read_us;
        v2_full_down_h2d_enqueue_us += local_h2d_enqueue_us;
        v2_full_down_copied_entries += (int)v2_full_down_iouring_jobs.size();
        v2_full_down_copied_bytes += (uint64_t)v2_full_down_nbytes * (uint64_t)v2_full_down_iouring_jobs.size();
    }
    if (v2_full_down_active) {
        const auto v2_full_down_total_t1 = std::chrono::steady_clock::now();
        const uint64_t v2_full_down_total_us =
            (uint64_t)std::chrono::duration_cast<std::chrono::microseconds>(
                    v2_full_down_total_t1 - v2_full_down_total_t0).count();
        expert_pack_v2_full_cover_down_state &v2_state = g_expert_pack_v2_full_cover_down;
        v2_state.cache_hits.fetch_add((uint64_t)v2_full_down_cache_hits, std::memory_order_relaxed);
        v2_state.cache_misses.fetch_add((uint64_t)v2_full_down_cache_misses, std::memory_order_relaxed);
        v2_state.copied_entries.fetch_add((uint64_t)v2_full_down_copied_entries, std::memory_order_relaxed);
        v2_state.copied_bytes.fetch_add(v2_full_down_copied_bytes, std::memory_order_relaxed);
        v2_state.read_us.fetch_add(v2_full_down_read_us, std::memory_order_relaxed);
        v2_state.h2d_enqueue_us.fetch_add(v2_full_down_h2d_enqueue_us, std::memory_order_relaxed);
        v2_state.total_us.fetch_add(v2_full_down_total_us, std::memory_order_relaxed);
        expert_pack_v2_full_cover_down_profile_record(
                "accepted",
                "ok",
                src0_name,
                src0_type_int,
                v2_full_down_packed_type,
                n_active,
                src0_bytes,
                v2_full_down_nbytes,
                v2_full_down_cache_hits,
                v2_full_down_cache_misses,
                v2_full_down_copied_entries,
                v2_full_down_copied_bytes,
                (uint64_t)(src0_bytes - v2_full_down_nbytes) * (uint64_t)n_active,
                v2_full_down_read_us,
                v2_full_down_h2d_enqueue_us,
                v2_full_down_total_us);
    }
    if (updown_paired_down_name_ok) {
        int paired_jobs = 0;
        int paired_cache_hits = 0;
        int paired_missing_pack = 0;
        for (int j = 0; j < n_active; ++j) {
            const int expert = active_experts[j];
            const uintptr_t down_key = batch_key_hash(updown_paired_down_name, expert);
            if (batch_cache_find_slot(cache, down_key) >= 0) {
                ++paired_cache_hits;
                continue;
            }
            const int down_slot = batch_cache_insert_slot(cache, down_key, nullptr, src0_bytes, st,
                    true, false, bc.h_x_ids, n_active, false, updown_paired_down_name, expert, true);
            if (down_slot < 0) {
                continue;
            }
            const expert_pack_entry *pack_entry = expert_pack_lookup(updown_paired_down_name, expert, src0_bytes);
            if (!pack_entry) {
                ++paired_missing_pack;
                batch_cache_clear_slot(cache, down_slot);
                continue;
            }
            down_stage_copy_job job;
            job.slot = down_slot;
            job.key = down_key;
            job.generation = cache->slot_generation[down_slot];
            job.dst = (char *)cache->pool + (size_t)down_slot * cache->slot_sz;
            job.host_data = nullptr;
            job.pack_entry = pack_entry;
            job.expert_idx = expert;
            std::snprintf(job.tensor, sizeof(job.tensor), "%s", updown_paired_down_name);
            cache->slot_filling[down_slot] = true;
            if (down_stage_single_ring) {
                down_jobs_a.push_back(job);
            } else if ((int)(down_jobs_a.size() + down_jobs_b.size()) & 1) {
                down_jobs_b.push_back(job);
            } else {
                down_jobs_a.push_back(job);
            }
            ++paired_jobs;
        }
        static std::atomic<int> first_updown_paired_read{0};
        if (paired_jobs > 0 && first_updown_paired_read.fetch_add(1) == 0) {
            std::fprintf(stderr,
                    "[moe_stream_batch] up/down paired read active: up=%s down=%s jobs=%d cache_hits=%d missing_pack=%d\n",
                    src0_name ? src0_name : "", updown_paired_down_name, paired_jobs, paired_cache_hits, paired_missing_pack);
        }
        if (updown_pair_profile_enabled()) {
            updown_pair_profile_write("paired_down_plan", src0_name, updown_paired_down_name, src0_bytes, n_active,
                    updown_pair_active_hash(active_experts, n_active), paired_cache_hits, paired_jobs,
                    paired_jobs, paired_missing_pack);
        }
    }
    bc.h_bounds[n_active] = n_active;
    updown_pair_profile_actual(src0_name, src0_bytes, active_experts, n_active,
            down_profile_cache_hits, down_profile_cache_misses);
    mxfp4_stage_trace("stage_jobs_done");

    cross_role_call = common_cross_role_plan(
            src0_name, src0_type, active_experts, token_ids, n_active, src0_bytes,
            down_jobs_a.size() + down_jobs_b.size(),
            down_parallel_stage && !down_hit_only && !v2_full_down_active && !updown_paired_read);

    if (down_parallel_stage && (!down_jobs_a.empty() || !down_jobs_b.empty())) {
        bool copy_a_ok = true;
        bool copy_b_ok = true;
        std::thread copy_a([&]() {
            copy_a_ok = copy_down_stage_jobs(down_jobs_a, bc.up_stream, bc.stage_ring);
        });
        std::thread copy_b([&]() {
            copy_b_ok = copy_down_stage_jobs(down_jobs_b, bc.gate_stream, bc.stage_ring_gate);
        });
        copy_a.join();
        copy_b.join();
        if (!copy_a_ok || !copy_b_ok) {
            clear_down_stage_jobs(down_jobs_a);
            clear_down_stage_jobs(down_jobs_b);
            return decline("parallel_stage_copy");
        }
        if (cudaEventRecord(bc.ev_up_done, bc.up_stream) != cudaSuccess) return decline("record_up_done");
        if (cudaEventRecord(bc.ev_gate_done, bc.gate_stream) != cudaSuccess) return decline("record_gate_done");
        if (cudaStreamWaitEvent(st, bc.ev_up_done, 0) != cudaSuccess) return decline("wait_up_done");
        if (cudaStreamWaitEvent(st, bc.ev_gate_done, 0) != cudaSuccess) return decline("wait_gate_done");
    }
    mxfp4_stage_trace("parallel_stage_done");

    if (mxfp4_q80_compat_candidate) {
        if (cudaMemcpyAsync(bc.d_src1_q8, bc.h_src1, src1_q80_bytes, cudaMemcpyHostToDevice, st) != cudaSuccess) return decline("copy_src1_q80_h2d");
    } else if (!use_handoff && cudaMemcpyAsync(bc.d_src1_f32, bc.h_src1, src1_f32_bytes, cudaMemcpyHostToDevice, st) != cudaSuccess) {
        return decline("copy_src1_h2d");
    }
    if (cudaMemcpyAsync(bc.d_ids_src1, bc.h_ids_src1, ids_bytes, cudaMemcpyHostToDevice, st) != cudaSuccess) return decline("copy_ids_src1_h2d");
    if (cudaMemcpyAsync(bc.d_ids_dst, bc.h_ids_dst, ids_bytes, cudaMemcpyHostToDevice, st) != cudaSuccess) return decline("copy_ids_dst_h2d");
    if (cudaMemcpyAsync(bc.d_x_ids, bc.h_x_ids, ids_bytes, cudaMemcpyHostToDevice, st) != cudaSuccess) return decline("copy_x_ids_h2d");
    if (cudaMemcpyAsync(bc.d_bounds, bc.h_bounds, bounds_bytes, cudaMemcpyHostToDevice, st) != cudaSuccess) return decline("copy_bounds_h2d");
    if (cudaMemsetAsync(bc.d_dst, 0, dst_bytes, st) != cudaSuccess) return decline("memset_dst");
    mxfp4_stage_trace("h2d_meta_enqueued");
    if (profile) cudaEventRecord(bc.ev_stage, st);

    if (use_handoff) {
        static std::atomic<int> first_handoff_consume{0};
        if (first_handoff_consume.fetch_add(1) == 0) {
            std::fprintf(stderr, "[moe_stream_batch] GPU handoff consumed: ne00=%ld dst_cols=%ld\n",
                         (long)ne00, (long)dst_cols);
        }
    }
    if (profile) cudaEventRecord(bc.ev_quant, st);

    const float *d_src1_run = use_handoff ? g_handoff.d_data : (const float *)bc.d_src1_f32;
    const int64_t src1_run_stride = use_handoff ? g_handoff.ne01 : ne00;
    const int32_t *src1_rows = use_handoff ? bc.h_ids_dst : nullptr;
    const ggml_type run_src0_type = v2_full_down_active ? (ggml_type)v2_full_down_packed_type : src0_type;
    const int64_t run_nb01 = v2_full_down_active ? v2_full_down_nb01 : nb01;
    const char *launch_cache_name = v2_full_down_active ? v2_full_down_cache_name : src0_name;
    const ggml_moe_common::role launch_cache_role = is_prompt_up ? ggml_moe_common::role::up :
        (is_prompt_gate ? ggml_moe_common::role::gate : ggml_moe_common::role::down);
    mxfp4_stage_trace("pre_kernel");
    if (down_q8k_requested) {
        if (ne00 % QK_K != 0) return decline("down_q8k_bad_ne00");
        const int nblocks = (int)(n_active * (ne00 / QK_K));
        moe_quantize_row_q8_k_kernel<<<nblocks, 1, 0, st>>>((const float *)bc.d_src1_f32, (block_q8_K *)bc.d_src1_q8k, nblocks);
        if (cudaGetLastError() != cudaSuccess) return decline("down_q8k_quantize");
    }
    const char *launch_failure_reason = "role_kernel_lease";
    if (!batch_cache_launch_with_role_leases(
            cache, launch_cache_name, launch_cache_role, active_experts, bc.h_x_ids,
            n_active, st, [&]() -> bool {
                if (mxfp4_q80_compat_candidate) {
                    static std::atomic<int> first_mxfp4_q80_compat{0};
                    if (first_mxfp4_q80_compat.fetch_add(1) == 0) {
                        std::fprintf(stderr, "[moe_stream_batch] MXFP4 Q8_0-compatible batch path active\n");
                    }
                    launch_failure_reason = "launch_mxfp4_down_q80_compat_batch";
                    return launch_mxfp4_down_q80_compat_batch(
                        (const char *)cache->pool, bc.d_x_ids, cache->slot_sz,
                        ne00, ne01, nb01, (const char *)bc.d_src1_q8, src1_q8_0_row_size,
                        (float *)bc.d_dst, n_active,
                        mxfp4_down_q80_cpu_order_enabled(),
                        mxfp4_down_q80_cpu_order_lane8_enabled(),
                        mxfp4_down_q80_cpu_order_lane8_shared_enabled(), st);
                }
                if (mxfp4_f32_exact_candidate) {
                    static std::atomic<int> first_mxfp4_f32_exact{0};
                    if (first_mxfp4_f32_exact.fetch_add(1) == 0) {
                        std::fprintf(stderr, "[moe_stream_batch] MXFP4 down f32 exact probe path active\n");
                    }
                    launch_failure_reason = "launch_mxfp4_down_f32_exact_batch";
                    return launch_mxfp4_down_f32_exact_batch(
                        (const char *)cache->pool, bc.d_x_ids, cache->slot_sz,
                        ne00, ne01, nb01, d_src1_run, src1_run_stride, bc.d_ids_src1,
                        (float *)bc.d_dst, n_active, st);
                }
                if (down_q8k_requested) {
                    launch_failure_reason = "launch_down_q8k_batch";
                    return launch_moe_iq3_xxs_q8k_batch(
                        src0_type, (const char *)cache->pool, (const block_q8_K *)bc.d_src1_q8k,
                        bc.d_ids_dst, bc.d_x_ids, (float *)bc.d_dst,
                        ne00, ne01, nb01, cache->slot_sz, n_active, dst_cols, false, st);
                }
                launch_failure_reason = "launch_moe_mmvq_compact_batch";
                return launch_moe_mmvq_compact_batch(
                    run_src0_type,
                    (const char *)cache->pool, bc.h_x_ids, cache->slot_sz,
                    ne00, ne01, run_nb01, d_src1_run, src1_run_stride, src1_rows,
                    bc.d_src1_q8, (float *)bc.d_dst, n_active, st);
            })) {
        if (std::strcmp(launch_failure_reason, "launch_moe_mmvq_compact_batch") == 0) {
            mxfp4_stage_trace("launch_moe_mmvq_compact_batch_fail");
        }
        return decline(launch_failure_reason);
    }
    mxfp4_stage_trace("kernel_enqueued");
    if (use_handoff) {
        g_handoff.host_ptr = nullptr;
        g_handoff.d_data = nullptr;
    }
    if (profile) cudaEventRecord(bc.ev_kernel, st);
    if (!g_expert_pack.glm52_colibri) {
        if (cudaMemcpyAsync(bc.h_dst, bc.d_dst, dst_bytes, cudaMemcpyDeviceToHost, st) != cudaSuccess) return decline("copy_dst_d2h");
        mxfp4_stage_trace("d2h_enqueued");
        if (profile) cudaEventRecord(bc.ev_d2h, st);
    }
    mxfp4_stage_trace("pre_sync");
    if (cudaStreamSynchronize(st) != cudaSuccess) {
        mxfp4_stage_trace("sync_stream_fail");
        return decline("sync_stream");
    }
    mxfp4_stage_trace("sync_done");
    if (cross_role_call) common_cross_role_finish(src0_name);

    if (mxfp4_probe_run) {
        mxfp4_stage_trace("pre_report");
        mxfp4_down_probe_report(
                src0_name, mxfp4_probe_call, src0_data, nb01, nb02, ne00, ne01,
                src1_f32, src1_nb1, src1_nb2,
                active_experts, dst_ids, token_ids, n_active, (const float *)bc.h_dst);
        return false;
    }

    if (q4_parity_run) {
        q4_down_parity_report(
                src0_name, q4_parity_call, src0_data, nb01, nb02, ne00, ne01,
                src1_f32, src1_nb1, src1_nb2,
                active_experts, dst_ids, token_ids, n_active, (const float *)bc.h_dst);
        return false;
    }

    if (shadow_error) {
        const std::vector<double> &thresholds = down_act_shadow_thresholds();
        const size_t block_size = down_act_sparsity_block_size();
        std::vector<uint64_t> skipped_blocks((size_t)n_active);
        std::vector<uint64_t> skipped_values((size_t)n_active);
        std::vector<uint64_t> total_blocks((size_t)n_active);
        const float *exact_rows = (const float *)bc.h_dst;

        for (double threshold : thresholds) {
            std::memcpy(bc.h_src1_shadow, bc.h_src1, src1_f32_bytes);
            for (int j = 0; j < n_active; ++j) {
                float *row = (float *)bc.h_src1_shadow + (size_t)j * ne00;
                down_act_mask_row(
                        row,
                        ne00,
                        block_size,
                        threshold,
                        skipped_blocks[(size_t)j],
                        skipped_values[(size_t)j],
                        total_blocks[(size_t)j]);
            }

            if (cudaMemcpyAsync(bc.d_src1_f32, bc.h_src1_shadow, src1_f32_bytes, cudaMemcpyHostToDevice, st) != cudaSuccess) {
                return decline("shadow_copy_src1_h2d");
            }
            if (cudaMemsetAsync(bc.d_dst, 0, dst_bytes, st) != cudaSuccess) {
                return decline("shadow_memset_dst");
            }
            if (down_q8k_requested) {
                if (ne00 % QK_K != 0) return decline("shadow_down_q8k_bad_ne00");
                const int nblocks = (int)(n_active * (ne00 / QK_K));
                moe_quantize_row_q8_k_kernel<<<nblocks, 1, 0, st>>>((const float *)bc.d_src1_f32, (block_q8_K *)bc.d_src1_q8k, nblocks);
                if (cudaGetLastError() != cudaSuccess) return decline("shadow_down_q8k_quantize");
            }
            const char *shadow_launch_failure_reason = "shadow_role_kernel_lease";
            if (!batch_cache_launch_with_role_leases(
                    cache, launch_cache_name, launch_cache_role, active_experts, bc.h_x_ids,
                    n_active, st, [&]() -> bool {
                        if (down_q8k_requested) {
                            shadow_launch_failure_reason = "shadow_launch_down_q8k_batch";
                            return launch_moe_iq3_xxs_q8k_batch(
                                src0_type, (const char *)cache->pool,
                                (const block_q8_K *)bc.d_src1_q8k,
                                bc.d_ids_dst, bc.d_x_ids, (float *)bc.d_dst,
                                ne00, ne01, nb01, cache->slot_sz, n_active,
                                dst_cols, false, st);
                        }
                        shadow_launch_failure_reason = "shadow_launch_moe_mmvq_compact_batch";
                        return launch_moe_mmvq_compact_batch(
                            src0_type,
                            (const char *)cache->pool, bc.h_x_ids, cache->slot_sz,
                            ne00, ne01, nb01, (const float *)bc.d_src1_f32,
                            ne00, nullptr, bc.d_src1_q8, (float *)bc.d_dst,
                            n_active, st);
                    })) {
                return decline(shadow_launch_failure_reason);
            }
            if (cudaMemcpyAsync(bc.h_dst_shadow, bc.d_dst, dst_bytes, cudaMemcpyDeviceToHost, st) != cudaSuccess) {
                return decline("shadow_copy_dst_d2h");
            }
            if (cudaStreamSynchronize(st) != cudaSuccess) {
                return decline("shadow_sync_stream");
            }

            const float *shadow_rows = (const float *)bc.h_dst_shadow;
            for (int j = 0; j < n_active; ++j) {
                down_act_shadow_error_record(
                        (uint64_t)batch_call,
                        src0_name,
                        src0_type,
                        j,
                        active_experts[j],
                        dst_ids[j],
                        token_ids[j],
                        threshold,
                        ne00,
                        ne01,
                        block_size,
                        skipped_blocks[(size_t)j],
                        total_blocks[(size_t)j],
                        skipped_values[(size_t)j],
                        exact_rows + (size_t)j * ne01,
                        shadow_rows + (size_t)j * ne01);
            }
        }
    }

    float stage_ms = 0.0f;
    float quant_ms = 0.0f;
    float kernel_ms = 0.0f;
    float d2h_ms = 0.0f;
    if (profile) {
        cudaEventElapsedTime(&stage_ms, bc.ev_start, bc.ev_stage);
        cudaEventElapsedTime(&quant_ms, bc.ev_stage, bc.ev_quant);
        cudaEventElapsedTime(&kernel_ms, bc.ev_quant, bc.ev_kernel);
        cudaEventElapsedTime(&d2h_ms, bc.ev_kernel, bc.ev_d2h);
    }

    const float *tmp = (const float *)bc.h_dst;
    const auto scatter_start = std::chrono::steady_clock::now();
    for (int j = 0; j < n_active; ++j) {
        float *dst_row = (float *)((char *)dst + (size_t)dst_ids[j] * dst_nb1 + (size_t)token_ids[j] * dst_nb2);
        if (g_expert_pack.glm52_colibri) {
            const float *device_src_row = (const float *)bc.d_dst + (size_t)j * ne01;
            if (cudaMemcpyAsync(dst_row, device_src_row, (size_t)ne01 * sizeof(float), cudaMemcpyDeviceToDevice, st) != cudaSuccess) {
                return decline("scatter_d2d");
            }
        } else {
            std::memcpy(dst_row, tmp + (size_t)j * ne01, (size_t)ne01 * sizeof(float));
        }
    }
    if (g_expert_pack.glm52_colibri && cudaStreamSynchronize(st) != cudaSuccess) return decline("scatter_d2d_sync");
    if (profile) {
        const auto scatter_end = std::chrono::steady_clock::now();
        const double scatter_ms = std::chrono::duration<double, std::milli>(scatter_end - scatter_start).count();
        const double wall_ms = std::chrono::duration<double, std::milli>(scatter_end - wall_start).count();
        ++g_bprof.calls;
        g_bprof.active_experts += (uint64_t)n_active;
        g_bprof.stage_ms += stage_ms;
        g_bprof.quant_ms += quant_ms;
        g_bprof.kernel_ms += kernel_ms;
        g_bprof.d2h_ms += d2h_ms;
        g_bprof.scatter_ms += scatter_ms;
        g_bprof.wall_ms += wall_ms;
        if (down_batch_profile_enabled()) {
            down_batch_profile_record(
                    src0_name,
                    src0_type,
                    n_active,
                    down_profile_cache_hits,
                    down_profile_cache_misses,
                    (int)(down_jobs_a.size() + down_jobs_b.size()),
                    stage_ms,
                    quant_ms,
                    kernel_ms,
                    d2h_ms,
                    scatter_ms,
                    wall_ms);
        }
    }
    batch_prompt_mmap_dontneed(
            src0_data, (size_t)(n_as - 1) * nb02 + src0_bytes, prompt_multirow);
    if (prompt_multirow && src0_name) {
        std::string gate_name;
        std::string up_name;
        std::string down_name;
        if (q4_tier_role_family_names(src0_name, gate_name, up_name, down_name)) {
            registered_tensor sibling;
            if (registered_tensor_lookup(up_name.c_str(), &sibling)) {
                batch_prompt_mmap_dontneed(
                        sibling.data,
                        (size_t)(sibling.n_as - 1) * sibling.nb02 + sibling.expert_bytes,
                        true);
            }
            if (registered_tensor_lookup(gate_name.c_str(), &sibling)) {
                batch_prompt_mmap_dontneed(
                        sibling.data,
                        (size_t)(sibling.n_as - 1) * sibling.nb02 + sibling.expert_bytes,
                        true);
            }
        }
    }
    return true;
}


} // namespace ggml_moe_common_adapter

#endif // GGML_CUDA_MOE_STREAM_BATCH
